/**
 * ThemeContext 适配器 — 对齐 web 端 useTheme() 接口。
 * 实际主题状态来自 desktop usePreferences。
 */
import { usePreferences } from '@/store/preferences'
import { useEffect, useState } from 'react'

export function useTheme() {
  const { theme } = usePreferences()
  const [resolvedTheme, setResolvedTheme] = useState<'light' | 'dark'>('light')

  useEffect(() => {
    if (theme === 'dark') {
      setResolvedTheme('dark')
    } else if (theme === 'light') {
      setResolvedTheme('light')
    } else {
      // system
      const mq = window.matchMedia('(prefers-color-scheme: dark)')
      setResolvedTheme(mq.matches ? 'dark' : 'light')
      const handler = (e: MediaQueryListEvent) => setResolvedTheme(e.matches ? 'dark' : 'light')
      mq.addEventListener('change', handler)
      return () => mq.removeEventListener('change', handler)
    }
  }, [theme])

  return { theme, resolvedTheme }
}

import { createContext, useContext, useState, useCallback, useRef, useEffect } from 'react'
import type { ReactNode } from 'react'
import { toast } from 'sonner'
import { addPhotosToAlbum, addPhotosToStory } from '@/lib/api'
import { getErrorMessage, isAuthError } from '@/lib/auth-errors'
import { invalidateDesktopCache } from '@/lib/app-cache'
import { useAuth } from '@/contexts/AuthContext'

export type UploadTaskStatus = 'pending' | 'uploading' | 'completed' | 'failed'

export interface UploadTask {
  id: string
  filePath: string
  assetId?: string
  fileName: string
  fileSize: number
  status: UploadTaskStatus
  progress: number
  error?: string
  photoId?: string
}

interface UploadQueueContextType {
  tasks: UploadTask[]
  isUploading: boolean
  addTasks: (files: Array<{ filePath: string; assetId?: string; fileName: string; fileSize: number; hash: string; exif?: any }>, settings: UploadSettings) => UploadTask[]
  retryTask: (taskId: string) => void
  retryAllFailed: () => void
  removeTask: (taskId: string) => void
  clearCompleted: () => void
}

interface UploadSettings {
  title: string
  categories: string[]
  albumIds?: string[]
  storyId?: string
  filmRollId?: string
  storageSourceId: string
  storagePath: string
  compressEnabled: boolean
  maxSizeMB: number
  showFlag: boolean
  stripGPS: boolean
}

const CONCURRENCY = 3

const UploadQueueContext = createContext<UploadQueueContextType | null>(null)

export function useUploadQueue() {
  const ctx = useContext(UploadQueueContext)
  if (!ctx) throw new Error('useUploadQueue must be used within UploadQueueProvider')
  return ctx
}

export function UploadQueueProvider({ children }: { children: ReactNode }) {
  const { token } = useAuth()
  const [tasks, setTasks] = useState<UploadTask[]>([])
  const [isUploading, setIsUploading] = useState(false)
  // tasksRef 是队列状态的唯一权威来源；tasks state 仅用于渲染。
  // processQueue 的副作用（启动上传）绝不能放进 setTasks 的 updater：
  // React 会在 StrictMode/并发渲染下重复调用 updater，导致同一文件被上传两次。
  const tasksRef = useRef<UploadTask[]>([])
  const activeCountRef = useRef(0)
  const startedIdsRef = useRef<Set<string>>(new Set())
  // 设置按任务绑定：后加入的批次可能带不同设置（showFlag/分类/存储等），
  // 共用一个全局设置会让上一批还在排队的任务用新批次的设置上传。
  const taskSettingsRef = useRef<Map<string, UploadSettings>>(new Map())
  const hashesRef = useRef<Map<string, string>>(new Map())
  const exifsRef = useRef<Map<string, any>>(new Map())
  const tokenRef = useRef('')

  useEffect(() => {
    tokenRef.current = token || ''
  }, [token])

  const patchTasks = useCallback((updater: (prev: UploadTask[]) => UploadTask[]) => {
    tasksRef.current = updater(tasksRef.current)
    setTasks(tasksRef.current)
  }, [])

  const updateTask = useCallback((id: string, patch: Partial<UploadTask>) => {
    patchTasks(prev => prev.map(t => t.id === id ? { ...t, ...patch } : t))
  }, [patchTasks])

  const uploadSingleFile = useCallback(async (task: UploadTask, settings: UploadSettings) => {
    let progressTimer: number | undefined
    updateTask(task.id, { status: 'uploading', progress: 5 })
    progressTimer = window.setInterval(() => {
      patchTasks(prev => prev.map(t => {
        if (t.id !== task.id || t.status !== 'uploading') return t
        return { ...t, progress: Math.min(95, t.progress + Math.max(1, Math.round((95 - t.progress) * 0.08))) }
      }))
    }, 500)
    try {
      const hash = hashesRef.current.get(task.filePath) || ''
      const exif = exifsRef.current.get(task.filePath) || null
      const uploadMethod = task.assetId
        ? (window as any).go.main.App.UploadLocalAsset
        : (window as any).go.main.App.UploadFile
      const source = task.assetId || task.filePath
      const result = await uploadMethod(
        source,
        {
          title: settings.title || task.fileName,
          categories: settings.categories,
          filmRollId: settings.filmRollId || undefined,
          storageSourceId: settings.storageSourceId,
          storagePath: settings.storagePath || undefined,
          compressEnabled: settings.compressEnabled,
          maxSizeMB: settings.maxSizeMB,
          showFlag: settings.showFlag,
          stripGPS: settings.stripGPS,
          originFlag: 'desktop',
        },
        hash,
        exif,
      )

      if (result?.isDuplicate) {
        updateTask(task.id, { status: 'completed', progress: 100, error: `已存在: ${result.existing?.title || ''}` })
      } else if (result?.success && result.photo?.id) {
        const photoId = result.photo.id
        updateTask(task.id, { status: 'completed', progress: 100, photoId })
        invalidateDesktopCache(['overview', 'equipment', 'photos', 'albums', 'categories', 'film-rolls', 'stories'])

        // ── 补偿调用：关联相册/故事 ──────────────────────────────────
        // Go UploadSettings 不包含 albumIds/storyId，所以在此处通过 HTTP
        // 直连 Web API 完成关联（模式参考故事编辑器 useStoryEditorActions.ts:323）
        const compensationToken = tokenRef.current
        if (compensationToken) {
          // 关联到相册（失败不影响上传成功状态，提示用户手动补救）
          if (settings.albumIds?.length) {
            for (const albumId of settings.albumIds) {
              try {
                await addPhotosToAlbum(compensationToken, albumId, [photoId])
              } catch (err) {
                if (isAuthError(err)) {
                  tokenRef.current = ''
                  return
                }
                console.error(`关联相册 ${albumId} 失败:`, err)
                toast.error(`「${task.fileName}」已上传，但添加到相册失败，请到相册页手动添加`)
              }
            }
          }

          // 关联到故事
          if (settings.storyId) {
            try {
              await addPhotosToStory(compensationToken, settings.storyId, [photoId])
            } catch (err) {
              if (isAuthError(err)) {
                tokenRef.current = ''
                return
              }
              console.error(`关联故事 ${settings.storyId} 失败:`, err)
              toast.error(`「${task.fileName}」已上传，但关联故事失败，请到故事编辑器手动添加`)
            }
          }
        }
      } else {
        updateTask(task.id, { status: 'failed', progress: 0, error: result?.error || '上传失败' })
      }
    } catch (err: unknown) {
      if (isAuthError(err)) {
        tokenRef.current = ''
        startedIdsRef.current.delete(task.id)
        updateTask(task.id, { status: 'pending', progress: 0, error: undefined })
        return
      }
      updateTask(task.id, { status: 'failed', progress: 0, error: getErrorMessage(err) })
    } finally {
      if (progressTimer) window.clearInterval(progressTimer)
      activeCountRef.current--
      processQueue()
    }
  }, [updateTask, patchTasks])

  const processQueue = useCallback(() => {
    if (!tokenRef.current) {
      setIsUploading(false)
      return
    }

    const pending = tasksRef.current.filter(
      t => t.status === 'pending' && !startedIdsRef.current.has(t.id)
    )
    const slots = CONCURRENCY - activeCountRef.current
    if (slots <= 0 || pending.length === 0) {
      if (activeCountRef.current === 0 && tasksRef.current.every(t => t.status !== 'pending')) {
        setIsUploading(false)
      }
      return
    }

    for (const task of pending.slice(0, slots)) {
      const settings = taskSettingsRef.current.get(task.id)
      if (!settings) {
        updateTask(task.id, { status: 'failed', progress: 0, error: '内部错误：缺少上传设置' })
        continue
      }
      startedIdsRef.current.add(task.id)
      activeCountRef.current++
      uploadSingleFile(task, settings)
    }
  }, [uploadSingleFile, updateTask])

  const addTasks = useCallback((files: Array<{ filePath: string; assetId?: string; fileName: string; fileSize: number; hash: string; exif?: any }>, settings: UploadSettings) => {
    const newTasks: UploadTask[] = files.map(f => {
      hashesRef.current.set(f.filePath, f.hash)
      if (f.exif) exifsRef.current.set(f.filePath, f.exif)
      const task: UploadTask = {
        id: crypto.randomUUID(),
        filePath: f.filePath,
        assetId: f.assetId,
        fileName: f.fileName,
        fileSize: f.fileSize,
        status: 'pending' as const,
        progress: 0,
      }
      taskSettingsRef.current.set(task.id, settings)
      return task
    })

    patchTasks(prev => [...prev, ...newTasks])
    setIsUploading(true)
    setTimeout(processQueue, 0)
    return newTasks
  }, [patchTasks, processQueue])

  const retryTask = useCallback((taskId: string) => {
    startedIdsRef.current.delete(taskId)
    patchTasks(prev => prev.map(t => t.id === taskId ? { ...t, status: 'pending' as const, progress: 0, error: undefined } : t))
    setTimeout(processQueue, 0)
  }, [patchTasks, processQueue])

  const retryAllFailed = useCallback(() => {
    patchTasks(prev => prev.map(t => {
      if (t.status !== 'failed') return t
      startedIdsRef.current.delete(t.id)
      return { ...t, status: 'pending' as const, progress: 0, error: undefined }
    }))
    setTimeout(processQueue, 0)
  }, [patchTasks, processQueue])

  const removeTask = useCallback((taskId: string) => {
    startedIdsRef.current.delete(taskId)
    taskSettingsRef.current.delete(taskId)
    patchTasks(prev => prev.filter(t => t.id !== taskId))
  }, [patchTasks])

  const clearCompleted = useCallback(() => {
    patchTasks(prev => prev.filter(t => {
      if (t.status !== 'completed') return true
      startedIdsRef.current.delete(t.id)
      taskSettingsRef.current.delete(t.id)
      return false
    }))
  }, [patchTasks])

  return (
    <UploadQueueContext.Provider value={{ tasks, isUploading, addTasks, retryTask, retryAllFailed, removeTask, clearCompleted }}>
      {children}
    </UploadQueueContext.Provider>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { ExternalLink, FileText, FolderInput, Heart, ImageOff, Loader2, Maximize2, Pencil, Plus, RefreshCw, RotateCcw, Star, Trash2, X } from 'lucide-react'
import { isPhotoAsset } from './types'
import type { LocalAsset, LocalCollection, LocalTag } from './types'
import type { LocalLibraryCopy } from './copy'

interface Props {
  asset: LocalAsset | null
  copy: LocalLibraryCopy
  saving: boolean
  maintenanceBusy: boolean
  tags: LocalTag[]
  collections: LocalCollection[]
  organizationBusy: boolean
  onSave: (assetId: string, patch: Pick<LocalAsset, 'displayTitle' | 'notes' | 'rating' | 'colorLabel' | 'isFavorite'>) => Promise<void>
  onPreview: (asset: LocalAsset) => void
  onOpenSystem: (asset: LocalAsset) => void
  onMove: (asset: LocalAsset) => void
  onDelete: (asset: LocalAsset) => void
  onRestore: (asset: LocalAsset) => void
  onRetryPreview: (asset: LocalAsset) => void
  onRecheckMissing: (asset: LocalAsset) => void
  onRemoveMissing: (asset: LocalAsset) => void
  onSetTags: (assetId: string, tagIds: string[]) => Promise<void>
  onCreateTag: (name: string) => Promise<LocalTag | undefined>
  onSetCollections: (assetId: string, collectionIds: string[]) => Promise<void>
}

const colors = ['', 'red', 'orange', 'yellow', 'green', 'blue', 'purple']

function formatBytes(value: number) {
  if (value < 1024) return `${value} B`
  if (value < 1024 ** 2) return `${(value / 1024).toFixed(1)} KB`
  if (value < 1024 ** 3) return `${(value / 1024 ** 2).toFixed(1)} MB`
  return `${(value / 1024 ** 3).toFixed(2)} GB`
}

function formatDate(value: string | number | null | undefined) {
  if (value === null || value === undefined || value === '') return '—'
  const date = typeof value === 'number' ? new Date(value / 1e6) : new Date(value)
  if (Number.isNaN(date.getTime())) return '—'
  return date.toLocaleDateString('zh-CN', {
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit',
  })
}

function SectionLabel({ label }: { label: string }) {
  return (
    <span className="mb-2 block text-[10px] font-medium uppercase tracking-[0.16em]" style={{ color: 'var(--muted-foreground)' }}>{label}</span>
  )
}

export function LocalAssetDetails({ asset, copy, saving, maintenanceBusy, tags, collections, organizationBusy, onSave, onPreview, onOpenSystem, onMove, onDelete, onRestore, onRetryPreview, onRecheckMissing, onRemoveMissing, onSetTags, onCreateTag, onSetCollections }: Props) {
  const [title, setTitle] = useState('')
  const [notes, setNotes] = useState('')
  const [rating, setRating] = useState(0)
  const [color, setColor] = useState('')
  const [favorite, setFavorite] = useState(false)
  const [editingInfo, setEditingInfo] = useState(false)
  const [tagQuery, setTagQuery] = useState('')
  const [tagMenuOpen, setTagMenuOpen] = useState(false)
  const [assignedTagIds, setAssignedTagIds] = useState<string[]>([])
  const infoEditorRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setTitle(asset?.displayTitle || '')
    setNotes(asset?.notes || '')
    setRating(asset?.rating || 0)
    setColor(asset?.colorLabel || '')
    setFavorite(Boolean(asset?.isFavorite))
    setAssignedTagIds(asset?.tags.map((tag) => tag.id) || [])
    setEditingInfo(false)
    setTagQuery('')
    setTagMenuOpen(false)
  }, [asset?.id])

  const saveCurrent = useCallback((overrides: Partial<Pick<LocalAsset, 'displayTitle' | 'notes' | 'rating' | 'colorLabel' | 'isFavorite'>> = {}) => {
    if (!asset) return Promise.resolve()
    return onSave(asset.id, {
      displayTitle: title,
      notes,
      rating,
      colorLabel: color,
      isFavorite: favorite,
      ...overrides,
    })
  }, [asset, color, favorite, notes, onSave, rating, title])

  const finishInfoEditing = useCallback(() => {
    if (!editingInfo) return
    setEditingInfo(false)
    if (!asset || (title === (asset.displayTitle || '') && notes === (asset.notes || ''))) return
    void saveCurrent()
  }, [asset, editingInfo, notes, saveCurrent, title])

  useEffect(() => {
    if (!editingInfo) return
    const handlePointerDown = (event: PointerEvent) => {
      if (!infoEditorRef.current?.contains(event.target as Node)) finishInfoEditing()
    }
    document.addEventListener('pointerdown', handlePointerDown, true)
    return () => document.removeEventListener('pointerdown', handlePointerDown, true)
  }, [editingInfo, finishInfoEditing])

  const assignedTags = useMemo(() => {
    const source = new Map([...tags, ...(asset?.tags || [])].map((tag) => [tag.id, tag]))
    return assignedTagIds.flatMap((id) => source.get(id) ? [source.get(id)!] : [])
  }, [asset?.tags, assignedTagIds, tags])
  const matchingTags = useMemo(() => {
    const query = tagQuery.trim().toLocaleLowerCase()
    return tags.filter((tag) => !assignedTagIds.includes(tag.id) && (!query || tag.name.toLocaleLowerCase().includes(query))).slice(0, 8)
  }, [assignedTagIds, tagQuery, tags])

  const updateTags = async (nextIds: string[]) => {
    if (!asset) return
    setAssignedTagIds(nextIds)
    await onSetTags(asset.id, nextIds)
  }

  const addTag = async (tag?: LocalTag) => {
    const name = tagQuery.trim()
    const selected = tag || tags.find((item) => item.name.toLocaleLowerCase() === name.toLocaleLowerCase()) || (name ? await onCreateTag(name) : undefined)
    if (!selected || assignedTagIds.includes(selected.id)) return
    await updateTags([...assignedTagIds, selected.id])
    setTagQuery('')
    setTagMenuOpen(false)
  }

  if (!asset) {
    return <aside className="hidden h-full w-[292px] shrink-0 items-center justify-center border-l p-6 text-center xl:flex" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }} data-local-library-guide="details"><div><ImageOff size={26} className="mx-auto mb-3" /><p className="text-xs">{copy.noSelection}</p></div></aside>
  }

  const previewPending = asset.previewStatus === 'pending' || asset.previewStatus === 'generating'
  const unavailable = asset.previewStatus === 'unavailable'
  const missing = asset.availability === 'missing'
  const trashed = asset.availability === 'trashed'
  const isPhoto = isPhotoAsset(asset)
  return (
    <aside className="custom-scrollbar hidden h-full w-[292px] shrink-0 overflow-y-auto border-l bg-card xl:block" style={{ borderColor: 'var(--border)' }} data-local-library-guide="details">
      <div className="border-b p-3" style={{ borderColor: 'var(--border)' }}>
        <button type="button" onClick={() => onPreview(asset)} disabled={previewPending || missing || trashed} className="group relative flex aspect-[4/3] w-full items-center justify-center overflow-hidden rounded-md bg-secondary disabled:cursor-not-allowed">
          {asset.previewStatus === 'ready' && isPhoto ? (
            <img src={asset.previewUrl} alt="" className="h-full w-full object-contain" />
          ) : previewPending && isPhoto ? (
            <Loader2 size={28} className="animate-spin" style={{ color: 'var(--muted-foreground)' }} />
          ) : isPhoto ? (
            <ImageOff size={28} style={{ color: 'var(--muted-foreground)' }} />
          ) : (
            <span className="flex flex-col items-center gap-2" style={{ color: 'var(--muted-foreground)' }}>
              <FileText size={30} strokeWidth={1.4} />
              <span className="max-w-[80%] truncate text-[10px] uppercase tracking-wider">{asset.format}</span>
            </span>
          )}
          {!previewPending && !missing && !trashed && <span className="absolute bottom-2 right-2 flex h-8 w-8 items-center justify-center rounded-full bg-black/65 text-white opacity-0 transition group-hover:opacity-100"><Maximize2 size={15} /></span>}
        </button>
        {previewPending && isPhoto && <p className="mt-2 text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{copy.generatingPreview}</p>}
        {missing && <p className="mt-2 text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{copy.missingHint}</p>}
        {trashed && asset.trashEntryKind === 'folder' && <p className="mt-2 rounded-md border border-amber-500/35 bg-amber-500/10 px-2.5 py-2 text-[10px] leading-4 text-amber-700 dark:text-amber-300">{copy.folderBatchHint}</p>}
        {!missing && unavailable && isPhoto && (
          <div className="mt-2 space-y-2 text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>
            <p>{copy.unavailablePreview}</p>
            {asset.previewError && <p className="line-clamp-3 break-words"><span className="font-medium">{copy.previewFailureReason}:</span> {asset.previewError}</p>}
          </div>
        )}
      </div>

      <div className="space-y-5 p-4">
        {/* 标题信息块：双击或点击铅笔编辑 */}
        <div ref={infoEditorRef} onDoubleClick={() => setEditingInfo(true)} className="rounded-md border border-transparent p-1 transition hover:border-border">
          <div className="flex items-center justify-between gap-2">
            <span className="text-[10px] font-medium uppercase tracking-[0.16em]" style={{ color: 'var(--muted-foreground)' }}>{copy.details}</span>
            <div className="flex shrink-0 items-center gap-0.5">
              <button
                type="button"
                title={copy.autoSaveHint}
                aria-label={copy.autoSaveHint}
                onClick={() => setEditingInfo(true)}
                className="flex size-8 items-center justify-center rounded-md hover:bg-secondary"
                style={{ color: 'var(--muted-foreground)' }}
              >
                <Pencil size={14} />
              </button>
              <button
                type="button"
                title={favorite ? copy.unmarkFavorite : copy.markFavorite}
                aria-label={favorite ? copy.unmarkFavorite : copy.markFavorite}
                onClick={() => {
                  const next = !favorite
                  setFavorite(next)
                  void saveCurrent({ isFavorite: next })
                }}
                className="flex size-8 shrink-0 items-center justify-center rounded-md hover:bg-secondary"
              >
                <Heart size={17} fill={favorite ? 'currentColor' : 'none'} style={{ color: favorite ? 'var(--primary)' : 'var(--muted-foreground)' }} />
              </button>
            </div>
          </div>
          <p className="mt-1 break-all text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{asset.relativePath}</p>
          {editingInfo ? (
            <div className="mt-3 space-y-3" onKeyDown={(event) => {
              if (event.key !== 'Enter' || (event.target instanceof HTMLTextAreaElement && event.shiftKey)) return
              event.preventDefault()
              finishInfoEditing()
            }}>
              <label className="block text-xs"><span className="mb-1.5 block" style={{ color: 'var(--muted-foreground)' }}>{copy.titleField}</span><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} className="w-full rounded-md border bg-input px-2.5 py-2 outline-none focus:ring-1" /></label>
              <label className="block text-xs"><span className="mb-1.5 block" style={{ color: 'var(--muted-foreground)' }}>{copy.notes}</span><textarea value={notes} onChange={(event) => setNotes(event.target.value)} rows={4} className="w-full resize-none rounded-md border bg-input px-2.5 py-2 outline-none focus:ring-1" /></label>
              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={finishInfoEditing}
                  className="flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-medium transition-opacity hover:opacity-90"
                  style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}
                >
                  {copy.save}
                </button>
              </div>
            </div>
          ) : (
            <div className="mt-3 space-y-2 text-xs">
              <h2 className="break-words font-sans text-sm font-semibold leading-5">{title || asset.fileName}</h2>
              {notes && <p className="whitespace-pre-wrap leading-5" style={{ color: 'var(--muted-foreground)' }}>{notes}</p>}
            </div>
          )}
          <div className="mt-2 flex min-h-4 items-center gap-1.5 text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
            {saving && <Loader2 size={10} className="animate-spin" />}
            {saving ? copy.autoSaving : copy.autoSaveHint}
          </div>
        </div>

        {/* 标签 */}
        <div>
          <SectionLabel label={copy.tags} />
          <div className="flex flex-wrap gap-1.5">
            {assignedTags.map((tag) => <span key={tag.id} className="flex max-w-full items-center gap-1 rounded border bg-secondary px-1.5 py-1 text-[10px]"><span className="size-1.5 shrink-0 rounded-full" style={{ backgroundColor: tag.color || 'var(--muted-foreground)' }} /><span className="truncate">{tag.name}</span><button type="button" disabled={organizationBusy} aria-label={copy.remove} onClick={() => void updateTags(assignedTagIds.filter((id) => id !== tag.id))} className="rounded p-0.5 hover:bg-background disabled:opacity-50"><X size={10} /></button></span>)}
          </div>
          <div className="relative mt-2">
            <div className="flex items-center rounded-md border bg-input focus-within:ring-1 focus-within:ring-ring">
              <input value={tagQuery} disabled={organizationBusy} onFocus={() => setTagMenuOpen(true)} onBlur={() => window.setTimeout(() => setTagMenuOpen(false), 0)} onChange={(event) => { setTagQuery(event.target.value); setTagMenuOpen(true) }} onKeyDown={(event) => { if (event.key === 'Enter') { event.preventDefault(); void addTag() } }} placeholder={copy.tagInputPlaceholder} className="h-8 min-w-0 flex-1 bg-transparent px-2.5 text-xs outline-none" />
              <button type="button" disabled={organizationBusy || !tagQuery.trim()} title={copy.add} aria-label={copy.add} onClick={() => void addTag()} className="flex size-8 items-center justify-center disabled:opacity-40"><Plus size={13} /></button>
            </div>
            {tagMenuOpen && (matchingTags.length > 0 || tagQuery.trim()) && <div className="absolute left-0 right-0 top-full z-20 mt-1 max-h-44 overflow-y-auto rounded-md border bg-popover p-1 shadow-lg">
              {matchingTags.map((tag) => <button key={tag.id} type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => void addTag(tag)} className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-[11px] hover:bg-secondary"><span className="size-2 rounded-full" style={{ backgroundColor: tag.color || 'var(--muted-foreground)' }} /><span className="truncate">{tag.name}</span></button>)}
              {tagQuery.trim() && !tags.some((tag) => tag.name.toLocaleLowerCase() === tagQuery.trim().toLocaleLowerCase()) && <button type="button" onMouseDown={(event) => event.preventDefault()} onClick={() => void addTag()} className="flex w-full items-center gap-2 rounded px-2 py-1.5 text-left text-[11px] hover:bg-secondary"><Plus size={12} />{copy.createTagFromInput.replace('{name}', tagQuery.trim())}</button>}
            </div>}
          </div>
        </div>

        {/* 集合 */}
        <div>
          <SectionLabel label={copy.collections} />
          <div className="custom-scrollbar max-h-28 space-y-1 overflow-y-auto rounded-md border p-2">
            {collections.length === 0 ? <p className="text-[10px] text-muted-foreground">{copy.noCollections}</p> : collections.map((collection) => {
              const checked = asset.collections.some((item) => item.id === collection.id)
              return <label key={collection.id} className="flex cursor-pointer items-center gap-2 text-[11px]"><input type="checkbox" disabled={organizationBusy} checked={checked} onChange={() => void onSetCollections(asset.id, checked ? asset.collections.filter((item) => item.id !== collection.id).map((item) => item.id) : [...asset.collections.map((item) => item.id), collection.id])} /><span className="truncate">{collection.name}</span></label>
            })}
          </div>
        </div>

        {/* 评分 + 颜色标记 */}
        {isPhoto && (
        <div className="grid grid-cols-2 gap-3">
          <div>
            <SectionLabel label={copy.rating} />
            <div className="flex gap-0.5">{[1,2,3,4,5].map((value) => <button key={value} type="button" title={`${value}★`} onClick={() => { const next = rating === value ? 0 : value; setRating(next); void saveCurrent({ rating: next }) }} className="p-0.5"><Star size={16} fill={value <= rating ? 'currentColor' : 'none'} style={{ color: value <= rating ? 'var(--primary)' : 'var(--muted-foreground)' }} /></button>)}</div>
          </div>
          <div>
            <SectionLabel label={copy.color} />
            <div className="flex flex-wrap gap-2">{colors.map((value) => <button key={value || 'none'} type="button" title={value || copy.noColor} onClick={() => { setColor(value); void saveCurrent({ colorLabel: value }) }} className="h-5 w-5 rounded-full border-2 transition-transform hover:scale-110" style={{ background: value || 'transparent', borderColor: color === value ? 'var(--foreground)' : 'var(--border)' }} />)}</div>
          </div>
        </div>
        )}

        {/* 主色 */}
        {isPhoto && asset.dominantColors && asset.dominantColors.length > 0 && <div>
          <SectionLabel label={copy.dominantColors} />
          <div className="flex h-7 overflow-hidden rounded-md border" style={{ borderColor: 'var(--border)' }}>
            {asset.dominantColors.map((value) => <span key={value} title={value} className="min-w-0 flex-1" style={{ backgroundColor: value }} />)}
          </div>
        </div>}

        {/* 文件信息 */}
        <dl className="grid grid-cols-[80px_1fr] gap-x-3 gap-y-2 border-t pt-4 text-[11px]" style={{ borderColor: 'var(--border)' }}>
          {isPhoto && <><dt style={{ color: 'var(--muted-foreground)' }}>{copy.dimensions}</dt><dd>{asset.width && asset.height ? `${asset.width} \u00d7 ${asset.height}` : '\u2014'}</dd></>}
          <dt style={{ color: 'var(--muted-foreground)' }}>{copy.format}</dt><dd className="uppercase">{asset.format}</dd>
          <dt style={{ color: 'var(--muted-foreground)' }}>{copy.fileSize}</dt><dd>{formatBytes(asset.byteSize)}</dd>
          {isPhoto && <><dt style={{ color: 'var(--muted-foreground)' }}>{copy.captured}</dt><dd>{formatDate(asset.capturedAt)}</dd></>}
          <dt style={{ color: 'var(--muted-foreground)' }}>{copy.modified}</dt><dd>{formatDate(asset.modifiedAtNs)}</dd>
          <dt style={{ color: 'var(--muted-foreground)' }}>{copy.originalPath}</dt><dd className="break-all font-mono text-[10px]">{asset.relativePath}</dd>
        </dl>

        {/* 操作 */}
        <div className="space-y-2 border-t pt-4" style={{ borderColor: 'var(--border)' }}>
          {missing ? (
            <>
              <button type="button" disabled={maintenanceBusy} onClick={() => onRecheckMissing(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs hover:bg-secondary disabled:cursor-wait disabled:opacity-50"><RefreshCw size={14} className={maintenanceBusy ? 'animate-spin' : ''} />{copy.recheckMissing}</button>
              <button type="button" disabled={maintenanceBusy} onClick={() => onRemoveMissing(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs text-destructive hover:bg-secondary disabled:opacity-50"><Trash2 size={14} />{copy.removeMissingRecord}</button>
            </>
          ) : (
            <>
              {asset.availability === 'active' && unavailable && isPhoto && (
                <button type="button" disabled={maintenanceBusy} onClick={() => onRetryPreview(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs hover:bg-secondary disabled:cursor-wait disabled:opacity-50"><RefreshCw size={14} className={maintenanceBusy ? 'animate-spin' : ''} />{copy.retryPreview}</button>
              )}
              {trashed ? (
                <>
                  <button type="button" onClick={() => onRestore(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs hover:bg-secondary"><RotateCcw size={14} />{copy.restoreTrashedAsset}</button>
                  <button type="button" onClick={() => onDelete(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs text-destructive hover:bg-secondary"><Trash2 size={14} />{copy.permanentTrashedAsset}</button>
                </>
              ) : (
                <>
                  <button type="button" onClick={() => onOpenSystem(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs hover:bg-secondary"><ExternalLink size={14} />{copy.openSystem}</button>
                  <button type="button" onClick={() => onMove(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs hover:bg-secondary"><FolderInput size={14} />{copy.moveAssetsToFolder}</button>
                  <button type="button" onClick={() => onDelete(asset)} className="flex w-full items-center gap-2 rounded-md border px-3 py-2 text-xs text-destructive hover:bg-secondary"><Trash2 size={14} />{copy.delete}</button>
                </>
              )}
            </>
          )}
        </div>
      </div>
    </aside>
  )
}

import { useEffect, useMemo, useState } from 'react'
import type { ReactNode } from 'react'
import { Check, Filter, X } from 'lucide-react'
import type { AssetStructuredFilters } from './types'
import type { LocalLibraryCopy } from './copy'

interface Props {
  copy: LocalLibraryCopy
  filters: AssetStructuredFilters
  onChange: (filters: AssetStructuredFilters) => void
  onClear: () => void
}

type FilterKey = keyof AssetStructuredFilters

const COLORS = ['red', 'yellow', 'green', 'blue', 'purple'] as const
const FORMATS = ['jpeg', 'png', 'gif', 'webp', 'tiff', 'heif', 'avif', 'cr2', 'cr3', 'nef', 'arw', 'dng', 'raf', 'rw2']

function numberValue(value: string) {
  if (value.trim() === '') return undefined
  const parsed = Number(value)
  return Number.isFinite(parsed) ? parsed : undefined
}

function dateInputValue(value?: number) {
  if (value === undefined) return ''
  const date = new Date(value)
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, '0')
  const day = String(date.getDate()).padStart(2, '0')
  return `${year}-${month}-${day}`
}

function dateMilliseconds(value: string, endOfDay = false) {
  if (!value) return undefined
  const timestamp = new Date(`${value}T00:00:00`).getTime()
  return Number.isFinite(timestamp) ? timestamp + (endOfDay ? 86_399_999 : 0) : undefined
}

function activeCount(filters: AssetStructuredFilters) {
  const { photosOnly: _photosOnly, ...rest } = filters
  return Object.values(rest).filter((value) => Array.isArray(value) ? value.length > 0 : value !== undefined).length
}

function toggleValue(values: string[] | undefined, value: string) {
  const current = values ?? []
  return current.includes(value) ? current.filter((item) => item !== value) : [...current, value]
}

function TextListInput({ value, placeholder, onCommit }: { value?: string[], placeholder: string, onCommit: (value: string[] | undefined) => void }) {
  const [text, setText] = useState((value ?? []).join(', '))
  useEffect(() => setText((value ?? []).join(', ')), [value])
  return <input value={text} placeholder={placeholder} onChange={(event) => setText(event.target.value)} onBlur={() => {
    const next = [...new Set(text.split(/[,?]/).map((item) => item.trim()).filter(Boolean))]
    onCommit(next.length ? next : undefined)
  }} className="h-8 w-full rounded-md border bg-input px-2 text-xs outline-none focus:ring-1" />
}

export function LocalAssetFilters({ copy, filters, onChange, onClear }: Props) {
  const [open, setOpen] = useState(false)
  const count = activeCount(filters)

  useEffect(() => {
    if (!open) return
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }
    window.addEventListener('keydown', onKeyDown)
    return () => window.removeEventListener('keydown', onKeyDown)
  }, [open])

  const update = <K extends FilterKey>(key: K, value: AssetStructuredFilters[K]) => {
    const next = { ...filters, [key]: value }
    if (value === undefined || (Array.isArray(value) && value.length === 0)) delete next[key]
    onChange(next)
  }
  const removeMany = (...keys: FilterKey[]) => {
    const next = { ...filters }
    keys.forEach((key) => delete next[key])
    onChange(next)
  }

  const chips = useMemo(() => {
    const result: Array<{ key: string, label: string, remove: () => void }> = []
    const range = (key: string, label: string, minKey: FilterKey, maxKey: FilterKey, suffix = '') => {
      const min = filters[minKey] as number | undefined
      const max = filters[maxKey] as number | undefined
      if (min !== undefined || max !== undefined) result.push({ key, label: `${label}: ${min ?? '?'}?${max ?? '?'}${suffix}`, remove: () => removeMany(minKey, maxKey) })
    }
    range('rating', copy.filterRating, 'ratingMin', 'ratingMax')
    if (filters.colorLabels?.length) result.push({ key: 'colors', label: `${copy.filterColor}: ${filters.colorLabels.join('/')}`, remove: () => update('colorLabels', undefined) })
    if (filters.formats?.length) result.push({ key: 'formats', label: `${copy.filterFormat}: ${filters.formats.join('/')}`, remove: () => update('formats', undefined) })
    if (filters.capturedFromMs !== undefined || filters.capturedToMs !== undefined) result.push({ key: 'captured', label: copy.filterCapturedDate, remove: () => removeMany('capturedFromMs', 'capturedToMs') })
    if (filters.discoveredFromMs !== undefined || filters.discoveredToMs !== undefined) result.push({ key: 'discovered', label: copy.filterDiscoveredDate, remove: () => removeMany('discoveredFromMs', 'discoveredToMs') })
    if (filters.cameraMakes?.length) result.push({ key: 'make', label: `${copy.filterCameraMake}: ${filters.cameraMakes.join('/')}`, remove: () => update('cameraMakes', undefined) })
    if (filters.cameraModels?.length) result.push({ key: 'model', label: `${copy.filterCameraModel}: ${filters.cameraModels.join('/')}`, remove: () => update('cameraModels', undefined) })
    if (filters.lensModels?.length) result.push({ key: 'lens', label: `${copy.filterLens}: ${filters.lensModels.join('/')}`, remove: () => update('lensModels', undefined) })
    return result
  }, [copy, filters]) // callback closures intentionally track current filters

  return (
    <>
      <button
        type="button"
        onClick={() => setOpen(true)}
        aria-haspopup="dialog"
        aria-expanded={open}
        title={copy.filters}
        aria-label={copy.filters}
        className="relative flex h-8 w-8 shrink-0 items-center justify-center rounded-md border bg-input hover:bg-secondary"
      >
        <Filter size={13} />
        {count > 0 && (
          <span className="absolute -right-1.5 -top-1.5 flex h-3.5 min-w-3.5 items-center justify-center rounded-full bg-primary px-1 text-[8px] font-medium text-primary-foreground">
            {count}
          </span>
        )}
      </button>
      {open && (
        <div className="fixed inset-0 z-[130] flex items-center justify-center p-5">
          <button type="button" aria-label={copy.closeFilters} className="absolute inset-0 bg-black/55 backdrop-blur-sm" onClick={() => setOpen(false)} />
          <div role="dialog" aria-modal="true" aria-labelledby="local-library-filters-title" className="relative flex max-h-[86vh] w-full max-w-3xl flex-col rounded-xl border bg-background shadow-2xl">
            <div className="flex items-start justify-between gap-4 border-b px-5 py-4" style={{ borderColor: 'var(--border)' }}>
              <div>
                <h2 id="local-library-filters-title" className="text-sm font-semibold">{copy.filters}</h2>
                <p className="mt-0.5 text-[10px]" style={{ color: 'var(--muted-foreground)' }}>{copy.filterLogicHint}</p>
              </div>
              <button type="button" onClick={() => setOpen(false)} aria-label={copy.closeFilters} className="rounded-md p-1.5 hover:bg-secondary"><X size={15} /></button>
            </div>
            {chips.length > 0 && (
              <div className="flex flex-wrap gap-1.5 border-b px-5 py-3" style={{ borderColor: 'var(--border)' }}>
                {chips.map((chip) => <button key={chip.key} type="button" onClick={chip.remove} className="flex items-center gap-1 rounded-full border px-2 py-1 text-[10px] hover:bg-secondary">{chip.label}<X size={10} /></button>)}
              </div>
            )}
            <div className="custom-scrollbar grid min-h-0 flex-1 grid-cols-2 gap-x-5 gap-y-4 overflow-y-auto p-5">
            <label className="col-span-2 flex cursor-pointer items-center gap-2 text-[11px]">
              <input type="checkbox" checked={filters.photosOnly !== false} onChange={(event) => update('photosOnly', event.target.checked)} />
              {copy.photosOnly}
            </label>
            <FilterSection title={copy.filterRating}>
              <RangeInputs min={filters.ratingMin} max={filters.ratingMax} minLimit={0} maxLimit={5} onMin={(value) => update('ratingMin', value)} onMax={(value) => update('ratingMax', value)} />
            </FilterSection>
            <FilterSection title={copy.filterColor}>
              <div className="flex flex-wrap gap-2">
                {COLORS.map((color) => {
                  const active = filters.colorLabels?.includes(color) ?? false
                  return (
                    <button
                      key={color}
                      type="button"
                      onClick={() => update('colorLabels', toggleValue(filters.colorLabels, color))}
                      title={copy[color]}
                      aria-label={copy[color]}
                      aria-pressed={active}
                      className="relative h-6 w-6 rounded-full border transition-transform hover:scale-110"
                      style={{
                        backgroundColor: color,
                        borderColor: active ? 'var(--foreground)' : 'var(--border)',
                        boxShadow: active ? '0 0 0 2px var(--background), 0 0 0 4px var(--foreground)' : undefined,
                      }}
                    >
                      {active && <Check size={13} className="absolute inset-0 m-auto" style={{ color: 'white', filter: 'drop-shadow(0 0 1.5px rgba(0,0,0,0.9))' }} />}
                    </button>
                  )
                })}
              </div>
            </FilterSection>
            <FilterSection title={copy.filterFormat}>
              <div className="flex flex-wrap gap-1">{FORMATS.map((format) => <Toggle key={format} active={filters.formats?.includes(format) ?? false} onClick={() => update('formats', toggleValue(filters.formats, format))}>{format.toUpperCase()}</Toggle>)}</div>
            </FilterSection>
            <FilterSection title={copy.filterCapturedDate}>
              <DateRange from={filters.capturedFromMs} to={filters.capturedToMs} copy={copy} onFrom={(value) => update('capturedFromMs', value)} onTo={(value) => update('capturedToMs', value)} />
            </FilterSection>
            <FilterSection title={copy.filterDiscoveredDate}>
              <DateRange from={filters.discoveredFromMs} to={filters.discoveredToMs} copy={copy} onFrom={(value) => update('discoveredFromMs', value)} onTo={(value) => update('discoveredToMs', value)} />
            </FilterSection>
            <FilterSection title={copy.filterCamera}>
              <div className="space-y-2"><TextListInput value={filters.cameraMakes} placeholder={copy.filterCameraMake} onCommit={(value) => update('cameraMakes', value)} /><TextListInput value={filters.cameraModels} placeholder={copy.filterCameraModel} onCommit={(value) => update('cameraModels', value)} /><TextListInput value={filters.lensModels} placeholder={copy.filterLens} onCommit={(value) => update('lensModels', value)} /></div>
            </FilterSection>
            </div>
            <div className="flex items-center justify-between gap-3 border-t px-5 py-3" style={{ borderColor: 'var(--border)' }}>
              <button type="button" disabled={count === 0} onClick={onClear} className="flex items-center gap-1 rounded-md border px-3 py-1.5 text-[10px] hover:bg-secondary disabled:opacity-40"><X size={11} />{copy.clearFilters}</button>
              <button type="button" onClick={() => setOpen(false)} className="rounded-md bg-primary px-4 py-1.5 text-[10px] font-medium text-primary-foreground hover:opacity-90">{copy.filterDone}</button>
            </div>
          </div>
        </div>
      )}
    </>
  )
}

function FilterSection({ title, children }: { title: string, children: ReactNode }) {
  return <section><h3 className="mb-2 text-[11px] font-medium">{title}</h3>{children}</section>
}

function Toggle({ active, onClick, children }: { active: boolean, onClick: () => void, children: ReactNode }) {
  return <button type="button" onClick={onClick} className="rounded-md border px-2 py-1 text-[10px]" style={{ backgroundColor: active ? 'var(--accent)' : undefined, borderColor: active ? 'var(--primary)' : 'var(--border)' }}>{children}</button>
}

function RangeInputs({ min, max, minLimit, maxLimit, step, onMin, onMax }: { min?: number, max?: number, minLimit?: number, maxLimit?: number, step?: string, onMin: (value?: number) => void, onMax: (value?: number) => void }) {
  return <div className="grid grid-cols-[1fr_auto_1fr] items-center gap-2"><input type="number" value={min ?? ''} min={minLimit} max={maxLimit} step={step} placeholder="Min" onChange={(event) => onMin(numberValue(event.target.value))} className="h-8 min-w-0 rounded-md border bg-input px-2 text-xs" /><span className="text-xs" style={{ color: 'var(--muted-foreground)' }}>?</span><input type="number" value={max ?? ''} min={minLimit} max={maxLimit} step={step} placeholder="Max" onChange={(event) => onMax(numberValue(event.target.value))} className="h-8 min-w-0 rounded-md border bg-input px-2 text-xs" /></div>
}

function DateRange({ from, to, copy, onFrom, onTo }: { from?: number, to?: number, copy: LocalLibraryCopy, onFrom: (value?: number) => void, onTo: (value?: number) => void }) {
  return <div className="grid grid-cols-2 gap-2"><label className="text-[9px]" style={{ color: 'var(--muted-foreground)' }}>{copy.from}<input type="date" value={dateInputValue(from)} onChange={(event) => onFrom(dateMilliseconds(event.target.value))} className="mt-1 h-8 w-full rounded-md border bg-input px-2 text-xs" /></label><label className="text-[9px]" style={{ color: 'var(--muted-foreground)' }}>{copy.to}<input type="date" value={dateInputValue(to)} onChange={(event) => onTo(dateMilliseconds(event.target.value, true))} className="mt-1 h-8 w-full rounded-md border bg-input px-2 text-xs" /></label></div>
}

