export { normalizeSnapshot }

const CACHE_PREFIX = 'mo-gallery:desktop-cache'
const CACHE_SCHEMA_VERSION = 2

export type PersistentCacheResource =
  | 'overview'
  | 'equipment-camera'
  | 'equipment-lens'
  | 'albums'
  | 'categories'
  | 'film-rolls'
  | 'stories'
  | 'friends'

interface PersistentCacheRecord<T> {
  schemaVersion: number
  savedAt: number
  data: T
}

export const PERSISTENT_CACHE_TTL_MS: Record<PersistentCacheResource, number> = {
  overview: 2 * 60 * 1000,
  'equipment-camera': 30 * 60 * 1000,
  'equipment-lens': 30 * 60 * 1000,
  albums: 10 * 60 * 1000,
  categories: 24 * 60 * 60 * 1000,
  'film-rolls': 10 * 60 * 1000,
  stories: 10 * 60 * 1000,
  friends: 10 * 60 * 1000,
}

export interface PersistentCacheEntry<T> {
  data: T
  savedAt: number
  fresh: boolean
}

interface InFlightLoad<T = unknown> {
  generation: number
  globalGeneration: number
  promise: Promise<T>
}

const inFlightLoads = new Map<string, InFlightLoad>()
const resourceGenerations = new Map<string, number>()
let globalGeneration = 0
let legacyCleanupAttempted = false

function getStorage(): Storage | null {
  if (typeof window === 'undefined') return null
  try {
    const storage = window.localStorage
    if (!legacyCleanupAttempted) {
      legacyCleanupAttempted = true
      const currentPrefix = `${CACHE_PREFIX}:v${CACHE_SCHEMA_VERSION}:`
      const legacyKeys: string[] = []
      for (let index = 0; index < storage.length; index += 1) {
        const key = storage.key(index)
        if (key?.startsWith(`${CACHE_PREFIX}:`) && !key.startsWith(currentPrefix)) legacyKeys.push(key)
      }
      for (const key of legacyKeys) storage.removeItem(key)
    }
    return storage
  } catch {
    return null
  }
}

function normalizeScopePart(value: string) {
  return encodeURIComponent(value.trim().toLowerCase())
}

function currentScope(storage = getStorage()) {
  if (!storage) return null

  try {
    const server = storage.getItem('mo-gallery-server')?.replace(/\/+$/, '')
    const rawUser = storage.getItem('mo-gallery-user')
    if (!server || !rawUser) return null

    const user = JSON.parse(rawUser) as { id?: string; username?: string }
    const identity = user.id || user.username
    if (!identity) return null
    return `${normalizeScopePart(server)}:${normalizeScopePart(identity)}`
  } catch {
    return null
  }
}

export function getCurrentPersistentCacheScope() {
  return currentScope()
}

function resourceKey(resource: PersistentCacheResource) {
  const scope = currentScope()
  return scope ? `${CACHE_PREFIX}:v${CACHE_SCHEMA_VERSION}:${scope}:${resource}` : null
}

function generationKey(resource: PersistentCacheResource, key: string | null) {
  return key ?? `volatile:${resource}`
}

function getGeneration(key: string) {
  return resourceGenerations.get(key) ?? 0
}

function invalidateGeneration(key: string) {
  resourceGenerations.set(key, getGeneration(key) + 1)
  inFlightLoads.delete(key)
}

function safelyRemove(storage: Storage, key: string) {
  try {
    storage.removeItem(key)
  } catch {
    // Cache cleanup is best effort when storage access is restricted.
  }
}

export function getPersistentCache<T>(resource: PersistentCacheResource): PersistentCacheEntry<T> | null {
  const storage = getStorage()
  const key = resourceKey(resource)
  if (!storage || !key) return null

  try {
    const raw = storage.getItem(key)
    if (!raw) return null
    const record = JSON.parse(raw) as PersistentCacheRecord<T>
    if (record.schemaVersion !== CACHE_SCHEMA_VERSION || typeof record.savedAt !== 'number') {
      safelyRemove(storage, key)
      return null
    }
    return {
      data: record.data,
      savedAt: record.savedAt,
      fresh: Date.now() - record.savedAt <= PERSISTENT_CACHE_TTL_MS[resource],
    }
  } catch {
    safelyRemove(storage, key)
    return null
  }
}

function projectPersistentData<T>(resource: PersistentCacheResource, data: T): T {
  if (!Array.isArray(data)) return data

  if (resource === 'albums') {
    return data.map((value) => {
      const album = value as Record<string, unknown>
      return {
        id: album.id,
        name: album.name,
        description: album.description,
        coverUrl: album.coverUrl,
        location: album.location,
        isPublished: album.isPublished,
        sortOrder: album.sortOrder,
        photoCount: album.photoCount,
        createdAt: album.createdAt,
        updatedAt: album.updatedAt,
      }
    }) as T
  }

  if (resource === 'stories') {
    return data.map((value) => {
      const story = value as Record<string, unknown>
      const photos = Array.isArray(story.photos) ? story.photos : []
      return {
        id: story.id,
        title: story.title,
        coverPhotoId: story.coverPhotoId,
        coverCrop: story.coverCrop,
        isPublished: story.isPublished,
        storyDate: story.storyDate,
        createdAt: story.createdAt,
        updatedAt: story.updatedAt,
        photoCount: story.photoCount ?? photos.length,
      }
    }) as T
  }

  if (resource === 'film-rolls') {
    return data.map((value) => {
      const {
        photos: _photos,
        filmPhotos: _filmPhotos,
        ...filmRoll
      } = value as Record<string, unknown>
      return filmRoll
    }) as T
  }

  return data
}

function setPersistentCacheByKey<T>(resource: PersistentCacheResource, key: string | null, data: T) {
  const storage = getStorage()
  if (!storage || !key) return

  try {
    const record: PersistentCacheRecord<T> = {
      schemaVersion: CACHE_SCHEMA_VERSION,
      savedAt: Date.now(),
      data: projectPersistentData(resource, data),
    }
    storage.setItem(key, JSON.stringify(record))
  } catch {
    // Cache writes are best effort. Quota/privacy errors must not break the page.
  }
}

export function setPersistentCache<T>(resource: PersistentCacheResource, data: T) {
  setPersistentCacheByKey(resource, resourceKey(resource), data)
}

export function clearCurrentPersistentCache(resources?: PersistentCacheResource[]) {
  const storage = getStorage()
  const scope = currentScope(storage)
  if (!storage || !scope) return

  const targets = resources ?? (Object.keys(PERSISTENT_CACHE_TTL_MS) as PersistentCacheResource[])
  for (const resource of targets) {
    const key = `${CACHE_PREFIX}:v${CACHE_SCHEMA_VERSION}:${scope}:${resource}`
    invalidateGeneration(key)
    safelyRemove(storage, key)
  }
}

export function clearPersistentCache(resources?: PersistentCacheResource[]) {
  if (resources) {
    clearCurrentPersistentCache(resources)
    return
  }

  globalGeneration += 1
  inFlightLoads.clear()

  const storage = getStorage()
  if (!storage) return

  try {
    const prefix = `${CACHE_PREFIX}:`
    const keys: string[] = []
    for (let index = 0; index < storage.length; index += 1) {
      const key = storage.key(index)
      if (key?.startsWith(prefix)) keys.push(key)
    }
    for (const key of keys) safelyRemove(storage, key)
  } catch {
    // Cache cleanup is best effort when storage enumeration is restricted.
  }
}

export function getPersistentCacheSnapshot() {
  const storage = getStorage()
  if (!storage) return { resourceCount: 0, bytes: 0 }

  const resources = Object.keys(PERSISTENT_CACHE_TTL_MS) as PersistentCacheResource[]
  let resourceCount = 0
  let bytes = 0

  try {
    for (const resource of resources) {
      const key = resourceKey(resource)
      if (!key) continue
      const value = storage.getItem(key)
      if (!value) continue
      resourceCount += 1
      bytes += new Blob([value]).size
    }
  } catch {
    return { resourceCount: 0, bytes: 0 }
  }

  return { resourceCount, bytes }
}

export async function loadPersistentResource<T>(
  resource: PersistentCacheResource,
  loader: () => Promise<T>,
  options: { force?: boolean; allowStaleOnError?: boolean } = {},
): Promise<T> {
  const key = resourceKey(resource)
  const cached = getPersistentCache<T>(resource)
  if (!options.force && cached?.fresh) return cached.data

  const inFlightKey = generationKey(resource, key)
  if (options.force) invalidateGeneration(inFlightKey)

  const generation = getGeneration(inFlightKey)
  const capturedGlobalGeneration = globalGeneration
  const existing = inFlightLoads.get(inFlightKey) as InFlightLoad<T> | undefined
  if (
    existing
    && existing.generation === generation
    && existing.globalGeneration === capturedGlobalGeneration
  ) return existing.promise

  let request: Promise<T>
  request = loader()
    .then((data) => {
      if (
        getGeneration(inFlightKey) === generation
        && globalGeneration === capturedGlobalGeneration
      ) setPersistentCacheByKey(resource, key, data)
      return data
    })
    .catch((error) => {
      if (
        options.allowStaleOnError !== false
        && cached
        && getGeneration(inFlightKey) === generation
        && globalGeneration === capturedGlobalGeneration
      ) return cached.data
      throw error
    })
    .finally(() => {
      const active = inFlightLoads.get(inFlightKey)
      if (active?.promise === request) inFlightLoads.delete(inFlightKey)
    })

  inFlightLoads.set(inFlightKey, {
    generation,
    globalGeneration: capturedGlobalGeneration,
    promise: request,
  })
  return request
}

/**
 * Privacy Strip Utility
 * 
 * Removes GPS/location data from images before upload.
 * This utility preserves other EXIF data like camera settings, date taken, etc.
 */

// GPS-related EXIF tags to remove (IFD GPS tags)
const GPS_TAGS_TO_REMOVE = [
  'GPSVersionID',
  'GPSLatitudeRef',
  'GPSLatitude',
  'GPSLongitudeRef',
  'GPSLongitude',
  'GPSAltitudeRef',
  'GPSAltitude',
  'GPSTimeStamp',
  'GPSSatellites',
  'GPSStatus',
  'GPSMeasureMode',
  'GPSDOP',
  'GPSSpeedRef',
  'GPSSpeed',
  'GPSTrackRef',
  'GPSTrack',
  'GPSImgDirectionRef',
  'GPSImgDirection',
  'GPSMapDatum',
  'GPSDestLatitudeRef',
  'GPSDestLatitude',
  'GPSDestLongitudeRef',
  'GPSDestLongitude',
  'GPSDestBearingRef',
  'GPSDestBearing',
  'GPSDestDistanceRef',
  'GPSDestDistance',
  'GPSProcessingMethod',
  'GPSAreaInformation',
  'GPSDateStamp',
  'GPSDifferential',
  'GPSHPositioningError',
]

/**
 * Strips GPS/location data from a JPEG image while preserving other EXIF data.
 * For non-JPEG images, returns the original file unchanged.
 * 
 * @param file - The image file to process
 * @returns A new File with GPS data removed (for JPEG) or the original file
 */
export async function stripGpsData(file: File): Promise<File> {
  // Only process JPEG images (EXIF is primarily in JPEG)
  if (!file.type.includes('jpeg') && !file.type.includes('jpg')) {
    return file
  }

  try {
    const arrayBuffer = await file.arrayBuffer()
    const dataView = new DataView(arrayBuffer)
    
    // Check for JPEG magic number
    if (dataView.getUint16(0) !== 0xFFD8) {
      return file
    }

    // Find and process EXIF data
    const strippedBuffer = await removeGpsFromJpeg(arrayBuffer)
    
    if (strippedBuffer) {
      return new File([strippedBuffer], file.name, {
        type: file.type,
        lastModified: Date.now(),
      })
    }
    
    return file
  } catch (error) {
    console.warn('Failed to strip GPS data, returning original file:', error)
    return file
  }
}

/**
 * Removes GPS IFD from JPEG EXIF data
 */
async function removeGpsFromJpeg(buffer: ArrayBuffer): Promise<ArrayBuffer | null> {
  const data = new Uint8Array(buffer)
  let offset = 2 // Skip SOI marker
  
  while (offset < data.length - 1) {
    // Check for marker
    if (data[offset] !== 0xFF) {
      offset++
      continue
    }
    
    const marker = data[offset + 1]
    
    // End of image
    if (marker === 0xD9) break
    
    // APP1 marker (EXIF)
    if (marker === 0xE1) {
      const segmentLength = (data[offset + 2] << 8) | data[offset + 3]
      
      // Check for "Exif\0\0" identifier
      if (
        data[offset + 4] === 0x45 && // E
        data[offset + 5] === 0x78 && // x
        data[offset + 6] === 0x69 && // i
        data[offset + 7] === 0x66 && // f
        data[offset + 8] === 0x00 &&
        data[offset + 9] === 0x00
      ) {
        // Found EXIF segment, process it
        const exifStart = offset + 10 // Start of TIFF header
        const processedExif = processExifSegment(data, exifStart, segmentLength - 8)
        
        if (processedExif) {
          // Rebuild the JPEG with modified EXIF
          const newBuffer = new Uint8Array(buffer.byteLength)
          
          // Copy everything before EXIF segment
          newBuffer.set(data.subarray(0, offset + 4), 0)
          
          // Write "Exif\0\0"
          newBuffer.set([0x45, 0x78, 0x69, 0x66, 0x00, 0x00], offset + 4)
          
          // Write processed EXIF
          newBuffer.set(processedExif, offset + 10)
          
          // Update segment length
          const newSegmentLength = processedExif.length + 8
          newBuffer[offset + 2] = (newSegmentLength >> 8) & 0xFF
          newBuffer[offset + 3] = newSegmentLength & 0xFF
          
          // Copy rest of the file
          const restStart = offset + 2 + segmentLength
          const newRestStart = offset + 10 + processedExif.length
          newBuffer.set(data.subarray(restStart), newRestStart)
          
          // Trim to actual size
          const actualSize = newRestStart + (data.length - restStart)
          return newBuffer.buffer.slice(0, actualSize)
        }
      }
    }
    
    // Skip to next marker
    if (marker >= 0xD0 && marker <= 0xD9) {
      // Standalone markers (RST, SOI, EOI)
      offset += 2
    } else {
      // Markers with length
      const length = (data[offset + 2] << 8) | data[offset + 3]
      offset += 2 + length
    }
  }
  
  return null
}

/**
 * Process EXIF segment to remove GPS IFD
 */
function processExifSegment(
  data: Uint8Array,
  exifStart: number,
  exifLength: number
): Uint8Array | null {
  try {
    // Copy EXIF data to work with
    const exifData = data.slice(exifStart, exifStart + exifLength)
    const view = new DataView(exifData.buffer, exifData.byteOffset, exifData.byteLength)
    
    // Determine byte order
    const byteOrder = view.getUint16(0)
    const littleEndian = byteOrder === 0x4949 // "II" = Intel = little endian
    
    // Verify TIFF magic number
    if (view.getUint16(2, littleEndian) !== 0x002A) {
      return null
    }
    
    // Get IFD0 offset
    const ifd0Offset = view.getUint32(4, littleEndian)
    
    // Process IFD0 to find and nullify GPS IFD pointer
    const numEntries = view.getUint16(ifd0Offset, littleEndian)
    
    for (let i = 0; i < numEntries; i++) {
      const entryOffset = ifd0Offset + 2 + i * 12
      const tag = view.getUint16(entryOffset, littleEndian)
      
      // GPS IFD Pointer tag (0x8825)
      if (tag === 0x8825) {
        // Zero out the GPS IFD pointer value
        // This effectively removes the GPS data reference
        view.setUint32(entryOffset + 8, 0, littleEndian)
        
        // Also zero out the GPS IFD data if we can find it
        const gpsIfdOffset = view.getUint32(entryOffset + 8, littleEndian)
        if (gpsIfdOffset > 0 && gpsIfdOffset < exifData.length - 2) {
          const gpsNumEntries = view.getUint16(gpsIfdOffset, littleEndian)
          // Zero out GPS IFD entries
          for (let j = 0; j < gpsNumEntries && gpsIfdOffset + 2 + j * 12 + 12 <= exifData.length; j++) {
            const gpsEntryOffset = gpsIfdOffset + 2 + j * 12
            // Zero out each GPS entry
            for (let k = 0; k < 12; k++) {
              exifData[gpsEntryOffset + k] = 0
            }
          }
        }
        
        break
      }
    }
    
    return exifData
  } catch (error) {
    console.warn('Error processing EXIF segment:', error)
    return null
  }
}

/**
 * Strips GPS data from multiple files
 * 
 * @param files - Array of files to process
 * @param onProgress - Optional progress callback
 * @returns Array of processed files
 */
export async function stripGpsDataBatch(
  files: File[],
  onProgress?: (current: number, total: number) => void
): Promise<File[]> {
  const results: File[] = []
  
  for (let i = 0; i < files.length; i++) {
    results.push(await stripGpsData(files[i]))
    onProgress?.(i + 1, files.length)
  }
  
  return results
}

/**
 * Check if a file likely contains GPS data
 * This is a quick check, not a full parse
 * 
 * @param file - The file to check
 * @returns true if GPS data might be present
 */
export async function mightContainGpsData(file: File): Promise<boolean> {
  if (!file.type.includes('jpeg') && !file.type.includes('jpg')) {
    return false
  }

  try {
    // Read first 64KB which should contain EXIF
    const slice = file.slice(0, 65536)
    const buffer = await slice.arrayBuffer()
    const data = new Uint8Array(buffer)
    
    // Look for GPS IFD tag (0x8825) in the data
    // This is a simplified check
    for (let i = 0; i < data.length - 1; i++) {
      // Check for GPS IFD tag in both byte orders
      if ((data[i] === 0x88 && data[i + 1] === 0x25) ||
          (data[i] === 0x25 && data[i + 1] === 0x88)) {
        return true
      }
    }
    
    return false
  } catch {
    return false
  }
}

