}

function appApi(): AlbumAppAPI {
  const bridge = (window as unknown as { go?: { main?: { App?: AlbumAppAPI } } }).go?.main?.App
  if (!bridge) throw new Error('Wails API is not available')
  return bridge
}

function errorMessage(error: unknown, fallback: string) {
  return error instanceof Error && error.message ? error.message : fallback
}

function inputStyle(): CSSProperties {
  return {
    borderColor: 'var(--border)',
    backgroundColor: 'var(--background)',
    color: 'var(--foreground)',
  }
}

function normalizeAlbum(album: Album): Album {
  const photos = album.photos ?? []
  return {
    ...album,
    description: album.description ?? '',
    coverUrl: album.coverUrl ?? '',
    location: album.location ?? '',
    photos,
    photoCount: album.photoCount ?? photos.length,
  }
}

function newDraftAlbum(sortOrder: number): Album {
  const now = new Date().toISOString()
  return {
    id: '',
    name: '',
    description: '',
    coverUrl: '',
    location: '',
    isPublished: false,
    sortOrder,
    photoCount: 0,
    photos: [],
    createdAt: now,
    updatedAt: now,
  }
}

function isCoverPhoto(album: Album, photo: Photo) {
  if (!album.coverUrl) return false
  const coverUrl = resolveAssetUrl(album.coverUrl)
  return [photo.url, photo.thumbnailUrl]
    .filter((url): url is string => Boolean(url))
    .some(url => resolveAssetUrl(url) === coverUrl)
}

interface AlbumsPageProps {
  initialAlbumId?: string | null
  initialTab?: DetailTab
  createMode?: boolean
  onBackToBrowser?: () => void
  onAlbumsChanged?: () => void
}

export function AlbumsPage({
  initialAlbumId = null,
  initialTab = 'photos',
  createMode = false,
  onBackToBrowser,
  onAlbumsChanged,
}: AlbumsPageProps = {}) {
  const { language } = usePreferences()
  const [albums, setAlbums] = useState<Album[]>([])
  const [photos, setPhotos] = useState<Photo[]>([])
  const [loading, setLoading] = useState(true)
  const [loadingCurrentAlbum, setLoadingCurrentAlbum] = useState(false)
  const [saving, setSaving] = useState(false)
  const [currentAlbum, setCurrentAlbum] = useState<Album | null>(null)
  const [activeTab, setActiveTab] = useState<DetailTab>('overview')
  const [showPhotoSelector, setShowPhotoSelector] = useState(false)
  const [selectedPhotoIds, setSelectedPhotoIds] = useState<Set<string>>(new Set())
  const [photoSelectorSearch, setPhotoSelectorSearch] = useState('')
  const currentAlbumRequestIdRef = useRef(0)
  const handledExternalIntentRef = useRef('')

  const fetchAlbums = useCallback(async (force = false) => {
    setLoading(true)
    try {
      const result = await loadPersistentResource('albums', () => appApi().GetAlbums(), { force })
      setAlbums((result ?? []).map(normalizeAlbum))
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    } finally {
      setLoading(false)
    }
  }, [language])

  const fetchPhotos = useCallback(async () => {
    try {
      setPhotos(await appApi().GetAllPhotos())
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    }
  }, [language])

  useEffect(() => {
    void fetchAlbums()
    void fetchPhotos()
  }, [fetchAlbums, fetchPhotos])

  const openAlbum = useCallback(async (album: Album, tab: DetailTab = 'photos') => {
    const requestId = ++currentAlbumRequestIdRef.current
    setCurrentAlbum(normalizeAlbum(album))
    setActiveTab(tab)
    setShowPhotoSelector(false)
    setSelectedPhotoIds(new Set())
    setPhotoSelectorSearch('')
    setLoadingCurrentAlbum(true)

    try {
      const fullAlbum = normalizeAlbum(await appApi().GetAlbum(album.id))
      if (requestId !== currentAlbumRequestIdRef.current) return
      setCurrentAlbum(fullAlbum)
      setAlbums(current => current.map(item => item.id === fullAlbum.id ? fullAlbum : item))
    } catch (error) {
      if (requestId !== currentAlbumRequestIdRef.current) return
      toast.error(errorMessage(error, t('common.error', language)))
    } finally {
      if (requestId === currentAlbumRequestIdRef.current) setLoadingCurrentAlbum(false)
    }
  }, [language])

  const handleCreateAlbum = useCallback(() => {
    currentAlbumRequestIdRef.current += 1
    setCurrentAlbum(newDraftAlbum(albums.length))
    setActiveTab('overview')
    setShowPhotoSelector(false)
    setSelectedPhotoIds(new Set())
    setPhotoSelectorSearch('')
    setLoadingCurrentAlbum(false)
  }, [albums.length])

  useEffect(() => {
    const intentKey = createMode ? 'create' : initialAlbumId ? `${initialAlbumId}:${initialTab}` : ''
    if (!intentKey) {
      handledExternalIntentRef.current = ''
      return
    }
    if (loading || handledExternalIntentRef.current === intentKey) return

    handledExternalIntentRef.current = intentKey
    if (createMode) {
      handleCreateAlbum()
      return
    }

    const target = albums.find(album => album.id === initialAlbumId)
    if (target) void openAlbum(target, initialTab)
  }, [albums, createMode, handleCreateAlbum, initialAlbumId, initialTab, loading, openAlbum])

  const handleBackToList = useCallback(() => {
    const isUnsavedDraft = !currentAlbum?.id && Boolean(
      currentAlbum?.name.trim() || currentAlbum?.description?.trim() || currentAlbum?.location?.trim(),
    )
    if (isUnsavedDraft && !confirm(t('admin.discard_album_confirm', language))) return
    currentAlbumRequestIdRef.current += 1
    setCurrentAlbum(null)
    if (onBackToBrowser) onBackToBrowser()
    else void fetchAlbums()
  }, [currentAlbum, fetchAlbums, language, onBackToBrowser])

  const handleSave = useCallback(async () => {
    if (!currentAlbum) return
    const name = currentAlbum.name.trim()
    if (!name) {
      toast.error(t('admin.album_name_required', language))
      return
    }

    setSaving(true)
    try {
      const payload: AlbumPayload = {
        name,
        description: currentAlbum.description?.trim() || undefined,
        coverUrl: currentAlbum.coverUrl || undefined,
        location: currentAlbum.location?.trim() || '',
        isPublished: currentAlbum.isPublished,
        sortOrder: currentAlbum.sortOrder,
      }
      const wasExisting = Boolean(currentAlbum.id)
      const saved = wasExisting
        ? await appApi().UpdateAlbum(currentAlbum.id, payload)
        : await appApi().CreateAlbum(payload)
      const fullAlbum = normalizeAlbum(await appApi().GetAlbum(saved.id))

      setCurrentAlbum(fullAlbum)
      setActiveTab('photos')
      toast.success(t(wasExisting ? 'admin.album_updated' : 'admin.album_created', language))
      await fetchAlbums(true)
      invalidateDesktopCache(['overview'])
      onAlbumsChanged?.()
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    } finally {
      setSaving(false)
    }
  }, [currentAlbum, fetchAlbums, language, onAlbumsChanged])

  const handleDelete = useCallback(async (album: Album) => {
    if (!confirm(t('admin.album_delete_confirm', language))) return
    try {
      await appApi().DeleteAlbum(album.id)
      if (currentAlbum?.id === album.id) setCurrentAlbum(null)
      toast.success(t('common.deleted', language))
      await fetchAlbums(true)
      invalidateDesktopCache(['overview', 'photos'])
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    }
  }, [currentAlbum?.id, fetchAlbums, language])

  const togglePublished = useCallback(async (album: Album) => {
    try {
      const updated = normalizeAlbum(await appApi().UpdateAlbum(album.id, { isPublished: !album.isPublished }))
      await fetchAlbums(true)
      invalidateDesktopCache(['overview'])
      if (currentAlbum?.id === updated.id) {
        setCurrentAlbum(current => current ? { ...current, isPublished: updated.isPublished } : current)
      }
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    }
  }, [currentAlbum?.id, fetchAlbums, language])

  const handleAddPhotos = useCallback(async () => {
    if (!currentAlbum?.id || selectedPhotoIds.size === 0) return
    setSaving(true)
    try {
      const updated = normalizeAlbum(await appApi().AddPhotosToAlbum(currentAlbum.id, Array.from(selectedPhotoIds)))
      setCurrentAlbum(updated)
      setSelectedPhotoIds(new Set())
      setShowPhotoSelector(false)
      setPhotoSelectorSearch('')
      await fetchAlbums(true)
      invalidateDesktopCache(['photos'])
      toast.success(t('admin.photos_added', language))
      onAlbumsChanged?.()
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    } finally {
      setSaving(false)
    }
  }, [currentAlbum?.id, fetchAlbums, language, onAlbumsChanged, selectedPhotoIds])

  const handleRemovePhoto = useCallback(async (photoId: string) => {
    if (!currentAlbum?.id) return
    try {
      const updated = normalizeAlbum(await appApi().RemovePhotoFromAlbum(currentAlbum.id, photoId))
      setCurrentAlbum(updated)
      await fetchAlbums(true)
      invalidateDesktopCache(['photos'])
      toast.success(t('admin.photo_removed', language))
      onAlbumsChanged?.()
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    }
  }, [currentAlbum?.id, fetchAlbums, language, onAlbumsChanged])

  const handleSetCover = useCallback(async (photoId: string) => {
    if (!currentAlbum?.id) return
    try {
      const updated = normalizeAlbum(await appApi().SetAlbumCover(currentAlbum.id, photoId))
      setCurrentAlbum(updated)
      await fetchAlbums(true)
      toast.success(t('admin.cover_set', language))
      onAlbumsChanged?.()
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    }
  }, [currentAlbum?.id, fetchAlbums, language, onAlbumsChanged])

  const availablePhotos = useMemo(() => {
    const currentPhotoIds = new Set(currentAlbum?.photos?.map(photo => photo.id) ?? [])
    const query = photoSelectorSearch.trim().toLowerCase()
    return photos.filter(photo => {
      if (currentPhotoIds.has(photo.id)) return false
      if (!query) return true
      return [photo.title, photo.category].some(value => value?.toLowerCase().includes(query))
    })
  }, [currentAlbum?.photos, photoSelectorSearch, photos])

  if (currentAlbum) {
    return (
      <>
        <PageHeader
          title={currentAlbum.name || t('admin.new_album', language)}
          description={`${currentAlbum.photoCount} ${t('admin.photos', language)}`}
          actions={
            <div className="flex items-center gap-2">
              <button
                onClick={handleBackToList}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md border"
                style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}
              >
                <ChevronLeft size={14} /> {t('admin.back_list', language)}
              </button>
              {activeTab === 'overview' && (
                <button
                  onClick={handleSave}
                  disabled={saving || !currentAlbum.name.trim()}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md disabled:opacity-50"
                  style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}
                >
                  {saving ? <RefreshCw size={14} className="animate-spin" /> : <Save size={14} />}
                  {t('common.save', language)}
                </button>
              )}
            </div>
          }
        />

        <div className="flex-1 overflow-auto p-6">
          <div className="flex gap-4 mb-6 border-b" style={{ borderColor: 'var(--border)' }}>
            {(['overview', 'photos'] as const).map(tab => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className="pb-2 text-sm transition-colors relative"
                style={{ color: activeTab === tab ? 'var(--foreground)' : 'var(--muted-foreground)' }}
              >
                {tab === 'overview' ? t('admin.overview', language) : t('admin.manage_photos', language)}
                {activeTab === tab && <span className="absolute bottom-0 left-0 right-0 h-0.5" style={{ backgroundColor: 'var(--primary)' }} />}
              </button>
            ))}
          </div>

          {activeTab === 'overview' ? (
            <AlbumOverview album={currentAlbum} onChange={setCurrentAlbum} language={language} autoFocus={!currentAlbum.id} />
          ) : !currentAlbum.id ? (
            <div className="flex flex-col items-center justify-center h-56 border border-dashed rounded-lg" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
              <ImageIcon size={32} className="mb-3 opacity-40" />
              <p className="text-sm mb-4">{t('admin.save_first_hint', language)}</p>
              <button onClick={handleSave} disabled={saving || !currentAlbum.name.trim()} className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md disabled:opacity-50" style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
                <Save size={14} /> {t('common.save', language)}
              </button>
            </div>
          ) : loadingCurrentAlbum ? (
            <ListSkeleton count={4} />
          ) : showPhotoSelector ? (
            <AlbumPhotoSelector
              photos={availablePhotos}
              selectedIds={selectedPhotoIds}
              search={photoSelectorSearch}
              saving={saving}
              onSearchChange={setPhotoSelectorSearch}
              onToggle={photoId => setSelectedPhotoIds(current => {
                const next = new Set(current)
                if (next.has(photoId)) next.delete(photoId)
                else next.add(photoId)
                return next
              })}
              onConfirm={handleAddPhotos}
              onClose={() => {
                setShowPhotoSelector(false)
                setSelectedPhotoIds(new Set())
                setPhotoSelectorSearch('')
              }}
              language={language}
            />
          ) : (
            <AlbumPhotos
              album={currentAlbum}
              onRemovePhoto={handleRemovePhoto}
              onSetCover={handleSetCover}
              onShowSelector={() => setShowPhotoSelector(true)}
              language={language}
            />
          )}
        </div>
      </>
    )
  }

  return (
    <>
      <PageHeader
        title={t('admin.page_albums', language)}
        description={`${albums.length} albums`}
        actions={
          <button
            onClick={handleCreateAlbum}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md"
            style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}
          >
            <Plus size={14} /> {t('admin.create_album', language)}
          </button>
        }
      />

      <div className="flex-1 overflow-auto p-6">
        {loading ? (
          <CardGridSkeleton count={8} cols={4} />
        ) : albums.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 border border-dashed rounded-lg" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
            <ImageIcon size={32} className="mb-3 opacity-40" />
            <p className="text-sm mb-4">{t('admin.no_albums', language)}</p>
            <button onClick={handleCreateAlbum} className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md border" style={{ borderColor: 'var(--border)' }}>
              <Plus size={14} /> {t('admin.create_first_album', language)}
            </button>
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
            {albums.map(album => (
              <div
                key={album.id}
                role="button"
                tabIndex={0}
                onClick={() => void openAlbum(album)}
                onKeyDown={event => {
                  if (event.key === 'Enter' || event.key === ' ') {
                    event.preventDefault()
                    void openAlbum(album)
                  }
                }}
                className="rounded-lg border overflow-hidden group cursor-pointer transition-opacity hover:opacity-90"
                style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}
              >
                <div className="aspect-video relative"
                  style={{ backgroundColor: 'var(--muted)' }}>
                  {album.coverUrl ? (
                    <img src={resolveAssetUrl(album.coverUrl)} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <div className="flex items-center justify-center h-full" style={{ color: 'var(--muted-foreground)' }}><ImageIcon size={28} /></div>
                  )}
                </div>
                <div className="p-3">
                  <div className="flex items-center justify-between mb-1">
                    <h3 className="text-sm font-medium truncate">{album.name}</h3>
                    <span className="text-xs px-1.5 py-0.5 rounded"
                      style={{
                        backgroundColor: album.isPublished ? 'var(--accent)' : 'var(--muted)',
                        color: album.isPublished ? 'var(--accent-foreground)' : 'var(--muted-foreground)',
                      }}>
                      {album.isPublished ? t('admin.albums_status_published', language) : t('admin.albums_status_draft', language)}
                    </span>
                  </div>
                  {album.location && (
                    <p className="mb-1 flex items-center gap-1 text-xs" style={{ color: 'var(--muted-foreground)' }}>
                      <MapPin size={12} className="shrink-0" />
                      <span className="truncate">{album.location}</span>
                    </p>
                  )}
                  <p className="text-xs mb-2" style={{ color: 'var(--muted-foreground)' }}>
                    {album.photoCount} {t('admin.photos', language)}
                  </p>
                  <div className="flex items-center gap-1">
                    <button onClick={event => { event.stopPropagation(); void togglePublished(album) }}
                      className="p-1 rounded hover:opacity-80" style={{ color: 'var(--muted-foreground)' }}>
                      {album.isPublished ? <EyeOff size={14} /> : <Eye size={14} />}
                    </button>
                    <button onClick={event => { event.stopPropagation(); void handleDelete(album) }}
                      className="p-1 rounded hover:opacity-80" style={{ color: 'var(--destructive)' }}>
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  )
}

function AlbumOverview({ album, onChange, language, autoFocus }: {
  album: Album
  onChange: (album: Album) => void
  language: Locale
  autoFocus?: boolean
}) {
  const [nameTouched, setNameTouched] = useState(false)
  const update = (patch: Partial<Album>) => onChange({ ...album, ...patch })
  const nameEmpty = !album.name.trim()

  return (
    <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_280px]">
      <div className="space-y-5">
        <section className="rounded-lg border p-5" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
          <h3 className="mb-4 text-sm font-medium">{t('admin.album_basic_info', language)}</h3>
          <div className="space-y-4">
            <Field label={t('admin.album_name', language)} required>
              <input
                autoFocus={autoFocus}
                value={album.name}
                onChange={event => update({ name: event.target.value })}
                onBlur={() => setNameTouched(true)}
                placeholder={t('admin.album_name_placeholder', language)}
                maxLength={60}
                className="w-full px-3 py-2 text-sm rounded-lg border outline-none transition-colors"
                style={{ ...inputStyle(), borderColor: nameTouched && nameEmpty ? 'var(--destructive)' : 'var(--border)' }}
              />
              {nameTouched && nameEmpty && (
                <p className="mt-1.5 text-xs" style={{ color: 'var(--destructive)' }}>
                  {t('admin.album_name_required', language)}
                </p>
              )}
            </Field>
            <Field label={t('admin.album_location', language)}>
              <div className="relative">
                <MapPin size={15} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--muted-foreground)' }} />
                <input
                  value={album.location ?? ''}
                  onChange={event => update({ location: event.target.value })}
                  placeholder={t('admin.album_location_placeholder', language)}
                  maxLength={80}
                  className="w-full rounded-lg border py-2 pl-9 pr-3 text-sm outline-none"
                  style={inputStyle()}
                />
              </div>
            </Field>
            <Field label={t('admin.description', language)}>
              <textarea
                value={album.description ?? ''}
                onChange={event => update({ description: event.target.value })}
                placeholder={t('admin.description_placeholder', language)}
                rows={4}
                maxLength={300}
                className="w-full px-3 py-2 text-sm rounded-lg border outline-none resize-none"
                style={inputStyle()}
              />
              <p className="mt-1 text-right text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
                {(album.description ?? '').length}/300
              </p>
            </Field>
          </div>
        </section>

        <section className="rounded-lg border p-5" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
          <h3 className="mb-4 text-sm font-medium">{t('admin.album_display_settings', language)}</h3>
          <div className="space-y-4">
            <Field label={t('admin.sort_order', language)}>
              <input
                type="number"
                value={album.sortOrder}
                onChange={event => update({ sortOrder: Number(event.target.value) || 0 })}
                className="w-40 px-3 py-2 text-sm rounded-lg border outline-none"
                style={inputStyle()}
              />
              <p className="mt-1.5 text-xs" style={{ color: 'var(--muted-foreground)' }}>{t('admin.sort_order_hint', language)}</p>
            </Field>
            <label className="flex items-start gap-3 p-4 rounded-lg border cursor-pointer" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--background)' }}>
              <input type="checkbox" checked={album.isPublished} onChange={event => update({ isPublished: event.target.checked })} className="mt-0.5" />
              <span>
                <span className="block text-sm font-medium">{t('admin.publish', language)}</span>
                <span className="block mt-0.5 text-xs" style={{ color: 'var(--muted-foreground)' }}>{t('admin.publish_hint', language)}</span>
              </span>
            </label>
          </div>
        </section>
      </div>

      <div className="lg:sticky lg:top-0">
        <p className="mb-2 text-xs font-medium" style={{ color: 'var(--muted-foreground)' }}>
          {t('admin.album_preview', language)}
        </p>
        <AlbumPreviewCard album={album} language={language} />
      </div>
    </div>
  )
}

function AlbumPreviewCard({ album, language }: { album: Album; language: Locale }) {
  return (
    <div className="rounded-lg border overflow-hidden" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
      <div className="aspect-video relative" style={{ backgroundColor: 'var(--muted)' }}>
        {album.coverUrl ? (
          <img src={resolveAssetUrl(album.coverUrl)} alt="" className="w-full h-full object-cover" />
        ) : (
          <div className="flex flex-col items-center justify-center h-full gap-1.5" style={{ color: 'var(--muted-foreground)' }}>
            <ImageIcon size={24} className="opacity-40" />
            <span className="text-[10px]">{t('admin.no_cover', language)}</span>
          </div>
        )}
      </div>
      <div className="p-3">
        <div className="flex items-center justify-between gap-2 mb-1">
          <h3 className="text-sm font-medium truncate">{album.name.trim() || t('admin.untitled_album', language)}</h3>
          <span className="text-[10px] px-1.5 py-0.5 rounded shrink-0"
            style={{
              backgroundColor: album.isPublished ? 'var(--accent)' : 'var(--muted)',
              color: album.isPublished ? 'var(--accent-foreground)' : 'var(--muted-foreground)',
            }}>
            {album.isPublished ? t('admin.albums_status_published', language) : t('admin.albums_status_draft', language)}
          </span>
        </div>
        {album.location && (
          <p className="mb-1 flex items-center gap-1 text-xs" style={{ color: 'var(--muted-foreground)' }}>
            <MapPin size={12} className="shrink-0" />
            <span className="truncate">{album.location}</span>
          </p>
        )}
        <p className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
          {album.photoCount} {t('admin.photos', language)}
        </p>
      </div>
    </div>
  )
}

function AlbumPhotos({ album, onRemovePhoto, onSetCover, onShowSelector, language }: {
  album: Album
  onRemovePhoto: (photoId: string) => void
  onSetCover: (photoId: string) => void
  onShowSelector: () => void
  language: Locale
}) {
  const albumPhotos = album.photos ?? []

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between gap-3">
        <span className="text-sm" style={{ color: 'var(--muted-foreground)' }}>{albumPhotos.length} {t('admin.photos', language)}</span>
        <button onClick={onShowSelector} className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md" style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
          <Plus size={14} /> {t('admin.add_photos', language)}
        </button>
      </div>

      {albumPhotos.length > 0 ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-5 gap-3">
          {albumPhotos.map(photo => {
            const cover = isCoverPhoto(album, photo)
            return (
              <div key={photo.id} className="relative group rounded-lg overflow-hidden border" style={{ borderColor: cover ? 'var(--primary)' : 'var(--border)', backgroundColor: 'var(--muted)' }}>
                <div className="aspect-square">
                  <img src={resolveAssetUrl(photo.thumbnailUrl || photo.url)} alt={photo.title} className="w-full h-full object-cover" />
                </div>
                <div className="absolute inset-x-0 bottom-0 px-2 pt-6 pb-2 bg-gradient-to-t from-black/80 to-transparent">
                  <p className="text-[11px] text-white truncate">{photo.title}</p>
                </div>
                {cover && (
                  <span className="absolute top-2 left-2 flex items-center gap-1 px-1.5 py-0.5 rounded bg-black/65 text-[10px] text-white">
                    <Star size={10} fill="currentColor" /> {t('admin.cover', language)}
                  </span>
                )}
                <div className="absolute top-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  {!cover && (
                    <button onClick={() => onSetCover(photo.id)} title={t('admin.set_cover', language)} className="p-1.5 rounded-md" style={{ backgroundColor: 'rgba(0,0,0,0.65)', color: 'white' }}>
                      <Star size={12} />
                    </button>
                  )}
                  <button onClick={() => onRemovePhoto(photo.id)} title={t('admin.remove', language)} className="p-1.5 rounded-md" style={{ backgroundColor: 'rgba(0,0,0,0.65)', color: 'white' }}>
                    <X size={12} />
                  </button>
                </div>
              </div>
            )
          })}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center h-52 border border-dashed rounded-lg" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
          <ImageIcon size={32} className="mb-3 opacity-40" />
          <p className="text-sm mb-4">{t('admin.album_empty', language)}</p>
          <button onClick={onShowSelector} className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md border" style={{ borderColor: 'var(--border)' }}>
            <Plus size={14} /> {t('admin.add_photos', language)}
          </button>
        </div>
      )}
    </div>
  )
}

function AlbumPhotoSelector({ photos, selectedIds, search, saving, onSearchChange, onToggle, onConfirm, onClose, language }: {
  photos: Photo[]
  selectedIds: Set<string>
  search: string
  saving: boolean
  onSearchChange: (value: string) => void
  onToggle: (photoId: string) => void
  onConfirm: () => void
  onClose: () => void
  language: Locale
}) {
  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 p-3 rounded-lg border" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
        <div className="flex flex-wrap items-center gap-3">
          <button onClick={onClose} className="p-1.5 rounded-md border" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}><X size={14} /></button>
          <span className="text-sm">{selectedIds.size} {t('admin.selected', language)}</span>
          <div className="relative">
            <Search size={14} className="absolute left-2.5 top-1/2 -translate-y-1/2" style={{ color: 'var(--muted-foreground)' }} />
            <input value={search} onChange={event => onSearchChange(event.target.value)} placeholder={t('common.search', language)} className="w-56 pl-8 pr-3 py-1.5 text-xs rounded-md border outline-none" style={inputStyle()} />
          </div>
        </div>
        <button onClick={onConfirm} disabled={saving || selectedIds.size === 0} className="flex items-center justify-center gap-1.5 px-3 py-1.5 text-xs rounded-md disabled:opacity-50" style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
          {saving ? <RefreshCw size={14} className="animate-spin" /> : <Check size={14} />}
          {t('admin.confirm_add', language)} ({selectedIds.size})
        </button>
      </div>

      {photos.length === 0 ? (
        <div className="flex items-center justify-center h-48 border border-dashed rounded-lg" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
          <p className="text-sm">{t('admin.no_photos_available', language)}</p>
        </div>
      ) : (
        <div className="grid grid-cols-3 sm:grid-cols-5 xl:grid-cols-7 gap-2">
          {photos.map(photo => (
            <button key={photo.id} onClick={() => onToggle(photo.id)} className="relative aspect-square rounded-md overflow-hidden border-2 transition-all" style={{ borderColor: selectedIds.has(photo.id) ? 'var(--primary)' : 'transparent', backgroundColor: 'var(--muted)' }}>
              <img src={resolveAssetUrl(photo.thumbnailUrl || photo.url)} alt={photo.title} className="w-full h-full object-cover" />
              <span className="absolute inset-x-0 bottom-0 px-1.5 pt-5 pb-1.5 text-left text-[10px] text-white truncate bg-gradient-to-t from-black/75 to-transparent">{photo.title}</span>
              {selectedIds.has(photo.id) && <span className="absolute top-1.5 right-1.5 flex items-center justify-center w-5 h-5 rounded-full" style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}><Check size={12} /></span>}
            </button>
          ))}
        </div>
      )}
    </div>
  )
}

function Field({ label, required, children }: { label: string; required?: boolean; children: ReactNode }) {
  return (
    <label className="block">
      <span className="block mb-1.5 text-xs font-medium" style={{ color: 'var(--muted-foreground)' }}>
        {label}
        {required && <span className="ml-0.5" style={{ color: 'var(--destructive)' }}>*</span>}
      </span>
      {children}
    </label>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  Camera,
  ChevronDown,
  ChevronRight,
  Eye,
  EyeOff,
  Film,
  Folder,
  FolderOpen,
  Images,
  Loader2,
  MapPin,
  Pencil,
  Plus,
  RefreshCw,
  Star,
  Tag,
  Trash2,
} from 'lucide-react'
import { useSearchParams } from 'react-router-dom'
import { toast } from 'sonner'
import { AlbumsPage } from '@/pages/AlbumsPage'
import { FilmRollsPage } from '@/pages/FilmRollsPage'
import { PhotosPage } from '@/pages/PhotosPage'
import { PageHeader } from '@/components/layout/PageHeader'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuLabel,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from '@/components/ui/ContextMenu'
import { resolveAssetUrl } from '@/lib/api'
import { normalizePhotoCategories } from '@/lib/photoCategories'
import { invalidateDesktopCache } from '@/lib/app-cache'
import { loadPersistentResource } from '@/lib/persistent-cache'
import { useLibrarySections, usePreferences, usePhotoFilters } from '@/store/preferences'
import { t } from '@/lib/i18n'
import type { Album } from '@/types'

type CloudView = 'photos' | 'albums' | 'film-rolls'
type AlbumDetailTab = 'overview' | 'photos'

interface AlbumAppAPI {
  GetAlbums(): Promise<Album[]>
  GetCategories(): Promise<string[]>
  UpdateAlbum(id: string, params: { isPublished?: boolean }): Promise<Album>
  DeleteAlbum(id: string): Promise<void>
}

function appApi(): AlbumAppAPI {
  const bridge = (window as unknown as { go?: { main?: { App?: AlbumAppAPI } } }).go?.main?.App
  if (!bridge) throw new Error('Wails API is not available')
  return bridge
}

function errorMessage(error: unknown, fallback: string) {
  return error instanceof Error && error.message ? error.message : fallback
}

function SectionHeader({ open, onToggle, label, onRefresh, refreshing = false, refreshLabel }: {
  open: boolean
  onToggle: () => void
  label: string
  onRefresh?: () => void
  refreshing?: boolean
  refreshLabel?: string
}) {
  return (
    <div className="mb-2 mt-5 flex items-center gap-1 px-1">
      <button
        type="button"
        onClick={onToggle}
        aria-expanded={open}
        className="flex min-w-0 flex-1 items-center gap-1 rounded px-1 py-1 text-left text-[10px] font-medium uppercase tracking-[0.16em] transition hover:bg-secondary"
        style={{ color: 'var(--muted-foreground)' }}
      >
        {open ? <ChevronDown size={12} className="shrink-0" /> : <ChevronRight size={12} className="shrink-0" />}
        <span className="truncate">{label}</span>
      </button>
      {onRefresh && (
        <button
          type="button"
          onClick={onRefresh}
          disabled={refreshing}
          title={refreshLabel}
          aria-label={refreshLabel}
          className="flex size-6 shrink-0 items-center justify-center rounded hover:bg-secondary disabled:cursor-wait disabled:opacity-50"
          style={{ color: 'var(--muted-foreground)' }}
        >
          {refreshing ? <Loader2 size={11} className="animate-spin" /> : <RefreshCw size={11} />}
        </button>
      )}
    </div>
  )
}

export function CloudLibraryPage() {
  const language = usePreferences((state) => state.language)
  const sections = useLibrarySections((state) => state.sections)
  const toggleSection = useLibrarySections((state) => state.toggleSection)
  const albumId = usePhotoFilters((state) => state.albumId)
  const category = usePhotoFilters((state) => state.category)
  const photoType = usePhotoFilters((state) => state.photoType)
  const featured = usePhotoFilters((state) => state.featured)
  const setAlbumId = usePhotoFilters((state) => state.setAlbumId)
  const setCategory = usePhotoFilters((state) => state.setCategory)
  const setPhotoType = usePhotoFilters((state) => state.setPhotoType)
  const setFeatured = usePhotoFilters((state) => state.setFeatured)
  const [searchParams, setSearchParams] = useSearchParams()
  const [albums, setAlbums] = useState<Album[]>([])
  const [categories, setCategories] = useState<string[]>([])
  const [loading, setLoading] = useState(true)
  const [albumsLoaded, setAlbumsLoaded] = useState(false)
  const [deleteTarget, setDeleteTarget] = useState<Album | null>(null)
  const [updatingAlbumId, setUpdatingAlbumId] = useState<string | null>(null)
  const albumsRequestIdRef = useRef(0)

  const requestedView = searchParams.get('view')
  const view: CloudView = requestedView === 'albums' || requestedView === 'film-rolls' ? requestedView : 'photos'
  const createMode = view === 'albums' && searchParams.get('create') === '1'
  const managingAlbumId = view === 'albums' ? searchParams.get('manage') : null
  const managerTab: AlbumDetailTab = searchParams.get('tab') === 'photos' ? 'photos' : 'overview'
  const showingAlbumBrowser = view === 'albums' && !createMode && !managingAlbumId

  const fetchAlbums = useCallback(async (force = false) => {
    const requestId = ++albumsRequestIdRef.current
    setLoading(true)
    try {
      const [result, categoryResult] = await Promise.all([
        loadPersistentResource('albums', () => appApi().GetAlbums(), { force }),
        loadPersistentResource('categories', async () => normalizePhotoCategories(await appApi().GetCategories()), { force }),
      ])
      if (requestId !== albumsRequestIdRef.current) return
      setAlbums(result ?? [])
      setCategories(categoryResult)
      setAlbumsLoaded(true)
    } catch (error) {
      if (requestId !== albumsRequestIdRef.current) return
      toast.error(errorMessage(error, t('common.error', language)))
    } finally {
      if (requestId === albumsRequestIdRef.current) setLoading(false)
    }
  }, [language])

  useEffect(() => {
    void fetchAlbums()
  }, [fetchAlbums])

  useEffect(() => {
    if (albumsLoaded && !loading && albumId && !albums.some((album) => album.id === albumId)) setAlbumId(null)
  }, [albumId, albums, albumsLoaded, loading, setAlbumId])

  const sortedAlbums = useMemo(() => (
    [...albums].sort((left, right) => left.sortOrder - right.sortOrder || left.name.localeCompare(right.name))
  ), [albums])

  const showAllPhotos = useCallback(() => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(null)
    setFeatured(null)
    setSearchParams({ source: 'cloud' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const showFeaturedPhotos = useCallback(() => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(null)
    setFeatured(true)
    setSearchParams({ source: 'cloud' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const showFilmRolls = useCallback(() => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(null)
    setFeatured(null)
    setSearchParams({ source: 'cloud', view: 'film-rolls' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const showPhotoType = useCallback((nextPhotoType: 'digital' | 'film') => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(nextPhotoType)
    setFeatured(null)
    setSearchParams({ source: 'cloud' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const showCategory = useCallback((nextCategory: string) => {
    setAlbumId(null)
    setCategory(nextCategory)
    setPhotoType(null)
    setFeatured(null)
    setSearchParams({ source: 'cloud' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const showAlbum = useCallback((id: string) => {
    setCategory('全部')
    setPhotoType(null)
    setFeatured(null)
    setAlbumId(id)
    setSearchParams({ source: 'cloud' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const showAlbumBrowser = useCallback(() => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(null)
    setFeatured(null)
    setSearchParams({ source: 'cloud', view: 'albums' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const createAlbum = useCallback(() => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(null)
    setFeatured(null)
    setSearchParams({ source: 'cloud', view: 'albums', create: '1' }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const manageAlbum = useCallback((id: string, tab: AlbumDetailTab) => {
    setAlbumId(null)
    setCategory('全部')
    setPhotoType(null)
    setFeatured(null)
    setSearchParams({ source: 'cloud', view: 'albums', manage: id, tab }, { replace: true })
  }, [setAlbumId, setCategory, setFeatured, setPhotoType, setSearchParams])

  const togglePublished = useCallback(async (album: Album) => {
    if (updatingAlbumId) return
    setUpdatingAlbumId(album.id)
    try {
      const updated = await appApi().UpdateAlbum(album.id, { isPublished: !album.isPublished })
      await fetchAlbums(true)
      invalidateDesktopCache(['overview'])
      toast.success(t(updated.isPublished ? 'admin.album_published' : 'admin.album_unpublished', language))
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    } finally {
      setUpdatingAlbumId(null)
    }
  }, [fetchAlbums, language, updatingAlbumId])

  const deleteAlbum = useCallback(async () => {
    const target = deleteTarget
    if (!target) return
    try {
      await appApi().DeleteAlbum(target.id)
      await fetchAlbums(true)
      invalidateDesktopCache(['overview', 'photos'])
      if (albumId === target.id) setAlbumId(null)
      if (managingAlbumId === target.id) showAlbumBrowser()
      setDeleteTarget(null)
      toast.success(t('common.deleted', language))
    } catch (error) {
      toast.error(errorMessage(error, t('common.error', language)))
    }
  }, [albumId, deleteTarget, fetchAlbums, language, managingAlbumId, setAlbumId, showAlbumBrowser])

  const albumMenuActions = useMemo(() => ({
    onOpen: showAlbum,
    onEdit: (id: string) => manageAlbum(id, 'overview'),
    onManagePhotos: (id: string) => manageAlbum(id, 'photos'),
    onTogglePublished: (album: Album) => void togglePublished(album),
    onDelete: setDeleteTarget,
  }), [manageAlbum, showAlbum, togglePublished])

  return (
    <div className="flex h-full min-h-0 bg-background">
      <aside className="flex w-[218px] shrink-0 flex-col overflow-hidden border-r bg-card p-3" style={{ borderColor: 'var(--border)' }}>
        <div className="custom-scrollbar min-h-0 flex-1 overflow-y-auto">
          <CloudNavButton
            active={view === 'photos' && !albumId && featured !== true && category === '全部' && !photoType}
            icon={Images}
            label={t('admin.resource_library_all_photos', language)}
            onClick={showAllPhotos}
          />
          <CloudNavButton
            active={view === 'photos' && !albumId && featured === true && !photoType}
            icon={Star}
            label={t('admin.featured', language)}
            onClick={showFeaturedPhotos}
          />
          <CloudNavButton
            active={view === 'film-rolls'}
            icon={Film}
            label={t('admin.film_rolls', language)}
            onClick={showFilmRolls}
          />

          <SectionHeader
            open={sections.cloudPhotoType}
            onToggle={() => toggleSection('cloudPhotoType')}
            label={language === 'zh' ? '照片类型' : 'Photo type'}
          />
          {sections.cloudPhotoType && (
            <div className="space-y-0.5">
              <CloudNavButton
                active={view === 'photos' && !albumId && featured !== true && category === '全部' && photoType === 'digital'}
                icon={Camera}
                label={t('admin.photos_type_digital', language)}
                onClick={() => showPhotoType('digital')}
              />
              <CloudNavButton
                active={view === 'photos' && !albumId && featured !== true && category === '全部' && photoType === 'film'}
                icon={Film}
                label={t('admin.photos_type_film', language)}
                onClick={() => showPhotoType('film')}
              />
            </div>
          )}

          <SectionHeader
            open={sections.cloudCategories}
            onToggle={() => toggleSection('cloudCategories')}
            label={t('ui.category_filter', language)}
            onRefresh={() => void fetchAlbums(true)}
            refreshing={loading}
            refreshLabel={t('common.refresh', language)}
          />
          {sections.cloudCategories && (
            <div className="space-y-0.5">
              {categories.map((item) => (
                <CloudNavButton
                  key={item}
                  active={view === 'photos' && !albumId && featured !== true && !photoType && category === item}
                  icon={Tag}
                  label={item}
                  onClick={() => showCategory(item)}
                />
              ))}
              {!loading && categories.length === 0 && <p className="px-2.5 py-2 text-[10px]" style={{ color: 'var(--muted-foreground)' }}>{language === 'zh' ? '暂无分类' : 'No categories'}</p>}
            </div>
          )}

          <div className="mb-2 mt-5 flex items-center gap-1 px-1">
            <button
              type="button"
              onClick={() => toggleSection('cloudAlbums')}
              aria-expanded={sections.cloudAlbums}
              aria-label={sections.cloudAlbums ? t('common.collapse', language) : t('common.expand', language)}
              title={sections.cloudAlbums ? t('common.collapse', language) : t('common.expand', language)}
              className="flex size-5 shrink-0 items-center justify-center rounded hover:bg-secondary"
              style={{ color: 'var(--muted-foreground)' }}
            >
              {sections.cloudAlbums ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
            </button>
            <button
              type="button"
              onClick={showAlbumBrowser}
              className="flex min-w-0 flex-1 items-center gap-1.5 rounded px-1 py-1 text-left text-[10px] font-medium uppercase transition hover:bg-secondary"
              style={{
                color: view === 'albums' ? 'var(--foreground)' : 'var(--muted-foreground)',
                backgroundColor: showingAlbumBrowser ? 'var(--accent)' : undefined,
              }}
              title={t('admin.album_browse', language)}
            >
              <FolderOpen size={12} className="shrink-0" />
              <span className="truncate tracking-[0.16em]">{t('gallery.albums', language)}</span>
              <span className="ml-auto text-[9px] tabular-nums tracking-normal" style={{ color: 'var(--muted-foreground)' }}>{albums.length}</span>
            </button>
            <button
              type="button"
              onClick={createAlbum}
              title={t('admin.create_album', language)}
              aria-label={t('admin.create_album', language)}
              className="flex size-6 shrink-0 items-center justify-center rounded hover:bg-secondary"
              style={{ color: 'var(--muted-foreground)' }}
            >
              <Plus size={12} />
            </button>
            <button
              type="button"
              onClick={() => void fetchAlbums(true)}
              title={t('common.refresh', language)}
              aria-label={t('common.refresh', language)}
              className="flex size-6 shrink-0 items-center justify-center rounded hover:bg-secondary"
              style={{ color: 'var(--muted-foreground)' }}
            >
              {loading ? <Loader2 size={11} className="animate-spin" /> : <RefreshCw size={11} />}
            </button>
          </div>

          {sections.cloudAlbums && (
            <div className="space-y-0.5">
              {sortedAlbums.map((album) => (
                <AlbumContextTarget key={album.id} album={album} language={language} busy={updatingAlbumId === album.id} {...albumMenuActions}>
                  <button
                    type="button"
                    onClick={() => showAlbum(album.id)}
                    className="flex w-full items-center gap-2 rounded-md px-2.5 py-2 text-left text-xs transition hover:bg-secondary"
                    style={{
                      backgroundColor: view === 'photos' && albumId === album.id ? 'var(--accent)' : undefined,
                      color: view === 'photos' && albumId === album.id ? 'var(--accent-foreground)' : undefined,
                    }}
                    title={album.name}
                  >
                    <Folder size={15} className="shrink-0" />
                    <span className="min-w-0 flex-1 truncate">{album.name}</span>
                    {!album.isPublished && <EyeOff size={11} className="shrink-0" style={{ color: 'var(--muted-foreground)' }} />}
                    <span className="shrink-0 text-[10px] tabular-nums" style={{ color: 'var(--muted-foreground)' }}>{album.photoCount || 0}</span>
                  </button>
                </AlbumContextTarget>
              ))}
              {!loading && sortedAlbums.length === 0 && (
                <button type="button" onClick={createAlbum} className="w-full rounded-md px-2.5 py-3 text-left text-[10px] hover:bg-secondary" style={{ color: 'var(--muted-foreground)' }}>
                  {t('admin.no_albums', language)} · {t('admin.create_album', language)}
                </button>
              )}
            </div>
          )}
        </div>
      </aside>

      <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
        {view === 'photos' ? (
          <PhotosPage />
        ) : view === 'film-rolls' ? (
          <FilmRollsPage />
        ) : createMode || managingAlbumId ? (
          <AlbumsPage
            initialAlbumId={managingAlbumId}
            initialTab={managerTab}
            createMode={createMode}
            onBackToBrowser={showAlbumBrowser}
            onAlbumsChanged={() => void fetchAlbums(true)}
          />
        ) : (
          <CloudAlbumsBrowser
            albums={sortedAlbums}
            loading={loading}
            language={language}
            onOpen={showAlbum}
          />
        )}
      </div>

      <SimpleDeleteDialog
        isOpen={!!deleteTarget}
        title={t('admin.delete_album', language)}
        message={deleteTarget ? t('admin.album_delete_named_confirm', language).replace('{name}', deleteTarget.name) : ''}
        onConfirm={deleteAlbum}
        onCancel={() => setDeleteTarget(null)}
        t={(key) => t(key, language)}
      />
    </div>
  )
}

interface AlbumActions {
  onOpen: (id: string) => void
  onEdit: (id: string) => void
  onManagePhotos: (id: string) => void
  onTogglePublished: (album: Album) => void
  onDelete: (album: Album) => void
}

function AlbumContextTarget({ album, language, busy, children, ...actions }: AlbumActions & {
  album: Album
  language: 'zh' | 'en'
  busy: boolean
  children: React.ReactElement
}) {
  return (
    <ContextMenu>
      <ContextMenuTrigger asChild>{children}</ContextMenuTrigger>
      <ContextMenuContent>
        <ContextMenuLabel className="max-w-56 truncate">{album.name}</ContextMenuLabel>
        <ContextMenuSeparator />
        <ContextMenuItem onSelect={() => actions.onOpen(album.id)}><FolderOpen size={14} />{t('admin.open_album', language)}</ContextMenuItem>
        <ContextMenuItem onSelect={() => actions.onEdit(album.id)}><Pencil size={14} />{t('admin.edit_album', language)}</ContextMenuItem>
        <ContextMenuItem onSelect={() => actions.onManagePhotos(album.id)}><Images size={14} />{t('admin.manage_photos', language)}</ContextMenuItem>
        <ContextMenuSeparator />
        <ContextMenuItem disabled={busy} onSelect={() => actions.onTogglePublished(album)}>
          {busy ? <Loader2 size={14} className="animate-spin" /> : album.isPublished ? <EyeOff size={14} /> : <Eye size={14} />}
          {t(album.isPublished ? 'admin.unpublish_album' : 'admin.publish_album', language)}
        </ContextMenuItem>
        <ContextMenuSeparator />
        <ContextMenuItem variant="destructive" onSelect={() => actions.onDelete(album)}><Trash2 size={14} />{t('admin.delete_album', language)}</ContextMenuItem>
      </ContextMenuContent>
    </ContextMenu>
  )
}

function CloudAlbumsBrowser({ albums, loading, language, onOpen }: {
  albums: Album[]
  loading: boolean
  language: 'zh' | 'en'
  onOpen: (id: string) => void
}) {
  return (
    <>
      <PageHeader title={t('gallery.albums', language)} />

      <div className="custom-scrollbar min-h-0 flex-1 overflow-auto p-6">
        {loading ? (
          <div className="grid grid-cols-2 gap-5 lg:grid-cols-3 2xl:grid-cols-5">
            {Array.from({ length: 8 }, (_, index) => <div key={index} className="aspect-[4/3] animate-pulse rounded-md bg-muted" />)}
          </div>
        ) : albums.length === 0 ? (
          <div className="flex h-full min-h-72 flex-col items-center justify-center gap-3 text-muted-foreground">
            <span className="flex size-14 items-center justify-center rounded-lg bg-muted"><FolderOpen size={25} /></span>
            <p className="text-sm">{t('admin.no_albums', language)}</p>
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-x-5 gap-y-7 lg:grid-cols-3 2xl:grid-cols-5">
            {albums.map(album => (
                <button
                  key={album.id}
                  type="button"
                  onClick={() => onOpen(album.id)}
                  className="group min-w-0 text-left outline-none"
                  title={`${album.name} · ${album.photoCount || 0} ${t('admin.photos', language)}`}
                >
                  <div className="relative pt-3">
                    <span className="absolute left-3 top-0 h-5 w-20 rounded-t-md border border-b-0 bg-muted transition-colors group-hover:bg-accent" style={{ borderColor: 'var(--border)' }} />
                    <span className="relative block aspect-[4/3] overflow-hidden rounded-md rounded-tl-sm border bg-muted shadow-sm transition group-hover:-translate-y-0.5 group-hover:shadow-md" style={{ borderColor: 'var(--border)' }}>
                      {album.coverUrl ? (
                        <img src={resolveAssetUrl(album.coverUrl)} alt="" className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.02]" />
                      ) : (
                        <span className="flex h-full flex-col items-center justify-center gap-2 text-muted-foreground"><FolderOpen size={30} /><span className="text-[10px]">{t('admin.album_empty', language)}</span></span>
                      )}
                      <span className="absolute inset-0 bg-gradient-to-t from-black/45 via-transparent to-transparent" />
                      <span className="absolute bottom-2 left-2 right-2 flex items-end justify-between gap-2 text-white">
                        <span className="truncate text-xs font-medium">{album.name}</span>
                        <span className="shrink-0 rounded bg-black/45 px-1.5 py-0.5 text-[9px] tabular-nums backdrop-blur-sm">{album.photoCount || 0}</span>
                      </span>
                      {!album.isPublished && <span className="absolute right-2 top-2 flex items-center gap-1 rounded bg-black/50 px-1.5 py-0.5 text-[9px] text-white backdrop-blur-sm"><EyeOff size={9} />{t('admin.draft', language)}</span>}
                    </span>
                  </div>
                  <span className="mt-2 block min-w-0 px-1">
                    <span className="block truncate text-xs font-medium">{album.name}</span>
                    <span className="mt-0.5 flex items-center gap-1 truncate text-[10px] text-muted-foreground">
                      {album.location ? <><MapPin size={10} className="shrink-0" /><span className="truncate">{album.location}</span></> : <span>{album.photoCount || 0} {t('admin.photos', language)}</span>}
                    </span>
                  </span>
                </button>
            ))}
          </div>
        )}
      </div>
    </>
  )
}

function CloudNavButton({
  active,
  icon: Icon,
  label,
  onClick,
}: {
  active: boolean
  icon: typeof Images
  label: string
  onClick: () => void
}) {
