  BookText,
  BookOpen,
  FileArchive,
  Clock,
  Trash2,
  Eye,
  X,
  Image as ImageIcon,
  Edit3,
  ArrowRight,
  Search,
  RefreshCw,
  type LucideIcon,
} from 'lucide-react'

interface StoryDraftWithPreviews extends Omit<StoryDraftData, 'files'> {
  files: { id: string; file: File; preview: string }[]
}

