      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <h4 className="truncate font-serif text-base">{title}</h4>
          {badge}
        </div>
        <p className="mt-0.5 truncate text-xs" style={{ color: 'var(--muted-foreground)' }}>
