    >
      <div
        className={`group overflow-hidden border text-left transition focus:outline-none ${masonry ? 'mb-1.5 inline-block w-full rounded-sm align-top' : 'flex h-full min-w-0 flex-col rounded-lg'} ${isDeleting ? 'cursor-wait opacity-75' : 'cursor-pointer'}`}
        style={{
          borderColor: isSelected ? 'var(--primary)' : masonry ? 'transparent' : 'var(--border)',
          backgroundColor: isSelected ? 'var(--accent)' : masonry ? 'transparent' : 'var(--card)',
          boxShadow: isSelected ? '0 0 0 1px var(--primary)' : undefined,
          breakInside: masonry ? 'avoid' : undefined,
          contentVisibility: masonry ? undefined : 'auto',
        }}
        onClick={(event) => { if (!isDeleting) onCardClick(event, photo) }}
        onDoubleClick={() => { if (!isDeleting) onCardDoubleClick(photo) }}
      >
        <div
          className={`relative min-h-0 w-full overflow-hidden bg-secondary ${masonry ? '' : 'aspect-[5/4]'}`}
          style={masonry ? { aspectRatio: photo.width > 0 && photo.height > 0 ? `${photo.width} / ${photo.height}` : '4 / 3' } : undefined}
        >
          <Thumb
            src={resolveAssetUrl(photo.thumbnailUrl || photo.url)}
            alt={photo.title}
            width={masonry ? photo.width : undefined}
            height={masonry ? photo.height : undefined}
            className={`w-full transition-[transform,opacity] duration-300 ${masonry ? 'block h-full object-cover group-hover:scale-[1.015]' : viewMode === 'fit' ? 'h-full object-contain p-1' : 'h-full object-cover group-hover:scale-[1.025]'} ${isDeleting ? '!opacity-50' : ''}`}
          />
          <button
            onClick={(event) => { event.stopPropagation(); if (!isDeleting) onToggleSelect(photo.id) }}
            className={`absolute left-2 top-2 z-30 flex h-5 w-5 items-center justify-center rounded border transition-opacity ${isSelected ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'}`}
            style={{ backgroundColor: isSelected ? 'var(--primary)' : 'rgba(0,0,0,0.4)', borderColor: isSelected ? 'var(--primary)' : 'rgba(255,255,255,0.7)' }}
          >
            {isSelected && <Check size={12} className="text-white" />}
          </button>
          <div className="absolute right-2 top-2 z-20 flex items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100">
            <button onClick={(event) => { event.stopPropagation(); onToggleFeatured(photo.id) }} disabled={isDeleting} title={photo.isFeatured ? '取消精选' : '设为精选'} className="rounded bg-black/60 p-1.5 text-white hover:bg-black/75 disabled:opacity-50"><Star size={12} fill={photo.isFeatured ? 'currentColor' : 'none'} /></button>
            <button onClick={(event) => { event.stopPropagation(); onToggleShow(photo.id) }} disabled={isDeleting} title={photo.showFlag ? '设为隐藏' : '设为展示'} className="rounded bg-black/60 p-1.5 text-white hover:bg-black/75 disabled:opacity-50">{photo.showFlag ? <Eye size={12} /> : <EyeOff size={12} />}</button>
            <button onClick={(event) => { event.stopPropagation(); onRequestDelete(photo) }} disabled={isDeleting} title="删除照片" className="rounded bg-black/60 p-1.5 text-white hover:bg-red-600/85 disabled:opacity-50">{isDeleting ? <Loader2 size={12} className="animate-spin" /> : <Trash2 size={12} />}</button>
          </div>
          {(photo.isFeatured || !photo.showFlag || photo.photoType === 'film') && (
            <div className="absolute bottom-2 right-2 flex items-center gap-1 rounded bg-black/60 px-1.5 py-1 text-white">
              {photo.isFeatured && <Star size={11} fill="currentColor" />}
              {!photo.showFlag && <EyeOff size={11} />}
              {photo.photoType === 'film' && <Film size={11} />}
            </div>
          )}
          {isDeleting && <div className="absolute inset-0 z-40 flex flex-col items-center justify-center gap-2 bg-black/45 text-white"><Loader2 size={20} className="animate-spin" /><span className="text-xs">删除中...</span></div>}
        </div>
        {!masonry && (
          <div className="block w-full px-2.5 py-2">
            <span className="block truncate text-xs font-medium">{photo.title || 'Untitled'}</span>
            <span className="mt-0.5 block truncate text-[10px]" style={{ color: 'var(--muted-foreground)' }}>{photo.width && photo.height ? `${photo.width} × ${photo.height}` : photo.category || '—'}</span>
          </div>
        )}
      </div>
    </PhotoContextTarget>
  )
})

export function PhotosPage() {
  const { language, photoGridSize, photoViewMode: viewMode, setPhotoGridSize, setPhotoViewMode: setViewMode } = usePreferences()
  const gridSize = Math.min(MAX_PHOTO_GRID_SIZE, Math.max(MIN_PHOTO_GRID_SIZE, photoGridSize))
  const filters = usePhotoFilters()
  const { token, logout } = useAuth()
  const navigate = useNavigate()

  const filterKey = JSON.stringify([
    filters.category, filters.search, filters.photoType, filters.channel,
    filters.albumId, filters.cameraId, filters.lensId, filters.featured,
    filters.sortBy, filters.sortOrder,
  ])
  const photosPageCache = getPhotosPageCache()
  const cacheGenerationRef = useRef(getPhotosPageCacheGeneration())
  const invalidateAfterLocalMutation = useCallback((domains: Parameters<typeof invalidateDesktopCache>[0]) => {
    invalidateDesktopCache(domains)
    cacheGenerationRef.current = getPhotosPageCacheGeneration()
  }, [])
  const cacheHitRef = useRef(
    photosPageCache !== null && photosPageCache.loaded && photosPageCache.filterKey === filterKey,
  )

  const [photos, setPhotos] = useState<Photo[]>(() => cacheHitRef.current ? photosPageCache!.photos : [])
  const [total, setTotal] = useState(() => cacheHitRef.current ? photosPageCache!.total : 0)
  const [hasMore, setHasMore] = useState(() => cacheHitRef.current ? photosPageCache!.hasMore : true)
  const [loading, setLoading] = useState(false)
  const [loadingMore, setLoadingMore] = useState(false)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [categories, setCategories] = useState<string[]>([])
  const [deletingIds, setDeletingIds] = useState<Set<string>>(new Set())
  const [deleteTarget, setDeleteTarget] = useState<Photo | null>(null)
  const [batchDeleting, setBatchDeleting] = useState(false)
  const [batchDeleteDialogOpen, setBatchDeleteDialogOpen] = useState(false)
  const [batchUpdating, setBatchUpdating] = useState(false)
  const [detailPhoto, setDetailPhoto] = useState<Photo | null>(null)
  // 大图预览（双击卡片/点击侧栏缩略图打开）
  const [previewPhoto, setPreviewPhoto] = useState<Photo | null>(null)
  // 完整编辑/叙事弹层（从右侧信息栏打开，信息页签或叙事页签）
  const [editorState, setEditorState] = useState<{ photo: Photo; mode: 'info' | 'story' } | null>(null)
  // 搜索输入本地回显，300ms 防抖后才写入筛选（避免每键一次全量请求）
  const [searchInput, setSearchInput] = useState(filters.search)
  const [photoGridWidth, setPhotoGridWidth] = useState(900)

  const pageRef = useRef(cacheHitRef.current ? photosPageCache!.page : 1)
  const scrollRef = useRef<HTMLDivElement>(null)
  const loadMoreSentinelRef = useRef<HTMLDivElement>(null)
  const autoFillAttemptPageRef = useRef<number | null>(null)
  const fetchingRef = useRef(false)
  const fetchRequestIdRef = useRef(0)
  const hasLoadedInitialPageRef = useRef(cacheHitRef.current)
  const lastScrollTopRef = useRef(0)
  const scrollRafPendingRef = useRef(false)
  // Shift 范围选择的锚点（最近一次勾选的照片）
  const anchorIdRef = useRef<string | null>(null)

  // 渲染期同步最新状态，供卸载写缓存和稳定回调（滚动/键盘）读取
  const latestRef = useRef({ photos, total, hasMore, filterKey })
  latestRef.current = { photos, total, hasMore, filterKey }

  const masonryColumnCount = Math.max(1, Math.floor((photoGridWidth + MASONRY_COLUMN_GAP) / (gridSize + MASONRY_COLUMN_GAP)))
  const masonryColumnWidth = Math.max(
    1,
    (photoGridWidth - Math.max(0, masonryColumnCount - 1) * MASONRY_COLUMN_GAP) / masonryColumnCount,
  )
  const masonryColumns = useMemo(
    () => distributeMasonryPhotos(photos, masonryColumnCount, masonryColumnWidth),
    [masonryColumnCount, masonryColumnWidth, photos],
  )

  useLayoutEffect(() => {
    const element = scrollRef.current
    if (!element) return

    const updateGridWidth = () => {
      const style = window.getComputedStyle(element)
      const horizontalPadding = Number.parseFloat(style.paddingLeft) + Number.parseFloat(style.paddingRight)
      const width = Math.max(1, element.clientWidth - horizontalPadding)
      setPhotoGridWidth(current => Math.abs(current - width) < 0.5 ? current : width)
    }

    updateGridWidth()
    const observer = new ResizeObserver(updateGridWidth)
    observer.observe(element)
    return () => observer.disconnect()
  }, [])

  useLayoutEffect(() => {
    if (cacheHitRef.current && photosPageCache && scrollRef.current) {
      scrollRef.current.scrollTop = photosPageCache.scrollTop
      lastScrollTopRef.current = photosPageCache.scrollTop
    }
  }, [])

  useEffect(() => () => {
    // 让卸载前尚未完成的请求失效，避免 StrictMode/HMR 的旧闭包继续参与状态判断。
    fetchRequestIdRef.current += 1
    fetchingRef.current = false

    // 只缓存已完成的首屏结果；请求中的空数组不能成为下一次挂载的“有效缓存”。
    if (!hasLoadedInitialPageRef.current) return
    setPhotosPageCache({
      filterKey: latestRef.current.filterKey,
      photos: latestRef.current.photos,
      total: latestRef.current.total,
      hasMore: latestRef.current.hasMore,
      page: pageRef.current,
      scrollTop: lastScrollTopRef.current,
      loaded: true,
    }, cacheGenerationRef.current)
  }, [])

  // 全部照片使用分页接口；选中相册后直接读取相册管理详情接口中的 photos。
  const fetchPhotos = useCallback(async (pageNum: number, append: boolean) => {
    if (append && (fetchingRef.current || filters.albumId)) return

    const requestId = ++fetchRequestIdRef.current
    fetchingRef.current = true
    if (!append) hasLoadedInitialPageRef.current = false

    if (append) setLoadingMore(true)
    else setLoading(true)

    try {
      if (filters.albumId) {
        const album: Album = await (window as any).go.main.App.GetAlbum(filters.albumId)
        if (requestId !== fetchRequestIdRef.current) return

        const albumPhotos = filterAndSortAlbumPhotos(album?.photos || [], filters)
        setPhotos(albumPhotos)
        setTotal(albumPhotos.length)
        setHasMore(false)
        pageRef.current = 1
        hasLoadedInitialPageRef.current = true
        setLoadError(null)
        return
      }

      const result: PaginatedResponse<Photo> = await (window as any).go.main.App.GetPhotos({
        category: filters.category === '全部' ? '' : filters.category,
        search: filters.search,
        photoType: filters.photoType,
        channel: filters.channel,
        albumId: '',
        cameraId: filters.cameraId,
        lensId: filters.lensId,
        featured: filters.featured,
        sortBy: filters.sortBy,
        sortOrder: filters.sortOrder,
        page: pageNum,
        pageSize: PAGE_SIZE,
      })
      if (requestId !== fetchRequestIdRef.current) return

      const newData = result.data || []
      setPhotos(prev => append ? [...prev, ...newData] : newData)
      if (result.meta?.total !== undefined) setTotal(result.meta.total)
      else setTotal(prev => append ? prev + newData.length : newData.length)
      // 某些旧服务响应可能不含 meta；满页时继续尝试下一页，空页后自然停止。
      setHasMore(result.meta?.hasMore ?? newData.length >= PAGE_SIZE)
      pageRef.current = pageNum
      if (!append) hasLoadedInitialPageRef.current = true
      setLoadError(null)
    } catch (err: any) {
      if (requestId !== fetchRequestIdRef.current) return
      console.error('获取照片失败:', err)
      setLoadError(err?.message || '加载照片失败，请检查网络连接')
      if (append) {
        if (autoFillAttemptPageRef.current === pageNum) autoFillAttemptPageRef.current = null
        toast.error(err?.message || '加载更多失败')
      }
    } finally {
      if (requestId === fetchRequestIdRef.current) {
        setLoading(false)
        setLoadingMore(false)
        fetchingRef.current = false
      }
    }
  }, [filters])

  // 滚动/键盘等稳定回调通过 ref 调用最新的 fetchPhotos
  const fetchPhotosRef = useRef(fetchPhotos)
  fetchPhotosRef.current = fetchPhotos

  // 搜索防抖：停止输入 300ms 后才更新筛选条件
  useEffect(() => {
    const timer = window.setTimeout(() => {
      if (searchInput !== filters.search) filters.setSearch(searchInput)
    }, 300)
    return () => window.clearTimeout(timer)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchInput])

  // 筛选变化时重置列表；命中模块缓存的首次挂载跳过（沿用缓存数据）
  useEffect(() => {
    if (cacheHitRef.current) {
      cacheHitRef.current = false
      return
    }
    pageRef.current = 1
    autoFillAttemptPageRef.current = null
    setHasMore(true)
    setPhotos([])
    setSelected(new Set())
    anchorIdRef.current = null
    scrollRef.current?.scrollTo({ top: 0 })
    fetchPhotos(1, false)
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterKey])

  // 加载分类
  useEffect(() => {
    (async () => {
      try {
        const result = await loadPersistentResource('categories', async () => (
          normalizePhotoCategories(await (window as any).go.main.App.GetCategories())
        ))
        setCategories(result)
      } catch {}
    })()
  }, [])

  // 滚动到底部附近时加载更多；rAF 节流，滚动事件本身只记录位置
  const handleScroll = useCallback(() => {
    const el = scrollRef.current
    if (!el) return
    lastScrollTopRef.current = el.scrollTop

    if (scrollRafPendingRef.current) return
    scrollRafPendingRef.current = true
    requestAnimationFrame(() => {
      scrollRafPendingRef.current = false
      const node = scrollRef.current
      if (!node || fetchingRef.current || !latestRef.current.hasMore) return
      // 距离底部 300px 时触发（IntersectionObserver 的备用机制）
      if (node.scrollTop + node.clientHeight >= node.scrollHeight - 300) {
        fetchPhotosRef.current(pageRef.current + 1, true)
      }
    })
  }, [])

  // 嵌套到资源库三栏布局后，滚动事件在部分 WebView 中不会稳定抵达底部。
  // 使用滚动容器内的底部哨兵作为主分页触发；每次追加后重新观察，
  // 即使首屏高度不足以产生滚动条，也会继续加载直到填满视口。
  useEffect(() => {
    const root = scrollRef.current
    const sentinel = loadMoreSentinelRef.current
    if (!root || !sentinel || loading || photos.length === 0 || !hasMore) return

    const observer = new IntersectionObserver((entries) => {
      if (!entries[0]?.isIntersecting || fetchingRef.current || !latestRef.current.hasMore) return
      fetchPhotosRef.current(pageRef.current + 1, true)
    }, {
      root,
      rootMargin: '360px 0px',
      threshold: 0,
    })

    observer.observe(sentinel)
    return () => observer.disconnect()
  }, [hasMore, loading, photos.length, viewMode])

  // 页面没有产生滚动条时，单靠 onScroll 永远无法触发下一页。
  // 渲染完成后直接比较 scrollHeight/clientHeight，未填满视口则自动请求下一页。
  useEffect(() => {
    const node = scrollRef.current
    if (!node || loading || loadingMore || photos.length === 0 || !hasMore) return

    let frame = 0
    const checkViewportFill = () => {
      window.cancelAnimationFrame(frame)
      frame = window.requestAnimationFrame(() => {
        if (fetchingRef.current || !latestRef.current.hasMore) return
        if (node.scrollHeight > node.clientHeight + 8) return

        const nextPage = pageRef.current + 1
        if (autoFillAttemptPageRef.current === nextPage) return
        autoFillAttemptPageRef.current = nextPage
        fetchPhotosRef.current(nextPage, true)
      })
    }

    checkViewportFill()
    const resizeObserver = new ResizeObserver(checkViewportFill)
    resizeObserver.observe(node)

    return () => {
      window.cancelAnimationFrame(frame)
      resizeObserver.disconnect()
    }
  }, [gridSize, hasMore, loading, loadingMore, photos.length, viewMode])

  const toggleSelect = useCallback((id: string) => {
    anchorIdRef.current = id
    setSelected(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }, [])

  // 与 web 端后台一致：普通点击打开详情，Shift+点击 / 复选框负责多选；
  // 已有锚点时 Shift+点击 选中锚点到当前的整段范围
  const handlePhotoClick = useCallback((event: React.MouseEvent, photo: Photo) => {
    if (event.shiftKey) {
      event.preventDefault()
      const list = latestRef.current.photos
      const anchorId = anchorIdRef.current
      if (anchorId && anchorId !== photo.id) {
        const anchorIdx = list.findIndex(p => p.id === anchorId)
        const currentIdx = list.findIndex(p => p.id === photo.id)
        if (anchorIdx !== -1 && currentIdx !== -1) {
          const [start, end] = anchorIdx < currentIdx ? [anchorIdx, currentIdx] : [currentIdx, anchorIdx]
          const rangeIds = list.slice(start, end + 1).map(p => p.id)
          setSelected(prev => new Set([...prev, ...rangeIds]))
          return
        }
      }
      toggleSelect(photo.id)
      return
    }
    setDetailPhoto(photo)
  }, [toggleSelect])

  // 双击卡片：打开全屏大图预览
  const handlePhotoDoubleClick = useCallback((photo: Photo) => {
    setPreviewPhoto(photo)
  }, [])

  // 右侧信息栏按钮：打开完整编辑弹层（info/story 页签）
  const openEditor = useCallback((photo: Photo, mode: 'info' | 'story') => {
    setEditorState({ photo, mode })
  }, [])

  // 详情面板保存后把更新合并回列表（接口 JSON 不含 undefined 键，直接展开安全）
  const handleDetailSave = useCallback((updated: PhotoDto) => {
    setPhotos(prev => prev.map(p => p.id === updated.id ? { ...p, ...updated } as Photo : p))
    setDetailPhoto(prev => prev && prev.id === updated.id ? { ...prev, ...updated } as Photo : prev)
    setEditorState(prev => prev && prev.photo.id === updated.id ? { ...prev, photo: { ...prev.photo, ...updated } as Photo } : prev)
    invalidateAfterLocalMutation(['overview', 'equipment', 'photos', 'albums', 'film-rolls'])
  }, [invalidateAfterLocalMutation])

  // 右侧信息栏始终以列表数据为准（乐观更新/删除后自动同步）
  const sidebarPhoto = useMemo(() => {
    if (!detailPhoto) return null
    return photos.find(p => p.id === detailPhoto.id) ?? detailPhoto
  }, [detailPhoto, photos])

  // 筛选变化/批量删除后若选中照片已不在列表，清空选中
  useEffect(() => {
    if (detailPhoto && !photos.some(p => p.id === detailPhoto.id)) setDetailPhoto(null)
  }, [photos, detailPhoto])

  // 大图预览：←/→ 切换当前已加载照片，接近末尾预取下一页
  const previewIndex = previewPhoto ? photos.findIndex(p => p.id === previewPhoto.id) : -1
  const goPreview = useCallback((direction: 1 | -1) => {
    if (previewIndex === -1) return
    const nextIndex = previewIndex + direction
    if (nextIndex < 0 || nextIndex >= photos.length) return
    setPreviewPhoto(photos[nextIndex])
    if (direction === 1 && nextIndex >= photos.length - 5 && latestRef.current.hasMore && !fetchingRef.current) {
      fetchPhotosRef.current(pageRef.current + 1, true)
    }
  }, [photos, previewIndex])

  const tForPanel = useCallback((key: string) => t(key, language), [language])

  const notifyForPanel = useCallback((message: string, type?: 'success' | 'error' | 'info') => {
    if (type === 'error') toast.error(message)
    else if (type === 'info') toast.info(message)
    else toast.success(message)
  }, [])

  // 乐观更新：先切换本地状态给即时反馈，失败再回滚
  const toggleFeatured = useCallback(async (id: string) => {
    setPhotos(prev => prev.map(p => p.id === id ? { ...p, isFeatured: !p.isFeatured } : p))
    try {
      await (window as any).go.main.App.ToggleFeatured(id)
      invalidateAfterLocalMutation(['overview', 'photos'])
    } catch (err: any) {
      setPhotos(prev => prev.map(p => p.id === id ? { ...p, isFeatured: !p.isFeatured } : p))
      toast.error(err?.message || '更新精选状态失败')
    }
  }, [invalidateAfterLocalMutation])

  const toggleShowFlag = useCallback(async (id: string) => {
    setPhotos(prev => prev.map(p => p.id === id ? { ...p, showFlag: !p.showFlag } : p))
    try {
      await (window as any).go.main.App.ToggleShowFlag(id)
      invalidateAfterLocalMutation(['overview', 'photos'])
    } catch (err: any) {
      setPhotos(prev => prev.map(p => p.id === id ? { ...p, showFlag: !p.showFlag } : p))
      toast.error(err?.message || '更新展示状态失败')
    }
  }, [invalidateAfterLocalMutation])

  // 单张删除：用非阻塞对话框代替原生 confirm（不再冻结整个窗口）
  const requestDeletePhoto = useCallback((photo: Photo) => {
    setDeleteTarget(photo)
  }, [])

  const handleDeleteConfirm = async () => {
    const target = deleteTarget
    if (!target) return
    setDeleteTarget(null)
    const id = target.id
    const toastId = toast.loading('正在删除照片...')
    setDeletingIds(prev => new Set(prev).add(id))
    try {
      await (window as any).go.main.App.DeletePhoto(id, { deleteOriginal: false, deleteThumbnail: true, force: false })
      setPhotos(prev => prev.filter(p => p.id !== id))
      setSelected(prev => { const next = new Set(prev); next.delete(id); return next })
      setDetailPhoto(prev => prev && prev.id === id ? null : prev)
      setPreviewPhoto(prev => prev && prev.id === id ? null : prev)
      setEditorState(prev => prev && prev.photo.id === id ? null : prev)
      setTotal(prev => prev - 1)
      invalidateAfterLocalMutation(['overview', 'equipment', 'photos', 'albums', 'film-rolls', 'stories'])
      toast.success('照片已删除', { id: toastId })
    } catch (err: any) {
      toast.error(err?.message || '删除失败', { id: toastId })
    } finally {
      setDeletingIds(prev => { const next = new Set(prev); next.delete(id); return next })
    }
  }

  // ── 批量操作（底部选中操作条） ─────────────────────

  const handleBatchDelete = async () => {
    if (selected.size === 0 || batchDeleting) return
    const ids = Array.from(selected)
    setBatchDeleteDialogOpen(false)
    const toastId = toast.loading(`正在删除 ${ids.length} 张照片...`)
    setBatchDeleting(true)
    setDeletingIds(prev => new Set([...prev, ...ids]))
    try {
      await (window as any).go.main.App.BatchDeletePhotos({
        photoIds: ids, deleteOriginal: false, deleteThumbnail: true, force: false,
      })
      setSelected(new Set())
      pageRef.current = 1
      await fetchPhotos(1, false)
      invalidateAfterLocalMutation(['overview', 'equipment', 'photos', 'albums', 'film-rolls', 'stories'])
      toast.success('照片已删除', { id: toastId })
    } catch (err: any) {
      toast.error(err?.message || '批量删除失败', { id: toastId })
    } finally {
      setBatchDeleting(false)
      setDeletingIds(prev => {
        const next = new Set(prev)
        ids.forEach(id => next.delete(id))
        return next
      })
    }
  }

  const handleBatchShowFlag = async (show: boolean) => {
    if (selected.size === 0 || batchUpdating) return
    const ids = Array.from(selected)
    setBatchUpdating(true)
    try {
      await (window as any).go.main.App.BatchUpdateShowFlag(ids, show)
      setPhotos(prev => prev.map(p => selected.has(p.id) ? { ...p, showFlag: show } : p))
      invalidateAfterLocalMutation(['overview', 'photos'])
      toast.success(show ? `已将 ${ids.length} 张照片设为展示` : `已将 ${ids.length} 张照片设为隐藏`)
    } catch (err: any) {
      toast.error(err?.message || '批量更新失败')
    } finally {
      setBatchUpdating(false)
    }
  }

  // 全选/取消全选当前已加载的照片
  const toggleSelectAllLoaded = () => {
    setSelected(prev => prev.size === photos.length && photos.length > 0
      ? new Set()
      : new Set(photos.map(p => p.id)))
  }

  // Esc 清除多选（编辑弹层/大图预览/对话框打开时让位）
  useEffect(() => {
    if (selected.size === 0) return
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && !detailPhoto && !editorState && !previewPhoto && !batchDeleteDialogOpen && !deleteTarget) {
        setSelected(new Set())
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [selected.size, detailPhoto, editorState, previewPhoto, batchDeleteDialogOpen, deleteTarget])

  // 右侧信息栏键盘导航：←/→ 切换上一张/下一张选中照片，Esc 取消选中；
  // 输入控件聚焦时不拦截，接近已加载末尾时预取下一页
  useEffect(() => {
    if (!detailPhoto || previewPhoto || editorState) return
    const onKey = (e: KeyboardEvent) => {
      if (batchDeleteDialogOpen || deleteTarget) return
      const target = e.target as HTMLElement | null
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.tagName === 'SELECT' || target.isContentEditable)) return
      if (e.key === 'Escape') {
        setDetailPhoto(null)
        return
      }
      if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return
      const list = latestRef.current.photos
      const idx = list.findIndex(p => p.id === detailPhoto.id)
      if (idx === -1) return
      const nextIdx = e.key === 'ArrowRight' ? idx + 1 : idx - 1
      if (nextIdx < 0 || nextIdx >= list.length) return
      e.preventDefault()
      setDetailPhoto(list[nextIdx])
      if (e.key === 'ArrowRight' && nextIdx >= list.length - 5 && latestRef.current.hasMore && !fetchingRef.current) {
        fetchPhotosRef.current(pageRef.current + 1, true)
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [detailPhoto, previewPhoto, editorState, batchDeleteDialogOpen, deleteTarget])

  const renderPhotoCard = (photo: Photo) => (
    <PhotoGridCard
      key={photo.id}
      photo={photo}
      isSelected={selected.has(photo.id)}
      isDeleting={deletingIds.has(photo.id)}
      language={language}
      viewMode={viewMode}
      onCardClick={handlePhotoClick}
      onCardDoubleClick={handlePhotoDoubleClick}
      onContextOpen={setDetailPhoto}
      onEditDetails={(item) => openEditor(item, 'info')}
      onEditStory={(item) => openEditor(item, 'story')}
      onToggleSelect={toggleSelect}
      onToggleFeatured={toggleFeatured}
      onToggleShow={toggleShowFlag}
      onRequestDelete={requestDeletePhoto}
    />
  )

  const collectionTitle = filters.featured
    ? t('admin.featured', language)
    : filters.albumId
      ? (language === 'zh' ? '相册照片' : 'Album photos')
      : filters.category !== '全部'
        ? filters.category
        : filters.photoType === 'digital'
          ? t('admin.photos_type_digital', language)
          : filters.photoType === 'film'
            ? t('admin.photos_type_film', language)
            : t('admin.resource_library_all_photos', language)

  return (
    <>
      <PageHeader title={collectionTitle} />

      {/* 与本地资源库一致：搜索、筛选、视图和排序集中在内容工具栏。 */}
      <div className="flex min-h-13 shrink-0 flex-wrap items-center gap-2 border-b px-3 py-2" style={{ borderColor: 'var(--border)' }}>
        <div className="relative min-w-0 flex-1">
          <Search size={14} className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2" style={{ color: 'var(--muted-foreground)' }} />
          <input
            type="text"
            placeholder={t('common.search', language)}
            value={searchInput}
            onChange={(event) => setSearchInput(event.target.value)}
            className="h-8 w-full rounded-md border bg-input pl-8 pr-8 text-xs outline-none focus:ring-1"
          />
          {searchInput && <button type="button" onClick={() => setSearchInput('')} className="absolute right-1.5 top-1/2 -translate-y-1/2 rounded p-1"><X size={13} /></button>}
        </div>
        <SelectDropdown
          value={filters.category}
          options={[
            { value: '全部', label: t('common.all', language) },
            ...categories.filter((category) => category !== '全部').map((category) => ({ value: category, label: category })),
          ]}
          onChange={(value) => filters.setCategory(value as string)}
          placeholder={t('common.all', language)}
          ariaLabel={t('ui.category_filter', language)}
          className="w-32 shrink-0"
        />
        <SelectDropdown
          value={filters.photoType || ''}
          options={[
            { value: '', label: language === 'zh' ? '全部类型' : 'All types' },
            { value: 'digital', label: t('admin.photos_type_digital', language) },
            { value: 'film', label: t('admin.photos_type_film', language) },
          ]}
          onChange={(value) => filters.setPhotoType((value as string) || null)}
          placeholder={language === 'zh' ? '全部类型' : 'All types'}
          ariaLabel={language === 'zh' ? '照片类型' : 'Photo type'}
          className="w-28 shrink-0"
        />
        <div className="flex h-8 shrink-0 items-center rounded-md border bg-input p-0.5">
          <button type="button" onClick={() => setViewMode('crop')} title={language === 'zh' ? '裁切填充' : 'Cropped view'} aria-label={language === 'zh' ? '裁切填充' : 'Cropped view'} className="flex size-7 items-center justify-center rounded" style={{ backgroundColor: viewMode === 'crop' ? 'var(--secondary)' : undefined }}><LayoutGrid size={13} /></button>
          <button type="button" onClick={() => setViewMode('fit')} title={language === 'zh' ? '适应显示' : 'Fitted view'} aria-label={language === 'zh' ? '适应显示' : 'Fitted view'} className="flex size-7 items-center justify-center rounded" style={{ backgroundColor: viewMode === 'fit' ? 'var(--secondary)' : undefined }}><Maximize2 size={13} /></button>
          <button type="button" onClick={() => setViewMode('masonry')} title={language === 'zh' ? '瀑布流' : 'Masonry view'} aria-label={language === 'zh' ? '瀑布流' : 'Masonry view'} className="flex size-7 items-center justify-center rounded" style={{ backgroundColor: viewMode === 'masonry' ? 'var(--secondary)' : undefined }}><Columns3 size={13} /></button>
        </div>
        <SelectDropdown
          value={filters.sortBy}
          options={[
            { value: 'createdAt', label: language === 'zh' ? '上传时间' : 'Uploaded' },
            { value: 'takenAt', label: language === 'zh' ? '拍摄时间' : 'Captured' },
          ]}
          onChange={(value) => filters.setSortBy(value as 'createdAt' | 'takenAt')}
          ariaLabel={language === 'zh' ? '排序' : 'Sort'}
          className="w-28 shrink-0"
        />
        <button type="button" onClick={() => filters.setSortOrder(filters.sortOrder === 'asc' ? 'desc' : 'asc')} title={filters.sortOrder === 'asc' ? (language === 'zh' ? '升序' : 'Ascending') : (language === 'zh' ? '降序' : 'Descending')} aria-label={filters.sortOrder === 'asc' ? (language === 'zh' ? '升序' : 'Ascending') : (language === 'zh' ? '降序' : 'Descending')} className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md border bg-input hover:bg-secondary">{filters.sortOrder === 'asc' ? <ArrowUp size={13} /> : <ArrowDown size={13} />}</button>
      </div>

      {/* 与本地资源库一致：中间浏览工作区 + 底部状态栏 + 右侧详情栏。 */}
      <div className="flex min-h-0 flex-1">
        <main className="flex min-w-0 flex-1 flex-col">
        <div ref={scrollRef} className="custom-scrollbar min-h-0 flex-1 overflow-auto px-3 pb-4" onScroll={handleScroll}>
        <div className="sticky top-0 z-10 flex h-8 items-center justify-between gap-3 bg-background/90 text-[10px] backdrop-blur" style={{ color: 'var(--muted-foreground)' }}>
          <div className="flex min-w-0 items-center gap-2"><span className="flex size-5 shrink-0 items-center justify-center rounded bg-secondary" style={{ color: 'var(--foreground)' }}><LayoutGrid size={11} /></span><span className="truncate font-medium" style={{ color: 'var(--foreground)' }}>{collectionTitle}</span></div>
          <span className="shrink-0 rounded bg-secondary px-2 py-0.5 tabular-nums">{total.toLocaleString()} {t('admin.photos', language)}</span>
        </div>
        {loading ? (
          <ThumbGridSkeleton count={15} cols={Math.max(2, Math.floor(900 / gridSize))} aspectClassName="aspect-[5/4]" gapClassName="gap-2.5" />
        ) : photos.length === 0 && loadError ? (
          <div className="flex h-full flex-col items-center justify-center gap-3" style={{ color: 'var(--muted-foreground)' }}>
            <span className="text-sm">{loadError}</span>
            <button onClick={() => fetchPhotos(1, false)} className="flex items-center gap-1.5 rounded-md border px-3 py-1.5 text-xs" style={{ borderColor: 'var(--border)', color: 'var(--foreground)' }}><RefreshCw size={14} /> {t('common.retry', language)}</button>
          </div>
        ) : photos.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center gap-3">
            <div className="flex h-12 w-12 items-center justify-center rounded-lg" style={{ backgroundColor: 'var(--muted)' }}><ImageOff size={20} style={{ color: 'var(--muted-foreground)' }} /></div>
            <p className="text-sm" style={{ color: 'var(--muted-foreground)' }}>{t('admin.no_photos', language)}</p>
            <button onClick={() => navigate('/upload')} className="rounded-md px-3 py-1.5 text-xs font-medium transition-opacity hover:opacity-90" style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>{t('admin.upload', language)}</button>
          </div>
        ) : (
          <>
            {viewMode === 'masonry' ? (
              <div className="flex w-full items-start" style={{ gap: MASONRY_COLUMN_GAP }}>
                {masonryColumns.map((columnPhotos, columnIndex) => (
                  <div key={columnIndex} className="min-w-0 flex-1">
                    {columnPhotos.map(renderPhotoCard)}
                  </div>
                ))}
              </div>
            ) : (
              <div
                className="grid gap-2.5"
                style={{ gridTemplateColumns: `repeat(auto-fill, minmax(${gridSize}px, 1fr))` }}
              >
                {photos.map(renderPhotoCard)}
              </div>
            )}
            {loadingMore && <div className="flex items-center justify-center gap-2 py-5 text-xs" style={{ color: 'var(--muted-foreground)' }}><Loader2 size={14} className="animate-spin" />{language === 'zh' ? '加载中...' : 'Loading...'}</div>}
            {!hasMore && photos.length > 0 && <div className="py-4 text-center text-xs" style={{ color: 'var(--muted-foreground)' }}>{language === 'zh' ? `已加载全部 ${total} 张照片` : `All ${total} photos loaded`}</div>}
          </>
        )}

        {/* 保留原有多选交互：照片区域底部悬浮操作栏。 */}
        {selected.size > 0 && (
          <div className="sticky bottom-4 z-20 mt-4 flex justify-center pointer-events-none">
            <div className="pointer-events-auto flex items-center gap-0.5 rounded-lg border px-1.5 py-1.5 shadow-lg" style={{ backgroundColor: 'var(--card)', borderColor: 'var(--border)' }}>
              <span className="whitespace-nowrap px-2 text-xs font-medium">{t('admin.selected', language)} {selected.size}</span>
              <div className="mx-0.5 h-4 w-px" style={{ backgroundColor: 'var(--border)' }} />
              <button onClick={toggleSelectAllLoaded} title={selected.size === photos.length ? (language === 'zh' ? '取消全选' : 'Deselect all') : (language === 'zh' ? '全选已加载' : 'Select loaded')} className="rounded-md p-1.5 transition-colors hover:opacity-80" style={{ backgroundColor: selected.size === photos.length ? 'var(--accent)' : 'transparent', color: selected.size === photos.length ? 'var(--accent-foreground)' : 'var(--muted-foreground)' }}><CheckSquare size={15} /></button>
              <button onClick={() => handleBatchShowFlag(true)} disabled={batchUpdating} title={language === 'zh' ? '设为展示' : 'Show in gallery'} className="rounded-md p-1.5 hover:opacity-80 disabled:cursor-wait disabled:opacity-50" style={{ color: 'var(--muted-foreground)' }}>{batchUpdating ? <Loader2 size={15} className="animate-spin" /> : <Eye size={15} />}</button>
              <button onClick={() => handleBatchShowFlag(false)} disabled={batchUpdating} title={language === 'zh' ? '设为隐藏' : 'Hide from gallery'} className="rounded-md p-1.5 hover:opacity-80 disabled:cursor-wait disabled:opacity-50" style={{ color: 'var(--muted-foreground)' }}><EyeOff size={15} /></button>
              <button onClick={() => setBatchDeleteDialogOpen(true)} disabled={batchDeleting} title={t('admin.delete_selected', language)} className="rounded-md p-1.5 hover:opacity-80 disabled:cursor-wait disabled:opacity-50" style={{ color: 'var(--destructive)' }}>{batchDeleting ? <Loader2 size={15} className="animate-spin" /> : <Trash2 size={15} />}</button>
              <div className="mx-0.5 h-4 w-px" style={{ backgroundColor: 'var(--border)' }} />
              <button onClick={() => setSelected(new Set())} title={`${t('common.cancel', language)} (Esc)`} className="rounded-md p-1.5 hover:opacity-80" style={{ color: 'var(--muted-foreground)' }}><X size={15} /></button>
            </div>
          </div>
        )}

        <div ref={loadMoreSentinelRef} className="h-px w-full" aria-hidden="true" />
        </div>

        <div className="flex min-h-10 shrink-0 items-center gap-3 border-t px-4" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
          <div className="flex min-w-0 flex-1 items-center gap-2 overflow-hidden whitespace-nowrap text-[11px]" style={{ color: 'var(--muted-foreground)' }}>
            <span>{photos.length.toLocaleString()} / {total.toLocaleString()} {t('admin.photos', language)}</span>
          </div>
          <button type="button" disabled={loading} onClick={() => fetchPhotos(1, false)} className="flex items-center gap-1.5 rounded px-2 py-1 text-[10px] hover:bg-secondary disabled:cursor-wait disabled:opacity-50"><RefreshCw size={11} className={loading ? 'animate-spin' : ''} />{t('common.refresh', language)}</button>
          <div className="ml-1 flex shrink-0 items-center gap-2 border-l pl-3" style={{ borderColor: 'var(--border)' }}>
            <Minus size={11} style={{ color: 'var(--muted-foreground)' }} />
            <input type="range" min={MIN_PHOTO_GRID_SIZE} max={MAX_PHOTO_GRID_SIZE} step={8} value={gridSize} onChange={(event) => setPhotoGridSize(Number(event.target.value))} aria-label={language === 'zh' ? '网格缩放' : 'Grid zoom'} title={language === 'zh' ? '网格缩放' : 'Grid zoom'} className="h-1 w-28 cursor-pointer accent-current" />
            <Plus size={11} style={{ color: 'var(--muted-foreground)' }} />
            <span className="w-8 text-right text-[9px] tabular-nums" style={{ color: 'var(--muted-foreground)' }}>{Math.round(gridSize / 176 * 100)}%</span>
          </div>
        </div>
        </main>

        <PhotoInfoSidebar
          photo={sidebarPhoto}
          token={token}
          t={tForPanel}
          notify={notifyForPanel}
          onOpenPreview={handlePhotoDoubleClick}
          onEditDetails={(photo) => openEditor(photo, 'info')}
          onEditStory={(photo) => openEditor(photo, 'story')}
          onToggleFeatured={toggleFeatured}
          onToggleShow={toggleShowFlag}
          onDelete={requestDeletePhoto}
          onSave={handleDetailSave}
          onUnauthorized={logout}
        />
      </div>

      <SimpleDeleteDialog
        isOpen={batchDeleteDialogOpen}
        title={t('common.batchDelete', language)}
        message={t('admin.photos_batch_delete_confirm', language, { count: selected.size })}
        onConfirm={handleBatchDelete}
        onCancel={() => setBatchDeleteDialogOpen(false)}
        t={(key) => t(key, language)}
      />

      <SimpleDeleteDialog
        isOpen={!!deleteTarget}
        message={t('admin.photos_delete_confirm', language)}
        onConfirm={handleDeleteConfirm}
        onCancel={() => setDeleteTarget(null)}
        t={(key) => t(key, language)}
      />

      {/* 完整编辑/叙事弹层（从右侧信息栏打开） */}
      <PhotoDetailPanel
        photo={editorState ? (editorState.photo as unknown as PhotoDto) : null}
        isOpen={!!editorState}
        initialTab={editorState?.mode}
        categories={categories}
        allPhotos={photos as unknown as PhotoDto[]}
        token={token}
        onClose={() => setEditorState(null)}
        onSave={handleDetailSave}
        onUnauthorized={logout}
        t={tForPanel}
        notify={notifyForPanel}
      />

      {/* 大图预览（双击卡片/点击侧栏缩略图打开） */}
      {previewPhoto && (
        <PhotoPreviewOverlay
          photo={previewPhoto}
          t={tForPanel}
          onClose={() => setPreviewPhoto(null)}
          onPrevious={() => goPreview(-1)}
          onNext={() => goPreview(1)}
          hasPrevious={previewIndex > 0}
          hasNext={previewIndex >= 0 && previewIndex < photos.length - 1}
        />
      )}
    </>
  )
}

import { useState, useEffect, useCallback, useRef } from 'react'
import { toast } from 'sonner'
import { PageHeader } from '@/components/layout/PageHeader'
import {
  clearCloudLibraryPageCache,
  clearDesktopRuntimeCache,
  clearEquipmentCache,
  clearOverviewPageCache,
  getDesktopCacheSnapshot,
} from '@/lib/app-cache'
import { clearCurrentPersistentCache, getCurrentPersistentCacheScope } from '@/lib/persistent-cache'
import { useAuth } from '@/contexts/AuthContext'
import { usePreferences } from '@/store/preferences'
import { t } from '@/lib/i18n'
import { formatBytes } from '@/lib/utils'
import { Skeleton } from '@/components/admin/Skeleton'
import { ClearLocalLibraryPreviewCache, GetAiConfig, GetLocalLibraryCacheStats, GetLocalLibraryPreferences, GetStoryAiProviderModels, SetLocalLibraryImportMode, UpdateAiConfig } from '../../wailsjs/go/main/App'
import { config as wailsConfig, local_library } from '../../wailsjs/go/models'
import { version } from '../../package.json'
import { BrowserOpenURL } from '../../wailsjs/runtime/runtime'
import { getWindowAppearance, restartApplication, updateWindowStyle, type WindowAppearance, type WindowStyle } from '@/lib/window-appearance'
import {
  Settings, Info,
  Save, Loader2, HardDrive, MessageSquare, User, Server, RefreshCw,
  Pencil, Trash2, Plus, X, Check, Cloud,
  Unlink, Link, Sparkles, Eye, EyeOff,
  FileText, Trash, Filter, FolderOpen, FolderInput, Copy, Database, Image as ImageIcon,
  Github, ExternalLink, LayoutDashboard, Images, ChevronRight,
  AppWindow, Monitor, Moon, Palette, Sun,
} from 'lucide-react'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import { SelectDropdown } from '@/components/ui/SelectDropdown'

// ─── 与 Web 端一致的 5 个标签 ────────────────────────

type Tab = 'site' | 'appearance' | 'storage' | 'local-library' | 'comments' | 'account' | 'ai' | 'log' | 'cache' | 'about'
type CommentsSubTab = 'manage' | 'config'

const OFFLINE_SETTINGS_TABS = new Set<Tab>(['appearance', 'local-library', 'ai', 'log', 'cache', 'about'])

export function SettingsPage() {
  const { isAuthenticated } = useAuth()
  const { language } = usePreferences()
  const [tab, setTab] = useState<Tab>(() => isAuthenticated ? 'site' : 'appearance')
  const [config, setConfig] = useState<Record<string, string>>({})
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [dirty, setDirty] = useState(false)
  const activeTab = isAuthenticated || OFFLINE_SETTINGS_TABS.has(tab) ? tab : 'appearance'

  const fetchSettings = useCallback(async () => {
    if (!isAuthenticated) {
      setConfig({})
      setLoading(false)
      return
    }

    setLoading(true)
    try {
      const result = await (window as any).go.main.App.GetSettings()
      setConfig(result || {})
    } catch (err) {
      console.error('获取设置失败:', err)
    } finally {
      setLoading(false)
    }
  }, [isAuthenticated])

  useEffect(() => { void fetchSettings() }, [fetchSettings])

  const updateConfig = (key: string, value: string) => {
    setConfig(prev => ({ ...prev, [key]: value }))
    setDirty(true)
  }

  const handleSave = async () => {
    if (!isAuthenticated) return
    setSaving(true)
    try {
      const result = await (window as any).go.main.App.UpdateSettings(config)
      setConfig(result || {})
      setDirty(false)
      toast.success('设置已保存')
    } catch (error: unknown) {
      toast.error('保存失败: ' + getErrorMessage(error))
    } finally {
      setSaving(false)
    }
  }

  const tabs = ([
    { key: 'site', label: '站点', icon: Server },
    { key: 'appearance', label: '外观', icon: Palette },
    { key: 'storage', label: '存储', icon: HardDrive },
    { key: 'local-library', label: '本地资源库', icon: FolderOpen },
    { key: 'comments', label: '评论', icon: MessageSquare },
    { key: 'account', label: '账户', icon: User },
    { key: 'ai', label: '模型配置', icon: Sparkles },
    { key: 'log', label: '日志', icon: FileText },
    { key: 'cache', label: '缓存', icon: Database },
    { key: 'about', label: '关于', icon: Info },
  ] satisfies { key: Tab; label: string; icon: typeof Settings }[]).filter(({ key }) => isAuthenticated || OFFLINE_SETTINGS_TABS.has(key))

  // site 与 comments/config 标签有保存按钮（其他标签要么只读要么有独立保存）
  const showSaveButton = isAuthenticated && (activeTab === 'comments' || activeTab === 'site')

  return (
    <>
      <PageHeader
        title={t('admin.page_settings', language)}
        actions={dirty && showSaveButton ? (
          <button onClick={handleSave} disabled={saving}
            className={btnPrimary}
            style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
            {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
            {saving ? '保存中...' : t('common.save', language)}
          </button>
        ) : undefined}
      />

      <div className="flex flex-1 overflow-hidden">
        {/* 左侧标签栏 */}
        <div className="flex w-48 shrink-0 flex-col overflow-hidden border-r p-3" style={{ borderColor: 'var(--border)' }}>
          <div className="custom-scrollbar min-h-0 flex-1 space-y-0.5 overflow-y-auto">
            {tabs.map(({ key, label, icon: Icon }) => (
              <button key={key} onClick={() => setTab(key)}
                className="flex w-full items-center gap-2 rounded-md px-3 py-2 text-sm transition-colors hover:bg-secondary"
                style={{
                  backgroundColor: activeTab === key ? 'var(--accent)' : 'transparent',
                  color: activeTab === key ? 'var(--accent-foreground)' : 'var(--muted-foreground)',
                }}>
                <Icon size={16} />
                {label}
              </button>
            ))}
          </div>

        </div>

        {/* 右侧内容 */}
        <div className={activeTab === 'ai' || activeTab === 'cache' ? 'flex-1 overflow-hidden' : 'flex-1 overflow-auto p-6'}>
          {loading ? (
            <div className="max-w-2xl space-y-6">
              <Skeleton className="h-4 w-20" />
              <Skeleton className="h-9 w-full" />
              <Skeleton className="h-4 w-16" />
              <Skeleton className="h-9 w-full" />
              <Skeleton className="h-4 w-24" />
              <Skeleton className="h-9 w-full" />
            </div>
          ) : activeTab === 'ai' ? (
            <div className="h-full min-h-0">
              <AiTab />
            </div>
          ) : activeTab === 'cache' ? (
            <div className="h-full min-h-0">
              <CacheTab />
            </div>
          ) : (
            <div className="max-w-2xl">
              {activeTab === 'site' && <SiteTab config={config} updateConfig={updateConfig} />}
              {activeTab === 'appearance' && <AppearanceTab />}
              {activeTab === 'storage' && <StorageTab />}
              {activeTab === 'local-library' && <LocalLibraryTab onManageCache={() => setTab('cache')} />}
              {activeTab === 'comments' && <CommentsTab config={config} updateConfig={updateConfig} />}
              {activeTab === 'account' && <AccountTab />}
              {activeTab === 'log' && <LogTab />}
              {activeTab === 'about' && <AboutTab />}
            </div>
          )}
        </div>
      </div>
    </>
  )
}

// ─── Tab 1: 站点（与 Web 端一致：site_title 和 cdn_domain 只读） ──

function SiteTab({ config }: {
  config: Record<string, string>
  updateConfig: (key: string, value: string) => void
}) {
  return (
    <div className="space-y-6">
      <Section title="站点信息">
        <Field label="站点标题" description="通过 .env 文件中的 SITE_TITLE 配置">
          <input type="text" value={config.site_title || ''} disabled
            className={`${inputClass} cursor-not-allowed opacity-60`}
            style={inputStyle} />
        </Field>
        <Field label="CDN 域名" description="通过 .env 文件中的 CDN_DOMAIN 配置">
          <input type="text" value={config.cdn_domain || ''} disabled
            className={`${inputClass} cursor-not-allowed opacity-60`}
            style={inputStyle} />
        </Field>
      </Section>
    </div>
  )
}

// ─── Tab 2: 外观 ─────────────────────────────────────

const themeChoices = [
  { value: 'light' as const, label: '浅色', icon: Sun },
  { value: 'dark' as const, label: '深色', icon: Moon },
  { value: 'system' as const, label: '跟随系统', icon: Monitor },
]

const windowStyleChoices: { value: WindowStyle; label: string; description: string }[] = [
  { value: 'native', label: '原生', description: '使用操作系统提供的标题栏与窗口控制按钮。' },
  { value: 'integrated', label: '一体化', description: '使用与应用界面一致的紧凑标题栏和窗口控制按钮。' },
]

function AppearanceTab() {
  const { theme, setTheme, language } = usePreferences()
  const [appearance, setAppearance] = useState<WindowAppearance | null>(null)
  const [loading, setLoading] = useState(true)
  const [savingStyle, setSavingStyle] = useState<WindowStyle | null>(null)
  const [restartDialogOpen, setRestartDialogOpen] = useState(false)

  useEffect(() => {
    let cancelled = false
    getWindowAppearance()
      .then((result) => {
        if (!cancelled) setAppearance(result)
      })
      .catch((error: unknown) => {
        if (!cancelled) toast.error('读取窗口外观失败: ' + getErrorMessage(error))
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => { cancelled = true }
  }, [])

  const handleWindowStyleChange = async (style: WindowStyle) => {
    if (savingStyle || appearance?.configuredStyle === style) return
    setSavingStyle(style)
    try {
      const result = await updateWindowStyle(style)
      setAppearance(result)
      if (result.activeStyle === result.configuredStyle) {
        toast.success('窗口风格已保存')
      } else {
        setRestartDialogOpen(true)
      }
    } catch (error: unknown) {
      toast.error('保存窗口风格失败: ' + getErrorMessage(error))
    } finally {
      setSavingStyle(null)
    }
  }

  const handleRestartConfirm = async () => {
    toast.success('正在重新加载窗口…')
    try {
      await restartApplication()
      setRestartDialogOpen(false)
    } catch (error: unknown) {
      toast.error('自动切换窗口风格失败: ' + getErrorMessage(error))
    }
  }

  const handleRestartCancel = () => {
    setRestartDialogOpen(false)
    toast.info('窗口风格已保存，将在下次启动时生效')
  }

  const configuredStyle = appearance?.configuredStyle ?? 'native'
  const restartRequired = Boolean(appearance && appearance.activeStyle !== appearance.configuredStyle)

  return (
    <div className="space-y-6">
      <Section title="主题" description="调整应用界面的明暗外观，修改后立即生效。">
        <div className="flex h-10 items-center rounded-md border bg-background p-0.5" role="radiogroup" aria-label="主题">
          {themeChoices.map(({ value, label, icon: Icon }) => {
            const selected = theme === value
            return (
              <button
                key={value}
                type="button"
                role="radio"
                aria-checked={selected}
                onClick={() => setTheme(value)}
                className="flex h-8 min-w-0 flex-1 items-center justify-center gap-2 rounded px-3 text-xs font-medium transition-colors hover:bg-secondary focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
                style={{
                  backgroundColor: selected ? 'var(--accent)' : 'transparent',
                  color: selected ? 'var(--accent-foreground)' : 'var(--muted-foreground)',
                }}
              >
                <Icon size={14} />
                <span className="truncate">{label}</span>
              </button>
            )
          })}
        </div>
      </Section>

      <Section title="窗口风格" description="窗口边框由桌面运行时创建，保存后会询问是否立即重启以应用新的外观。">
        {loading ? (
          <div className="space-y-2">
            <Skeleton className="h-16 w-full rounded-md" />
            <Skeleton className="h-16 w-full rounded-md" />
          </div>
        ) : (
          <div className="divide-y border-y" role="radiogroup" aria-label="窗口风格" style={{ borderColor: 'var(--border)' }}>
            {windowStyleChoices.map(({ value, label, description }) => {
              const selected = configuredStyle === value
              const saving = savingStyle === value
              return (
                <button
                  key={value}
                  type="button"
                  role="radio"
                  aria-checked={selected}
                  disabled={savingStyle !== null}
                  onClick={() => void handleWindowStyleChange(value)}
                  className="flex w-full items-center gap-3 px-2 py-3 text-left transition-colors hover:bg-secondary disabled:cursor-wait disabled:opacity-60"
                >
                  <span className="flex size-9 shrink-0 items-center justify-center rounded-md" style={{ backgroundColor: 'var(--muted)' }}>
                    {value === 'native' ? <Monitor size={16} /> : <AppWindow size={16} />}
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block text-xs font-medium">{label}</span>
                    <span className="mt-0.5 block text-[11px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{description}</span>
                  </span>
                  {saving ? <Loader2 size={14} className="shrink-0 animate-spin" /> : selected ? <Check size={14} className="shrink-0" /> : null}
                </button>
              )
            })}
          </div>
        )}

        {restartRequired && (
          <div className="flex items-start gap-2 rounded-md border px-3 py-2.5 text-[11px] leading-5" role="status" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--muted)', color: 'var(--muted-foreground)' }}>
            <Info size={14} className="mt-0.5 shrink-0" />
            <span>当前窗口仍使用“{appearance?.activeStyle === 'integrated' ? '一体化' : '原生'}”风格；已保存的“{configuredStyle === 'integrated' ? '一体化' : '原生'}”风格将在下次启动时生效。</span>
          </div>
        )}
      </Section>

      <SimpleDeleteDialog
        isOpen={restartDialogOpen}
        title="应用窗口风格"
        message={`窗口风格已保存为“${configuredStyle === 'integrated' ? '一体化' : '原生'}”。是否立即重启 MO Gallery Desktop 以应用新风格？`}
        confirmLabel="立即重启"
        cancelLabel="稍后重启"
        pendingLabel="正在重启..."
        confirmIcon="refresh"
        confirmVariant="primary"
        onConfirm={handleRestartConfirm}
        onCancel={handleRestartCancel}
        t={(key) => t(key, language)}
      />
    </div>
  )
}

// ─── 本地资源库 ──────────────────────────────────────

type LocalLibraryCacheInfo = {
  loading: boolean
  stats: local_library.LocalLibraryCacheStats | null
  error: string | null
}

function useLocalLibraryCacheInfo() {
  const [cacheInfo, setCacheInfo] = useState<LocalLibraryCacheInfo>({ loading: true, stats: null, error: null })
  const requestIdRef = useRef(0)

  const refresh = useCallback(async () => {
    const requestId = ++requestIdRef.current
    setCacheInfo(prev => ({ ...prev, loading: true, error: null }))
    try {
      const stats = await GetLocalLibraryCacheStats()
      if (requestId !== requestIdRef.current) return
      setCacheInfo({ loading: false, stats, error: null })
    } catch (error: unknown) {
      if (requestId !== requestIdRef.current) return
      setCacheInfo({
        loading: false,
        stats: null,
        error: error instanceof Error ? error.message : '本地资源库不可用',
      })
    }
  }, [])

  useEffect(() => {
    void refresh()
    return () => { requestIdRef.current += 1 }
  }, [refresh])
  return { ...cacheInfo, refresh }
}

function LocalLibraryTab({ onManageCache }: { onManageCache: () => void }) {
  const [importMode, setImportMode] = useState<'copy' | 'move' | undefined>()
  const [preferencesLoading, setPreferencesLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const localCacheInfo = useLocalLibraryCacheInfo()

  useEffect(() => {
    let active = true
    GetLocalLibraryPreferences()
      .then((result) => {
        if (!active) return
        setImportMode(result?.importMode === 'copy' || result?.importMode === 'move' ? result.importMode : undefined)
      })
      .catch((error) => toast.error('读取本地资源库设置失败: ' + getErrorMessage(error)))
      .finally(() => { if (active) setPreferencesLoading(false) })
    return () => { active = false }
  }, [])

  const chooseMode = async (mode: 'copy' | 'move') => {
    if (saving || mode === importMode) return
    setSaving(true)
    try {
      const result = await SetLocalLibraryImportMode(mode)
      setImportMode(result.importMode === 'copy' || result.importMode === 'move' ? result.importMode : mode)
      toast.success('本地资源库导入方式已更新')
    } catch (error) {
      toast.error('保存失败: ' + getErrorMessage(error))
    } finally {
      setSaving(false)
    }
  }

  const stats = localCacheInfo.stats

  return (
    <div className="space-y-6">
      <Section title="本地资源库">
        <Field label="应用内导入方式" description="选择或拖入库外照片时使用。系统文件资源管理器中的复制、移动操作不受此设置影响。">
          {preferencesLoading ? (
            <div className="flex h-20 items-center justify-center"><Loader2 size={16} className="animate-spin" /></div>
          ) : (
            <div className="grid gap-3 sm:grid-cols-2">
              <button type="button" disabled={saving} onClick={() => chooseMode('copy')}
                className="rounded-lg border p-4 text-left transition-colors hover:bg-secondary disabled:opacity-50"
                style={{ borderColor: importMode === 'copy' ? 'var(--primary)' : 'var(--border)', backgroundColor: importMode === 'copy' ? 'var(--accent)' : undefined }}>
                <span className="flex items-center gap-2 text-sm font-medium"><Copy size={16} />复制到资源库{importMode === 'copy' && <Check size={15} style={{ color: 'var(--primary)' }} />}</span>
                <span className="mt-2 block text-xs leading-5" style={{ color: 'var(--muted-foreground)' }}>保留库外源文件，库内副本成为资源库管理的文件。</span>
              </button>
              <button type="button" disabled={saving} onClick={() => chooseMode('move')}
                className="rounded-lg border p-4 text-left transition-colors hover:bg-secondary disabled:opacity-50"
                style={{ borderColor: importMode === 'move' ? 'var(--primary)' : 'var(--border)', backgroundColor: importMode === 'move' ? 'var(--accent)' : undefined }}>
                <span className="flex items-center gap-2 text-sm font-medium"><FolderInput size={16} />移动到资源库{importMode === 'move' && <Check size={15} style={{ color: 'var(--primary)' }} />}</span>
                <span className="mt-2 block text-xs leading-5" style={{ color: 'var(--muted-foreground)' }}>确认安全写入资源库后，从原位置移除源文件。</span>
              </button>
            </div>
          )}
          {!preferencesLoading && !importMode && <p className="mt-2 text-xs" style={{ color: 'var(--muted-foreground)' }}>尚未选择。首次导入照片时会提示选择。</p>}
        </Field>
      </Section>

      <Section title="存储占用" description="统计当前资源库的 .mo-gallery 保留目录。资源库数据不可再生，不会被缓存清理删除。">
        <div className="flex items-center justify-between gap-3">
          <p className="text-[11px] leading-5" style={{ color: 'var(--muted-foreground)' }}>
            缩略图与大图预览可由原文件重新生成；数据库、清单、备份和回收站属于资源库数据。
          </p>
          <button type="button" onClick={() => void localCacheInfo.refresh()} disabled={localCacheInfo.loading}
            className={`${btnOutline} shrink-0`} title="重新统计存储占用">
            <RefreshCw size={13} className={localCacheInfo.loading ? 'animate-spin' : ''} />
            重新统计
          </button>
        </div>

        {localCacheInfo.loading ? (
          <div className="space-y-2">
            <Skeleton className="h-14 w-full rounded-md" />
            <Skeleton className="h-14 w-full rounded-md" />
            <Skeleton className="h-14 w-full rounded-md" />
          </div>
        ) : stats ? (
          <div className="divide-y border-y" style={{ borderColor: 'var(--border)' }}>
            <StorageUsageRow icon={HardDrive} label=".mo-gallery 总占用" value={formatBytes(stats.internal.bytes)} detail={`${stats.internal.fileCount} 个文件`} />
            <StorageUsageRow icon={Database} label="资源库数据" value={formatBytes(stats.libraryData.bytes)} detail={`${stats.libraryData.fileCount} 个文件 · 不可作为缓存清理`} />
            <StorageUsageRow icon={Images} label="网格缩略图" value={formatBytes(stats.thumbnails.bytes)} detail={`${stats.thumbnails.fileCount} 个文件 · 长期保留以保证浏览速度`} />
            <StorageUsageRow icon={ImageIcon} label="大图预览" value={formatBytes(stats.previews.bytes)} detail={`${stats.previews.fileCount} 个文件 · 空间上限 ${formatBytes(stats.previewLimitBytes)}`} />
          </div>
        ) : (
          <div className="rounded-md border border-dashed px-4 py-6 text-center" style={{ borderColor: 'var(--border)' }}>
            <p className="text-xs font-medium">当前未打开本地资源库</p>
            <p className="mt-1 text-[11px]" style={{ color: 'var(--muted-foreground)' }}>{localCacheInfo.error || '打开资源库后可查看实际磁盘占用。'}</p>
          </div>
        )}

        <div className="flex justify-end">
          <button type="button" onClick={onManageCache} className={btnOutline}>
            <Database size={13} />
            管理缓存
            <ChevronRight size={13} />
          </button>
        </div>
      </Section>
    </div>
  )
}

function StorageUsageRow({ icon: Icon, label, value, detail }: {
  icon: typeof Database
  label: string
  value: string
  detail: string
}) {
  return (
    <div className="flex min-h-14 items-center gap-3 py-3">
      <span className="flex size-8 shrink-0 items-center justify-center rounded-md" style={{ backgroundColor: 'var(--muted)' }}>
        <Icon size={15} style={{ color: 'var(--muted-foreground)' }} />
      </span>
      <div className="min-w-0 flex-1">
        <p className="text-xs font-medium">{label}</p>
        <p className="mt-0.5 text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{detail}</p>
      </div>
      <span className="shrink-0 text-xs font-medium tabular-nums">{value}</span>
    </div>
  )
}

// ─── Tab 3: 存储（StorageSource CRUD） ─────────────────

interface StorageSource {
  id: string
  name: string
  type: string
  accessKey?: string
  secretKey?: string
  bucket?: string
  region?: string
  endpoint?: string
  publicUrl?: string
  basePath?: string
  branch?: string
  accessMethod?: string
}

const STORAGE_TYPE_META: Record<string, { label: string; icon: typeof HardDrive }> = {
  local: { label: '本地存储', icon: HardDrive },
  github: { label: 'GitHub', icon: Github },
  s3: { label: 'S3/R2', icon: Cloud },
}

function storageTypeMeta(type: string) {
  return STORAGE_TYPE_META[type] || { label: type, icon: Database }
}

function StorageTab() {
  const { language } = usePreferences()
  const [sources, setSources] = useState<StorageSource[]>([])
  const [loading, setLoading] = useState(false)
  const [editingId, setEditingId] = useState<string | null>(null)
  const [adding, setAdding] = useState<string | null>(null) // 'local' | 'github' | 's3'
  const [deleteTarget, setDeleteTarget] = useState<StorageSource | null>(null)

  const fetchSources = useCallback(async () => {
    setLoading(true)
    try {
      const result = await (window as any).go.main.App.GetStorageSources()
      setSources(result || [])
    } catch {} finally { setLoading(false) }
  }, [])

  useEffect(() => { fetchSources() }, [fetchSources])

  const confirmDelete = async () => {
    if (!deleteTarget) return
    try {
      await (window as any).go.main.App.DeleteStorageSource(deleteTarget.id)
      toast.success('已删除')
      setDeleteTarget(null)
      fetchSources()
    } catch (err: any) {
      toast.error(err?.message || '删除失败')
    }
  }

  const addActions = [
    { type: 'local' as const, label: '添加本地存储', icon: HardDrive },
    { type: 'github' as const, label: '添加 GitHub', icon: Github },
    { type: 's3' as const, label: '添加 S3/R2', icon: Cloud },
  ]

  return (
    <div className="space-y-6">
      <Section title="存储源">
        <p className="text-xs leading-5" style={{ color: 'var(--muted-foreground)' }}>
          配置照片原图与缩略图的存储位置，支持本地目录、GitHub 仓库或 S3/R2 兼容服务。
        </p>
        {loading ? (
          <div className="space-y-3">
            <Skeleton className="h-14 w-full rounded-lg" />
            <Skeleton className="h-14 w-full rounded-lg" />
          </div>
        ) : (
          <div className="space-y-3">
            {sources.length === 0 && !adding && (
              <div className="flex flex-col items-center gap-2 rounded-lg border border-dashed px-6 py-10 text-center" style={{ borderColor: 'var(--border)' }}>
                <span className="flex size-12 items-center justify-center rounded-full" style={{ backgroundColor: 'var(--muted)' }}>
                  <Database size={22} style={{ color: 'var(--muted-foreground)' }} />
                </span>
                <p className="text-sm font-medium">暂无存储源</p>
                <p className="max-w-sm text-xs leading-5" style={{ color: 'var(--muted-foreground)' }}>
                  添加本地目录、GitHub 仓库或 S3/R2 兼容存储，用于保存照片原图与缩略图。
                </p>
              </div>
            )}

            {sources.map(source => (
              <StorageSourceCard
                key={source.id}
                source={source}
                isEditing={editingId === source.id}
                onEdit={() => { setEditingId(editingId === source.id ? null : source.id); setAdding(null) }}
                onDelete={() => setDeleteTarget(source)}
                onSaved={() => { setEditingId(null); fetchSources() }}
              />
            ))}

            {/* 新增按钮 */}
            {!adding ? (
              <div className="flex flex-wrap gap-2 pt-1">
                {addActions.map(({ type, label, icon: Icon }) => (
                  <button key={type} onClick={() => { setAdding(type); setEditingId(null) }}
                    className="flex items-center gap-1.5 rounded-md border px-3 py-2 text-xs transition-colors hover:bg-secondary"
                    style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
                    <Plus size={14} />
                    {label}
                  </button>
                ))}
              </div>
            ) : (
              <StorageSourceForm
                type={adding}
                onCancel={() => setAdding(null)}
                onSaved={() => { setAdding(null); fetchSources() }}
              />
            )}
          </div>
        )}
      </Section>

      <SimpleDeleteDialog
        isOpen={!!deleteTarget}
        title="删除存储源"
        message={deleteTarget ? `确定要删除「${deleteTarget.name}」吗？已上传的照片文件不会被删除，但该存储源将无法再用于上传与访问。` : ''}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteTarget(null)}
        t={(key) => t(key, language)}
      />
    </div>
  )
}

function StorageSourceCard({ source, isEditing, onEdit, onDelete, onSaved }: {
  source: StorageSource; isEditing: boolean; onEdit: () => void; onDelete: () => void; onSaved: () => void
}) {
  if (isEditing) {
    return <StorageSourceForm source={source} onCancel={onEdit} onSaved={onSaved} />
  }

  const meta = storageTypeMeta(source.type)
  const Icon = meta.icon

  return (
    <div className="flex items-center gap-3 rounded-lg border px-4 py-3 transition-colors hover:bg-secondary/40"
      style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
      <span className="flex size-9 shrink-0 items-center justify-center rounded-md" style={{ backgroundColor: 'var(--muted)' }}>
        <Icon size={16} style={{ color: 'var(--muted-foreground)' }} />
      </span>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <span className="truncate text-sm font-medium">{source.name}</span>
          <span className="shrink-0 rounded border px-1.5 py-0.5 text-[10px]"
            style={{ borderColor: 'var(--border)', backgroundColor: 'var(--muted)', color: 'var(--muted-foreground)' }}>
            {meta.label}
          </span>
        </div>
        <p className="mt-0.5 truncate font-mono text-[11px]" style={{ color: 'var(--muted-foreground)' }}>
          {source.type === 'local' && (source.basePath || '/')}
          {source.type === 'github' && `${source.bucket || ''} / ${source.branch || 'main'}`}
          {source.type === 's3' && `${source.bucket || ''} @ ${source.endpoint || source.region || ''}`}
        </p>
      </div>
      <div className="flex shrink-0 items-center gap-0.5">
        <button onClick={onEdit} title="编辑" aria-label="编辑"
          className="flex size-7 items-center justify-center rounded-md transition-colors hover:bg-secondary"
          style={{ color: 'var(--muted-foreground)' }}>
          <Pencil size={14} />
        </button>
        <button onClick={onDelete} title="删除" aria-label="删除"
          className="flex size-7 items-center justify-center rounded-md transition-colors hover:bg-secondary"
          style={{ color: 'var(--destructive)' }}>
          <Trash2 size={14} />
        </button>
      </div>
    </div>
  )
}

function StorageSourceForm({ source, type, onCancel, onSaved }: {
  source?: StorageSource; type?: string; onCancel: () => void; onSaved: () => void
}) {
  const [form, setForm] = useState({
    name: source?.name || '',
    type: source?.type || type || 'local',
    accessKey: source?.accessKey || '',
    secretKey: source?.secretKey || '',
    bucket: source?.bucket || '',
    region: source?.region || '',
    endpoint: source?.endpoint || '',
    publicUrl: source?.publicUrl || '',
    basePath: source?.basePath || '',
    branch: source?.branch || 'main',
    accessMethod: source?.accessMethod || 'raw',
  })
  const [saving, setSaving] = useState(false)

  const handleSave = async () => {
    setSaving(true)
    try {
      if (source?.id) {
        await (window as any).go.main.App.UpdateStorageSource(source.id, form)
        toast.success('已更新')
      } else {
        await (window as any).go.main.App.CreateStorageSource(form)
        toast.success('已创建')
      }
      onSaved()
    } catch (err: any) {
      toast.error(err?.message || '保存失败')
    } finally {
      setSaving(false)
    }
  }

  const meta = storageTypeMeta(form.type)
  const Icon = meta.icon
  const isEditing = Boolean(source?.id)

  return (
    <div className="rounded-lg border p-4" style={{ borderColor: 'var(--ring)', backgroundColor: 'var(--card)' }}>
      <div className="mb-4 flex items-center justify-between gap-2 border-b pb-3" style={{ borderColor: 'var(--border)' }}>
        <span className="flex items-center gap-2 text-sm font-medium">
          <span className="flex size-7 items-center justify-center rounded-md" style={{ backgroundColor: 'var(--muted)' }}>
            <Icon size={14} style={{ color: 'var(--muted-foreground)' }} />
          </span>
          {isEditing ? '编辑存储源' : `添加${meta.label}`}
        </span>
        <span className="shrink-0 rounded border px-1.5 py-0.5 text-[10px]"
          style={{ borderColor: 'var(--border)', backgroundColor: 'var(--muted)', color: 'var(--muted-foreground)' }}>
          {meta.label}
        </span>
      </div>

      <div className="space-y-3">
        <div className="grid grid-cols-2 gap-3">
          <Field label="名称">
            <input value={form.name} onChange={e => setForm(f => ({ ...f, name: e.target.value }))}
              className={inputClass} style={inputStyle} />
          </Field>
          <Field label="类型">
            <SelectDropdown
              value={form.type}
              options={[
                { value: 'local', label: '本地' },
                { value: 'github', label: 'GitHub' },
                { value: 's3', label: 'S3/R2' },
              ]}
              onChange={() => {}}
              disabled
              ariaLabel="类型"
            />
          </Field>
        </div>

        {form.type === 'local' && (
          <Field label="路径前缀" description="本地存储的根目录路径，默认为服务器存储根目录。">
            <input value={form.basePath} placeholder="/"
              onChange={e => setForm(f => ({ ...f, basePath: e.target.value }))}
              className={inputClass} style={inputStyle} />
          </Field>
        )}

        {form.type === 'github' && (
          <>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Personal Access Token" description="需要 repo 写权限，仅保存在服务端配置中。">
                <input type="password" value={form.accessKey}
                  onChange={e => setForm(f => ({ ...f, accessKey: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
              <Field label="仓库 (owner/repo)">
                <input value={form.bucket} placeholder="user/repo"
                  onChange={e => setForm(f => ({ ...f, bucket: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
            </div>
            <div className="grid grid-cols-3 gap-3">
              <Field label="分支">
                <input value={form.branch} placeholder="main"
                  onChange={e => setForm(f => ({ ...f, branch: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
              <Field label="路径前缀">
                <input value={form.basePath} placeholder="images/"
                  onChange={e => setForm(f => ({ ...f, basePath: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
              <Field label="访问方式">
                <SelectDropdown
                  value={form.accessMethod}
                  options={[
                    { value: 'raw', label: 'Raw' },
                    { value: 'jsdelivr', label: 'jsDelivr' },
                    { value: 'pages', label: 'GitHub Pages' },
                  ]}
                  onChange={value => setForm(f => ({ ...f, accessMethod: String(value) }))}
                  ariaLabel="访问方式"
                />
              </Field>
            </div>
            {form.accessMethod === 'pages' && (
              <Field label="Pages URL">
                <input value={form.publicUrl} placeholder="https://user.github.io/repo"
                  onChange={e => setForm(f => ({ ...f, publicUrl: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
            )}
          </>
        )}

        {form.type === 's3' && (
          <>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Endpoint">
                <input value={form.endpoint} placeholder="https://xxx.r2.cloudflarestorage.com"
                  onChange={e => setForm(f => ({ ...f, endpoint: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
              <Field label="Region">
                <input value={form.region} placeholder="auto"
                  onChange={e => setForm(f => ({ ...f, region: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Access Key ID">
                <input value={form.accessKey}
                  onChange={e => setForm(f => ({ ...f, accessKey: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
              <Field label="Secret Access Key" description="仅保存在服务端配置中，不会回显。">
                <input type="password" value={form.secretKey}
                  onChange={e => setForm(f => ({ ...f, secretKey: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
            </div>
            <div className="grid grid-cols-2 gap-3">
              <Field label="Bucket">
                <input value={form.bucket}
                  onChange={e => setForm(f => ({ ...f, bucket: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
              <Field label="公开访问 URL">
                <input value={form.publicUrl} placeholder="https://pub-xxx.r2.dev"
                  onChange={e => setForm(f => ({ ...f, publicUrl: e.target.value }))}
                  className={inputClass} style={inputStyle} />
              </Field>
            </div>
            <Field label="路径前缀">
              <input value={form.basePath} placeholder="photos/"
                onChange={e => setForm(f => ({ ...f, basePath: e.target.value }))}
                className={inputClass} style={inputStyle} />
            </Field>
          </>
        )}
      </div>

      <div className="mt-4 flex justify-end gap-2 border-t pt-4" style={{ borderColor: 'var(--border)' }}>
        <button onClick={onCancel}
          className="rounded-md border px-3 py-1.5 text-xs transition-colors hover:bg-secondary"
          style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
          取消
        </button>
        <button onClick={handleSave} disabled={saving}
          className="flex items-center gap-1.5 rounded-md px-3 py-1.5 text-xs font-medium transition-opacity disabled:opacity-50 hover:opacity-90"
          style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
          {saving ? <Loader2 size={14} className="animate-spin" /> : <Check size={14} />}
          {saving ? '保存中...' : '保存'}
        </button>
      </div>
    </div>
  )
}

// ─── Tab 4: 评论（与 Web 端一致：Manage + Config 子标签） ──

function CommentsTab({ config, updateConfig }: {
  config: Record<string, string>
  updateConfig: (key: string, value: string) => void
}) {
  const [subTab, setSubTab] = useState<CommentsSubTab>('manage')

  return (
    <div className="space-y-4">
      {/* 子标签切换 */}
      <div className="flex gap-1 border-b pb-2" style={{ borderColor: 'var(--border)' }}>
        {[
          { key: 'manage' as const, label: '管理' },
          { key: 'config' as const, label: '配置' },
        ].map(({ key, label }) => (
          <button key={key} onClick={() => setSubTab(key)}
            className="px-3 py-1.5 text-xs rounded-md transition-colors"
            style={{
              backgroundColor: subTab === key ? 'var(--accent)' : 'transparent',
              color: subTab === key ? 'var(--accent-foreground)' : 'var(--muted-foreground)',
            }}>
            {label}
          </button>
        ))}
      </div>

      {subTab === 'manage' && <CommentsManageTab />}
      {subTab === 'config' && <CommentsConfigTab config={config} updateConfig={updateConfig} />}
    </div>
  )
}

function CommentsManageTab() {
  const { language } = usePreferences()
  const [comments, setComments] = useState<any[]>([])
  const [loading, setLoading] = useState(false)
  const [statusFilter, setStatusFilter] = useState('')
  const [page, setPage] = useState(1)
  const [total, setTotal] = useState(0)
  const [deleteTarget, setDeleteTarget] = useState<any | null>(null)

  const fetchComments = useCallback(async () => {
    setLoading(true)
    try {
      const result = await (window as any).go.main.App.GetComments({
        status: statusFilter, page, limit: 20,
      })
      setComments(result?.data || [])
      setTotal(result?.meta?.total || 0)
    } catch {} finally { setLoading(false) }
  }, [statusFilter, page])

  useEffect(() => { fetchComments() }, [fetchComments])

  const updateStatus = async (id: string, status: string) => {
    try {
      await (window as any).go.main.App.UpdateCommentStatus(id, status)
      fetchComments()
    } catch {}
  }

  const deleteComment = async () => {
    if (!deleteTarget) return
    try {
      await (window as any).go.main.App.DeleteComment(deleteTarget.id)
      setDeleteTarget(null)
      fetchComments()
    } catch {}
  }

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-2">
        <SelectDropdown
          value={statusFilter}
          options={[
            { value: 'pending', label: '待审核' },
            { value: 'approved', label: '已通过' },
            { value: 'rejected', label: '已拒绝' },
          ]}
          onChange={value => { setStatusFilter(String(value)); setPage(1) }}
          placeholder="全部状态"
          clearLabel="全部状态"
          size="sm"
          ariaLabel="评论状态筛选"
          className="w-36"
        />
        <span className="text-xs" style={{ color: 'var(--muted-foreground)' }}>{total} 条评论</span>
      </div>

      {loading ? (
        <div className="flex items-center justify-center py-8" style={{ color: 'var(--muted-foreground)' }}>
          <Loader2 size={16} className="animate-spin" />
        </div>
      ) : comments.length === 0 ? (
        <p className="text-xs py-4" style={{ color: 'var(--muted-foreground)' }}>暂无评论</p>
      ) : (
        <div className="space-y-2">
          {comments.map(c => (
            <div key={c.id} className="px-4 py-3 rounded-lg border"
              style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
              <div className="flex items-start justify-between">
                <div className="min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium">{c.author}</span>
                    <Badge tone={c.status === 'approved' ? 'green' : c.status === 'rejected' ? 'red' : undefined}>
                      {c.status === 'pending' ? '待审核' : c.status === 'approved' ? '已通过' : '已拒绝'}
                    </Badge>
                  </div>
                  <p className="mt-1 text-xs" style={{ color: 'var(--foreground)' }}>{c.content}</p>
                  <p className="mt-1 text-[11px]" style={{ color: 'var(--muted-foreground)' }}>
                    {c.email && `${c.email} · `}{new Date(c.createdAt).toLocaleString()}
                  </p>
                </div>
                <div className="ml-2 flex shrink-0 items-center gap-0.5">
                  {c.status !== 'approved' && (
                    <button onClick={() => updateStatus(c.id, 'approved')}
                      className="flex size-7 items-center justify-center rounded-md border transition-colors hover:bg-secondary"
                      style={{ borderColor: 'var(--border)', color: STATUS_COLORS.green.fg }} title="通过" aria-label="通过">
                      <Check size={13} />
                    </button>
                  )}
                  {c.status !== 'rejected' && (
                    <button onClick={() => updateStatus(c.id, 'rejected')}
                      className="flex size-7 items-center justify-center rounded-md border transition-colors hover:bg-secondary"
                      style={{ borderColor: 'var(--border)', color: 'var(--destructive)' }} title="拒绝" aria-label="拒绝">
                      <X size={13} />
                    </button>
                  )}
                  <button onClick={() => setDeleteTarget(c)}
                    className="flex size-7 items-center justify-center rounded-md transition-colors hover:bg-secondary"
                    style={{ color: 'var(--destructive)' }} title="删除" aria-label="删除">
                    <Trash2 size={13} />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {total > 20 && (
        <div className="flex items-center justify-between pt-2">
          <span className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
            第 {page} 页 / 共 {Math.ceil(total / 20)} 页
          </span>
          <div className="flex gap-1">
            <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page <= 1}
              className="px-2 py-1 text-xs rounded disabled:opacity-30"
              style={{ backgroundColor: 'var(--secondary)', color: 'var(--secondary-foreground)' }}>
              上一页
            </button>
            <button onClick={() => setPage(p => p + 1)} disabled={page >= Math.ceil(total / 20)}
              className="px-2 py-1 text-xs rounded disabled:opacity-30"
              style={{ backgroundColor: 'var(--secondary)', color: 'var(--secondary-foreground)' }}>
              下一页
            </button>
          </div>
        </div>
      )}

      <SimpleDeleteDialog
        isOpen={!!deleteTarget}
        title="删除评论"
        message={deleteTarget ? `确定要删除 ${deleteTarget.author || '此用户'} 的评论吗？` : ''}
        onConfirm={deleteComment}
        onCancel={() => setDeleteTarget(null)}
        t={(key) => t(key, language)}
      />
    </div>
  )
}

function CommentsConfigTab({ config, updateConfig }: {
  config: Record<string, string>
  updateConfig: (key: string, value: string) => void
}) {
  const provider = config.comment_provider || 'local'

  return (
    <div className="space-y-4">
      <Section title="评论配置">
        <Field label="评论审核">
          <label className="flex items-center gap-2 cursor-pointer">
            <input type="checkbox"
              checked={config.comment_moderation === 'manual'}
              onChange={e => updateConfig('comment_moderation', e.target.checked ? 'manual' : 'auto')}
              className="rounded" />
            <span className="text-xs">新评论需要人工审核</span>
          </label>
        </Field>

        <Field label="评论提供者">
          <SelectDropdown
            value={provider}
            options={[
              { value: 'local', label: '本地' },
              { value: 'openai', label: 'OpenAI' },
              { value: 'gemini', label: 'Gemini' },
              { value: 'anthropic', label: 'Anthropic' },
            ]}
            onChange={value => updateConfig('comment_provider', String(value))}
            placeholder="请选择评论提供者"
            ariaLabel="评论提供者"
          />
        </Field>

        {provider !== 'local' && (
          <>
            <Field label="API Key">
              <input type="password" value={config.comment_api_key || ''}
                onChange={e => updateConfig('comment_api_key', e.target.value)}
                className={inputClass} style={inputStyle} />
            </Field>
            <Field label="API Endpoint">
              <input type="text" value={config.comment_api_endpoint || ''}
                onChange={e => updateConfig('comment_api_endpoint', e.target.value)}
                className={inputClass} style={inputStyle} />
            </Field>
            <Field label="模型">
              <input type="text" value={config.comment_model || ''}
                onChange={e => updateConfig('comment_model', e.target.value)}
                className={inputClass} style={inputStyle} />
            </Field>
          </>
        )}

        <Field label="屏蔽关键词" description="逗号分隔">
          <textarea value={config.blocked_keywords || ''}
            onChange={e => updateConfig('blocked_keywords', e.target.value)}
            rows={3}
            className={textareaClass} style={inputStyle} />
        </Field>
      </Section>
    </div>
  )
}

// ─── Tab 5: 账户（与 Web 端一致：Linux DO 绑定） ────────────

function AccountTab() {
  const { language } = usePreferences()
  const [linuxDoEnabled, setLinuxDoEnabled] = useState(false)
  const [linuxDoBinding, setLinuxDoBinding] = useState<any>(null)
  const [linuxDoLoading, setLinuxDoLoading] = useState(false)
  const [linuxDoBindLoading, setLinuxDoBindLoading] = useState(false)
  const [deleteDialog, setDeleteDialog] = useState(false)

  const loadLinuxDoStatus = async () => {
    setLinuxDoLoading(true)
    try {
      const enabled = await (window as any).go.main.App.IsLinuxDoEnabled()
      setLinuxDoEnabled(enabled)
      if (enabled) {
        const binding = await (window as any).go.main.App.GetLinuxDoBinding()
        setLinuxDoBinding(binding)
      } else {
        setLinuxDoBinding(null)
      }
    } catch (err: any) {
      toast.error('加载 Linux DO 状态失败: ' + (err?.message || '未知错误'))
    } finally {
      setLinuxDoLoading(false)
    }
  }

  useEffect(() => { loadLinuxDoStatus() }, [])

  const handleLinuxDoBind = async () => {
    try {
      setLinuxDoBindLoading(true)
      const { url, state } = await (window as any).go.main.App.GetLinuxDoAuthUrl()
      // 保存 state 和当前路径到 sessionStorage
      sessionStorage.setItem('linuxdo_oauth_state', state)
      sessionStorage.setItem('linuxdo_redirect', window.location.pathname)
      // 跳转到 Linux DO 授权页
      window.location.href = url
    } catch (err: any) {
      toast.error('获取授权 URL 失败: ' + (err?.message || '未知错误'))
      setLinuxDoBindLoading(false)
    }
  }

  const handleLinuxDoUnbind = async () => {
    try {
      await (window as any).go.main.App.UnbindLinuxDoAccount()
      toast.success('已解绑 Linux DO 账户')
      setDeleteDialog(false)
      loadLinuxDoStatus()
    } catch (err: any) {
      toast.error('解绑失败: ' + (err?.message || '未知错误'))
    }
  }

  return (
    <div className="space-y-6">
      <Section title="Linux DO 绑定">
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <svg className="w-5 h-5 text-[#f8d568]" viewBox="0 0 24 24" fill="currentColor">
              <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
            </svg>
            <h4 className="text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--foreground)' }}>
              Linux DO
            </h4>
          </div>
          <p className="text-[10px] text-muted-foreground mt-2">
            绑定 Linux DO 账户后，可以使用 Linux DO 登录。
          </p>
        </div>

        {!linuxDoEnabled ? (
          <div className="p-6 rounded-lg border border-dashed text-center" style={{ borderColor: 'var(--border)' }}>
            <p className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
              Linux DO 未配置
            </p>
            <p className="mt-2 font-mono text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
              请在 .env 中配置 LINUXDO_CLIENT_ID 和 LINUXDO_CLIENT_SECRET
            </p>
          </div>
        ) : linuxDoLoading ? (
          <div className="flex items-center justify-center p-8">
            <Loader2 size={16} className="animate-spin" />
          </div>
        ) : linuxDoBinding ? (
          <div className="space-y-6 rounded-lg border p-6" style={{ borderColor: 'var(--border)' }}>
            <div className="flex items-center gap-4">
              {linuxDoBinding.avatarUrl ? (
                <img
                  src={linuxDoBinding.avatarUrl}
                  alt={linuxDoBinding.username || ''}
                  className="h-12 w-12 rounded-full border"
                  style={{ borderColor: 'var(--border)' }}
                />
              ) : (
                <div className="flex h-12 w-12 items-center justify-center rounded-full border bg-muted" style={{ borderColor: 'var(--border)' }}>
                  <User size={20} className="text-muted-foreground" />
                </div>
              )}
              <div>
                <p className="font-medium" style={{ color: 'var(--foreground)' }}>
                  {linuxDoBinding.username}
                </p>
                {linuxDoBinding.trustLevel !== null && (
                  <p className="mt-0.5 font-mono text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
                    Trust Level: {linuxDoBinding.trustLevel}
                  </p>
                )}
              </div>
              <div className="ml-auto">
                <Badge tone="green"><Check size={10} /> 已绑定</Badge>
              </div>
            </div>
            <button
              onClick={() => setDeleteDialog(true)}
              disabled={linuxDoBindLoading}
              className="flex w-full items-center justify-center gap-2 rounded-md border px-3 py-2 text-xs transition-colors hover:bg-secondary disabled:opacity-50"
              style={{ borderColor: 'color-mix(in srgb, var(--destructive) 40%, transparent)', color: 'var(--destructive)' }}
            >
              {linuxDoBindLoading ? (
                <Loader2 size={14} className="animate-spin" />
              ) : (
                <Unlink size={14} />
              )}
              解绑 Linux DO
            </button>
          </div>
        ) : (
          <div className="space-y-4 rounded-lg border border-dashed p-6 text-center" style={{ borderColor: 'var(--border)' }}>
            <div className="space-y-2">
              <p className="text-xs" style={{ color: 'var(--muted-foreground)' }}>
                未绑定 Linux DO 账户
              </p>
              <p className="text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
                绑定后可以使用 Linux DO 登录
              </p>
            </div>
            <button
              onClick={handleLinuxDoBind}
              disabled={linuxDoBindLoading}
              className="mx-auto flex items-center justify-center gap-2 rounded-md px-5 py-2 text-xs font-semibold transition-opacity hover:opacity-90 disabled:opacity-50"
              style={{ backgroundColor: '#f8d568', color: '#1a1a1a' }}
            >
              {linuxDoBindLoading ? (
                <Loader2 size={14} className="animate-spin" />
              ) : (
                <Link size={14} />
              )}
              绑定 Linux DO
            </button>
          </div>
        )}
      </Section>

      <SimpleDeleteDialog
        isOpen={deleteDialog}
        title="解绑 Linux DO"
        message="确定要解绑 Linux DO 账户吗？解绑后无法使用 Linux DO 登录。"
        onConfirm={handleLinuxDoUnbind}
        onCancel={() => setDeleteDialog(false)}
        t={(key) => t(key, language)}
      />
    </div>
  )
}

// ─── Tab 8: 缓存管理 ─────────────────────────────────

const APP_CACHE_STORAGE_PREFIX = 'mo-gallery:desktop-cache-storage'

async function getCurrentAppCacheStorageKeys() {
  if (!('caches' in window)) return []
  const scope = getCurrentPersistentCacheScope()
  if (!scope) return []
  const prefix = `${APP_CACHE_STORAGE_PREFIX}:${scope}:`
  return (await caches.keys()).filter(key => key.startsWith(prefix))
}

function CacheTab() {
  const { language } = usePreferences()
  const [snapshot, setSnapshot] = useState(getDesktopCacheSnapshot)
  const [clearingPage, setClearingPage] = useState<'overview' | 'cloud' | null>(null)
  const [clearingApplication, setClearingApplication] = useState(false)
  const [clearingLocalPreviews, setClearingLocalPreviews] = useState(false)
  const [clearingCacheStorage, setClearingCacheStorage] = useState(false)
  const [confirmAction, setConfirmAction] = useState<'application' | 'previews' | null>(null)
  const [cacheStorageInfo, setCacheStorageInfo] = useState({
    supported: false,
    loading: true,
    count: 0,
    bytes: 0,
    error: null as string | null,
  })
  const cacheStorageRequestIdRef = useRef(0)
  const localCacheInfo = useLocalLibraryCacheInfo()

  const refreshSnapshot = () => setSnapshot(getDesktopCacheSnapshot())

  const refreshCacheStorageInfo = useCallback(async () => {
    const requestId = ++cacheStorageRequestIdRef.current
    if (!('caches' in window)) {
      setCacheStorageInfo({ supported: false, loading: false, count: 0, bytes: 0, error: null })
      return
    }

    setCacheStorageInfo(prev => ({ ...prev, supported: true, loading: true, error: null }))
    try {
      const keys = await getCurrentAppCacheStorageKeys()
      let count = 0
      let bytes = 0
      for (const key of keys) {
        const cache = await caches.open(key)
        const requests = await cache.keys()
        count += requests.length
        for (const request of requests) {
          const response = await cache.match(request)
          if (!response) continue
          bytes += (await response.clone().blob()).size
        }
      }
      if (requestId !== cacheStorageRequestIdRef.current) return
      setCacheStorageInfo({ supported: true, loading: false, count, bytes, error: null })
    } catch (error: unknown) {
      if (requestId !== cacheStorageRequestIdRef.current) return
      setCacheStorageInfo({
        supported: true,
        loading: false,
        count: 0,
        bytes: 0,
        error: error instanceof Error ? error.message : '统计失败',
      })
    }
  }, [])

  useEffect(() => {
    void refreshCacheStorageInfo()
    return () => { cacheStorageRequestIdRef.current += 1 }
  }, [refreshCacheStorageInfo])

  const refreshAll = () => {
    refreshSnapshot()
    void refreshCacheStorageInfo()
    void localCacheInfo.refresh()
  }

  const handleClearPageCache = (scope: 'overview' | 'cloud') => {
    setClearingPage(scope)
    if (scope === 'overview') {
      clearOverviewPageCache()
      clearEquipmentCache()
    } else {
      clearCloudLibraryPageCache()
    }
    refreshSnapshot()
    setClearingPage(null)
    toast.success(scope === 'overview' ? '概览页缓存已清理，下次进入时会重新加载' : '云端照片列表缓存已清理，下次进入时会重新加载')
  }

  const deleteCacheStorage = async () => {
    if (!('caches' in window)) return 0
    cacheStorageRequestIdRef.current += 1
    const keys = await getCurrentAppCacheStorageKeys()
    await Promise.all(keys.map(key => caches.delete(key)))
    return keys.length
  }

  const handleClearCacheStorage = async () => {
    if (!cacheStorageInfo.supported) {
      toast.error('当前 WebView 不支持 CacheStorage')
      return
    }

    setClearingCacheStorage(true)
    try {
      const count = await deleteCacheStorage()
      await refreshCacheStorageInfo()
      toast.success(count > 0 ? `已清理 ${count} 个 CacheStorage` : '没有可清理的 CacheStorage')
    } catch (error: unknown) {
      toast.error('清理 CacheStorage 失败: ' + getErrorMessage(error))
    } finally {
      setClearingCacheStorage(false)
    }
  }

  const handleClearApplicationCache = async () => {
    setClearingApplication(true)
    try {
      clearDesktopRuntimeCache()
      clearCurrentPersistentCache()
      await deleteCacheStorage()
      refreshSnapshot()
      await refreshCacheStorageInfo()
      toast.success('应用缓存已清理；相关页面会在下次进入时自动重建')
    } catch (error: unknown) {
      refreshSnapshot()
      await refreshCacheStorageInfo()
      toast.error('部分应用缓存清理失败: ' + getErrorMessage(error))
    } finally {
      setClearingApplication(false)
      setConfirmAction(null)
    }
  }

  const handleClearLocalPreviews = async () => {
    setClearingLocalPreviews(true)
    try {
      await ClearLocalLibraryPreviewCache()
      await localCacheInfo.refresh()
      toast.success('本地大图预览已清理；查看照片时会按需重新生成')
    } catch (error: unknown) {
      toast.error('清理本地大图预览失败: ' + getErrorMessage(error))
    } finally {
      setClearingLocalPreviews(false)
      setConfirmAction(null)
    }
  }

  const cachedPageCount = Number(snapshot.overviewLoaded || snapshot.cameraLoaded || snapshot.lensLoaded) + Number(snapshot.photosLoaded)
  const runtimeBytes = snapshot.overviewPageBytes + snapshot.photosBytes
  const applicationDiskBytes = snapshot.persistentBytes + cacheStorageInfo.bytes
  const previewBytes = localCacheInfo.stats?.previews.bytes ?? 0
  const reclaimableBytes = applicationDiskBytes + previewBytes
  const hasApplicationCache = cachedPageCount > 0 || snapshot.persistentResourceCount > 0 || cacheStorageInfo.count > 0
  const isClearing = clearingApplication || clearingLocalPreviews || clearingCacheStorage || clearingPage !== null
  const isRefreshing = cacheStorageInfo.loading || localCacheInfo.loading || isClearing
  const previewUsagePercent = localCacheInfo.stats?.previewLimitBytes
    ? Math.min(100, Math.round((previewBytes / localCacheInfo.stats.previewLimitBytes) * 100))
    : 0

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden">
      <header className="flex h-14 shrink-0 items-center justify-between gap-3 border-b px-5" style={{ borderColor: 'var(--border)' }}>
        <div className="min-w-0">
          <h2 className="text-sm font-medium">缓存与空间</h2>
          <p className="mt-0.5 truncate text-[11px]" style={{ color: 'var(--muted-foreground)' }}>
            释放可再生数据占用，或在页面数据异常时清理并重建缓存。
          </p>
        </div>
        <button type="button" onClick={refreshAll} disabled={isRefreshing} className={btnOutline} title="重新统计缓存">
          <RefreshCw size={13} className={isRefreshing ? 'animate-spin' : ''} />
          重新统计
        </button>
      </header>

      <div className="custom-scrollbar min-h-0 flex-1 overflow-auto p-5">
        <div className="mx-auto max-w-4xl space-y-5">
          <section className="overflow-hidden rounded-lg border" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
            <div className="flex items-start justify-between gap-4 border-b px-5 py-4" style={{ borderColor: 'var(--border)' }}>
              <div>
                <p className="text-[10px] font-medium uppercase tracking-[0.16em]" style={{ color: 'var(--muted-foreground)' }}>可释放空间</p>
                <p className="mt-1 text-2xl font-semibold tabular-nums">{isRefreshing ? '正在统计' : formatBytes(reclaimableBytes)}</p>
                <p className="mt-1 text-[11px] leading-5" style={{ color: 'var(--muted-foreground)' }}>
                  仅计算可清理的磁盘数据，不包含运行时内存、原文件或资源库数据。
                </p>
              </div>
              <Badge tone={reclaimableBytes > 0 ? 'green' : undefined}>{reclaimableBytes > 0 ? '可清理' : '无需清理'}</Badge>
            </div>
            <div className="grid sm:grid-cols-3 sm:divide-x" style={{ borderColor: 'var(--border)' }}>
              <CacheSummaryMetric label="应用磁盘缓存" value={formatBytes(applicationDiskBytes)} detail={`${snapshot.persistentResourceCount} 项持久化数据 · ${cacheStorageInfo.count} 项当前账号网络响应`} />
              <CacheSummaryMetric label="本地大图预览" value={localCacheInfo.loading ? '统计中' : localCacheInfo.stats ? formatBytes(previewBytes) : '未打开资源库'} detail={localCacheInfo.stats ? `${localCacheInfo.stats.previews.fileCount} 个文件` : '打开本地资源库后可统计'} />
              <CacheSummaryMetric label="页面运行时状态" value={formatBytes(runtimeBytes)} detail={`${cachedPageCount}/2 个页面已缓存 · 不计入磁盘空间`} />
            </div>
          </section>

          <CacheDetailSection
            title="应用数据缓存"
            description="包含页面运行时状态、按账号保存的页面数据和 CacheStorage。清理后不会退出登录，相关页面会在下次进入时重新请求。"
            footer={(
              <button type="button" onClick={() => setConfirmAction('application')}
                disabled={isRefreshing || !hasApplicationCache} className={btnOutline} style={{ color: 'var(--destructive)' }}>
                {clearingApplication ? <Loader2 size={13} className="animate-spin" /> : <RefreshCw size={13} />}
                清理并重建
              </button>
            )}
          >
            <CacheManagementRow
              icon={LayoutDashboard}
              title="概览页"
              description="统计概览、相机列表和镜头列表的已加载数据。"
              status={snapshot.overviewLoaded || snapshot.cameraLoaded || snapshot.lensLoaded ? '已缓存' : '未缓存'}
              detail={`${formatBytes(snapshot.overviewPageBytes)} 运行时估算 · 相机 ${snapshot.cameraCount} · 镜头 ${snapshot.lensCount}`}
              actionLabel="清理"
              onAction={() => handleClearPageCache('overview')}
              disabled={isRefreshing || !(snapshot.overviewLoaded || snapshot.cameraLoaded || snapshot.lensLoaded)}
              loading={clearingPage === 'overview'}
            />
            <CacheManagementRow
              icon={Images}
              title="云端照片列表"
              description="已加载的分页数据与滚动位置。"
              status={snapshot.photosLoaded ? '已缓存' : '未缓存'}
              detail={snapshot.photosLoaded ? `${snapshot.photosCount} 张 · ${formatBytes(snapshot.photosBytes)} 运行时估算` : '进入云端照片页面后生成'}
              actionLabel="清理"
              onAction={() => handleClearPageCache('cloud')}
              disabled={isRefreshing || !snapshot.photosLoaded}
              loading={clearingPage === 'cloud'}
            />
            <CacheManagementRow
              icon={Database}
              title="持久化页面数据"
              description="按当前服务端与登录账号保存的概览、相册、分类、胶卷、故事和朋友列表。"
              status={snapshot.persistentResourceCount > 0 ? `${snapshot.persistentResourceCount} 项` : '无缓存'}
              detail={`${formatBytes(snapshot.persistentBytes)} 磁盘估算 · 清理并重建时统一移除`}
            />
            <CacheManagementRow
              icon={Cloud}
              title="CacheStorage"
              description="由 MO Gallery 网页功能写入、按当前服务端与账号隔离的网络响应缓存。"
              status={cacheStorageInfo.loading ? '计算中' : cacheStorageInfo.error ? '统计失败' : cacheStorageInfo.supported ? `${cacheStorageInfo.count} 项` : '不支持'}
              detail={cacheStorageInfo.error || (cacheStorageInfo.supported ? `${formatBytes(cacheStorageInfo.bytes)} 磁盘估算` : '当前 WebView 未提供 CacheStorage')}
              actionLabel="清理"
              onAction={handleClearCacheStorage}
              disabled={isRefreshing || !cacheStorageInfo.supported || cacheStorageInfo.count === 0}
              loading={clearingCacheStorage}
            />
          </CacheDetailSection>

          <CacheDetailSection
            title="本地预览缓存"
            description="管理当前本地资源库按需生成的 2048px 屏幕预览。清理不会影响 512px 网格缩略图、原文件、索引或整理数据。"
            footer={localCacheInfo.stats ? (
              <button type="button" onClick={() => setConfirmAction('previews')}
                disabled={isRefreshing || localCacheInfo.stats.previews.fileCount === 0}
                className={btnOutline} style={{ color: 'var(--destructive)' }}>
                {clearingLocalPreviews ? <Loader2 size={13} className="animate-spin" /> : <Trash size={13} />}
                清理大图预览
              </button>
            ) : undefined}
          >
            <CacheManagementRow
              icon={ImageIcon}
              title="大图预览"
              description="首次查看照片时生成，之后直接复用；清理后首次打开可能需要等待重新生成。"
              status={localCacheInfo.loading ? '计算中' : localCacheInfo.stats ? formatBytes(previewBytes) : '未打开资源库'}
              detail={localCacheInfo.stats
                ? `${localCacheInfo.stats.previews.fileCount} 个文件 · 已使用上限的 ${previewUsagePercent}% · 上限 ${formatBytes(localCacheInfo.stats.previewLimitBytes)}`
                : localCacheInfo.error || '打开本地资源库后可统计和清理'}
            />
          </CacheDetailSection>

          <div className="flex items-start gap-2 rounded-md border px-4 py-3 text-[11px] leading-5" style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}>
            <Info size={14} className="mt-0.5 shrink-0" />
            <span>缓存清理不会删除账户、设置、照片原文件或资源库数据库。系统 WebView 管理的 HTTP 图片缓存无法准确统计，因此不计入可释放空间。</span>
          </div>
        </div>
      </div>

      <SimpleDeleteDialog
        isOpen={confirmAction === 'application'}
        title="清理并重建应用缓存"
        message={`将清理约 ${formatBytes(applicationDiskBytes)} 的应用磁盘缓存，以及当前页面运行时状态。不会退出登录或删除任何照片；相关页面会在下次进入时重新加载。`}
        confirmLabel="清理并重建"
        pendingLabel="正在清理..."
        confirmIcon="refresh"
        onConfirm={handleClearApplicationCache}
        onCancel={() => setConfirmAction(null)}
        t={(key) => t(key, language)}
      />
      <SimpleDeleteDialog
        isOpen={confirmAction === 'previews'}
        title="清理本地大图预览"
        message={`将释放约 ${formatBytes(previewBytes)} 的大图预览缓存。原文件、网格缩略图和资源库数据会保留；之后首次查看照片时需要重新生成预览。`}
        confirmLabel="清理预览"
        pendingLabel="正在清理..."
        onConfirm={handleClearLocalPreviews}
        onCancel={() => setConfirmAction(null)}
        t={(key) => t(key, language)}
      />
    </div>
  )
}

function CacheSummaryMetric({ label, value, detail }: { label: string; value: string; detail: string }) {
  return (
    <div className="px-5 py-4">
      <p className="text-[10px] font-medium uppercase tracking-[0.16em]" style={{ color: 'var(--muted-foreground)' }}>{label}</p>
      <p className="mt-1 text-sm font-semibold tabular-nums">{value}</p>
      <p className="mt-1 text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{detail}</p>
    </div>
  )
}

function CacheDetailSection({ title, description, footer, children }: {
  title: string
  description: string
  footer?: React.ReactNode
  children: React.ReactNode
}) {
  return (
    <section>
      <div className="mb-3">
        <h3 className="text-sm font-medium">{title}</h3>
        <p className="mt-1 max-w-3xl text-[11px] leading-5" style={{ color: 'var(--muted-foreground)' }}>{description}</p>
      </div>
      <div className="overflow-hidden rounded-lg border" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
        <div className="divide-y" style={{ borderColor: 'var(--border)' }}>{children}</div>
        {footer && (
          <div className="flex justify-end border-t px-4 py-3" style={{ borderColor: 'var(--border)', backgroundColor: 'var(--muted)' }}>
            {footer}
          </div>
        )}
      </div>
    </section>
  )
}

function CacheManagementRow({ icon: Icon, title, description, status, detail, actionLabel, onAction, disabled, loading }: {
  icon: typeof Database
  title: string
  description: string
  status: string
  detail: string
  actionLabel?: string
  onAction?: () => void
  disabled?: boolean
  loading?: boolean
}) {
  return (
    <div className="flex min-h-20 items-center gap-4 px-4 py-3.5">
      <span className="flex size-9 shrink-0 items-center justify-center rounded-md" style={{ backgroundColor: 'var(--muted)' }}>
        <Icon size={16} style={{ color: 'var(--muted-foreground)' }} />
      </span>
      <div className="min-w-0 flex-1">
        <div className="flex flex-wrap items-center gap-2">
          <h4 className="text-xs font-medium">{title}</h4>
          <Badge>{status}</Badge>
        </div>
        <p className="mt-1 text-[11px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{description}</p>
        <p className="mt-0.5 text-[10px] leading-4" style={{ color: 'var(--muted-foreground)' }}>{detail}</p>
      </div>
      {actionLabel && onAction && (
        <button type="button" onClick={onAction} disabled={disabled} className={`${btnOutline} shrink-0`}>
          {loading ? <Loader2 size={13} className="animate-spin" /> : <Trash size={13} />}
          {actionLabel}
        </button>
      )}
    </div>
  )
}

function CacheStat({ label, value, detail }: { label: string; value: string; detail?: string }) {
  return (
    <div className="rounded-lg px-3 py-2" style={{ backgroundColor: 'var(--muted)' }}>
      <p className="text-xs" style={{ color: 'var(--muted-foreground)' }}>{label}</p>
      <p className="mt-0.5 text-sm font-medium" style={{ color: 'var(--foreground)' }}>{value}</p>
      {detail && <p className="mt-0.5 text-[10px]" style={{ color: 'var(--muted-foreground)' }}>{detail}</p>}
    </div>
  )
}

