import { useState, useEffect, useCallback } from 'react'
import { toast } from 'sonner'
import { PageHeader } from '@/components/layout/PageHeader'
import { usePreferences } from '@/store/preferences'
import { t } from '@/lib/i18n'
import { resolveAssetUrl } from '@/lib/api'
import { invalidateDesktopCache } from '@/lib/app-cache'
import { loadPersistentResource } from '@/lib/persistent-cache'
import type { Story, Photo } from '@/types'
import { ListSkeleton } from '@/components/admin/Skeleton'
import {
  Plus, Trash2, Eye, EyeOff, FileText, X, ChevronLeft,
  Save, Loader2, ImagePlus, GripVertical, Calendar,
} from 'lucide-react'

type View = 'list' | 'edit'

export function StoriesPage() {
  const { language } = usePreferences()
  const [stories, setStories] = useState<Story[]>([])
  const [loading, setLoading] = useState(false)
  const [view, setView] = useState<View>('list')
  const [editingStory, setEditingStory] = useState<Story | null>(null)

  const fetchStories = useCallback(async (force = false) => {
    setLoading(true)
    try {
      const result = await loadPersistentResource<Story[]>('stories', () => (window as any).go.main.App.GetStories(), { force })
      setStories(result || [])
    } catch (err: any) {
      console.error('加载叙事失败:', err)
      toast.error(err?.message || '加载叙事失败')
    } finally { setLoading(false) }
  }, [])

  useEffect(() => { fetchStories() }, [fetchStories])

  // 创建新故事
  const handleCreate = () => {
    setEditingStory(null)
    setView('edit')
  }

  // 编辑故事
  const handleEdit = (story: Story) => {
    setEditingStory(story)
    setView('edit')
  }

  // 删除故事
  const handleDelete = async (id: string) => {
    if (!confirm('确定要删除此故事吗？')) return
    try {
      await (window as any).go.main.App.DeleteStory(id)
      toast.success('已删除')
      await fetchStories(true)
      invalidateDesktopCache(['overview', 'photos'])
    } catch (err: any) {
      toast.error(err?.message || '删除失败')
    }
  }

  // 切换发布状态
  const togglePublished = async (story: Story) => {
    try {
      await (window as any).go.main.App.UpdateStory(story.id, { isPublished: !story.isPublished })
      toast.success(story.isPublished ? '已取消发布' : '已发布')
      await fetchStories(true)
      invalidateDesktopCache(['overview'])
    } catch (err: any) {
      toast.error(err?.message || '操作失败')
    }
  }

  // 从编辑器返回列表
  const handleBack = () => {
    setView('list')
    setEditingStory(null)
    invalidateDesktopCache(['overview', 'photos'])
    void fetchStories(true)
  }

  if (view === 'edit') {
    return <StoryEditor story={editingStory} onBack={handleBack} />
  }

  return (
    <>
      <PageHeader
        title={t('admin.page_stories', language)}
        description={`${stories.length} stories`}
        actions={
          <button onClick={handleCreate}
            className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md"
            style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
            <Plus size={14} /> {t('admin.create_story', language)}
          </button>
        }
      />

      <div className="flex-1 overflow-auto p-6">
        {loading ? (
          <ListSkeleton count={5} />
        ) : stories.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64" style={{ color: 'var(--muted-foreground)' }}>
            <FileText size={32} className="mb-2 opacity-40" />
            <p className="text-sm">{t('common.noData', language)}</p>
          </div>
        ) : (
          <div className="space-y-2">
            {stories.map(story => (
              <div key={story.id}
                className="flex items-center gap-4 px-4 py-3 rounded-lg border cursor-pointer hover:opacity-90 transition-opacity"
                style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}
                onClick={() => handleEdit(story)}>
                {/* 封面缩略图 */}
                {story.coverPhotoId ? (
                  <div className="w-12 h-12 rounded overflow-hidden shrink-0" style={{ backgroundColor: 'var(--muted)' }}>
                    <img src={resolveAssetUrl(story.coverPhotoId)} alt="" className="w-full h-full object-cover" />
                  </div>
                ) : (
                  <div className="w-12 h-12 rounded flex items-center justify-center shrink-0"
                    style={{ backgroundColor: 'var(--muted)' }}>
                    <FileText size={18} style={{ color: 'var(--muted-foreground)' }} />
                  </div>
                )}

                {/* 故事信息 */}
                <div className="flex-1 min-w-0">
                  <h3 className="text-sm font-medium truncate">{story.title}</h3>
                  <p className="text-xs mt-0.5" style={{ color: 'var(--muted-foreground)' }}>
                    {story.photoCount ?? story.photos?.length ?? 0} photos · {new Date(story.storyDate || story.createdAt).toLocaleDateString()}
                  </p>
                </div>

                {/* 状态标签 */}
                <span className="text-xs px-2 py-0.5 rounded shrink-0"
                  style={{
                    backgroundColor: story.isPublished ? 'var(--accent)' : 'var(--muted)',
                    color: story.isPublished ? 'var(--accent-foreground)' : 'var(--muted-foreground)',
                  }}>
                  {story.isPublished ? t('admin.stories_status_published', language) : t('admin.stories_status_draft', language)}
                </span>

                {/* 操作按钮 */}
                <div className="flex items-center gap-1 shrink-0" onClick={e => e.stopPropagation()}>
                  <button onClick={() => togglePublished(story)}
                    className="p-1 rounded hover:opacity-80" style={{ color: 'var(--muted-foreground)' }}>
                    {story.isPublished ? <EyeOff size={14} /> : <Eye size={14} />}
                  </button>
                  <button onClick={() => handleDelete(story.id)}
                    className="p-1 rounded hover:opacity-80" style={{ color: 'var(--destructive)' }}>
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </>
  )
}

// ─── 故事编辑器 ──────────────────────────────────────

interface StoryEditorProps {
  story: Story | null // null = 新建
  onBack: () => void
}

function StoryEditor({ story, onBack }: StoryEditorProps) {
  const isNew = !story
  const [title, setTitle] = useState(story?.title || '')
  const [content, setContent] = useState(story?.content || '')
  const [isPublished, setIsPublished] = useState(story?.isPublished ?? false)
  const [storyDate, setStoryDate] = useState(
    story?.storyDate ? new Date(story.storyDate).toISOString().split('T')[0] :
    new Date().toISOString().split('T')[0]
  )
  const [photos, setPhotos] = useState<Photo[]>(story?.photos || [])
  const [loadingDetail, setLoadingDetail] = useState(Boolean(story?.id))
  const [detailLoadFailed, setDetailLoadFailed] = useState(false)
  const [saving, setSaving] = useState(false)
  const [showPhotoSelector, setShowPhotoSelector] = useState(false)
  const [availablePhotos, setAvailablePhotos] = useState<Photo[]>([])
  const [loadingPhotos, setLoadingPhotos] = useState(false)
  const [photoSearch, setPhotoSearch] = useState('')
  const [photoPage, setPhotoPage] = useState(1)
  const [photoHasMore, setPhotoHasMore] = useState(true)

  // 加载故事详情（编辑模式）
  useEffect(() => {
    if (story?.id) {
      (async () => {
        try {
          const detail: Story = await (window as any).go.main.App.GetStory(story.id)
          if (!detail) throw new Error('Story detail is empty')
          setDetailLoadFailed(false)
          setTitle(detail.title || '')
          setContent(detail.content || '')
          setIsPublished(detail.isPublished ?? false)
          if (detail.storyDate) setStoryDate(new Date(detail.storyDate).toISOString().split('T')[0])
          setPhotos(detail.photos || [])
        } catch {
          setDetailLoadFailed(true)
          toast.error('加载故事详情失败，请返回列表后重试')
        } finally {
          setLoadingDetail(false)
        }
      })()
    }
  }, [story?.id])

  // 保存故事
  const handleSave = async () => {
    if (loadingDetail || detailLoadFailed) return
    if (!title.trim()) {
      toast.error('请输入标题')
      return
    }
    setSaving(true)
    try {
      if (isNew) {
        const result = await (window as any).go.main.App.CreateStory({
          title: title.trim(),
          content,
          isPublished,
          photoIds: photos.map(p => p.id),
        })
        toast.success('故事已创建')
        // 切换到编辑模式
        if (result?.id) {
          window.history.replaceState(null, '', `/stories`)
        }
      } else {
        await (window as any).go.main.App.UpdateStory(story!.id, {
          title: title.trim(),
          content,
          isPublished,
          storyDate: new Date(storyDate).toISOString(),
        })
        toast.success('已保存')
      }
    } catch (err: any) {
      toast.error(err?.message || '保存失败')
    } finally {
      setSaving(false)
    }
  }

  // 加载可选照片
  const loadAvailablePhotos = async (reset = false) => {
    if (loadingPhotos) return
    const page = reset ? 1 : photoPage
    setLoadingPhotos(true)
    try {
      const result = await (window as any).go.main.App.GetPhotos({
        search: photoSearch,
        page,
        pageSize: 30,
      })
      const newPhotos = result?.data || []
      setAvailablePhotos(prev => reset ? newPhotos : [...prev, ...newPhotos])
      setPhotoHasMore(result?.meta?.hasMore ?? false)
      setPhotoPage(page + 1)
    } catch {} finally { setLoadingPhotos(false) }
  }

  // 打开照片选择器
  const openPhotoSelector = () => {
    setShowPhotoSelector(true)
    setAvailablePhotos([])
    setPhotoPage(1)
    setPhotoSearch('')
    loadAvailablePhotos(true)
  }

  // 添加照片到故事
  const addPhoto = async (photo: Photo) => {
    if (photos.some(p => p.id === photo.id)) return
    if (!isNew && story?.id) {
      try {
        await (window as any).go.main.App.AddStoryPhoto(story.id, photo.id)
      } catch {}
    }
    setPhotos(prev => [...prev, photo])
  }

  // 移除照片
  const removePhoto = async (photoId: string) => {
    if (!isNew && story?.id) {
      try {
        await (window as any).go.main.App.RemoveStoryPhoto(story.id, photoId)
      } catch {}
    }
    setPhotos(prev => prev.filter(p => p.id !== photoId))
  }

  return (
    <>
      <PageHeader
        title={isNew ? '创建故事' : `编辑: ${story?.title || ''}`}
        actions={
          <div className="flex items-center gap-2">
            <button onClick={onBack}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md"
              style={{ backgroundColor: 'var(--secondary)', color: 'var(--secondary-foreground)' }}>
              <ChevronLeft size={14} /> 返回
            </button>
            <button onClick={handleSave} disabled={saving || loadingDetail || detailLoadFailed}
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-md disabled:opacity-50"
              style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
              {saving ? <Loader2 size={14} className="animate-spin" /> : <Save size={14} />}
              {saving ? '保存中...' : t('common.save', 'zh')}
            </button>
          </div>
        }
      />

      <div className="flex-1 overflow-hidden flex">
        {/* 左侧：编辑区 */}
        <div className="flex-1 overflow-auto p-6">
          <div className="max-w-3xl space-y-4">
            {/* 标题 */}
            <input type="text" value={title} onChange={e => setTitle(e.target.value)}
              placeholder="故事标题"
              className="w-full text-xl font-semibold px-0 py-2 border-0 outline-none bg-transparent"
              style={{ color: 'var(--foreground)' }} />

            {/* 元数据行 */}
            <div className="flex items-center gap-4">
              <label className="flex items-center gap-2 cursor-pointer">
                <input type="checkbox" checked={isPublished}
                  onChange={e => setIsPublished(e.target.checked)}
                  className="rounded" />
                <span className="text-xs">发布</span>
              </label>
              <div className="flex items-center gap-1.5">
                <Calendar size={14} style={{ color: 'var(--muted-foreground)' }} />
                <input type="date" value={storyDate}
                  onChange={e => setStoryDate(e.target.value)}
                  className="text-xs px-2 py-1 rounded border outline-none"
                  style={{ borderColor: 'var(--border)', backgroundColor: 'var(--background)', color: 'var(--foreground)' }} />
              </div>
            </div>

            {/* 内容 */}
            <div>
              <label className="block text-xs font-medium mb-1.5" style={{ color: 'var(--muted-foreground)' }}>
                内容 (Markdown)
              </label>
              <textarea value={content} onChange={e => setContent(e.target.value)}
                placeholder="在此输入故事内容..."
                rows={20}
                className="w-full px-4 py-3 text-sm rounded-lg border outline-none resize-y font-mono"
                style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)', color: 'var(--foreground)', minHeight: '300px' }} />
            </div>
          </div>
        </div>

        {/* 右侧：照片面板 */}
        <div className="w-80 border-l overflow-auto p-4 shrink-0" style={{ borderColor: 'var(--border)' }}>
          <div className="flex items-center justify-between mb-3">
            <span className="text-sm font-medium">照片 ({photos.length})</span>
            <button onClick={openPhotoSelector}
              className="flex items-center gap-1 px-2 py-1 text-xs rounded"
              style={{ backgroundColor: 'var(--secondary)', color: 'var(--secondary-foreground)' }}>
              <ImagePlus size={14} /> 添加
            </button>
          </div>

          {photos.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12"
              style={{ color: 'var(--muted-foreground)' }}>
              <ImagePlus size={24} className="mb-2 opacity-40" />
              <p className="text-xs">暂无照片</p>
            </div>
          ) : (
            <div className="space-y-2">
              {photos.map((photo, idx) => (
                <div key={photo.id}
                  className="flex items-center gap-2 px-2 py-1.5 rounded border"
                  style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}>
                  <GripVertical size={12} style={{ color: 'var(--muted-foreground)', cursor: 'grab' }} />
                  <img src={resolveAssetUrl(photo.thumbnailUrl || photo.url)} alt=""
                    className="w-10 h-10 rounded object-cover shrink-0" />
                  <div className="flex-1 min-w-0">
                    <p className="text-xs truncate">{photo.title || 'Untitled'}</p>
                    <p className="text-[10px]" style={{ color: 'var(--muted-foreground)' }}>
                      {photo.width}×{photo.height}
                    </p>
                  </div>
                  <button onClick={() => removePhoto(photo.id)}
                    className="p-0.5 rounded hover:opacity-80" style={{ color: 'var(--destructive)' }}>
                    <X size={12} />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* 照片选择弹窗 */}
      {showPhotoSelector && (
        <PhotoSelectorModal
          photos={availablePhotos}
          loading={loadingPhotos}
          hasMore={photoHasMore}
          selectedIds={new Set(photos.map(p => p.id))}
          search={photoSearch}
          onSearchChange={setPhotoSearch}
          onSearch={() => loadAvailablePhotos(true)}
          onLoadMore={() => loadAvailablePhotos(false)}
          onSelect={addPhoto}
          onClose={() => setShowPhotoSelector(false)}
        />
      )}
    </>
  )
}

// ─── 照片选择弹窗 ────────────────────────────────────

function PhotoSelectorModal({ photos, loading, hasMore, selectedIds, search, onSearchChange, onSearch, onLoadMore, onSelect, onClose }: {
  photos: Photo[]
  loading: boolean
  hasMore: boolean
  selectedIds: Set<string>
  search: string
  onSearchChange: (s: string) => void
  onSearch: () => void
  onLoadMore: () => void
  onSelect: (photo: Photo) => void
  onClose: () => void
}) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center" style={{ backgroundColor: 'rgba(0,0,0,0.5)' }}>
      <div className="w-[800px] max-h-[80vh] rounded-xl overflow-hidden flex flex-col"
        style={{ backgroundColor: 'var(--card)' }}>
        {/* 头部 */}
        <div className="flex items-center justify-between px-4 py-3 border-b" style={{ borderColor: 'var(--border)' }}>
          <span className="text-sm font-medium">选择照片</span>
          <button onClick={onClose} className="p-1 rounded hover:opacity-80" style={{ color: 'var(--muted-foreground)' }}>
            <X size={16} />
          </button>
        </div>

        {/* 搜索 */}
        <div className="px-4 py-2 border-b" style={{ borderColor: 'var(--border)' }}>
          <div className="flex gap-2">
            <input type="text" value={search}
              onChange={e => onSearchChange(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && onSearch()}
              placeholder="搜索照片..."
              className="flex-1 px-3 py-1.5 text-xs rounded border outline-none"
              style={{ borderColor: 'var(--border)', backgroundColor: 'var(--background)', color: 'var(--foreground)' }} />
            <button onClick={onSearch}
              className="px-3 py-1.5 text-xs rounded"
              style={{ backgroundColor: 'var(--primary)', color: 'var(--primary-foreground)' }}>
              搜索
            </button>
          </div>
        </div>

        {/* 照片网格 */}
        <div className="flex-1 overflow-auto p-4">
          {loading && photos.length === 0 ? (
            <div className="flex items-center justify-center py-12" style={{ color: 'var(--muted-foreground)' }}>
              <Loader2 size={16} className="animate-spin" />
            </div>
          ) : (
            <div className="grid grid-cols-6 gap-2">
              {photos.map(photo => {
                const isSelected = selectedIds.has(photo.id)
                return (
                  <div key={photo.id}
                    className="relative aspect-square rounded overflow-hidden cursor-pointer border-2 transition-all"
                    style={{ borderColor: isSelected ? 'var(--ring)' : 'transparent', opacity: isSelected ? 0.5 : 1 }}
                    onClick={() => { if (!isSelected) onSelect(photo) }}>
                    <img src={resolveAssetUrl(photo.thumbnailUrl || photo.url)} alt=""
                      className="w-full h-full object-cover" loading="lazy" />
                    {isSelected && (
                      <div className="absolute inset-0 flex items-center justify-center bg-black/30">
                        <span className="text-white text-xs font-medium">已添加</span>
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          )}

          {hasMore && (
            <div className="flex justify-center py-4">
              <button onClick={onLoadMore} disabled={loading}
                className="px-4 py-1.5 text-xs rounded disabled:opacity-50"
                style={{ backgroundColor: 'var(--secondary)', color: 'var(--secondary-foreground)' }}>
                {loading ? <Loader2 size={14} className="animate-spin" /> : '加载更多'}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

import { useState, useCallback, useRef, useEffect } from 'react'
import { PageHeader } from '@/components/layout/PageHeader'
import { SelectDropdown } from '@/components/ui/SelectDropdown'
import { usePreferences } from '@/store/preferences'
import { t } from '@/lib/i18n'
import { loadPersistentResource } from '@/lib/persistent-cache'
import { useUploadQueue } from '@/contexts/UploadQueueContext'
import { useUploadIntentStore } from '@/store/upload-intent'
import type { UploadTask } from '@/contexts/UploadQueueContext'
import { OnFileDrop, OnFileDropOff } from '../../wailsjs/runtime/runtime'
import { toast } from 'sonner'
import {
  Upload, X, CheckCircle, AlertCircle, Loader2, FileImage,
  Image as ImageIcon, Trash2, CloudUpload, GripVertical, Eye,
  Camera, Film, BookOpen, FolderOpen, Maximize2, ChevronDown, HardDrive,
} from 'lucide-react'

interface PreparedFile {
  assetId?: string
  filePath: string
  fileName: string
  fileSize: number
  hash: string
  exif?: {
    cameraMake?: string
    cameraModel?: string
    lensModel?: string
    focalLength?: string
    aperture?: string
    shutterSpeed?: string
    iso?: number
    takenAt?: string
    orientation?: number
  }
  error?: string
}

interface UploadItem {
  file: PreparedFile
  status: 'pending' | 'uploading' | 'done' | 'error' | 'duplicate'
  progress: number
  error?: string
  photoId?: string
  uploadTaskId?: string
}

interface UploadSettings {
  title: string
  categories: string[]
  albumIds: string[]
  storyId: string
  filmRollId: string
  storageSourceId: string
  storagePath: string
  compressEnabled: boolean
  maxSizeMB: number
  showFlag: boolean
  stripGPS: boolean
}

type UploadType = 'digital' | 'film'

const DEFAULT_UPLOAD_SETTINGS: UploadSettings = {
  title: '',
  categories: [],
  albumIds: [],
  storyId: '',
  filmRollId: '',
  storageSourceId: '',
  storagePath: '',
  compressEnabled: true,
  maxSizeMB: 0,
  showFlag: true,
  stripGPS: false,
}

interface UploadPageDraftState {
  items: UploadItem[]
  uploadType: UploadType
  settings: UploadSettings
  selectedIds: string[]
  categoryInput: string
  useCustomPrefix: boolean
}

let uploadPageDraftState: UploadPageDraftState = {
  items: [],
  uploadType: 'digital',
  settings: DEFAULT_UPLOAD_SETTINGS,
  selectedIds: [],
  categoryInput: '',
  useCustomPrefix: false,
}

export function UploadPage() {
  const { language } = usePreferences()
  const { tasks, addTasks } = useUploadQueue()
  const [items, setItems] = useState<UploadItem[]>(() => uploadPageDraftState.items)
  const [uploadType, setUploadType] = useState<UploadType>(() => uploadPageDraftState.uploadType)
  const [settings, setSettings] = useState<UploadSettings>(() => uploadPageDraftState.settings)
  const [preparing, setPreparing] = useState(false)
  const [isDragging, setIsDragging] = useState(false)
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set(uploadPageDraftState.selectedIds))
  const [categoryInput, setCategoryInput] = useState(() => uploadPageDraftState.categoryInput)
  const [previewFile, setPreviewFile] = useState<{ path: string; name: string } | null>(null)
  const [useCustomPrefix, setUseCustomPrefix] = useState(() => uploadPageDraftState.useCustomPrefix)
  const [showPrefixDropdown, setShowPrefixDropdown] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    uploadPageDraftState = {
      items,
      uploadType,
      settings,
      selectedIds: Array.from(selectedIds),
      categoryInput,
      useCustomPrefix,
    }
  }, [items, uploadType, settings, selectedIds, categoryInput, useCustomPrefix])

  // Wails 原生文件拖放（可获取完整路径）
  useEffect(() => {
    OnFileDrop((_x, _y, paths) => {
      if (paths && paths.length > 0) {
        processFiles(paths)
      }
      setIsDragging(false)
    }, true)

    const handleDragOver = (e: DragEvent) => { e.preventDefault(); e.stopPropagation() }
    const handleDragEnter = (e: DragEvent) => { e.preventDefault(); e.stopPropagation(); setIsDragging(true) }
    const handleDragLeave = (e: DragEvent) => {
      e.preventDefault()
      e.stopPropagation()
      if (e.relatedTarget === null) setIsDragging(false)
    }
    window.addEventListener('dragover', handleDragOver)
    window.addEventListener('dragenter', handleDragEnter)
    window.addEventListener('dragleave', handleDragLeave)

    return () => {
      OnFileDropOff()
      window.removeEventListener('dragover', handleDragOver)
      window.removeEventListener('dragenter', handleDragEnter)
      window.removeEventListener('dragleave', handleDragLeave)
    }
  }, [])

  // 关联数据
  const [albums, setAlbums] = useState<any[]>([])
  const [stories, setStories] = useState<any[]>([])
  const [filmRolls, setFilmRolls] = useState<any[]>([])
  const [storageSources, setStorageSources] = useState<any[]>([])

  // 点击外部关闭下拉框
  useEffect(() => {
    if (!showPrefixDropdown) return
    const handleClick = () => {
      setShowPrefixDropdown(false)
    }
    window.addEventListener('click', handleClick)
    return () => window.removeEventListener('click', handleClick)
  }, [showPrefixDropdown])

  // 加载关联数据
  useEffect(() => {
    (async () => {
      const failed: string[] = []
      try {
        const r = await loadPersistentResource<any[]>('albums', () => (window as any).go.main.App.GetAlbums())
        setAlbums(r || [])
      } catch { failed.push('相册') }
      try {
        const r = await loadPersistentResource<any[]>('stories', () => (window as any).go.main.App.GetStories())
        setStories(r || [])
      } catch { failed.push('故事') }
      try {
        const r = await loadPersistentResource<any[]>('film-rolls', () => (window as any).go.main.App.GetFilmRolls())
        setFilmRolls(r || [])
      } catch { failed.push('胶卷') }
      try {
        const r = await (window as any).go.main.App.GetStorageSources()
        const sources = r || []
        setStorageSources(sources)
        // 自动选中第一个存储源
        if (sources.length > 0 && !settings.storageSourceId) {
          setSettings(s => ({ ...s, storageSourceId: sources[0].id }))
        }
      } catch {
        // 存储源加载失败会导致上传按钮一直不可用，必须显式提示
        toast.error('存储源加载失败，无法上传。请检查服务器连接后重新进入本页')
      }
      if (failed.length > 0) {
        toast.error(`${failed.join('、')}列表加载失败，相关选项暂不可用`)
      }
    })()
  }, [])

  const handleSelectFiles = useCallback(async (files: FileList | null) => {
    if (!files || files.length === 0) return
    const paths: string[] = []
    for (let i = 0; i < files.length; i++) {
      const f = files[i] as any
      if (f.path) paths.push(f.path)
    }
    if (paths.length === 0) {
      toast.error('无法获取文件路径，请使用"选择文件"按钮')
      return
    }
    await processFiles(paths)
  }, [])

  const handleFileDialog = useCallback(async () => {
    try {
      const paths: string[] = await (window as any).go.main.App.SelectFiles()
      if (paths && paths.length > 0) {
        await processFiles(paths)
      }
    } catch {
      fileInputRef.current?.click()
    }
  }, [])

  const appendPreparedFiles = async (prepared: PreparedFile[]) => {
    const hashes = prepared.filter(f => f.hash).map(f => f.hash)
    let duplicates: Record<string, any> = {}
    if (hashes.length > 0) {
      try {
        const dupResult = await (window as any).go.main.App.CheckDuplicates(hashes)
        duplicates = dupResult?.duplicates || {}
      } catch {}
    }
    const newItems: UploadItem[] = prepared.map(f => ({
      file: f,
      status: f.error ? 'error' : (duplicates[f.hash] ? 'duplicate' : 'pending'),
      progress: f.error || duplicates[f.hash] ? 100 : 0,
      error: f.error || (duplicates[f.hash] ? `已存在: ${duplicates[f.hash].title || ''}` : undefined),
    }))
    setItems(prev => [...prev, ...newItems])
  }

  const processFiles = async (paths: string[]) => {
    setPreparing(true)
    try {
      const prepared: PreparedFile[] = await (window as any).go.main.App.PrepareUpload(paths)
      await appendPreparedFiles(prepared)
    } catch (err: unknown) {
      console.error('预处理失败:', err)
      toast.error(err instanceof Error ? err.message : '文件预处理失败，请重试')
    } finally {
      setPreparing(false)
    }
  }

  const processLocalAssets = async (assetIds: string[]) => {
    setPreparing(true)
    try {
      const prepared: PreparedFile[] = await (window as any).go.main.App.PrepareLocalAssetUpload(assetIds)
      await appendPreparedFiles(prepared)
    } catch (err: unknown) {
      console.error('本地资源预处理失败:', err)
      toast.error(err instanceof Error ? err.message : '本地资源预处理失败，请重新检查资源库')
    } finally {
      setPreparing(false)
    }
  }

  useEffect(() => {
    const intent = useUploadIntentStore.getState().consume()
    if (!intent) return
    if (intent.albumId) {
      setSettings((current) => ({ ...current, albumIds: [intent.albumId!] }))
    }
    if (intent.source === 'local-assets') {
      if (intent.assetIds.length > 0) void processLocalAssets(intent.assetIds)
      return
    }
    if (intent.paths.length > 0) void processFiles(intent.paths)
  }, [])

  const handleUpload = async () => {
    const pending = items.filter(i => i.status === 'pending')
    if (pending.length === 0) return

    const newTasks = addTasks(
      pending.map(item => ({
        filePath: item.file.filePath,
        assetId: item.file.assetId,
        fileName: item.file.fileName,
        fileSize: item.file.fileSize,
        hash: item.file.hash,
        exif: item.file.exif,
      })),
      {
        title: settings.title,
        categories: settings.categories,
        albumIds: settings.albumIds.length > 0 ? settings.albumIds : undefined,
        storyId: settings.storyId || undefined,
        filmRollId: uploadType === 'film' ? (settings.filmRollId || undefined) : undefined,
        storageSourceId: settings.storageSourceId,
        storagePath: settings.storagePath,
        compressEnabled: settings.compressEnabled,
        maxSizeMB: settings.maxSizeMB,
        showFlag: settings.showFlag,
        stripGPS: settings.stripGPS,
      }
    )

    const taskByPath = new Map(newTasks.map(task => [task.filePath, task]))
    setItems(prev => prev.map(item => {
      const task = taskByPath.get(item.file.filePath)
      return task ? { ...item, status: 'uploading', progress: task.progress, error: undefined, uploadTaskId: task.id } : item
    }))
    setSelectedIds(new Set())
  }

  useEffect(() => {
    if (tasks.length === 0) return
    const taskById = new Map(tasks.map(task => [task.id, task]))
    setItems(prev => prev.map(item => {
      if (!item.uploadTaskId) return item
      const task = taskById.get(item.uploadTaskId)
      if (!task) return item
      return {
        ...item,
        status: mapUploadTaskStatus(task),
        progress: task.status === 'completed' ? 100 : task.progress,
        error: task.error,
        photoId: task.photoId,
      }
    }))
  }, [tasks])

  const removeItem = (filePath: string) => {
    setItems(prev => prev.filter(i => i.file.filePath !== filePath))
    setSelectedIds(prev => { const n = new Set(prev); n.delete(filePath); return n })
  }
  const removeSelected = () => { setItems(prev => prev.filter(i => !selectedIds.has(i.file.filePath))); setSelectedIds(new Set()) }
  const clearAll = () => { setItems([]); setSelectedIds(new Set()) }
  const toggleSelect = (filePath: string) => { setSelectedIds(prev => { const n = new Set(prev); if (n.has(filePath)) n.delete(filePath); else n.add(filePath); return n }) }
  const toggleSelectAll = () => { if (selectedIds.size === items.length) setSelectedIds(new Set()); else setSelectedIds(new Set(items.map(i => i.file.filePath))) }

  const albumOptions = albums.map(a => ({ value: a.id, label: a.name }))
  const storyOptions = stories.map(s => ({ value: s.id, label: s.title }))
  const filmRollOptions = filmRolls.map(r => ({ value: r.id, label: `${r.name} · ${r.brand} · ${r.format}` }))
  const storageSourceOptions = storageSources.map(s => ({ value: s.id, label: `${s.name} (${s.type})` }))

  const pendingCount = items.filter(i => i.status === 'pending').length
  const doneCount = items.filter(i => i.status === 'done').length

  return (
    <>
      <PageHeader
        title={t('admin.page_upload', language)}
        description={items.length > 0 ? `${items.length} 个文件 · ${doneCount} 已上传 · ${pendingCount} 待上传` : undefined}
      />

      {/* 数码/胶片切换 */}
      <div className="flex gap-1 px-6 border-b" style={{ borderColor: 'var(--border)' }}>
        {[
