}

interface DesktopBlogApp extends DesktopBlogSaveApi {
  GetBlogs: () => Promise<BlogDto[]>
  DeleteBlog: (id: string) => Promise<void>
}

function getDesktopBlogApp() {
  return (window as unknown as { go: { main: { App: DesktopBlogApp } } }).go.main.App
}

export function BlogTab({ photos, settings, t, notify, refreshKey }: BlogTabProps) {
  const { token } = useAuth()
  const [blogs, setBlogs] = useState<BlogDto[]>([])
  const [loading, setLoading] = useState(true)
  const [currentBlog, setCurrentBlog] = useState<BlogFormData | null>(null)
  const [editMode, setEditMode] = useState<'list' | 'editor'>('list')
  const [isInsertingPhoto, setIsInsertingPhoto] = useState(false)
  const [saving, setSaving] = useState(false)
  const [isAiTaskLocked, setIsAiTaskLocked] = useState(false)
  const [draftDocumentId, setDraftDocumentId] = useState(createBlogDraftDocumentId)
  const editorRef = useRef<NarrativeTipTapEditorHandle>(null)

  // 自动保存状态
  const [draftSaved, setDraftSaved] = useState(false)
  const [lastSavedAt, setLastSavedAt] = useState<number | null>(null)
  const autoSaveTimerRef = useRef<NodeJS.Timeout | null>(null)

  // 记录初始状态，用于脏检查
  const [isDirty, setIsDirty] = useState(false)
  const initialBlogRef = useRef<{
    title: string
    content: string
    contentJson?: BlogDto['contentJson']
    category: string
    tags: string
    isPublished: boolean
  } | null>(null)

  // 删除确认对话框状态
  const [deleteBlogId, setDeleteBlogId] = useState<string | null>(null)

  // 发布状态筛选
  const [statusFilter, setStatusFilter] = useState('')
  // 搜索关键字
  const [blogSearchQuery, setBlogSearchQuery] = useState('')

  // 草稿恢复对话框状态
  const [draftRestoreDialog, setDraftRestoreDialog] = useState<{
    isOpen: boolean
    draft: BlogDraftData | null
    blog: BlogDto | null
    isNew: boolean
  }>({ isOpen: false, draft: null, blog: null, isNew: false })

  const fetchBlogs = useCallback(async () => {
    setLoading(true)
    try {
      const data = await getDesktopBlogApp().GetBlogs()
      setBlogs(data || [])
    } catch (error) {
      notify(t('common.error'), 'error')
      console.error('Failed to fetch blogs:', error)
    } finally {
      setLoading(false)
    }
  }, [notify, t])

  useEffect(() => {
    void fetchBlogs()
  }, [fetchBlogs])

  useEffect(() => {
    if (refreshKey && refreshKey > 0) {
      void fetchBlogs()
    }
  }, [fetchBlogs, refreshKey])

  // 进入编辑模式时加载草稿
  const loadDraftForBlog = useCallback(async (blogId?: string) => {
    try {
      const draft = await getBlogDraftFromDB(blogId)
      if (draft) {
        setLastSavedAt(draft.savedAt)
        return draft
      }
    } catch (e) {
      console.error('Failed to load blog draft', e)
    }
    return null
  }, [])

  // 保存草稿到 IndexedDB
  const saveDraft = useCallback(async () => {
    if (!currentBlog) return
    if (!currentBlog.title && !currentBlog.content) return

    try {
      await saveBlogDraftToDB({
        blogId: currentBlog.id,
        title: currentBlog.title,
        content: currentBlog.content,
        contentJson: currentBlog.contentJson ?? null,
        category: currentBlog.category,
        tags: currentBlog.tags,
        isPublished: currentBlog.isPublished,
      })
      setLastSavedAt(Date.now())
      setDraftSaved(true)
      setTimeout(() => setDraftSaved(false), 2000)
    } catch (e) {
      console.error('Failed to save blog draft', e)
    }
  }, [currentBlog])

  // 从 IndexedDB 清除草稿
  const clearDraft = useCallback(async (blogId?: string) => {
    try {
      await clearBlogDraftFromDB(blogId)
      setLastSavedAt(null)
    } catch (e) {
      console.error('Failed to clear blog draft', e)
    }
  }, [])

  // 格式化相对时间
  const formatRelativeTime = useMemo(() => {
    if (!lastSavedAt) return null
    return formatRelativeTimeLabel(lastSavedAt, t)
  }, [lastSavedAt, t])

  // 检查内容是否变更（脏检查）
  useEffect(() => {
    if (editMode !== 'editor' || !currentBlog || !initialBlogRef.current) {
      setIsDirty(false)
      return
    }

    const initial = initialBlogRef.current
    const hasChanged =
      currentBlog.title !== initial.title ||
      currentBlog.content !== initial.content ||
      JSON.stringify(currentBlog.contentJson ?? null) !== JSON.stringify(initial.contentJson ?? null) ||
      currentBlog.category !== initial.category ||
      currentBlog.tags !== initial.tags ||
      currentBlog.isPublished !== initial.isPublished

    setIsDirty(hasChanged)
  }, [editMode, currentBlog?.title, currentBlog?.content, currentBlog?.contentJson, currentBlog?.category, currentBlog?.tags, currentBlog?.isPublished])

  // 内容变更时自动保存草稿（仅在有修改时）
  useEffect(() => {
    if (isAiTaskLocked || !currentBlog || !isDirty) return
    if (!currentBlog.title && !currentBlog.content) return

    // 清除已有定时器
    if (autoSaveTimerRef.current) {
      clearTimeout(autoSaveTimerRef.current)
    }

    // 设置新的自动保存定时器
    autoSaveTimerRef.current = setTimeout(() => {
      saveDraft()
    }, AUTO_SAVE_DELAY)

    return () => {
      if (autoSaveTimerRef.current) {
        clearTimeout(autoSaveTimerRef.current)
      }
    }
  }, [currentBlog?.title, currentBlog?.content, currentBlog?.contentJson, currentBlog?.category, currentBlog?.tags, currentBlog?.isPublished, saveDraft, isAiTaskLocked, isDirty])

  // 将草稿应用到当前博客
  const applyDraft = useCallback((draft: BlogDraftData, blogId?: string) => {
    setCurrentBlog({
      id: blogId,
      title: draft.title,
      content: draft.content,
      contentJson: draft.contentJson ?? null,
      category: draft.category || t('blog.uncategorized'),
      tags: draft.tags || '',
      isPublished: draft.isPublished,
    })
    setLastSavedAt(draft.savedAt)
    // 更新初始引用以匹配恢复的草稿（不视为脏数据）
    initialBlogRef.current = {
      title: draft.title,
      content: draft.content,
      contentJson: draft.contentJson ?? null,
      category: draft.category || t('blog.uncategorized'),
      tags: draft.tags || '',
      isPublished: draft.isPublished,
    }
    notify(t('admin.restored_from_draft'), 'info')
  }, [t, notify])

  // 草稿恢复对话框 - 确认恢复
  const handleDraftRestore = useCallback(() => {
    if (draftRestoreDialog.draft) {
      applyDraft(draftRestoreDialog.draft, draftRestoreDialog.blog?.id)
    }
    setDraftRestoreDialog({ isOpen: false, draft: null, blog: null, isNew: false })
    setEditMode('editor')
  }, [draftRestoreDialog, applyDraft])

  // 草稿恢复对话框 - 丢弃草稿
  const handleDraftDiscard = useCallback(() => {
    if (draftRestoreDialog.isNew) {
      setCurrentBlog({
        title: '',
        content: '',
        contentJson: null,
        category: t('blog.uncategorized'),
        tags: '',
        isPublished: false,
      })
    } else if (draftRestoreDialog.blog) {
      setCurrentBlog({
        id: draftRestoreDialog.blog.id,
        title: draftRestoreDialog.blog.title,
        content: draftRestoreDialog.blog.content,
        contentJson: draftRestoreDialog.blog.contentJson ?? null,
        category: draftRestoreDialog.blog.category || t('blog.uncategorized'),
        tags: draftRestoreDialog.blog.tags || '',
        isPublished: draftRestoreDialog.blog.isPublished,
      })
    }
    setLastSavedAt(null)
    setDraftRestoreDialog({ isOpen: false, draft: null, blog: null, isNew: false })
    setEditMode('editor')
  }, [draftRestoreDialog, t])

  // 草稿恢复对话框 - 取消（关闭不操作）
  const handleDraftCancel = useCallback(() => {
    setDraftRestoreDialog({ isOpen: false, draft: null, blog: null, isNew: false })
    setCurrentBlog(null)
  }, [])

  const handleCreateBlog = async () => {
    setDraftDocumentId(rotateBlogDraftDocumentId)
    // 设置脏检查的初始状态
    initialBlogRef.current = {
      title: '',
      content: '',
      contentJson: null,
      category: t('blog.uncategorized'),
      tags: '',
      isPublished: false,
    }

    // 检查是否存在新博客的草稿
    const draft = await loadDraftForBlog(undefined)
    if (draft && (draft.title || draft.content)) {
      // 弹出对话框询问用户是否恢复草稿
      setCurrentBlog({
        title: '',
        content: '',
        contentJson: null,
        category: t('blog.uncategorized'),
        tags: '',
        isPublished: false,
      })
      setDraftRestoreDialog({ isOpen: true, draft, blog: null, isNew: true })
      return
    }

    setCurrentBlog({
      title: '',
      content: '',
      contentJson: null,
      category: t('blog.uncategorized'),
      tags: '',
      isPublished: false,
    })
    setEditMode('editor')
  }

  const handleEditBlog = async (blog: BlogDto) => {
    // 设置脏检查的初始状态
    initialBlogRef.current = {
      title: blog.title,
      content: blog.content,
      contentJson: blog.contentJson ?? null,
      category: blog.category || t('blog.uncategorized'),
      tags: blog.tags || '',
      isPublished: blog.isPublished,
    }

    // 检查是否存在该博客的草稿
    const draft = await loadDraftForBlog(blog.id)
    if (draft && draft.savedAt > new Date(blog.updatedAt).getTime()) {
      // 草稿比已保存版本更新，弹出对话框
      setCurrentBlog({
        id: blog.id,
        title: blog.title,
        content: blog.content,
        contentJson: blog.contentJson ?? null,
        category: blog.category || t('blog.uncategorized'),
        tags: blog.tags || '',
        isPublished: blog.isPublished,
      })
      setDraftRestoreDialog({ isOpen: true, draft, blog, isNew: false })
      return
    }

    setCurrentBlog({
      id: blog.id,
      title: blog.title,
      content: blog.content,
      contentJson: blog.contentJson ?? null,
      category: blog.category || t('blog.uncategorized'),
      tags: blog.tags || '',
      isPublished: blog.isPublished,
    })
    setLastSavedAt(null)
    setEditMode('editor')
  }

  const confirmDeleteBlog = async () => {
    if (!deleteBlogId) return
    try {
      await getDesktopBlogApp().DeleteBlog(deleteBlogId)
      await fetchBlogs()
      notify(t('admin.notify_log_deleted'))
    } catch (error) {
      notify(t('common.error'), 'error')
      console.error('Failed to delete blog:', error)
    } finally {
      setDeleteBlogId(null)
    }
  }

  const handleSaveBlog = async () => {
    if (isAiTaskLocked || !currentBlog) return
    if (!currentBlog.title.trim()) {
      notify(t('blog.enter_title'), 'error')
      return
    }
    if (!currentBlog.content.trim()) {
      notify(t('blog.enter_content'), 'error')
      return
    }

    setSaving(true)
    try {
      await persistDesktopBlog({
        api: getDesktopBlogApp(),
        blogId: currentBlog.id,
        data: {
          title: currentBlog.title,
          content: currentBlog.content,
          contentJson: currentBlog.contentJson ?? null,
          category: currentBlog.category,
          tags: currentBlog.tags,
          isPublished: currentBlog.isPublished,
        },
        onCreated: (blogId) => {
          setCurrentBlog((blog) => (blog ? { ...blog, id: blogId } : blog))
        },
      })
      await clearDraft(currentBlog.id)

      await fetchBlogs()
      setEditMode('list')
      setCurrentBlog(null)
      setLastSavedAt(null)
      notify(t('admin.notify_log_saved'))
    } catch (error) {
      notify(t('common.error'), 'error')
      console.error('Failed to save blog:', error)
    } finally {
      setSaving(false)
    }
  }

  const insertPhotoIntoBlog = (photo: PhotoDto) => {
    if (isAiTaskLocked) return
    const markdown = buildStoryMarkdownImage({
      url: resolveAssetUrl(photo.url, settings?.cdn_domain),
      alt: photo.title,
    })
    if (editorRef.current) {
      editorRef.current.insertMarkdown(markdown)
      const nextValue = editorRef.current.getValue()
      const nextJsonValue = editorRef.current.getJsonValue()
      setCurrentBlog((prev) => (prev ? { ...prev, content: nextValue, contentJson: nextJsonValue } : prev))
    } else if (currentBlog) {
      setCurrentBlog({ ...currentBlog, content: currentBlog.content + markdown })
    }
    setIsInsertingPhoto(false)
    notify(t('admin.notify_photo_inserted'), 'info')
  }

  const handleContentChange = (content: string) => {
    setCurrentBlog((prev) => (prev ? { ...prev, content } : prev))
  }

  const handleJsonContentChange = (contentJson: NonNullable<BlogDto['contentJson']>) => {
    setCurrentBlog((prev) => (prev ? { ...prev, contentJson } : prev))
  }

  const resolvedCdnDomain = settings?.cdn_domain?.trim() || undefined
  const blogDocumentId = resolveBlogDocumentId(currentBlog?.id, draftDocumentId)


  // 博客发布状态筛选选项
  const statusOptions: SelectOption[] = [
    { value: '', label: t('admin.all_status') || '全部状态' },
    { value: 'published', label: t('admin.published') || '已发布' },
    { value: 'draft', label: t('admin.draft') || '草稿' },
  ]

  const filteredBlogs = useMemo(() => {
    const query = blogSearchQuery.trim().toLowerCase()
    return blogs.filter((blog) => {
      const matchesStatus =
        !statusFilter ||
        (statusFilter === 'published' ? blog.isPublished : !blog.isPublished)
      const matchesQuery =
        !query ||
        [blog.title, blog.content, blog.category, blog.tags].some((value) =>
          value?.toLowerCase().includes(query),
        )
      return matchesStatus && matchesQuery
    })
  }, [blogs, blogSearchQuery, statusFilter])

  const hasActiveFilters = !!blogSearchQuery.trim() || !!statusFilter

  return (
    <div className="h-full flex flex-col gap-6 overflow-hidden">
      {editMode === 'list' ? (
        <div className="flex flex-1 flex-col gap-4 overflow-hidden">
          <div className="flex shrink-0 flex-wrap items-center justify-between gap-3 border-b border-border pb-4">
            <div className="flex min-w-0 flex-1 items-center gap-3">
              <div className="relative">
                <Search
                  size={14}
                  className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2"
                  style={{ color: 'var(--muted-foreground)' }}
                />
                <input
                  type="text"
                  value={blogSearchQuery}
                  onChange={(e) => setBlogSearchQuery(e.target.value)}
                  placeholder={t('admin.search_placeholder') || '搜索...'}
                  className="w-56 rounded-md border py-1.5 pl-8 pr-3 text-xs outline-none transition-colors focus:border-primary"
                  style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}
                />
              </div>
              <SelectDropdown
                value={statusFilter}
                options={statusOptions}
                onChange={(value) => setStatusFilter(value as string)}
                placeholder={t('admin.all_status') || '全部状态'}
                className="w-32"
              />
            </div>
            <AdminButton
              onClick={handleCreateBlog}
              adminVariant="primary"
              size="sm"
              className="flex items-center rounded-md px-3 py-1.5"
            >
              <Plus className="mr-1.5 h-3.5 w-3.5" />
              {t('ui.create_blog')}
            </AdminButton>
          </div>
          <div className="custom-scrollbar flex-1 overflow-y-auto">
            {loading ? (
              <AdminLoading text={t('common.loading')} className="min-h-[320px]" />
            ) : filteredBlogs.length > 0 ? (
              <div className="space-y-2">
                {filteredBlogs.map((blog) => (
                  <div
                    key={blog.id}
                    className="group flex items-center gap-4 rounded-lg border px-4 py-3 transition-colors hover:border-primary/50"
                    style={{ borderColor: 'var(--border)', backgroundColor: 'var(--card)' }}
                  >
                    <div
                      className="flex h-14 w-14 shrink-0 items-center justify-center rounded-md"
                      style={{ backgroundColor: 'color-mix(in srgb, var(--muted) 60%, transparent)' }}
                    >
                      <BookText className="h-5 w-5" style={{ color: 'var(--muted-foreground)' }} />
                    </div>
                    <div className="min-w-0 flex-1 cursor-pointer" onClick={() => handleEditBlog(blog)}>
                      <div className="mb-1 flex items-center gap-3">
                        <h4 className="truncate font-serif text-lg transition-colors group-hover:text-primary">
                          {blog.title || t('admin.untitled')}
                        </h4>
                        <span
                          className="shrink-0 rounded px-1.5 py-0.5 text-[10px]"
                          style={
                            blog.isPublished
                              ? { backgroundColor: 'var(--accent)', color: 'var(--accent-foreground)' }
                              : { backgroundColor: 'var(--muted)', color: 'var(--muted-foreground)' }
                          }
                        >
                          {blog.isPublished ? t('admin.published') : t('admin.draft')}
                        </span>
                      </div>
                      <div
                        className="flex flex-wrap items-center gap-x-5 gap-y-1 font-mono text-[10px] uppercase tracking-wide"
                        style={{ color: 'var(--muted-foreground)' }}
                      >
                        <span className="flex items-center gap-1.5">
                          <History className="h-3 w-3" />
                          {new Date(blog.updatedAt).toLocaleString()}
                        </span>
                        {blog.category && <span>{blog.category}</span>}
                        <span className="flex items-center gap-1.5">
                          <FileText className="h-3 w-3" />
                          {blog.content.length} {t('admin.characters')}
                        </span>
                      </div>
                    </div>
                    <div className="ml-auto flex shrink-0 items-center gap-1.5 transition-opacity duration-200 sm:opacity-0 sm:group-hover:opacity-100 sm:group-focus-within:opacity-100">
                      <AdminButton onClick={() => handleEditBlog(blog)} adminVariant="iconPrimary">
                        <Edit3 className="h-4 w-4" />
                      </AdminButton>
                      <AdminButton onClick={() => setDeleteBlogId(blog.id)} adminVariant="iconDestructive">
                        <Trash2 className="h-4 w-4" />
                      </AdminButton>
                    </div>
                  </div>
                ))}
              </div>
            ) : blogs.length === 0 ? (
              <div
                className="flex flex-col items-center justify-center rounded-lg border border-dashed px-4 py-20 text-center"
                style={{ borderColor: 'var(--border)', backgroundColor: 'color-mix(in srgb, var(--card) 50%, transparent)' }}
              >
                <div
                  className="mb-4 flex h-14 w-14 items-center justify-center rounded-xl border"
                  style={{ borderColor: 'var(--border)', backgroundColor: 'var(--muted)' }}
                >
                  <BookText className="h-6 w-6" style={{ color: 'var(--muted-foreground)' }} />
                </div>
                <h3 className="mb-4 text-sm font-semibold">{t('ui.no_blog')}</h3>
              </div>
            ) : (
              <div
                className="flex flex-col items-center justify-center rounded-lg border border-dashed px-4 py-20 text-center"
                style={{ borderColor: 'var(--border)', backgroundColor: 'color-mix(in srgb, var(--card) 50%, transparent)' }}
              >
                <div
                  className="mb-4 flex h-14 w-14 items-center justify-center rounded-xl border"
                  style={{ borderColor: 'var(--border)', backgroundColor: 'var(--muted)' }}
                >
                  <Search className="h-6 w-6" style={{ color: 'var(--muted-foreground)' }} />
                </div>
                <h3 className="mb-2 text-sm font-semibold">{t('common.search')}</h3>
                <p className="mb-4 text-xs" style={{ color: 'var(--muted-foreground)' }}>
                  {t('admin.no_albums_match_filters') || 'No blogs match the current filters'}
                </p>
                {hasActiveFilters && (
                  <div className="flex items-center gap-2">
                    {!!blogSearchQuery.trim() && (
                      <button
                        onClick={() => setBlogSearchQuery('')}
                        className="flex items-center gap-1.5 rounded-md border px-3 py-1.5 text-xs transition-opacity hover:opacity-80"
                        style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}
                      >
                        <X className="h-3.5 w-3.5" />
                        {t('common.search')}
                      </button>
                    )}
                    {!!statusFilter && (
                      <button
                        onClick={() => setStatusFilter('')}
                        className="flex items-center gap-1.5 rounded-md border px-3 py-1.5 text-xs transition-opacity hover:opacity-80"
                        style={{ borderColor: 'var(--border)', color: 'var(--muted-foreground)' }}
                      >
                        <X className="h-3.5 w-3.5" />
                        {t('admin.filter') || 'Filter'}
                      </button>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col gap-6 overflow-hidden">
          <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
            <div className="flex items-center gap-4">
              <AdminButton
                disabled={isAiTaskLocked}
                onClick={() => {
                  setEditMode('list')
                  setCurrentBlog(null)
                  setLastSavedAt(null)
                  initialBlogRef.current = null
                  setIsDirty(false)
                }}
                adminVariant="link"
                className="flex items-center gap-2 hover:no-underline"
              >
                <ChevronLeft className="w-4 h-4" /> {t('admin.back_list')}
              </AdminButton>
              {/* 草稿状态指示器 */}
              {draftSaved && (
                <div className="flex items-center gap-1 text-[10px] text-green-500">
                  <Check className="w-3 h-3" />
                  <span>{t('story.draft_saved') || '已保存'}</span>
                </div>
              )}
              {!draftSaved && lastSavedAt && (
                <div className="flex items-center gap-1 text-[10px] text-muted-foreground/60">
                  <Clock className="w-3 h-3" />
                  <span>{formatRelativeTime}</span>
                </div>
              )}
            </div>
            <div className="flex items-center gap-4">
              <label className="flex items-center gap-2 text-xs">
                <input
                  type="checkbox"
                  disabled={isAiTaskLocked}
                  checked={currentBlog?.isPublished || false}
                  onChange={(e) =>
                    setCurrentBlog((prev) => ({
                      ...prev!,
                      isPublished: e.target.checked,
                    }))
                  }
                  className="w-4 h-4"
                />
                <span className="font-bold uppercase tracking-widest">{t('admin.publish')}</span>
              </label>
              <AdminButton
                onClick={handleSaveBlog}
                disabled={saving || isAiTaskLocked}
                adminVariant="primary"
                size="lg"
                className="flex items-center gap-2"
              >
                {saving ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Save className="w-4 h-4" />
                )}
                <span>{t('admin.save')}</span>
              </AdminButton>
            </div>
          </div>
          <div className="flex-1 flex flex-col gap-4 overflow-hidden relative">
            <div className="flex-1 flex flex-col gap-4 overflow-hidden">
              <input
                type="text"
                disabled={isAiTaskLocked}
                value={currentBlog?.title || ''}
                onChange={(e) =>
                  setCurrentBlog((prev) => ({
                    ...prev!,
                    title: e.target.value,
                  }))
                }
                placeholder={t('blog.title_placeholder')}
                className="w-full p-6 bg-transparent border border-border focus:border-primary outline-none text-2xl font-serif rounded-none"
              />
              <div className="flex gap-4">
                <input
                  type="text"
                  disabled={isAiTaskLocked}
                  value={currentBlog?.category || ''}
                  onChange={(e) =>
                    setCurrentBlog((prev) => ({
                      ...prev!,
                      category: e.target.value,
                    }))
                  }
                  placeholder={t('ui.category_filter')}
                  className="flex-1 p-3 bg-transparent border border-border focus:border-primary outline-none text-sm rounded-none"
                />
                <input
                  type="text"
                  disabled={isAiTaskLocked}
                  value={currentBlog?.tags || ''}
                  onChange={(e) =>
                    setCurrentBlog((prev) => ({
                      ...prev!,
                      tags: e.target.value,
                    }))
                  }
                  placeholder="Tags"
                  className="flex-1 p-3 bg-transparent border border-border focus:border-primary outline-none text-sm rounded-none"
                />
              </div>
              <div className="flex-1 relative border border-border bg-card/30 overflow-visible">
                {currentBlog && (
                  <NarrativeTipTapEditor
                    key={blogDocumentId}
                    ref={editorRef}
                    value={currentBlog.content}
                    jsonValue={currentBlog.contentJson ?? null}
                    onChange={handleContentChange}
                    onJsonChange={handleJsonContentChange}
                    placeholder={t('ui.markdown_placeholder')}
                    className="overflow-hidden bg-background"
                    documentId={blogDocumentId}
                    documentKind="blog"
                    onAiTaskLockChange={setIsAiTaskLocked}
                    aiOptions={{
                      enabled: Boolean(token),
                      token,
                      scopeId: blogDocumentId,
                      title: currentBlog.title,
                    }}
                  />
                )}
                <AdminButton
                  disabled={isAiTaskLocked}
                  onClick={() => setIsInsertingPhoto(true)}
                  adminVariant="unstyled"
                  className="absolute bottom-6 right-6 p-4 bg-background border border-border hover:border-primary text-primary transition-all shadow-2xl z-10"
                  title={t('blog.insert_photo')}
                >
                  <ImageIcon className="w-6 h-6" />
                </AdminButton>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 插入照片弹窗 */}
      {isInsertingPhoto && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 md:p-12 bg-background/95 backdrop-blur-sm">
          <div className="w-full h-full max-w-6xl bg-background border border-border flex flex-col overflow-hidden shadow-2xl">
            <div className="p-6 border-b border-border flex items-center justify-between">
              <h3 className="font-serif text-2xl uppercase tracking-tight">
                {t('blog.insert_photo')}
              </h3>
              <AdminButton
                onClick={() => setIsInsertingPhoto(false)}
                adminVariant="icon"
              >
                <X className="w-6 h-6" />
              </AdminButton>
            </div>
            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
              <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-4">
                {photos.map((photo) => (
                  <button
                    type="button"
                    key={photo.id}
                    disabled={isAiTaskLocked}
                    onClick={() => insertPhotoIntoBlog(photo)}
                    className="group relative aspect-square bg-muted cursor-pointer overflow-hidden border border-transparent hover:border-primary transition-all disabled:cursor-not-allowed disabled:opacity-60"
                  >
                    <img
                      src={resolveAssetUrl(
                        photo.thumbnailUrl || photo.url,
                        resolvedCdnDomain
                      )}
                      alt=""
                      className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all"
                    />
                    <div className="absolute inset-0 bg-primary/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Plus className="w-8 h-8 text-white" />
                    </div>
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      <SimpleDeleteDialog isOpen={!!deleteBlogId} onConfirm={confirmDeleteBlog} onCancel={() => setDeleteBlogId(null)} t={t} />
      <DraftRestoreDialog
        isOpen={draftRestoreDialog.isOpen}
        draftTime={draftRestoreDialog.draft?.savedAt || 0}
        onRestore={handleDraftRestore}
        onDiscard={handleDraftDiscard}
        onCancel={handleDraftCancel}
        t={t}
      />
    </div>
  )
}

/**
 * 故事管理标签页 - 图文故事的创建、编辑、照片关联及发布管理
 */
'use client'

import { useCallback, useEffect, useRef, useState } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import {
  getPhotos,
  type PhotoDto,
  type StoryDto,
} from '@/lib/api'
import { PhotoSelectorModal } from '@/components/admin/PhotoSelectorModal'
import { ImageUploadSettingsModal, type UploadSettings } from '@/components/admin/ImageUploadSettingsModal'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import { DraftRestoreDialog } from '@/components/admin/DraftRestoreDialog'
import { StoryPreviewModal } from '@/components/admin/StoryPreviewModal'
import { StoryCoverCropModal } from '@/components/admin/StoryCoverCropModal'
import type { PendingImage } from '@/components/admin/StoryPhotoPanel'
import { getStoryReferencedPhotoIds } from '@/lib/story-rich-content'
import { getStoryCoverCrop, getStoryCoverPhoto, normalizeStoryCoverCrop, toStoryCoverCropValue } from '@/lib/story-cover'
import { normalizeCompressionMode } from '@/lib/image-compress'
import { useAdmin } from './layout'
import {
  STORY_PHOTO_PANEL_COLLAPSED_KEY,
  STORY_UPLOAD_SETTINGS_KEY,
  STORY_PASTE_UPLOAD_SETTINGS_KEY,
} from './stories/constants'
import { StoryEditorView } from './stories/StoryEditorView'
import { StoryListView } from './stories/StoryListView'
import type { StoriesTabProps } from './stories/types'
import { useStoryDraftState } from './stories/useStoryDraftState'
import { useStoryEditorActions } from './stories/useStoryEditorActions'
import { useStoryPhotoDnD } from './stories/useStoryPhotoDnD'
import { applySavedOrder, savePhotoOrder } from './stories/utils'

const DEFAULT_UPLOAD_SETTINGS: UploadSettings = {
  maxSizeMB: 0,
  compressionMode: 'compress',
  showFlag: true,
  storageProvider: 'local',
  categories: [],
  albumIds: [],
  stripGps: false,
}

const DEFAULT_PASTE_UPLOAD_SETTINGS: UploadSettings = {
  maxSizeMB: 0,
  compressionMode: 'compress',
  showFlag: true,
  storageProvider: 'local',
  categories: [],
  albumIds: [],
  stripGps: false,
}

export function StoriesTab({ token, t, notify, editStoryId, editFromDraft, onDraftConsumed, refreshKey, onEditingChange }: StoriesTabProps) {
  const navigate = useNavigate()
  const location = useLocation()
  const { settings, categories, isImmersiveMode, setIsImmersiveMode } = useAdmin()

  const [stories, setStories] = useState<StoryDto[]>([])
  const [loading, setLoading] = useState(true)
  const [currentStory, setCurrentStory] = useState<StoryDto | null>(null)
  const [storyEditMode, setStoryEditMode] = useState<'list' | 'editor'>('list')
  const [saving, setSaving] = useState(false)
  const [allPhotos, setAllPhotos] = useState<PhotoDto[]>([])
  const [pendingImages, setPendingImages] = useState<PendingImage[]>([])
  const [showPhotoSelector, setShowPhotoSelector] = useState(false)
  const [pendingCoverId, setPendingCoverId] = useState<string | null>(null)
  const [deleteStoryId, setDeleteStoryId] = useState<string | null>(null)
  const [statusFilter, setStatusFilter] = useState('')
  const [useCustomDate, setUseCustomDate] = useState(false)
  const [isPhotoPanelCollapsed, setIsPhotoPanelCollapsed] = useState(false)
  const [showPreview, setShowPreview] = useState(false)
  const [previewPhotoIndex, setPreviewPhotoIndex] = useState<number | null>(null)
  const [showCoverCropEditor, setShowCoverCropEditor] = useState(false)

  const initialLoadRef = useRef(false)
  const savingRef = useRef(false)
  const handledEditStoryIdRef = useRef<string | null>(null)
  const pendingPhotoIdsRef = useRef<string[] | null>(null)

  const loadStories = useCallback(async () => {
    try {
      setLoading(true)
      const data = await (window as any).go.main.App.GetStories()
      setStories(applySavedOrder(data || []))
    } catch (error) {
      console.error('Failed to load stories:', error)
      notify(t('story.load_failed'), 'error')
    } finally {
      setLoading(false)
    }
  }, [notify, t])

  const loadAllPhotos = useCallback(async () => {
    try {
      const data = await (window as any).go.main.App.GetAllPhotos()
      setAllPhotos(data || [])
    } catch (error) {
      console.error('Failed to load photos:', error)
    }
  }, [])

  const {
    draftSaved,
    lastSavedAt,
    initialStory,
    draftRestoreDialog,
    createStoryWithDraftCheck,
    editStoryWithDraftCheck,
    handleDraftRestore,
    handleDraftDiscard,
    handleDraftCancel,
    clearDraft,
    resetDraftState,
  } = useStoryDraftState({
    allPhotos,
    currentStory,
    pendingImages,
    pendingCoverId,
    stories,
    storyEditMode,
    editFromDraft,
    onDraftConsumed,
    notify,
    t,
    loadAllPhotos,
    setCurrentStory,
    setPendingImages,
    setPendingCoverId,
    setStoryEditMode,
  })

  const doSaveStory = useCallback(async () => {
    if (!currentStory) return
    if (savingRef.current) return

    try {
      savingRef.current = true
      setSaving(true)
      const isNew = !stories.find((story) => story.id === currentStory.id)
      const basePhotoIds = currentStory.photos?.map((photo) => photo.id) || []
      const extraIds = pendingPhotoIdsRef.current || []
      const photoIdSet = new Set(basePhotoIds)
      for (const id of extraIds) photoIdSet.add(id)
      const photoIds = Array.from(photoIdSet)
      pendingPhotoIdsRef.current = null

      const dateChanged = initialStory && currentStory.storyDate !== initialStory.storyDate

      if (isNew) {
        await (window as any).go.main.App.CreateStory({
          title: currentStory.title,
          content: currentStory.content,
          contentJson: currentStory.contentJson ?? null,
          isPublished: currentStory.isPublished,
          photoIds,
          coverPhotoId: currentStory.coverPhotoId,
          coverCrop: currentStory.coverCrop ?? null,
          ...(dateChanged && currentStory.storyDate ? { storyDate: currentStory.storyDate } : {}),
        })
        notify(t('story.created'), 'success')
      } else {
        await (window as any).go.main.App.UpdateStory(currentStory.id, {
          title: currentStory.title,
          content: currentStory.content,
          contentJson: currentStory.contentJson ?? null,
          isPublished: currentStory.isPublished,
          coverPhotoId: currentStory.coverPhotoId ?? null,
          coverCrop: currentStory.coverCrop ?? null,
          ...(dateChanged ? { storyDate: currentStory.storyDate } : {}),
        })
        if (photoIds.length > 0) {
          await (window as any).go.main.App.ReorderStoryPhotos(currentStory.id, photoIds)
        }
        savePhotoOrder(currentStory.id, photoIds)
        notify(t('story.updated'), 'success')
      }

      await clearDraft(currentStory.id)
      pendingImages.forEach((image) => URL.revokeObjectURL(image.previewUrl))
      setPendingImages([])
      setPendingCoverId(null)
      setUseCustomDate(false)
      setPreviewPhotoIndex(null)
      setShowPreview(false)
      resetDraftState()
      setStoryEditMode('list')
      setCurrentStory(null)
      await loadStories()
      if (location.search.includes('editStory=')) {
        navigate('/photo-journal', { replace: true })
      }
    } catch (error) {
      console.error('Failed to save story:', error)
      notify(t('story.save_failed'), 'error')
    } finally {
      savingRef.current = false
      setSaving(false)
    }
  }, [clearDraft, currentStory, initialStory, loadStories, location.search, notify, pendingImages, resetDraftState, navigate, stories, t])

  const {
    editorRef,
    showUploadSettings,
    setShowUploadSettings,
    showPasteUploadSettings,
    setShowPasteUploadSettings,
    isUploading,
    uploadProgress,
    pendingPasteFilesRef,
    uploadSettings,
    pasteUploadSettings,
    handlePhotoPanelDrop,
    handleRemovePendingImage,
    handleConfirmUpload,
    handleRetryFailedUploads,
    handlePasteFiles,
    handleConfirmPasteUpload,
    handleInsertPhotoMarkdown,
    handleInsertGalleryMarkdown,
    handleInsertExternalPhotoMarkdown,
    restorePasteUploadSettings,
    restoreUploadSettings,
  } = useStoryEditorActions({
    token,
    currentStory,
    allPhotos,
    stories,
    pendingImages,
    initialUploadSettings: DEFAULT_UPLOAD_SETTINGS,
    initialPasteUploadSettings: DEFAULT_PASTE_UPLOAD_SETTINGS,
    pendingPhotoIdsRef,
    setCurrentStory,
    setAllPhotos,
    setPendingImages,
    notify,
    t,
    onRequestSave: doSaveStory,
  })

  const {
    draggedItemId,
    draggedItemType,
    dragOverItemId,
    isDraggingOver,
    openMenuPhotoId,
    openMenuPendingId,
    setOpenMenuPhotoId,
    setOpenMenuPendingId,
    handlePhotoPanelDragOver,
    handlePhotoPanelDragLeave,
    handleItemDragStart,
    handleItemDragEnd,
    handleItemDragOver,
    handleItemDragLeave,
    handleItemDrop,
    setIsDraggingOver,
  } = useStoryPhotoDnD({
    currentStory,
    pendingImages,
    setCurrentStory,
    setPendingImages,
  })

  const resetEditorState = useCallback(() => {
    pendingImages.forEach((image) => URL.revokeObjectURL(image.previewUrl))
    setPendingImages([])
    setPendingCoverId(null)
    setUseCustomDate(false)
    setPreviewPhotoIndex(null)
    setShowPreview(false)
    setStoryEditMode('list')
    setCurrentStory(null)
    resetDraftState()
    setIsDraggingOver(false)
    if (location.search.includes('editStory=')) {
      navigate('/photo-journal', { replace: true })
    }
  }, [location.search, pendingImages, resetDraftState, navigate, setIsDraggingOver])

  const handleSaveStory = useCallback(async () => {
    if (!token || !currentStory) return
    if (savingRef.current) return
    if (!currentStory.title.trim() || !currentStory.content.trim()) {
      notify(t('story.fill_title_content'), 'error')
      return
    }

    const referencedPhotoIds = getStoryReferencedPhotoIds(currentStory.content)
    const availablePhotoIds = new Set((currentStory.photos || []).map((photo) => photo.id))
    const invalidPhotoIds = Array.from(referencedPhotoIds).filter((photoId) => !availablePhotoIds.has(photoId))
    if (invalidPhotoIds.length > 0) {
      notify(`正文中引用了未关联的图库图片：${invalidPhotoIds.slice(0, 3).join(', ')}`, 'error')
      return
    }

    const pendingToUpload = pendingImages.filter((image) => image.status === 'pending' || image.status === 'failed')
    if (pendingToUpload.length > 0) {
      setShowUploadSettings(true)
      return
    }

    await doSaveStory()
  }, [currentStory, doSaveStory, notify, pendingImages, setShowUploadSettings, t, token])

  const handleUpdatePhotos = useCallback(async (selectedPhotoIds: string[]) => {
    let sourcePhotos = allPhotos

    if (selectedPhotoIds.some((id) => !sourcePhotos.find((photo) => photo.id === id))) {
      try {
        sourcePhotos = await getPhotos({ all: true })
        setAllPhotos(sourcePhotos)
      } catch (error) {
        console.error('Failed to refresh photos for selector:', error)
      }
    }

    const selectedPhotos = selectedPhotoIds
      .map((id) => sourcePhotos.find((photo) => photo.id === id) || currentStory?.photos?.find((photo) => photo.id === id))
      .filter((photo): photo is PhotoDto => Boolean(photo))

    setCurrentStory((prev) => {
      if (!prev) return prev

      const coverStillExists = prev.coverPhotoId
        ? selectedPhotos.some((photo) => photo.id === prev.coverPhotoId)
        : true

      return {
        ...prev,
        photos: selectedPhotos,
        ...(coverStillExists
          ? {}
          : {
              coverPhotoId: undefined,
              coverCrop: null,
            }),
      }
    })
    setShowPhotoSelector(false)
  }, [allPhotos, currentStory?.photos])

  const handleRemovePhoto = useCallback((photoId: string) => {
    setCurrentStory((prev) => {
      if (!prev) return prev

      const nextPhotos = prev.photos?.filter((photo) => photo.id !== photoId) || []
      const removedCover = prev.coverPhotoId === photoId

      return {
        ...prev,
        photos: nextPhotos,
        ...(removedCover
          ? {
              coverPhotoId: undefined,
              coverCrop: null,
            }
          : {}),
      }
    })
  }, [])

  const handleSetCover = useCallback((photoId: string) => {
    setCurrentStory((prev) => {
      if (!prev) return prev
      const shouldResetCrop = prev.coverPhotoId !== photoId
      return {
        ...prev,
        coverPhotoId: photoId,
        ...(shouldResetCrop
          ? {
              coverCrop: null,
            }
          : {}),
      }
    })
    setPendingCoverId(null)
    setShowCoverCropEditor(true)
  }, [])

  const handleSetPendingCover = useCallback((id: string) => {
    setPendingCoverId(id)
    setCurrentStory((prev) => (prev ? {
      ...prev,
      coverPhotoId: undefined,
      coverCrop: null,
    } : prev))
  }, [])

  const handleSetPhotoDate = useCallback((takenAt: string) => {
    setCurrentStory((prev) => (prev ? { ...prev, storyDate: takenAt } : prev))
    setUseCustomDate(true)
  }, [])

  const handleApplyCoverCrop = useCallback((crop: { x: number; y: number; width: number; height: number } | null) => {
    setCurrentStory((prev) => {
      if (!prev) return prev
      const normalized = crop ? normalizeStoryCoverCrop(crop) : null
      return {
        ...prev,
        coverCrop: toStoryCoverCropValue(normalized),
      }
    })
    setShowCoverCropEditor(false)
  }, [])

  const handleTogglePublish = useCallback(async (story: StoryDto) => {
    try {
      await (window as any).go.main.App.UpdateStory(story.id, { isPublished: !story.isPublished })
      notify(story.isPublished ? t('story.unpublished') : t('story.published'), 'success')
      await loadStories()
    } catch (error) {
      console.error('Failed to toggle publish:', error)
      notify(t('story.operation_failed'), 'error')
    }
  }, [loadStories, notify, t])

  const confirmDeleteStory = useCallback(async () => {
    if (!deleteStoryId) return

    try {
      await (window as any).go.main.App.DeleteStory(deleteStoryId)
      notify(t('story.deleted'), 'success')
      await loadStories()
    } catch (error) {
      console.error('Failed to delete story:', error)
      notify(t('story.delete_failed'), 'error')
    } finally {
      setDeleteStoryId(null)
    }
  }, [deleteStoryId, loadStories, notify, t])

  const handleCreateStory = useCallback(async () => {
    await createStoryWithDraftCheck()
  }, [createStoryWithDraftCheck])

  const handleEditStory = useCallback(async (story: StoryDto) => {
    await editStoryWithDraftCheck(story)
  }, [editStoryWithDraftCheck])

  const currentPhotoIds = currentStory?.photos?.map((photo) => photo.id) || []
  const currentCoverPhoto = currentStory ? getStoryCoverPhoto(currentStory) : null
  const currentCoverCrop = currentStory ? getStoryCoverCrop(currentStory) : null

  const handlePrevPhoto = useCallback(() => {
    if (previewPhotoIndex === null || !currentStory?.photos) return
    setPreviewPhotoIndex(previewPhotoIndex > 0 ? previewPhotoIndex - 1 : currentStory.photos.length - 1)
  }, [currentStory?.photos, previewPhotoIndex])

  const handleNextPhoto = useCallback(() => {
    if (previewPhotoIndex === null || !currentStory?.photos) return
    setPreviewPhotoIndex(previewPhotoIndex < currentStory.photos.length - 1 ? previewPhotoIndex + 1 : 0)
  }, [currentStory?.photos, previewPhotoIndex])

  useEffect(() => {
    if (!initialLoadRef.current) {
      void loadStories()
      initialLoadRef.current = true
    }
  }, [loadStories])

  useEffect(() => {
    onEditingChange?.(storyEditMode === 'editor')
  }, [onEditingChange, storyEditMode])

  useEffect(() => {
    if (storyEditMode !== 'editor') {
      setIsImmersiveMode(false)
    }
  }, [setIsImmersiveMode, storyEditMode])

  useEffect(() => () => setIsImmersiveMode(false), [setIsImmersiveMode])

  useEffect(() => {
    if (refreshKey && refreshKey > 0) {
      void loadStories()
    }
  }, [loadStories, refreshKey])

  useEffect(() => {
    if (typeof window === 'undefined') return
    setIsPhotoPanelCollapsed(window.localStorage.getItem(STORY_PHOTO_PANEL_COLLAPSED_KEY) === 'true')

    const raw = window.localStorage.getItem(STORY_PASTE_UPLOAD_SETTINGS_KEY)
    if (raw) {
      try {
        const parsed = JSON.parse(raw) as UploadSettings
        if (parsed.compressionMode) parsed.compressionMode = normalizeCompressionMode(parsed.compressionMode)
        restorePasteUploadSettings({ ...DEFAULT_PASTE_UPLOAD_SETTINGS, ...parsed })
      } catch (error) {
        console.error('Failed to restore paste upload settings:', error)
      }
    }

    const uploadRaw = window.localStorage.getItem(STORY_UPLOAD_SETTINGS_KEY)
    if (!uploadRaw) return

    try {
      const parsed = JSON.parse(uploadRaw) as UploadSettings
      if (parsed.compressionMode) parsed.compressionMode = normalizeCompressionMode(parsed.compressionMode)
      restoreUploadSettings({ ...DEFAULT_UPLOAD_SETTINGS, ...parsed })
    } catch (error) {
      console.error('Failed to restore upload settings:', error)
    }
  }, [restorePasteUploadSettings, restoreUploadSettings])

  useEffect(() => {
    if (!editStoryId) {
      handledEditStoryIdRef.current = null
      return
    }

    if (handledEditStoryIdRef.current === editStoryId) {
      return
    }

    const story = stories.find((item) => item.id === editStoryId)
    if (!story) {
      return
    }

    if (storyEditMode === 'editor' && currentStory?.id === editStoryId) {
      handledEditStoryIdRef.current = editStoryId
      return
    }

    handledEditStoryIdRef.current = editStoryId
    void editStoryWithDraftCheck(story)
  }, [currentStory?.id, editStoryId, editStoryWithDraftCheck, stories, storyEditMode])

  const togglePhotoPanelCollapse = useCallback(() => {
    setIsPhotoPanelCollapsed((prev) => {
      const next = !prev
      if (typeof window !== 'undefined') {
        window.localStorage.setItem(STORY_PHOTO_PANEL_COLLAPSED_KEY, String(next))
      }
      return next
    })
  }, [])

  return (
    <div className="flex h-full flex-col gap-6 overflow-hidden">
      {storyEditMode === 'list' || !currentStory ? (
        <StoryListView
          stories={stories}
          loading={loading}
          statusFilter={statusFilter}
          onStatusFilterChange={setStatusFilter}
          onCreateStory={() => void handleCreateStory()}
          onEditStory={(story) => void handleEditStory(story)}
          onTogglePublish={(story) => void handleTogglePublish(story)}
          onRequestDelete={setDeleteStoryId}
          t={t}
          cdnDomain={settings?.cdn_domain}
          onRefresh={() => void loadStories()}
        />
      ) : (
        <StoryEditorView
          token={token}
          currentStory={currentStory}
          pendingImages={pendingImages}
          pendingCoverId={pendingCoverId}
          saving={saving}
          draftSaved={draftSaved}
          lastSavedAt={lastSavedAt}
          isImmersiveMode={isImmersiveMode}
          setIsImmersiveMode={setIsImmersiveMode}
          useCustomDate={useCustomDate}
          setUseCustomDate={setUseCustomDate}
          isPhotoPanelCollapsed={isPhotoPanelCollapsed}
          togglePhotoPanelCollapse={togglePhotoPanelCollapse}
          settingsCdnDomain={settings?.cdn_domain}
          isUploading={isUploading}
          uploadProgress={uploadProgress}
          isDraggingOver={isDraggingOver}
          draggedItemId={draggedItemId}
          draggedItemType={draggedItemType}
          dragOverItemId={dragOverItemId}
          openMenuPhotoId={openMenuPhotoId}
          openMenuPendingId={openMenuPendingId}
          showPreview={() => setShowPreview(true)}
          onBack={resetEditorState}
          onSave={() => void handleSaveStory()}
          onPasteFiles={handlePasteFiles}
          onOpenPhotoSelector={() => setShowPhotoSelector(true)}
          onInsertExternalPhotoMarkdown={handleInsertExternalPhotoMarkdown}
          onInsertPhotoMarkdown={handleInsertPhotoMarkdown}
          onInsertGalleryMarkdown={handleInsertGalleryMarkdown}
          onOpenPasteUploadSettings={() => setShowPasteUploadSettings(true)}
          onRemovePhoto={handleRemovePhoto}
          onRemovePendingImage={handleRemovePendingImage}
          onSetCover={handleSetCover}
          onSetPendingCover={handleSetPendingCover}
          onSetPhotoDate={handleSetPhotoDate}
          onRetryFailedUploads={handleRetryFailedUploads}
          onPhotoPanelDragOver={handlePhotoPanelDragOver}
          onPhotoPanelDragLeave={handlePhotoPanelDragLeave}
          onPhotoPanelDrop={async (event) => {
            handlePhotoPanelDragLeave(event)
            await handlePhotoPanelDrop(event)
          }}
          onItemDragStart={handleItemDragStart}
          onItemDragEnd={handleItemDragEnd}
          onItemDragOver={handleItemDragOver}
          onItemDragLeave={handleItemDragLeave}
          onItemDrop={handleItemDrop}
          onOpenMenuPhoto={setOpenMenuPhotoId}
          onOpenMenuPending={setOpenMenuPendingId}
          editorRef={editorRef}
          t={t}
          notify={notify}
          setCurrentStory={setCurrentStory}
        />
      )}

      <PhotoSelectorModal isOpen={showPhotoSelector} onClose={() => setShowPhotoSelector(false)} onConfirm={handleUpdatePhotos} initialSelectedPhotoIds={currentPhotoIds} t={t} />
      <ImageUploadSettingsModal isOpen={showUploadSettings} onClose={() => setShowUploadSettings(false)} onConfirm={handleConfirmUpload} pendingCount={pendingImages.filter((image) => image.status === 'pending' || image.status === 'failed').length} t={t} token={token} initialSettings={uploadSettings} settings={settings} categories={categories} currentStoryId={currentStory?.id} />
      <ImageUploadSettingsModal
        isOpen={showPasteUploadSettings}
        onClose={() => {
          setShowPasteUploadSettings(false)
          pendingPasteFilesRef.current = null
        }}
        onConfirm={handleConfirmPasteUpload}
        pendingCount={pendingPasteFilesRef.current?.length || 0}
        t={t}
        token={token}
        initialSettings={pasteUploadSettings}
        settings={settings}
        categories={categories}
        confirmLabel={t('admin.save_and_process_pasted_images')}
        currentStoryId={currentStory?.id}
      />
      <SimpleDeleteDialog isOpen={!!deleteStoryId} onConfirm={confirmDeleteStory} onCancel={() => setDeleteStoryId(null)} t={t} />
      <DraftRestoreDialog isOpen={draftRestoreDialog.isOpen} draftTime={draftRestoreDialog.draft?.savedAt || 0} onRestore={handleDraftRestore} onDiscard={handleDraftDiscard} onCancel={handleDraftCancel} t={t} />
      {showPreview && currentStory ? (
        <StoryPreviewModal
          story={currentStory}
          cdnDomain={settings?.cdn_domain}
          previewPhotoIndex={previewPhotoIndex}
          onClose={() => setShowPreview(false)}
          onPhotoClick={setPreviewPhotoIndex}
          onPhotoClose={() => setPreviewPhotoIndex(null)}
          onPrevPhoto={handlePrevPhoto}
          onNextPhoto={handleNextPhoto}
          t={t}
        />
      ) : null}
      {showCoverCropEditor && currentCoverPhoto ? (
        <StoryCoverCropModal
          photo={currentCoverPhoto}
          cdnDomain={settings?.cdn_domain}
          initialCrop={currentCoverCrop}
          onClose={() => setShowCoverCropEditor(false)}
          onApply={handleApplyCoverCrop}
          t={t}
        />
      ) : null}
    </div>
  )
}

/**
 * AdminContext 适配器 — 对齐 web 端 useAdmin() 接口。
 * desktop 不需要完整的管理页面布局，只提供 StoriesTab/BlogTab 所需的 context。
 */
'use client'

import React, { createContext, useContext, useCallback, useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { useNavigate } from 'react-router-dom'

interface AdminContextType {
  handleUnauthorized: () => void
  settings: Record<string, string> | null
  categories: string[]
  isImmersiveMode: boolean
  setIsImmersiveMode: React.Dispatch<React.SetStateAction<boolean>>
}

const AdminContext = createContext<AdminContextType | null>(null)

export function useAdmin() {
  const context = useContext(AdminContext)
  if (!context) {
    return {
      handleUnauthorized: () => {},
      settings: null as Record<string, string> | null,
      categories: [] as string[],
      isImmersiveMode: false,
      setIsImmersiveMode: (() => {}) as React.Dispatch<React.SetStateAction<boolean>>,
    }
  }
  return context
}

export function AdminLogsProvider({ children }: { children: React.ReactNode }) {
  const { logout } = useAuth()
  const navigate = useNavigate()
  const [settings, setSettings] = useState<Record<string, string> | null>(null)
  const [categories, setCategories] = useState<string[]>([])
  const [isImmersiveMode, setIsImmersiveMode] = useState(false)

  const handleUnauthorized = useCallback(() => {
    logout()
    navigate('/library?source=local', { replace: true })
  }, [logout, navigate])

  useEffect(() => {
    ;(async () => {
      try {
        const s = await (window as any).go.main.App.GetSettings()
        setSettings(s || {})
      } catch {}
      try {
        const c = await (window as any).go.main.App.GetCategories()
        setCategories(c || [])
      } catch {}
    })()
  }, [])

  return (
    <AdminContext.Provider value={{ handleUnauthorized, settings, categories, isImmersiveMode, setIsImmersiveMode }}>
      {children}
    </AdminContext.Provider>
  )
}

