function snapshot(revision = 'revision-1'): NarrativeDocumentSnapshot {
  return {
    capability: 'narrative',
    documentId: 'story-1',
    documentKind: 'story',
    title: 'Story title',
    root: { type: 'doc' },
    nodes: [],
    editorWidth: 960,
