/** 视图模式：网格 / 列表 */
type ViewMode = 'grid' | 'list'
/** 筛选状态：全部 / 已发布 / 草稿 */
type FilterStatus = 'all' | 'published' | 'draft'

/** AlbumsTab 组件属性 */
interface AlbumsTabProps {
  /** 认证令牌 */
  token: string | null
  /** 所有照片列表，用于添加照片到相册 */
