  onUnauthorized: () => void
  /** 照片预览回调 */
  onPreview: (photo: PhotoDto) => void
}

/**
 * 相册管理组件
 *
 * 功能：
 * - 相册列表（网格/列表视图）、搜索与筛选
 * - 创建/编辑/删除相册
 * - 管理相册照片（添加、移除、设置封面）
 * - 拖拽排序相册
 * - 切换发布/草稿状态
 */
export function AlbumsTab({
  token,
  photos,
  cdnDomain,
  t,
  notify,
  onUnauthorized,
  onPreview,
}: AlbumsTabProps) {
  // ==================== 状态定义 ====================

  const [albums, setAlbums] = useState<AlbumDto[]>([])           // 相册列表
  const [loading, setLoading] = useState(true)                   // 加载状态
  const [currentAlbum, setCurrentAlbum] = useState<AlbumDto | null>(null) // 当前编辑的相册（null 表示列表视图）
  const [loadingCurrentAlbum, setLoadingCurrentAlbum] = useState(false)
  const [activeTab, setActiveTab] = useState<'overview' | 'photos'>('overview') // 详情页子标签
  const [saving, setSaving] = useState(false)                    // 保存中状态
  const [showPhotoSelector, setShowPhotoSelector] = useState(false) // 是否显示照片选择器
  const [selectedPhotoIds, setSelectedPhotoIds] = useState<Set<string>>(new Set()) // 已选中待添加的照片 ID
  const [draggingId, setDraggingId] = useState<string | null>(null) // 正在拖拽的相册 ID
  const [deletingAlbumId, setDeletingAlbumId] = useState<string | null>(null)
  const [pendingAlbumDelete, setPendingAlbumDelete] = useState<AlbumDto | null>(null)

  // 筛选与视图状态
  const [viewMode, setViewMode] = useState<ViewMode>('grid')          // 视图模式
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all') // 发布状态筛选
  const [searchQuery, setSearchQuery] = useState('')                   // 搜索关键字
  const [showFilters, setShowFilters] = useState(false)                // 是否展开筛选面板
  const [photoSelectorSearch, setPhotoSelectorSearch] = useState('')
  const currentAlbumRequestIdRef = useRef(0)

  // ==================== 派生状态 ====================

  /** 当前激活的筛选条件数量 */
  const activeFilterCount = useMemo(() => {
    let count = 0
    if (filterStatus !== 'all') count++
    return count
  }, [filterStatus])

  /** 根据筛选条件过滤后的相册列表 */
  const filteredAlbums = useMemo(() => {
    return albums.filter(album => {
      if (filterStatus === 'published' && !album.isPublished) return false
      if (filterStatus === 'draft' && album.isPublished) return false
      if (searchQuery) {
        const query = searchQuery.toLowerCase()
        if (!album.name.toLowerCase().includes(query) && !album.location?.toLowerCase().includes(query)) return false
      }
      return true
    })
  }, [albums, filterStatus, searchQuery])

  /** 重置所有筛选条件 */
  const clearAllFilters = () => {
    setFilterStatus('all')
    setSearchQuery('')
  }

  const summarizeAlbum = useCallback((album: AlbumDto): AlbumDto => ({
    ...album,
    photos: album.photos.slice(0, 1),
  }), [])

  // ==================== 拖拽排序 ====================

  async function handleDragStart(e: React.DragEvent, id: string) {
    e.dataTransfer.effectAllowed = 'move'
    setDraggingId(id)
  }

  function handleDragOver(e: React.DragEvent, targetId: string) {
    e.preventDefault()
    if (!draggingId || draggingId === targetId) return
    const fromIndex = albums.findIndex(a => a.id === draggingId)
    const toIndex = albums.findIndex(a => a.id === targetId)
    if (fromIndex === -1 || toIndex === -1) return
    const newAlbums = [...albums]
    const [moved] = newAlbums.splice(fromIndex, 1)
    newAlbums.splice(toIndex, 0, moved)
    setAlbums(newAlbums)
  }

  /** 拖拽结束：持久化新排序到后端 */
  async function handleDragEnd() {
    setDraggingId(null)
    if (!token) return
    try {
      await reorderAlbums(token, albums.map((a, i) => ({ id: a.id, sortOrder: i })))
    } catch {
      notify(t('common.error'), 'error')
      await loadAlbums()
    }
  }

  async function confirmDeleteAlbum() {
    if (!token || !pendingAlbumDelete) return

    try {
      setDeletingAlbumId(pendingAlbumDelete.id)
      await deleteAlbum(token, pendingAlbumDelete.id)
      notify(t('admin.notify_success'), 'success')
      if (currentAlbum?.id === pendingAlbumDelete.id) setCurrentAlbum(null)
      setPendingAlbumDelete(null)
      await loadAlbums()
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setDeletingAlbumId(null)
    }
  }

  // ==================== 数据操作 ====================

  /** 加载相册列表 */
  const loadAlbums = useCallback(async () => {
    if (!token) return
    try {
      setLoading(true)
      const data = await getAdminAlbums(token)
      setAlbums(data.map(summarizeAlbum))
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setLoading(false)
    }
  }, [notify, onUnauthorized, summarizeAlbum, t, token])

  useEffect(() => { void loadAlbums() }, [loadAlbums])

  /** 初始化新相册并进入编辑视图 */
  function handleCreateAlbum() {
    currentAlbumRequestIdRef.current += 1
    setLoadingCurrentAlbum(false)
    setCurrentAlbum({
      id: '', name: '', description: '', coverUrl: '', location: '', isPublished: false,
      sortOrder: albums.length, createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(), photos: [], photoCount: 0,
    })
    setActiveTab('overview')
  }

  const openAlbumDetail = useCallback(async (album: AlbumDto) => {
    if (!token) return

    const requestId = currentAlbumRequestIdRef.current + 1
    currentAlbumRequestIdRef.current = requestId

    setCurrentAlbum(album)
    setActiveTab('photos')
    setShowPhotoSelector(false)
    setSelectedPhotoIds(new Set())
    setPhotoSelectorSearch('')
    setLoadingCurrentAlbum(true)

    try {
      const full = await getAdminAlbum(token, album.id)
      if (currentAlbumRequestIdRef.current !== requestId) return
      setCurrentAlbum(full)
      setAlbums(prev => prev.map(a => a.id === full.id ? summarizeAlbum(full) : a))
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      if (currentAlbumRequestIdRef.current !== requestId) return
      notify(t('common.error'), 'error')
    } finally {
      if (currentAlbumRequestIdRef.current === requestId) {
        setLoadingCurrentAlbum(false)
      }
    }
  }, [notify, onUnauthorized, summarizeAlbum, t, token])

  /** 删除相册（需用户确认） */
  function handleDeleteAlbum(album: AlbumDto, e?: React.MouseEvent) {
    e?.stopPropagation()
    if (!token) return
    setPendingAlbumDelete(album)
  }

  /** 保存相册（创建或更新） */
  async function handleSaveAlbum() {
    if (!token || !currentAlbum || !currentAlbum.name.trim()) {
      notify(t('admin.album_name_required'), 'error')
      return
    }
    try {
      setSaving(true)
      const isNew = !currentAlbum.id
      const data = {
        name: currentAlbum.name.trim(),
        description: currentAlbum.description || undefined,
        coverUrl: currentAlbum.coverUrl || undefined,
        location: currentAlbum.location?.trim() || null,
        isPublished: currentAlbum.isPublished,
        sortOrder: currentAlbum.sortOrder,
      }
      const result = isNew ? await createAlbum(token, data) : await updateAlbum(token, currentAlbum.id, data)
      notify(isNew ? (t('admin.album_created') || 'Album created') : (t('admin.album_updated') || 'Album updated'), 'success')
      setCurrentAlbum(result)
      setAlbums(prev => {
        if (isNew) return [...prev, summarizeAlbum(result)]
        return prev.map(a => a.id === result.id ? summarizeAlbum(result) : a)
      })
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setSaving(false)
    }
  }

  /** 切换相册发布/草稿状态 */
  async function handleTogglePublish(album: AlbumDto, e?: React.MouseEvent) {
    e?.stopPropagation()
    if (!token) return
    try {
      const updated = await updateAlbum(token, album.id, { isPublished: !album.isPublished })
      notify(t('admin.notify_success'), 'success')
      setAlbums(prev => prev.map(a => a.id === updated.id ? summarizeAlbum(updated) : a))
      if (currentAlbum?.id === updated.id) setCurrentAlbum(updated)
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    }
  }

  // ==================== 照片管理 ====================

  /** 批量添加照片到当前相册 */
  async function handleAddPhotos() {
    if (!token || !currentAlbum || selectedPhotoIds.size === 0) return
    try {
      setSaving(true)
      const updated = await addPhotosToAlbum(token, currentAlbum.id, Array.from(selectedPhotoIds))
      notify(t('admin.photos_added'), 'success')
      setCurrentAlbum(updated)
      setAlbums(prev => prev.map(a => a.id === updated.id ? summarizeAlbum(updated) : a))
      setShowPhotoSelector(false)
      setSelectedPhotoIds(new Set())
      setPhotoSelectorSearch('')
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setSaving(false)
    }
  }

  /** 从当前相册移除单张照片 */
  async function handleRemovePhoto(photoId: string) {
    if (!token || !currentAlbum) return
    try {
      const updated = await removePhotoFromAlbum(token, currentAlbum.id, photoId)
      setCurrentAlbum(updated)
      setAlbums(prev => prev.map(a => a.id === updated.id ? summarizeAlbum(updated) : a))
      notify(t('admin.photo_removed'), 'success')
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    }
  }

  /** 设置照片为相册封面 */
  async function handleSetCover(photoId: string) {
    if (!token || !currentAlbum) return
    try {
      const updated = await setAlbumCover(token, currentAlbum.id, photoId)
      setCurrentAlbum(updated)
      setAlbums(prev => prev.map(a => a.id === updated.id ? summarizeAlbum(updated) : a))
      notify(t('admin.cover_set'), 'success')
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    }
  }

  /** 可添加的照片：排除当前相册已有的照片 */
  const availablePhotos = useMemo(() => {
    if (!currentAlbum) return photos
    const albumPhotoIds = new Set(currentAlbum.photos.map(p => p.id))
    return photos.filter(p => !albumPhotoIds.has(p.id))
  }, [photos, currentAlbum])

  const filteredAvailablePhotos = useMemo(() => {
    if (!photoSelectorSearch.trim()) return availablePhotos
    const query = photoSelectorSearch.toLowerCase()
    return availablePhotos.filter(p =>
      p.title.toLowerCase().includes(query) ||
      p.category.toLowerCase().includes(query)
    )
  }, [availablePhotos, photoSelectorSearch])

  // ==================== 渲染 ====================


  // ---------- 列表视图（未选中相册） ----------
  if (!currentAlbum) {
    return (
      <>
        <div className="space-y-6">
        <AdminCollectionToolbar
          info={(
            <span className="text-sm font-medium text-foreground">
              <span className="text-muted-foreground">{filteredAlbums.length} {t('admin.albums')}</span>
            </span>
          )}
          searchValue={searchQuery}
          onSearchChange={setSearchQuery}
          searchPlaceholder={t('common.search')}
          actions={(
            <>
              {/* Filter Toggle */}
              <AdminButton
                onClick={() => setShowFilters(!showFilters)}
                adminVariant="unstyled"
                className={`flex items-center gap-2 px-3 py-2 text-xs font-medium border rounded-md transition-all ${showFilters || activeFilterCount > 0
                  ? 'bg-primary/10 border-primary/30 text-primary'
                  : 'bg-background border-border text-muted-foreground hover:text-foreground hover:border-foreground/30'
                  }`}
              >
                <Filter className="w-4 h-4" />
                <span className="hidden sm:inline">{t('admin.filter') || 'Filter'}</span>
                {activeFilterCount > 0 && (
                  <span className="flex items-center justify-center w-5 h-5 bg-primary text-primary-foreground text-[10px] font-bold rounded-full">
                    {activeFilterCount}
                  </span>
                )}
              </AdminButton>

              {/* View Mode Toggle */}
              <div className="flex bg-background border border-border rounded-md overflow-hidden">
                <AdminButton
                  onClick={() => setViewMode('grid')}
                  adminVariant="unstyled"
                  className={`p-2 transition-colors ${viewMode === 'grid'
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                    }`}
                  title={t('admin.grid_view')}
                >
                  <LayoutGrid className="w-4 h-4" />
                </AdminButton>
                <AdminButton
                  onClick={() => setViewMode('list')}
                  adminVariant="unstyled"
                  className={`p-2 transition-colors ${viewMode === 'list'
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                    }`}
                  title={t('admin.list_view')}
                >
                  <List className="w-4 h-4" />
                </AdminButton>
              </div>
            </>
          )}
          endActions={(
            <AdminButton
              onClick={handleCreateAlbum}
              adminVariant="unstyled"
              className="flex items-center gap-2 px-5 py-2.5 bg-foreground text-background text-xs font-medium hover:bg-primary hover:text-primary-foreground transition-colors"
            >
              <Plus className="w-4 h-4" />
              {t('admin.new_album') || 'New Album'}
            </AdminButton>
          )}
          filters={showFilters ? (
            <div className="flex flex-wrap items-center gap-3">
              {/* Status Filter */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground whitespace-nowrap">{t('admin.status') || 'Status'}:</span>
                <div className="flex bg-background border border-border rounded-md overflow-hidden">
                  {(['all', 'published', 'draft'] as FilterStatus[]).map(status => (
                    <AdminButton
                      key={status}
                      onClick={() => setFilterStatus(status)}
                      adminVariant="unstyled"
                      className={`px-3 py-1.5 text-xs font-medium transition-colors ${filterStatus === status ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`}
                    >
                      {status === 'all' ? t('common.all') || 'All' : status === 'published' ? t('admin.published') || 'Published' : t('admin.draft') || 'Draft'}
                    </AdminButton>
                  ))}
                </div>
              </div>

              {/* Clear Filters */}
              {activeFilterCount > 0 && (
                <>
                  <div className="h-5 w-px bg-border my-auto" />
                  <AdminButton
                    onClick={clearAllFilters}
                    adminVariant="unstyled"
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors"
                  >
                    <X className="w-3.5 h-3.5" />
                    <span>{t('admin.clear_all')}</span>
                  </AdminButton>
                </>
              )}
            </div>
          ) : undefined}
          activeFilters={activeFilterCount > 0 && !showFilters ? (
            <div className="mt-3 pt-3 border-t border-border flex flex-wrap items-center gap-2">
              <span className="text-xs text-muted-foreground">{t('admin.active_filters')}:</span>
              {filterStatus !== 'all' && (
                <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                  {filterStatus === 'published' ? t('admin.published') : t('admin.draft')}
                  <AdminButton onClick={() => setFilterStatus('all')} adminVariant="unstyled" className="hover:text-primary/70">
                    <X className="w-3 h-3" />
                  </AdminButton>
                </span>
              )}
              <AdminButton
                onClick={clearAllFilters}
                adminVariant="unstyled"
                className="text-xs text-muted-foreground hover:text-foreground underline"
              >
                {t('admin.clear_all')}
              </AdminButton>
            </div>
          ) : undefined}
        />

        {/* Content */}
        {loading ? (
          <div className="py-6">
            <CardGridSkeleton count={8} cols={4} />
          </div>
        ) : filteredAlbums.length === 0 ? (
          <div className="py-20 text-center border border-dashed border-border/50 bg-muted/5">
            <FolderOpen className="w-12 h-12 mx-auto mb-4 opacity-10" />
            <p className="text-sm text-muted-foreground mb-4">{searchQuery || filterStatus !== 'all' ? t('admin.no_albums_match_filters') : t('admin.no_albums')}</p>
            {!searchQuery && filterStatus === 'all' && (
              <AdminButton onClick={handleCreateAlbum} adminVariant="unstyled" className="inline-flex items-center gap-2 px-4 py-2 border border-border text-xs font-medium hover:bg-muted transition-colors">
                <Plus className="w-4 h-4" />
                {t('admin.create_first_album') || 'Create your first album'}
              </AdminButton>
            )}
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredAlbums.map(album => {
              return (
                <div
                  key={album.id}
                  onDragOver={e => handleDragOver(e, album.id)}
                  onClick={() => { void openAlbumDetail(album) }}
                  className={`group cursor-pointer bg-card border border-border/50 hover:border-border transition-all ${draggingId === album.id ? 'opacity-50' : ''}`}
                >
                  <div className="relative aspect-[4/3] bg-muted overflow-hidden">
                    <div
                      draggable
                      onDragStart={e => handleDragStart(e, album.id)}
                      onDragEnd={handleDragEnd}
                      className="absolute top-2 left-2 z-10 p-1 bg-black/40 text-white/70 hover:text-white cursor-grab opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={e => e.stopPropagation()}
                    >
                      <GripVertical className="w-4 h-4" />
                    </div>
                    {album.coverUrl || album.photos.length > 0 ? (
                      <img src={resolveAssetUrl(album.coverUrl || album.photos[0]?.thumbnailUrl || album.photos[0]?.url, cdnDomain)} alt={album.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center"><FolderOpen className="w-10 h-10 opacity-10" /></div>
                    )}
                    <div className="absolute top-2 right-2 px-2 py-0.5 bg-black/50 text-white text-[10px] font-medium">{album.photoCount}</div>
                    <div className="absolute bottom-2 right-2 flex gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity" onClick={e => e.stopPropagation()}>
                      <AdminButton onClick={e => handleTogglePublish(album, e)} adminVariant="unstyled" className="p-1.5 bg-white/20 hover:bg-white/30 text-white backdrop-blur-sm transition-colors">
                        {album.isPublished ? <Eye className="w-3.5 h-3.5" /> : <EyeOff className="w-3.5 h-3.5" />}
                      </AdminButton>
                      <AdminButton onClick={e => handleDeleteAlbum(album, e)} disabled={deletingAlbumId === album.id} adminVariant="unstyled" className="p-1.5 bg-red-500/80 hover:bg-red-500 text-white transition-colors disabled:opacity-50">
                        <Trash2 className="w-3.5 h-3.5" />
                      </AdminButton>
                    </div>
                  </div>
                  <div className="p-4">
                    <div className="flex items-center justify-between gap-2 mb-1">
                      <h3 className="font-medium truncate">{album.name}</h3>
                      <span className={`w-2 h-2 rounded-full flex-shrink-0 ${album.isPublished ? 'bg-green-500' : 'bg-muted-foreground/30'}`} />
                    </div>
                    {album.location && (
                      <p className="mb-1 flex items-center gap-1 text-xs text-muted-foreground">
                        <MapPin className="h-3 w-3 shrink-0" />
                        <span className="truncate">{album.location}</span>
                      </p>
                    )}
                    {album.description && <p className="text-xs text-muted-foreground line-clamp-1">{album.description}</p>}
                  </div>
                </div>
              )
            })}
          </div>
        ) : (
          <div className="space-y-2">
            {filteredAlbums.map(album => (
              <div
                key={album.id}
                onDragOver={e => handleDragOver(e, album.id)}
                onClick={() => { void openAlbumDetail(album) }}
                className={`group flex items-center gap-4 p-4 bg-card border border-border/50 hover:border-border cursor-pointer transition-all ${draggingId === album.id ? 'opacity-50' : ''}`}
              >
                <div
                  draggable
                  onDragStart={e => handleDragStart(e, album.id)}
                  onDragEnd={handleDragEnd}
                  className="text-muted-foreground/40 group-hover:text-muted-foreground cursor-grab"
                  onClick={e => e.stopPropagation()}
                >
                  <GripVertical className="w-4 h-4" />
                </div>
                <div className="w-16 h-12 bg-muted overflow-hidden flex-shrink-0">
                  {album.coverUrl || album.photos.length > 0 ? (
                    <img src={resolveAssetUrl(album.coverUrl || album.photos[0]?.thumbnailUrl || album.photos[0]?.url, cdnDomain)} alt={album.name} className="w-full h-full object-cover" />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center"><FolderOpen className="w-5 h-5 opacity-20" /></div>
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <h3 className="font-medium truncate">{album.name}</h3>
                    <span className={`w-2 h-2 rounded-full flex-shrink-0 ${album.isPublished ? 'bg-green-500' : 'bg-muted-foreground/30'}`} />
                  </div>
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground">
                    <span>{album.photoCount} {t('admin.photos_count')}</span>
                    {album.location && (
                      <span className="flex min-w-0 items-center gap-1">
                        <MapPin className="h-3 w-3 shrink-0" />
                        <span className="truncate">{album.location}</span>
                      </span>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity" onClick={e => e.stopPropagation()}>
                  <AdminButton onClick={e => handleTogglePublish(album, e)} adminVariant="unstyled" className="p-2 hover:bg-muted transition-colors">
                    {album.isPublished ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4 text-muted-foreground" />}
                  </AdminButton>
                  <AdminButton onClick={e => handleDeleteAlbum(album, e)} disabled={deletingAlbumId === album.id} adminVariant="unstyled" className="p-2 text-destructive hover:bg-destructive/10 transition-colors disabled:opacity-50">
                    <Trash2 className="w-4 h-4" />
                  </AdminButton>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
      <SimpleDeleteDialog
        isOpen={pendingAlbumDelete !== null}
        title={t('common.confirm')}
        message={t('admin.album_delete_confirm')}
        onConfirm={confirmDeleteAlbum}
        onCancel={() => {
          if (!deletingAlbumId) {
            setPendingAlbumDelete(null)
          }
        }}
        t={t}
      />
      </>
    )
  }

  // ---------- 详情视图（编辑相册） ----------
  return (
    <>
      <div className="space-y-6">
        <div className="flex items-center justify-between pb-4 border-b border-border">
          <div className="flex items-center gap-3">
            <AdminButton onClick={() => {
              currentAlbumRequestIdRef.current += 1
              setLoadingCurrentAlbum(false)
              setCurrentAlbum(null)
            }} adminVariant="icon">
              <ChevronLeft className="w-5 h-5" />
            </AdminButton>
            <div>
              <h2 className="text-lg font-medium">
                {currentAlbum.name || (t('admin.new_album') || 'New Album')}
              </h2>
              <p className="text-xs text-muted-foreground">
                {currentAlbum.isPublished ? t('admin.published') : t('admin.draft')}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {activeTab === 'overview' && (
              <AdminButton
                onClick={handleSaveAlbum}
                disabled={saving}
                adminVariant="unstyled"
                className="flex items-center gap-2 px-5 py-2 bg-foreground text-background text-xs font-medium hover:bg-primary hover:text-primary-foreground disabled:opacity-50 transition-colors"
              >
                <Save className="w-4 h-4" />
                {saving ? t('common.loading') : t('admin.save')}
              </AdminButton>
            )}
            {activeTab === 'photos' && (
              <AdminButton
                onClick={() => setShowPhotoSelector(true)}
                disabled={loadingCurrentAlbum}
                adminVariant="unstyled"
                className="flex items-center gap-2 px-5 py-2 bg-foreground text-background text-xs font-medium hover:bg-primary hover:text-primary-foreground transition-colors disabled:opacity-50"
              >
                <Plus className="w-4 h-4" />
                {t('admin.add_photos') || 'Add Photos'}
              </AdminButton>
            )}
          </div>
        </div>

        <div className="flex gap-1 border-b border-border">
          <AdminButton
            onClick={() => setActiveTab('overview')}
            adminVariant="unstyled"
            className={`flex items-center gap-2 px-4 py-3 text-xs font-medium border-b-2 transition-colors ${activeTab === 'overview' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
          >
            <Settings className="w-4 h-4" />
            {t('admin.overview') || 'Overview'}
          </AdminButton>
          {currentAlbum.id && (
            <AdminButton
              onClick={() => setActiveTab('photos')}
              adminVariant="unstyled"
              className={`flex items-center gap-2 px-4 py-3 text-xs font-medium border-b-2 transition-colors ${activeTab === 'photos' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
            >
              <Layout className="w-4 h-4" />
              {t('admin.photos') || 'Photos'}
              <span className="ml-1 px-1.5 py-0.5 bg-muted text-[10px]">
                {currentAlbum.photos.length}
              </span>
            </AdminButton>
          )}
        </div>

        <div className="pt-2">
          {activeTab === 'overview' ? (
            <div className="max-w-xl space-y-6">
              <div>
                <label className="block text-xs text-muted-foreground mb-2">{t('admin.album_name')}</label>
                <CustomInput
                  variant="config"
                  value={currentAlbum.name}
                  onChange={e => setCurrentAlbum({ ...currentAlbum, name: e.target.value })}
                  placeholder={t('admin.album_name_placeholder')}
                />
              </div>
              <div>
                <label className="block text-xs text-muted-foreground mb-2">{t('admin.album_location')}</label>
                <div className="relative">
                  <MapPin className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
                  <CustomInput
                    variant="config"
                    value={currentAlbum.location || ''}
                    onChange={e => setCurrentAlbum({ ...currentAlbum, location: e.target.value })}
                    placeholder={t('admin.album_location_placeholder')}
                    className="pl-9"
                  />
                </div>
              </div>
              <div>
                <label className="block text-xs text-muted-foreground mb-2">{t('admin.description')}</label>
                <textarea
                  value={currentAlbum.description || ''}
                  onChange={e => setCurrentAlbum({ ...currentAlbum, description: e.target.value })}
                  placeholder={t('admin.description_placeholder')}
                  className="w-full p-3 h-24 bg-muted/30 border-b border-border focus:border-primary outline-none text-sm transition-colors resize-none"
                />
              </div>
              <div className="flex items-center gap-3 p-3 bg-muted/30 border-b border-border">
                <input
                  type="checkbox"
                  checked={currentAlbum.isPublished}
                  onChange={e => setCurrentAlbum({ ...currentAlbum, isPublished: e.target.checked })}
                  className="w-4 h-4 accent-primary"
                />
                <span className="text-sm">
                  {currentAlbum.isPublished ? t('admin.published') : t('admin.draft')}
                </span>
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              {loadingCurrentAlbum ? (
                <div className="py-6">
                  <ListSkeleton count={3} />
                </div>
              ) : showPhotoSelector ? (
                <div className="space-y-4">
                  <div className="flex items-center justify-between p-3 bg-muted/30 border border-border">
                    <div className="flex items-center gap-3">
                      <AdminButton
                        onClick={() => {
                          setShowPhotoSelector(false)
                          setSelectedPhotoIds(new Set())
                          setPhotoSelectorSearch('')
                        }}
                        adminVariant="icon"
                      >
                        <X className="w-4 h-4" />
                      </AdminButton>
                      <span className="text-sm">{selectedPhotoIds.size} {t('admin.selected')}</span>
                      <input
                        type="text"
                        value={photoSelectorSearch}
                        onChange={(e) => setPhotoSelectorSearch(e.target.value)}
                        placeholder={t('common.search')}
                        className="px-2 py-1 text-sm bg-transparent border border-border rounded focus:border-primary outline-none w-40"
                      />
                    </div>
                    <AdminButton
                      onClick={handleAddPhotos}
                      disabled={selectedPhotoIds.size === 0 || saving}
                      adminVariant="unstyled"
                      className="flex items-center gap-2 px-4 py-1.5 bg-foreground text-background text-xs font-medium disabled:opacity-50 transition-colors"
                    >
                      <Check className="w-3.5 h-3.5" />
                      Add
                    </AdminButton>
                  </div>
                  {loading ? (
                    <div className="py-6"><ThumbGridSkeleton count={8} cols={6} /></div>
                  ) : (
                    <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-2">
                      {filteredAvailablePhotos.map(photo => {
                        const isSelected = selectedPhotoIds.has(photo.id)
                        return (
                          <div
                            key={photo.id}
                            onClick={() => setSelectedPhotoIds((prev) => {
                              const next = new Set(prev)
                              if (next.has(photo.id)) {
                                next.delete(photo.id)
                              } else {
                                next.add(photo.id)
                              }
                              return next
                            })}
                            className={`relative aspect-square cursor-pointer ${isSelected ? 'ring-2 ring-primary' : 'hover:opacity-80'}`}
                          >
                            <img
                              src={resolveAssetUrl(photo.thumbnailUrl || photo.url, cdnDomain)}
                              alt={photo.title}
                              className="w-full h-full object-cover"
                            />
                            {isSelected && (
                              <div className="absolute inset-0 bg-primary/20 flex items-center justify-center">
                                <Check className="w-5 h-5 text-primary" />
                              </div>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  )}
                </div>
              ) : currentAlbum.photos.length === 0 ? (
                <div className="py-16 text-center border border-dashed border-border/50 bg-muted/5">
                  <ImageIcon className="w-10 h-10 mx-auto mb-3 opacity-10" />
                  <p className="text-sm text-muted-foreground mb-3">
                    {t('admin.album_empty') || 'This album is empty'}
                  </p>
                  <AdminButton
                    onClick={() => setShowPhotoSelector(true)}
                    adminVariant="unstyled"
                    className="inline-flex items-center gap-2 px-4 py-2 border border-border text-xs font-medium hover:bg-muted transition-colors"
                  >
                    <Plus className="w-4 h-4" />
                    {t('admin.add_photos') || 'Add Photos'}
                  </AdminButton>
                </div>
              ) : (
                <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-2">
                  {currentAlbum.photos.map(photo => {
                    const isCover = currentAlbum.coverUrl === (photo.thumbnailUrl || photo.url)
                    return (
                      <div
                        key={photo.id}
                        className="relative aspect-square group bg-muted overflow-hidden cursor-pointer"
                        onClick={() => onPreview(photo)}
                      >
                        <img
                          src={resolveAssetUrl(photo.thumbnailUrl || photo.url, cdnDomain)}
                          alt={photo.title}
                          className="w-full h-full object-cover"
                        />
                        {isCover && (
                          <div className="absolute top-1 left-1 px-1.5 py-0.5 bg-primary text-primary-foreground text-[8px] font-medium">
                            {t('admin.cover')}
                          </div>
                        )}
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-1.5">
                          {!isCover && (
                            <AdminButton
                              onClick={(e) => {
                                e.stopPropagation()
                                handleSetCover(photo.id)
                              }}
                              adminVariant="unstyled"
                              className="px-2 py-1 bg-white/20 hover:bg-white/30 text-white text-[9px] font-medium"
                            >
                              {t('admin.set_cover')}
                            </AdminButton>
                          )}
                          <AdminButton
                            onClick={(e) => {
                              e.stopPropagation()
                              handleRemovePhoto(photo.id)
                            }}
                            adminVariant="unstyled"
                            className="px-2 py-1 bg-red-500/80 hover:bg-red-500 text-white text-[9px] font-medium"
                          >
                            {t('admin.remove')}
                          </AdminButton>
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
      <SimpleDeleteDialog
        isOpen={pendingAlbumDelete !== null}
        title={t('common.confirm')}
        message={t('admin.album_delete_confirm')}
        onConfirm={confirmDeleteAlbum}
        onCancel={() => {
          if (!deletingAlbumId) {
            setPendingAlbumDelete(null)
          }
        }}
        t={t}
      />
    </>
  )
}

'use client'

import { useState, useEffect, useMemo, useCallback, useRef } from 'react'
import {
  Film,
  Plus,
  Trash2,
  ChevronLeft,
  Save,
  Image as ImageIcon,
  X,
  Check,
  Settings,
  LayoutGrid,
  List,
  Filter,
  Layout,
  RefreshCw,
} from 'lucide-react'
import {
  getFilmRolls,
  getFilmRoll,
  createFilmRoll,
  updateFilmRoll,
  deleteFilmRoll,
  addPhotosToFilmRoll,
  reorderFilmRollFrames,
  removePhotoFromFilmRoll,
  type FilmRollDto,
  type PhotoDto,
  ApiUnauthorizedError,
  resolveAssetUrl,
} from '@/lib/api'
import { CustomInput } from '@/components/ui/CustomInput'
import { AdminButton } from '@/components/admin/AdminButton'
import { AdminSelect } from '@/components/admin/AdminFormControls'
import { CardGridSkeleton, ListSkeleton } from '@/components/admin/Skeleton'
import { AdminCollectionToolbar } from '@/components/admin/AdminCollectionToolbar'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import {
  FILM_FORMATS,
  FILM_STOCK_BRANDS,
  FILM_STOCK_PRESETS,
  getFilmStockNames,
  getFilmStockDisplay,
  getFilmStockDisplayStyle,
  type FilmFormat,
} from '@/lib/film-presets'

type ViewMode = 'grid' | 'list'
type PhotoTypeFilter = 'all' | 'digital' | 'film'

const FILM_STOCK_BRAND_OPTIONS = FILM_STOCK_BRANDS.map((brand) => ({
  value: brand,
  label: brand,
}))

const FILM_FORMAT_OPTIONS = FILM_FORMATS.map((format) => ({
  value: format,
  label: format,
}))

interface FilmRollsTabProps {
  token: string | null
  photos: PhotoDto[]
  cdnDomain: string
  t: (key: string) => string
  notify: (message: string, type?: 'success' | 'error' | 'info') => void
  onUnauthorized: () => void
  onPreview: (photo: PhotoDto) => void
}

export function FilmRollsTab({
  token,
  photos,
  cdnDomain,
  t,
  notify,
  onUnauthorized,
  onPreview,
}: FilmRollsTabProps) {
  const [rolls, setRolls] = useState<FilmRollDto[]>([])
  const [loading, setLoading] = useState(true)
  const [currentRoll, setCurrentRoll] = useState<FilmRollDto | null>(null)
  const [loadingCurrentRoll, setLoadingCurrentRoll] = useState(false)
  const [activeTab, setActiveTab] = useState<'overview' | 'photos'>('overview')
  const [saving, setSaving] = useState(false)
  const [showPhotoSelector, setShowPhotoSelector] = useState(false)
  const [selectedPhotoIds, setSelectedPhotoIds] = useState<Set<string>>(new Set())
  const [deletingRollId, setDeletingRollId] = useState<string | null>(null)
  const [pendingRollDelete, setPendingRollDelete] = useState<FilmRollDto | null>(null)

  const [viewMode, setViewMode] = useState<ViewMode>('grid')
  const [searchQuery, setSearchQuery] = useState('')
  const [showFilters, setShowFilters] = useState(false)
  const [filterBrand, setFilterBrand] = useState('')
  const [photoSelectorSearch, setPhotoSelectorSearch] = useState('')
  const [photoTypeFilter, setPhotoTypeFilter] = useState<PhotoTypeFilter>('film')
  const currentRollRequestIdRef = useRef(0)

  const brands = useMemo(() => {
    const set = new Set(rolls.map(r => r.brand))
    return Array.from(set).sort()
  }, [rolls])

  const activeFilterCount = useMemo(() => {
    let count = 0
    if (filterBrand) count++
    return count
  }, [filterBrand])

  const filteredRolls = useMemo(() => {
    return rolls.filter(roll => {
      if (filterBrand && roll.brand !== filterBrand) return false
      if (searchQuery) {
        const q = searchQuery.toLowerCase()
        if (!roll.name.toLowerCase().includes(q) && !roll.brand.toLowerCase().includes(q)) return false
      }
      return true
    })
  }, [rolls, filterBrand, searchQuery])

  const currentRollFormat = (currentRoll?.format ?? '135') as FilmFormat

  const currentNameOptions = useMemo(() => {
    if (!currentRoll?.brand) return []

    return getFilmStockNames(currentRoll.brand, currentRollFormat).map((name) => ({
      value: name,
      label: name,
    }))
  }, [currentRoll?.brand, currentRollFormat])

  const clearAllFilters = () => {
    setFilterBrand('')
    setSearchQuery('')
  }

  const loadRolls = useCallback(async () => {
    if (!token) return
    try {
      setLoading(true)
      setRolls(await getFilmRolls())
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setLoading(false)
    }
  }, [notify, onUnauthorized, t, token])

  useEffect(() => { loadRolls() }, [loadRolls])

  function handleCreateRoll() {
    const defaultPreset = FILM_STOCK_PRESETS[0]

    currentRollRequestIdRef.current += 1
    setLoadingCurrentRoll(false)
    setCurrentRoll({
      id: '', name: defaultPreset.name, brand: defaultPreset.brand, format: defaultPreset.format, iso: defaultPreset.iso, frameCount: defaultPreset.frameCount,
      notes: null, shootDate: null, endDate: null,
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
      photoCount: 0, filmPhotos: [],
    })
    setActiveTab('overview')
  }

  function getPresetForStock(brand: string, name: string, format: FilmFormat) {
    return FILM_STOCK_PRESETS.find((item) => item.brand === brand && item.name === name && item.format === format)
  }

  function handleFilmBrandChange(brand: string) {
    if (!currentRoll) return
    const names = getFilmStockNames(brand, currentRollFormat)
    const name = names.includes(currentRoll.name) ? currentRoll.name : names[0] ?? currentRoll.name
    const preset = getPresetForStock(brand, name, currentRollFormat)

    setCurrentRoll({
      ...currentRoll,
      brand,
      name,
      iso: preset?.iso ?? currentRoll.iso,
      frameCount: preset?.frameCount ?? currentRoll.frameCount,
    })
  }

  function handleFilmFormatChange(format: string) {
    if (!currentRoll) return
    const nextFormat = format as FilmFormat
    const names = getFilmStockNames(currentRoll.brand, nextFormat)
    const name = names.includes(currentRoll.name) ? currentRoll.name : names[0] ?? currentRoll.name
    const preset = getPresetForStock(currentRoll.brand, name, nextFormat)
    setCurrentRoll({
      ...currentRoll,
      format: nextFormat,
      name,
      iso: preset?.iso ?? currentRoll.iso,
      frameCount: preset?.frameCount ?? currentRoll.frameCount,
    })
  }

  function handleFilmNameChange(name: string) {
    if (!currentRoll) return
    const preset = getPresetForStock(currentRoll.brand, name, currentRollFormat)

    setCurrentRoll({
      ...currentRoll,
      name,
      iso: preset?.iso ?? currentRoll.iso,
      frameCount: preset?.frameCount ?? currentRoll.frameCount,
    })
  }

  const openRollDetail = useCallback(async (roll: FilmRollDto) => {
    const requestId = currentRollRequestIdRef.current + 1
    currentRollRequestIdRef.current = requestId

    setCurrentRoll({ ...roll, filmPhotos: roll.filmPhotos ?? [] })
    setActiveTab('photos')
    setShowPhotoSelector(false)
    setSelectedPhotoIds(new Set())
    setPhotoSelectorSearch('')
    setPhotoTypeFilter('film')
    setLoadingCurrentRoll(true)

    try {
      const full = await getFilmRoll(roll.id)
      if (currentRollRequestIdRef.current !== requestId) return
      setCurrentRoll(full)
    } catch {
      if (currentRollRequestIdRef.current !== requestId) return
      setCurrentRoll(prev => prev?.id === roll.id ? { ...roll, filmPhotos: roll.filmPhotos ?? [] } : prev)
    } finally {
      if (currentRollRequestIdRef.current === requestId) {
        setLoadingCurrentRoll(false)
      }
    }
  }, [])

  function handleDeleteRoll(roll: FilmRollDto, e?: React.MouseEvent) {
    e?.stopPropagation()
    if (!token) return
    if ((roll.photoCount ?? roll.filmPhotos?.length ?? 0) > 0) {
      notify(t('admin.film_roll_delete_not_empty'), 'error')
      return
    }
    setPendingRollDelete(roll)
  }

  async function confirmDeleteRoll() {
    if (!token || !pendingRollDelete) return
    try {
      setDeletingRollId(pendingRollDelete.id)
      await deleteFilmRoll(token, pendingRollDelete.id)
      notify(t('admin.notify_success'), 'success')
      if (currentRoll?.id === pendingRollDelete.id) setCurrentRoll(null)
      setPendingRollDelete(null)
      await loadRolls()
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    } finally {
      setDeletingRollId(null)
    }
  }

  async function handleSaveRoll() {
    if (!token || !currentRoll) return
    if (!currentRoll.name.trim()) {
      notify(t('admin.film_roll_name_required'), 'error')
      return
    }
    if (!currentRoll.brand.trim()) {
      notify(t('admin.film_roll_brand_required'), 'error')
      return
    }
    try {
      setSaving(true)
      const isNew = !currentRoll.id
      const data = {
        name: currentRoll.name,
        brand: currentRoll.brand,
        format: currentRollFormat,
        iso: currentRoll.iso,
        frameCount: currentRoll.frameCount,
        notes: currentRoll.notes || null,
        shootDate: currentRoll.shootDate || null,
        endDate: currentRoll.endDate || null,
      }
      const result = isNew
        ? await createFilmRoll(token, data)
        : await updateFilmRoll(token, currentRoll.id, data)
      notify(isNew ? t('admin.film_roll_created') : t('admin.film_roll_updated'), 'success')
      // Fetch full roll with photos if editing existing
      if (result.id && !isNew) {
        const full = await getFilmRoll(result.id)
        setCurrentRoll(full)
      } else {
        setCurrentRoll({ ...result, filmPhotos: result.filmPhotos ?? [] })
      }
      await loadRolls()
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setSaving(false)
    }
  }

  async function handleAddPhotos() {
    if (!token || !currentRoll?.id || selectedPhotoIds.size === 0) return
    try {
      setSaving(true)
      const updated = await addPhotosToFilmRoll(token, currentRoll.id, Array.from(selectedPhotoIds))
      setCurrentRoll(updated)
      setRolls(prev => prev.map(r => r.id === updated.id ? { ...r, photoCount: updated.photoCount ?? updated.filmPhotos?.length ?? r.photoCount } : r))
      setShowPhotoSelector(false)
      setSelectedPhotoIds(new Set())
      setPhotoSelectorSearch('')
      setPhotoTypeFilter('film')
      notify(t('admin.photos_added'), 'success')
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setSaving(false)
    }
  }

  async function handleReorderFrames() {
    if (!token || !currentRoll?.id) return
    try {
      setSaving(true)
      const updated = await reorderFilmRollFrames(token, currentRoll.id)
      setCurrentRoll(updated)
      notify(t('admin.film_roll_frames_reordered'), 'success')
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    } finally {
      setSaving(false)
    }
  }

  async function handleRemovePhoto(photoId: string) {
    if (!token || !currentRoll?.id) return
    try {
      const updated = await removePhotoFromFilmRoll(token, currentRoll.id, photoId)
      setCurrentRoll(updated)
      setRolls(prev => prev.map(r => r.id === updated.id ? { ...r, photoCount: updated.photoCount ?? updated.filmPhotos?.length ?? r.photoCount } : r))
      notify(t('admin.photo_removed'), 'success')
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(t('common.error'), 'error')
    }
  }

  const rollPhotoIds = useMemo(() => {
    if (!currentRoll?.filmPhotos) return new Set<string>()
    return new Set(currentRoll.filmPhotos.map(fp => fp.photoId))
  }, [currentRoll])

  const availablePhotos = useMemo(() => {
    return photos.filter((photo) => {
      if (rollPhotoIds.has(photo.id)) return false
      if (photo.filmRollId && photo.filmRollId !== currentRoll?.id) return false
      return true
    })
  }, [currentRoll?.id, photos, rollPhotoIds])

  const filteredAvailablePhotos = useMemo(() => {
    const q = photoSelectorSearch.trim().toLowerCase()

    return availablePhotos.filter((photo) => {
      const resolvedPhotoType = photo.photoType ?? (photo.filmRollId ? 'film' : 'digital')
      const matchesPhotoType = photoTypeFilter === 'all' || resolvedPhotoType === photoTypeFilter
      if (!matchesPhotoType) return false
      if (!q) return true

      return (
        photo.title.toLowerCase().includes(q) ||
        photo.category.toLowerCase().includes(q)
      )
    })
  }, [availablePhotos, photoSelectorSearch, photoTypeFilter])

  function formatDate(dateStr: string | null) {
    if (!dateStr) return '—'
    return new Date(dateStr).toLocaleDateString()
  }

  // Helper to get first photo thumbnail from a roll
  function getRollCover(roll: FilmRollDto): string | undefined {
    if (roll.filmPhotos && roll.filmPhotos.length > 0) {
      const photo = roll.filmPhotos[0].photo
      if (photo) return resolveAssetUrl(photo.thumbnailUrl || photo.url, cdnDomain)
    }
    return undefined
  }

  // ==================== List View ====================
  if (!currentRoll) {
    return (
      <>
        <div className="space-y-6">
        <AdminCollectionToolbar
          info={<span className="text-sm font-medium text-foreground"><span className="text-muted-foreground">{filteredRolls.length} {t('admin.film_rolls')}</span></span>}
          searchValue={searchQuery}
          onSearchChange={setSearchQuery}
          searchPlaceholder={t('common.search')}
          actions={<>
            <AdminButton
              onClick={() => setShowFilters(!showFilters)}
              adminVariant="unstyled"
              className={`flex items-center gap-2 px-3 py-2 text-xs font-medium border rounded-md transition-all ${showFilters || activeFilterCount > 0
                ? 'bg-primary/10 border-primary/30 text-primary'
                : 'bg-background border-border text-muted-foreground hover:text-foreground hover:border-foreground/30'
              }`}
            >
              <Filter className="w-4 h-4" />
              <span className="hidden sm:inline">{t('admin.filter') || 'Filter'}</span>
              {activeFilterCount > 0 && (
                <span className="flex items-center justify-center w-5 h-5 bg-primary text-primary-foreground text-[10px] font-bold rounded-full">{activeFilterCount}</span>
              )}
            </AdminButton>
            <div className="flex bg-background border border-border rounded-md overflow-hidden">
              <AdminButton onClick={() => setViewMode('grid')} adminVariant="unstyled" className={`p-2 transition-colors ${viewMode === 'grid' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`} title={t('admin.grid_view')}>
                <LayoutGrid className="w-4 h-4" />
              </AdminButton>
              <AdminButton onClick={() => setViewMode('list')} adminVariant="unstyled" className={`p-2 transition-colors ${viewMode === 'list' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`} title={t('admin.list_view')}>
                <List className="w-4 h-4" />
              </AdminButton>
            </div>
          </>}
          endActions={
            <AdminButton onClick={handleCreateRoll} adminVariant="unstyled" className="flex items-center gap-2 px-5 py-2.5 bg-foreground text-background text-xs font-medium hover:bg-primary hover:text-primary-foreground transition-colors">
              <Plus className="w-4 h-4" />
              {t('admin.new_film_roll')}
            </AdminButton>
          }
          filters={showFilters ? (
            <div className="flex flex-wrap items-center gap-3">
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground whitespace-nowrap">{t('admin.film_roll_brand')}:</span>
                <div className="flex bg-background border border-border rounded-md overflow-hidden">
                  <AdminButton onClick={() => setFilterBrand('')} adminVariant="unstyled" className={`px-3 py-1.5 text-xs font-medium transition-colors ${!filterBrand ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`}>
                    {t('common.all') || 'All'}
                  </AdminButton>
                  {brands.map(brand => (
                    <AdminButton key={brand} onClick={() => setFilterBrand(brand)} adminVariant="unstyled" className={`px-3 py-1.5 text-xs font-medium transition-colors ${filterBrand === brand ? 'bg-primary/10 text-primary' : 'text-muted-foreground hover:text-foreground hover:bg-muted'}`}>
                      {brand}
                    </AdminButton>
                  ))}
                </div>
              </div>
              {activeFilterCount > 0 && (
                <>
                  <div className="h-5 w-px bg-border my-auto" />
                  <AdminButton onClick={clearAllFilters} adminVariant="unstyled" className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors">
                    <X className="w-3.5 h-3.5" />
                    <span>{t('admin.clear_all')}</span>
                  </AdminButton>
                </>
              )}
            </div>
          ) : undefined}
          activeFilters={activeFilterCount > 0 && !showFilters ? (
            <div className="mt-3 pt-3 border-t border-border flex flex-wrap items-center gap-2">
              <span className="text-xs text-muted-foreground">{t('admin.active_filters')}:</span>
              {filterBrand && (
                <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                  {filterBrand}
                  <AdminButton onClick={() => setFilterBrand('')} adminVariant="unstyled" className="hover:text-primary/70"><X className="w-3 h-3" /></AdminButton>
                </span>
              )}
              <AdminButton onClick={clearAllFilters} adminVariant="unstyled" className="text-xs text-muted-foreground hover:text-foreground underline">{t('admin.clear_all')}</AdminButton>
            </div>
          ) : undefined}
        />

        {loading ? (
          <div className="py-6"><CardGridSkeleton count={6} cols={3} /></div>
        ) : filteredRolls.length === 0 ? (
          <div className="py-20 text-center border border-dashed border-border/50 bg-muted/5">
            <Film className="w-12 h-12 mx-auto mb-4 opacity-10" />
            <p className="text-sm text-muted-foreground mb-4">{searchQuery || filterBrand ? t('admin.no_film_rolls_match_filters') : t('admin.no_film_rolls')}</p>
            {!searchQuery && !filterBrand && (
              <AdminButton onClick={handleCreateRoll} adminVariant="unstyled" className="inline-flex items-center gap-2 px-4 py-2 border border-border text-xs font-medium hover:bg-muted transition-colors">
                <Plus className="w-4 h-4" />
                {t('admin.create_first_film_roll')}
              </AdminButton>
            )}
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredRolls.map(roll => {
              const cover = getRollCover(roll)
              const filmStockDisplay = getFilmStockDisplay(roll.brand, roll.name, roll.format ?? '135', 4 / 3)
              return (
                <div
                  key={roll.id}
                  onClick={() => { void openRollDetail(roll) }}
                  className="group cursor-pointer bg-card border border-border/50 hover:border-border transition-all"
                >
                  <div className="relative aspect-[4/3] bg-muted overflow-hidden">
                    {cover ? (
                      <img src={cover} alt={roll.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center bg-muted/50 p-6">
                        <img
                          src={filmStockDisplay.asset}
                          alt={`${roll.brand} ${roll.name}`}
                          style={getFilmStockDisplayStyle(filmStockDisplay)}
                          className="max-h-full max-w-full object-contain opacity-90"
                        />
                      </div>
                    )}
                    <div className="absolute top-2 right-2 px-2 py-0.5 bg-black/50 text-white text-[10px] font-medium">{roll.photoCount ?? 0}</div>
                    <div
                      className="absolute bottom-2 right-2 z-10 flex gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={e => e.stopPropagation()}
                    >
                      <AdminButton onClick={e => handleDeleteRoll(roll, e)} disabled={deletingRollId === roll.id} adminVariant="unstyled" className="p-1.5 bg-red-500/80 hover:bg-red-500 text-white transition-colors disabled:opacity-50">
                        <Trash2 className="w-3.5 h-3.5" />
                      </AdminButton>
                    </div>
                  </div>
                  <div className="p-4">
                    <h3 className="font-medium truncate mb-1">{roll.name}</h3>
                    <p className="text-xs text-muted-foreground">{roll.brand} · ISO {roll.iso} · {roll.frameCount} {t('admin.film_roll_frames')}</p>
                    {roll.shootDate && <p className="text-xs text-muted-foreground/60 mt-1">{formatDate(roll.shootDate)}</p>}
                  </div>
                </div>
              )
            })}
          </div>
        ) : (
          <div className="space-y-2">
            {filteredRolls.map(roll => (
              <div
                key={roll.id}
                onClick={() => { void openRollDetail(roll) }}
                className="group flex items-center gap-4 p-4 bg-card border border-border/50 hover:border-border cursor-pointer transition-all"
              >
                <div className="w-20 h-14 flex-shrink-0 flex items-center justify-center bg-muted/40 p-1.5">
                  {(() => {
                    const filmStockDisplay = getFilmStockDisplay(roll.brand, roll.name, roll.format ?? '135', 20 / 14)
                    return (
                      <img
                        src={filmStockDisplay.asset}
                        alt={`${roll.brand} ${roll.name}`}
                        style={getFilmStockDisplayStyle(filmStockDisplay)}
                        className="max-h-full max-w-full object-contain"
                      />
                    )
                  })()}
                </div>
                <div className="flex-1 min-w-0">
                  <h3 className="font-medium truncate">{roll.name}</h3>
                  <p className="text-xs text-muted-foreground">{roll.brand} · ISO {roll.iso} · {roll.photoCount ?? 0}/{roll.frameCount} {t('admin.film_roll_frames')}</p>
                </div>
                <div className="text-xs text-muted-foreground/60 hidden sm:block">{formatDate(roll.shootDate)}</div>
                <div
                  className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity"
                  onClick={e => e.stopPropagation()}
                >
                  <AdminButton onClick={e => handleDeleteRoll(roll, e)} disabled={deletingRollId === roll.id} adminVariant="unstyled" className="p-2 text-destructive hover:bg-destructive/10 transition-colors disabled:opacity-50">
                    <Trash2 className="w-4 h-4" />
                  </AdminButton>
                </div>
              </div>
            ))}
          </div>
        )}
        </div>
        <SimpleDeleteDialog
          isOpen={pendingRollDelete !== null}
          title={t('common.confirm')}
          message={t('admin.film_roll_delete_confirm')}
          onConfirm={confirmDeleteRoll}
          onCancel={() => { if (!deletingRollId) setPendingRollDelete(null) }}
          t={t}
        />
      </>
    )
  }

  // ==================== Detail View ====================
  const rollPhotos = currentRoll.filmPhotos?.map(fp => fp.photo!).filter(Boolean) ?? []

  return (
    <>
      <div className="space-y-6">
        <div className="flex items-center justify-between pb-4 border-b border-border">
          <div className="flex items-center gap-3">
            <AdminButton onClick={() => {
              currentRollRequestIdRef.current += 1
              setLoadingCurrentRoll(false)
              setCurrentRoll(null)
            }} adminVariant="icon">
              <ChevronLeft className="w-5 h-5" />
            </AdminButton>
            <div>
              <h2 className="text-lg font-medium">
                {currentRoll.name || t('admin.new_film_roll')}
              </h2>
              <p className="text-xs text-muted-foreground">
                {currentRoll.brand ? `${currentRoll.brand} · ISO ${currentRoll.iso}` : t('admin.new_film_roll')}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {activeTab === 'overview' && (
              <AdminButton
                onClick={handleSaveRoll}
                disabled={saving}
                adminVariant="unstyled"
                className="flex items-center gap-2 px-5 py-2 bg-foreground text-background text-xs font-medium hover:bg-primary hover:text-primary-foreground disabled:opacity-50 transition-colors"
              >
                <Save className="w-4 h-4" />
                {saving ? t('common.loading') : t('admin.save')}
              </AdminButton>
            )}
            {activeTab === 'photos' && currentRoll.id && (
              <div className="flex flex-wrap items-center justify-end gap-2">
                <AdminButton
                  onClick={handleReorderFrames}
                  disabled={loadingCurrentRoll || saving || rollPhotos.length === 0}
                  adminVariant="outline"
                  size="md"
                  className="gap-2"
                  title={t('admin.reorder_frames_by_filename')}
                >
                  <RefreshCw className={`w-4 h-4 ${saving ? 'animate-spin' : ''}`} />
                  {t('admin.reorder_frames')}
                </AdminButton>
                <AdminButton
                  onClick={() => setShowPhotoSelector(true)}
                  disabled={loadingCurrentRoll}
                  adminVariant="unstyled"
                  className="flex items-center gap-2 px-5 py-2 bg-foreground text-background text-xs font-medium hover:bg-primary hover:text-primary-foreground transition-colors disabled:opacity-50"
                >
                  <Plus className="w-4 h-4" />
                  {t('admin.add_photos')}
                </AdminButton>
              </div>
            )}
          </div>
        </div>

        <div className="flex gap-1 border-b border-border">
          <AdminButton
            onClick={() => setActiveTab('overview')}
            adminVariant="unstyled"
            className={`flex items-center gap-2 px-4 py-3 text-xs font-medium border-b-2 transition-colors ${activeTab === 'overview' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
          >
            <Settings className="w-4 h-4" />
            {t('admin.overview') || 'Overview'}
          </AdminButton>
          {currentRoll.id && (
            <AdminButton
              onClick={() => setActiveTab('photos')}
              adminVariant="unstyled"
              className={`flex items-center gap-2 px-4 py-3 text-xs font-medium border-b-2 transition-colors ${activeTab === 'photos' ? 'border-primary text-primary' : 'border-transparent text-muted-foreground hover:text-foreground'}`}
            >
              <Layout className="w-4 h-4" />
              {t('admin.photos') || 'Photos'}
              <span className="ml-1 px-1.5 py-0.5 bg-muted text-[10px]">{rollPhotos.length}</span>
            </AdminButton>
          )}
        </div>

        <div className="pt-2">
          {activeTab === 'overview' ? (
            <div className="max-w-xl space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">画幅</label>
                  <AdminSelect
                    value={currentRollFormat}
                    onChange={handleFilmFormatChange}
                    options={FILM_FORMAT_OPTIONS}
                    placeholder="135 / 120"
                  />
                </div>
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_brand')}</label>
                  <AdminSelect
                    value={currentRoll.brand}
                    onChange={handleFilmBrandChange}
                    options={FILM_STOCK_BRAND_OPTIONS}
                    placeholder={t('admin.film_roll_brand')}
                  />
                </div>
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_name')}</label>
                  <AdminSelect
                    value={currentRoll.name}
                    onChange={handleFilmNameChange}
                    options={currentNameOptions}
                    placeholder={t('admin.film_roll_name')}
                  />
                </div>
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_iso')}</label>
                  <CustomInput variant="config" type="number" value={String(currentRoll.iso)} onChange={e => setCurrentRoll({ ...currentRoll, iso: parseInt(e.target.value) || 0 })} />
                </div>
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_frame_count')}</label>
                  <CustomInput variant="config" type="number" value={String(currentRoll.frameCount)} onChange={e => setCurrentRoll({ ...currentRoll, frameCount: parseInt(e.target.value) || 0 })} />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_shoot_date')}</label>
                  <CustomInput variant="config" type="date" value={currentRoll.shootDate ? currentRoll.shootDate.slice(0, 10) : ''} onChange={e => setCurrentRoll({ ...currentRoll, shootDate: e.target.value ? new Date(e.target.value).toISOString() : null })} />
                </div>
                <div>
                  <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_end_date')}</label>
                  <CustomInput variant="config" type="date" value={currentRoll.endDate ? currentRoll.endDate.slice(0, 10) : ''} onChange={e => setCurrentRoll({ ...currentRoll, endDate: e.target.value ? new Date(e.target.value).toISOString() : null })} />
                </div>
              </div>
              <div>
                <label className="block text-xs text-muted-foreground mb-2">{t('admin.film_roll_notes')}</label>
                <textarea
                  value={currentRoll.notes || ''}
                  onChange={e => setCurrentRoll({ ...currentRoll, notes: e.target.value })}
                  placeholder={t('admin.film_roll_notes')}
                  className="w-full p-3 h-24 bg-muted/30 border-b border-border focus:border-primary outline-none text-sm transition-colors resize-none"
                />
              </div>
            </div>
          ) : (
            <div className="space-y-4">
              {loadingCurrentRoll ? (
                <div className="py-6"><ListSkeleton count={3} /></div>
              ) : showPhotoSelector ? (
                <div className="space-y-4">
                  <div className="flex flex-col gap-3 p-3 bg-muted/30 border border-border sm:flex-row sm:items-center sm:justify-between">
                    <div className="flex flex-wrap items-center gap-3">
                      <AdminButton onClick={() => { setShowPhotoSelector(false); setSelectedPhotoIds(new Set()); setPhotoSelectorSearch(''); setPhotoTypeFilter('film') }} adminVariant="icon">
                        <X className="w-4 h-4" />
                      </AdminButton>
                      <span className="text-sm">{selectedPhotoIds.size} {t('admin.selected')}</span>
                      <input type="text" value={photoSelectorSearch} onChange={e => setPhotoSelectorSearch(e.target.value)} placeholder={t('common.search')} className="px-2 py-1 text-sm bg-transparent border border-border rounded focus:border-primary outline-none w-40" />
                      <AdminSelect
                        value={photoTypeFilter}
                        onChange={(value) => setPhotoTypeFilter(value as PhotoTypeFilter)}
                        options={[
                          { value: 'all', label: t('common.all') },
                          { value: 'digital', label: t('admin.upload_type_digital') },
                          { value: 'film', label: t('admin.upload_type_film') },
                        ]}
                        className="min-w-[120px]"
                      />
                    </div>
                    <AdminButton onClick={handleAddPhotos} disabled={selectedPhotoIds.size === 0 || saving} adminVariant="unstyled" className="flex items-center gap-2 px-4 py-1.5 bg-foreground text-background text-xs font-medium disabled:opacity-50 transition-colors">
                      <Check className="w-3.5 h-3.5" />
                      {t('admin.add')}
                    </AdminButton>
                  </div>
                  {filteredAvailablePhotos.length === 0 ? (
                    <div className="py-16 text-center border border-dashed border-border/50 bg-muted/5">
                      <ImageIcon className="w-10 h-10 mx-auto mb-3 opacity-10" />
                      <p className="text-sm text-muted-foreground">
                        {availablePhotos.length === 0 ? t('admin.no_photos_available') : t('admin.no_photos_match_filter')}
                      </p>
                    </div>
                  ) : (
                    <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-2">
                      {filteredAvailablePhotos.map(photo => {
                        const isSelected = selectedPhotoIds.has(photo.id)
                        return (
                          <div
                            key={photo.id}
                            onClick={() => setSelectedPhotoIds(prev => {
                              const next = new Set(prev)
                              if (next.has(photo.id)) next.delete(photo.id)
                              else next.add(photo.id)
                              return next
                            })}
                            className={`relative aspect-square cursor-pointer ${isSelected ? 'ring-2 ring-primary' : 'hover:opacity-80'}`}
                          >
                            <img src={resolveAssetUrl(photo.thumbnailUrl || photo.url, cdnDomain)} alt={photo.title} className="w-full h-full object-cover" />
                            <div className="absolute left-1 bottom-1 px-1.5 py-0.5 bg-black/55 text-white text-[9px]">
                              {t(`admin.upload_type_${photo.photoType ?? (photo.filmRollId ? 'film' : 'digital')}`)}
                            </div>
                            {isSelected && (
                              <div className="absolute inset-0 bg-primary/20 flex items-center justify-center"><Check className="w-5 h-5 text-primary" /></div>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  )}
                </div>
              ) : rollPhotos.length === 0 ? (
                <div className="py-16 text-center border border-dashed border-border/50 bg-muted/5">
                  <ImageIcon className="w-10 h-10 mx-auto mb-3 opacity-10" />
                  <p className="text-sm text-muted-foreground mb-3">{t('admin.album_empty')}</p>
                  {currentRoll.id && (
                    <div className="flex flex-wrap items-center justify-center gap-2">
                      <AdminButton
                        onClick={handleReorderFrames}
                        disabled={saving}
                        adminVariant="outline"
                        size="md"
                        className="gap-2"
                        title={t('admin.reorder_frames_by_filename')}
                      >
                        <RefreshCw className={`w-4 h-4 ${saving ? 'animate-spin' : ''}`} />
                        {t('admin.reorder_frames')}
                      </AdminButton>
                      <AdminButton onClick={() => setShowPhotoSelector(true)} adminVariant="unstyled" className="inline-flex items-center gap-2 px-4 py-2 border border-border text-xs font-medium hover:bg-muted transition-colors">
                        <Plus className="w-4 h-4" />
                        {t('admin.add_photos')}
                      </AdminButton>
                    </div>
                  )}
                </div>
              ) : (
                <div className="grid grid-cols-3 sm:grid-cols-5 md:grid-cols-6 lg:grid-cols-8 gap-2">
                  {rollPhotos.map((photo, idx) => (
                    <div key={photo.id} className="relative aspect-square group bg-muted overflow-hidden cursor-pointer" onClick={() => onPreview(photo)}>
                      <img src={resolveAssetUrl(photo.thumbnailUrl || photo.url, cdnDomain)} alt={photo.title} className="w-full h-full object-cover" />
                      <div className="absolute top-1 left-1 px-1.5 py-0.5 bg-black/50 text-white text-[8px] font-mono">#{idx + 1}</div>
                      <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <AdminButton
                          onClick={e => { e.stopPropagation(); handleRemovePhoto(photo.id) }}
                          adminVariant="unstyled"
                          className="px-2 py-1 bg-red-500/80 hover:bg-red-500 text-white text-[9px] font-medium"
                        >
                          {t('admin.remove')}
                        </AdminButton>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
      <SimpleDeleteDialog
        isOpen={pendingRollDelete !== null}
        title={t('common.confirm')}
        message={t('admin.film_roll_delete_confirm')}
        onConfirm={confirmDeleteRoll}
        onCancel={() => { if (!deletingRollId) setPendingRollDelete(null) }}
        t={t}
      />
    </>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import {
  Users,
  Plus,
  Edit3,
  Trash2,
  Star,
  StarOff,
  ExternalLink,
  GripVertical,
  Loader2,
  X,
  Save,
  Eye,
  EyeOff,
} from 'lucide-react'
import type { FriendLinkDto } from '@/lib/api/types'
import { ApiUnauthorizedError } from '@/lib/api/core'
import {
  getAdminFriendLinks,
  createFriendLink,
  updateFriendLink,
  deleteFriendLink,
  reorderFriendLinks,
} from '@/lib/api/friends'
import { useAuth } from '@/contexts/AuthContext'
import { AdminButton } from '@/components/admin/AdminButton'
import { ListSkeleton } from '@/components/admin/Skeleton'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import { useAdmin } from '../layout'

// 友链表单数据接口
interface FriendFormData {
  id?: string
  name: string
  url: string
  description: string
  avatar: string
  featured: boolean
  sortOrder: number
  isActive: boolean
}

// 默认表单数据
const defaultFormData: FriendFormData = {
  name: '',
  url: '',
  description: '',
  avatar: '',
  featured: false,
  sortOrder: 0,
  isActive: true,
}

export default function FriendsPage() {
  const { t, notify, handleUnauthorized } = useAdmin()
  const { token } = useAuth()

  // 状态管理
  const [friends, setFriends] = useState<FriendLinkDto[]>([]) // 友链列表
  const [loading, setLoading] = useState(true) // 加载状态
  const [saving, setSaving] = useState(false) // 保存状态
  const [showModal, setShowModal] = useState(false) // 模态框显示状态
  const [editingFriend, setEditingFriend] = useState<FriendFormData | null>(null) // 正在编辑的友链
  const [deleteConfirm, setDeleteConfirm] = useState<string | null>(null) // 删除确认对话框
  const [draggedId, setDraggedId] = useState<string | null>(null) // 拖拽中的友链ID

  // 获取友链列表
  const fetchFriends = async () => {
    if (!token) return
    setLoading(true)
    try {
      const data = await getAdminFriendLinks(token)
      setFriends(data)
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
      console.error('Failed to fetch friends:', error)
    } finally {
      setLoading(false)
    }
  }

  // 初始化加载友链列表
  useEffect(() => {
    fetchFriends()
  }, [token]) // eslint-disable-line react-hooks/exhaustive-deps

  // 创建新友链
  const handleCreate = () => {
    setEditingFriend({ ...defaultFormData, sortOrder: friends.length })
    setShowModal(true)
  }

  // 编辑友链
  const handleEdit = (friend: FriendLinkDto) => {
    setEditingFriend({
      id: friend.id,
      name: friend.name,
      url: friend.url,
      description: friend.description || '',
      avatar: friend.avatar || '',
      featured: friend.featured,
      sortOrder: friend.sortOrder,
      isActive: friend.isActive,
    })
    setShowModal(true)
  }

  // 保存友链（创建或更新）
  const handleSave = async () => {
    if (!editingFriend || !token) return
    if (!editingFriend.name.trim()) {
      notify(t('admin.friends_name_required'), 'error')
      return
    }
    if (!editingFriend.url.trim()) {
      notify(t('admin.friends_url_required'), 'error')
      return
    }

    // 验证URL格式
    try {
      new URL(editingFriend.url)
    } catch {
      notify(t('admin.friends_url_invalid'), 'error')
      return
    }

    setSaving(true)
    try {
      const data = {
        name: editingFriend.name,
        url: editingFriend.url,
        description: editingFriend.description || undefined,
        avatar: editingFriend.avatar || undefined,
        featured: editingFriend.featured,
        sortOrder: editingFriend.sortOrder,
        isActive: editingFriend.isActive,
      }

      if (editingFriend.id) {
        await updateFriendLink(token, editingFriend.id, data)
        notify(t('admin.friends_updated'))
      } else {
        await createFriendLink(token, data)
        notify(t('admin.friends_created'))
      }
      await fetchFriends()
      setShowModal(false)
      setEditingFriend(null)
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
      console.error('Failed to save friend:', error)
    } finally {
      setSaving(false)
    }
  }

  // 删除友链
  const handleDelete = async (id: string) => {
    if (!token) return
    try {
      await deleteFriendLink(token, id)
      await fetchFriends()
      notify(t('admin.friends_deleted'))
      setDeleteConfirm(null)
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
      console.error('Failed to delete friend:', error)
    }
  }

  // 切换精选状态
  const handleToggleFeatured = async (friend: FriendLinkDto) => {
    if (!token) return
    try {
      await updateFriendLink(token, friend.id, { featured: !friend.featured })
      setFriends((prev) =>
        prev.map((f) =>
          f.id === friend.id ? { ...f, featured: !f.featured } : f
        )
      )
      notify(friend.featured ? t('admin.friends_unfeatured') : t('admin.friends_featured'))
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
    }
  }

  // 切换启用/禁用状态
  const handleToggleActive = async (friend: FriendLinkDto) => {
    if (!token) return
    try {
      await updateFriendLink(token, friend.id, { isActive: !friend.isActive })
      setFriends((prev) =>
        prev.map((f) =>
          f.id === friend.id ? { ...f, isActive: !f.isActive } : f
        )
      )
      notify(friend.isActive ? t('admin.friends_disabled') : t('admin.friends_enabled'))
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
    }
  }

  // 拖拽排序处理函数
  const handleDragStart = (e: React.DragEvent, id: string) => {
    setDraggedId(id)
    e.dataTransfer.effectAllowed = 'move'
  }

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
  }

  const handleDrop = async (e: React.DragEvent, targetId: string) => {
    e.preventDefault()
    if (!draggedId || draggedId === targetId || !token) return

    const draggedIndex = friends.findIndex((f) => f.id === draggedId)
    const targetIndex = friends.findIndex((f) => f.id === targetId)

    if (draggedIndex === -1 || targetIndex === -1) return

    // 先在本地重新排序
    const newFriends = [...friends]
    const [removed] = newFriends.splice(draggedIndex, 1)
    newFriends.splice(targetIndex, 0, removed)

    // 更新排序顺序
    const updatedFriends = newFriends.map((f, index) => ({
      ...f,
      sortOrder: index,
    }))

    setFriends(updatedFriends)
    setDraggedId(null)

    // 保存到服务器
    try {
      await reorderFriendLinks(
        token,
        updatedFriends.map((f) => ({ id: f.id, sortOrder: f.sortOrder }))
      )
      notify(t('admin.friends_reordered'))
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      // 出错时恢复原状态
      await fetchFriends()
      notify(t('common.error'), 'error')
    }
  }

  return (
    <div className="h-full flex flex-col gap-6 overflow-hidden">
      {/* 页面头部 */}
      <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
        <div className="flex items-center gap-4">
          <Users className="w-6 h-6 text-primary" />
          <h3 className="font-serif text-2xl uppercase tracking-tight">
            {t('admin.friends')}
          </h3>
          <span className="text-xs text-muted-foreground">
            {friends.length} {t('admin.items')}
          </span>
        </div>
        <AdminButton
          onClick={handleCreate}
          adminVariant="primary"
          size="lg"
          className="flex items-center"
        >
          <Plus className="w-4 h-4 mr-2" />
          {t('admin.friends_add')}
        </AdminButton>
      </div>

      {/* 友链列表 */}
      <div className="flex-1 overflow-y-auto custom-scrollbar">
        {loading ? (
          <div className="p-6"><ListSkeleton count={5} /></div>
        ) : friends.length === 0 ? (
          <div className="py-24 text-center border border-dashed border-border">
            <Users className="w-12 h-12 mx-auto mb-4 opacity-10" />
            <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
              {t('admin.friends_empty')}
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {friends.map((friend) => (
              <div
                key={friend.id}
                draggable
                onDragStart={(e) => handleDragStart(e, friend.id)}
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, friend.id)}
                className={`flex items-center gap-4 p-4 border border-border hover:border-primary transition-all group ${
                  draggedId === friend.id ? 'opacity-50' : ''
                } ${!friend.isActive ? 'opacity-60' : ''}`}
              >
                {/* 拖拽手柄 */}
                <div className="cursor-grab active:cursor-grabbing text-muted-foreground hover:text-foreground">
                  <GripVertical className="w-4 h-4" />
                </div>

                {/* 头像 */}
                <div className="w-12 h-12 rounded-lg overflow-hidden bg-muted flex-shrink-0">
                  {friend.avatar ? (
                    <img
                      src={friend.avatar}
                      alt={friend.name}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center bg-primary/10">
                      <span className="text-lg font-bold text-primary">
                        {friend.name.charAt(0).toUpperCase()}
                      </span>
                    </div>
                  )}
                </div>

                {/* 友链信息 */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <h4 className="font-serif text-lg truncate">{friend.name}</h4>
                    {friend.featured && (
                      <Star className="w-4 h-4 text-yellow-500 fill-yellow-500" />
                    )}
                    {!friend.isActive && (
                      <span className="text-[8px] font-black uppercase px-1.5 py-0.5 border border-muted-foreground text-muted-foreground">
                        {t('admin.friends_inactive')}
                      </span>
                    )}
                  </div>
                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <ExternalLink className="w-3 h-3" />
                    <span className="truncate">{friend.url}</span>
                  </div>
                  {friend.description && (
                    <p className="text-xs text-muted-foreground/70 mt-1 truncate">
                      {friend.description}
                    </p>
                  )}
                </div>

                {/* 操作按钮 */}
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <AdminButton
                    onClick={() => handleToggleActive(friend)}
                    adminVariant="icon"
                    title={friend.isActive ? t('admin.friends_disable') : t('admin.friends_enable')}
                  >
                    {friend.isActive ? (
                      <Eye className="w-4 h-4" />
                    ) : (
                      <EyeOff className="w-4 h-4" />
                    )}
                  </AdminButton>
                  <AdminButton
                    onClick={() => handleToggleFeatured(friend)}
                    adminVariant="icon"
                    className="hover:text-yellow-500"
                    title={friend.featured ? t('admin.friends_unfeature') : t('admin.friends_feature')}
                  >
                    {friend.featured ? (
                      <StarOff className="w-4 h-4" />
                    ) : (
                      <Star className="w-4 h-4" />
                    )}
                  </AdminButton>
                  <AdminButton
                    onClick={() => handleEdit(friend)}
                    adminVariant="iconPrimary"
                  >
                    <Edit3 className="w-4 h-4" />
                  </AdminButton>
                  <AdminButton
                    onClick={() => setDeleteConfirm(friend.id)}
                    adminVariant="iconDestructive"
                  >
                    <Trash2 className="w-4 h-4" />
                  </AdminButton>
                  <a
                    href={friend.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="p-2 text-muted-foreground hover:text-primary transition-colors"
                  >
                    <ExternalLink className="w-4 h-4" />
                  </a>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 编辑/创建模态框 */}
      {showModal && editingFriend && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-background/95 backdrop-blur-sm">
          <div className="w-full max-w-lg bg-background border border-border shadow-2xl">
            {/* 模态框头部 */}
            <div className="p-6 border-b border-border flex items-center justify-between">
              <h3 className="font-serif text-2xl uppercase tracking-tight">
                {editingFriend.id ? t('admin.friends_edit') : t('admin.friends_add')}
              </h3>
              <AdminButton
                onClick={() => {
                  setShowModal(false)
                  setEditingFriend(null)
                }}
                adminVariant="icon"
              >
                <X className="w-5 h-5" />
              </AdminButton>
            </div>

            {/* 模态框内容 */}
            <div className="p-6 space-y-4">
              {/* 名称 */}
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest mb-2">
                  {t('admin.friends_name')} *
                </label>
                <input
                  type="text"
                  value={editingFriend.name}
                  onChange={(e) =>
                    setEditingFriend({ ...editingFriend, name: e.target.value })
                  }
                  placeholder={t('admin.friends_name_placeholder')}
                  className="w-full p-3 bg-transparent border border-border focus:border-primary outline-none text-sm"
                />
              </div>

              {/* 网址 */}
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest mb-2">
                  {t('admin.friends_url')} *
                </label>
                <input
                  type="url"
                  value={editingFriend.url}
                  onChange={(e) =>
                    setEditingFriend({ ...editingFriend, url: e.target.value })
                  }
                  placeholder="https://example.com"
                  className="w-full p-3 bg-transparent border border-border focus:border-primary outline-none text-sm"
                />
              </div>

              {/* 描述 */}
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest mb-2">
                  {t('admin.friends_description')}
                </label>
                <input
                  type="text"
                  value={editingFriend.description}
                  onChange={(e) =>
                    setEditingFriend({ ...editingFriend, description: e.target.value })
                  }
                  placeholder={t('admin.friends_description_placeholder')}
                  className="w-full p-3 bg-transparent border border-border focus:border-primary outline-none text-sm"
                />
              </div>

              {/* 头像URL */}
              <div>
                <label className="block text-xs font-bold uppercase tracking-widest mb-2">
                  {t('admin.friends_avatar')}
                </label>
                <input
                  type="url"
                  value={editingFriend.avatar}
                  onChange={(e) =>
                    setEditingFriend({ ...editingFriend, avatar: e.target.value })
                  }
                  placeholder="https://example.com/avatar.png"
                  className="w-full p-3 bg-transparent border border-border focus:border-primary outline-none text-sm"
                />
              </div>

              {/* 选项 */}
              <div className="flex items-center gap-6">
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    type="checkbox"
                    checked={editingFriend.featured}
                    onChange={(e) =>
                      setEditingFriend({ ...editingFriend, featured: e.target.checked })
                    }
                    className="w-4 h-4"
                  />
                  <span className="font-bold uppercase tracking-widest text-xs">
                    {t('admin.friends_featured')}
                  </span>
                </label>
                <label className="flex items-center gap-2 text-sm cursor-pointer">
                  <input
                    type="checkbox"
                    checked={editingFriend.isActive}
                    onChange={(e) =>
                      setEditingFriend({ ...editingFriend, isActive: e.target.checked })
                    }
                    className="w-4 h-4"
                  />
                  <span className="font-bold uppercase tracking-widest text-xs">
                    {t('admin.friends_active')}
                  </span>
                </label>
              </div>
            </div>

            {/* 模态框底部 */}
            <div className="p-6 border-t border-border flex justify-end gap-3">
              <AdminButton
                onClick={() => {
                  setShowModal(false)
                  setEditingFriend(null)
                }}
                adminVariant="outline"
                size="lg"
              >
                {t('common.cancel')}
              </AdminButton>
              <AdminButton
                onClick={handleSave}
                disabled={saving}
                adminVariant="primary"
                size="lg"
                className="flex items-center gap-2"
              >
                {saving ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Save className="w-4 h-4" />
                )}
                <span>{t('common.save')}</span>
              </AdminButton>
            </div>
          </div>
        </div>
      )}

      <SimpleDeleteDialog
        isOpen={deleteConfirm !== null}
        title={t('common.delete')}
        message={t('admin.friends_delete_confirm')}
        onConfirm={() => handleDelete(deleteConfirm!)}
        onCancel={() => setDeleteConfirm(null)}
        t={t}
      />
    </div>
  )
}

/**
 * 博客管理标签页 - 博客文章的创建、编辑、删除及草稿恢复
 */
'use client'

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react'
import dynamic from 'next/dynamic'
import {
  BookText,
  Plus,
  History,
  FileText,
  Edit3,
  Trash2,
  ChevronLeft,
  Save,
  ImageIcon,
  X,
  Loader2,
  Check,
  Clock,
} from 'lucide-react'
import type { PhotoDto, AdminSettingsDto, BlogDto } from '@/lib/api/types'
import { resolveAssetUrl, ApiUnauthorizedError } from '@/lib/api/core'
import { getAdminBlogs, createBlog, updateBlog, deleteBlog } from '@/lib/api/blogs'
import { buildStoryMarkdownImage } from '@/lib/story-rich-content'
import { formatRelativeTimeLabel } from '@/lib/utils'
import { createBlogDraftDocumentId, resolveBlogDocumentId, rotateBlogDraftDocumentId } from '@/lib/blog-draft-document'
import { useAuth } from '@/contexts/AuthContext'
import { AdminSelect, type SelectOption } from '@/components/admin/AdminFormControls'
import { useAdmin } from '../layout'
import type { NarrativeTipTapEditorHandle } from '@/components/NarrativeTipTapEditor'
import {
  saveBlogDraftToDB,
  getBlogDraftFromDB,
  clearBlogDraftFromDB,
  type BlogDraftData
} from '@/lib/client-db'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import { DraftRestoreDialog } from '@/components/admin/DraftRestoreDialog'
import { AdminButton } from '@/components/admin/AdminButton'
import { ListSkeleton } from '@/components/admin/Skeleton'

// 动态导入 MilkdownEditor，避免 SSR 问题
const NarrativeTipTapEditor = dynamic(
  () => import('@/components/NarrativeTipTapEditor'),
  { 
    ssr: false,
    loading: () => (
      <div className="flex-1 flex items-center justify-center border border-border bg-card/30">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    )
  }
)

const AUTO_SAVE_DELAY = 2000 // 自动保存防抖延迟（毫秒）

interface BlogTabProps {
  photos: PhotoDto[]
  settings: AdminSettingsDto | null
  t: (key: string) => string
  notify: (message: string, type?: 'success' | 'error' | 'info') => void
  refreshKey?: number
}

interface BlogFormData {
  id?: string
  title: string
  content: string
  contentJson?: BlogDto['contentJson']
  category: string
  tags: string
  isPublished: boolean
}

export function BlogTab({ photos, settings, t, notify, refreshKey }: BlogTabProps) {
  const { token } = useAuth()
  const { handleUnauthorized } = useAdmin()
  const [blogs, setBlogs] = useState<BlogDto[]>([])
  const [loading, setLoading] = useState(true)
  const [currentBlog, setCurrentBlog] = useState<BlogFormData | null>(null)
  const [editMode, setEditMode] = useState<'list' | 'editor'>('list')
  const [isInsertingPhoto, setIsInsertingPhoto] = useState(false)
  const [saving, setSaving] = useState(false)
  const [isAiTaskLocked, setIsAiTaskLocked] = useState(false)
  const [draftDocumentId, setDraftDocumentId] = useState(createBlogDraftDocumentId)
  const editorRef = useRef<NarrativeTipTapEditorHandle>(null)
  
  // 自动保存状态
  const [draftSaved, setDraftSaved] = useState(false)
  const [lastSavedAt, setLastSavedAt] = useState<number | null>(null)
  const autoSaveTimerRef = useRef<NodeJS.Timeout | null>(null)
  
  // 记录初始状态，用于脏检查
  const [isDirty, setIsDirty] = useState(false)
  const initialBlogRef = useRef<{
    title: string
    content: string
    contentJson?: BlogDto['contentJson']
    category: string
    tags: string
    isPublished: boolean
  } | null>(null)
  
  // 删除确认对话框状态
  const [deleteBlogId, setDeleteBlogId] = useState<string | null>(null)
  
  // 发布状态筛选
  const [statusFilter, setStatusFilter] = useState('')
  
  // 草稿恢复对话框状态
  const [draftRestoreDialog, setDraftRestoreDialog] = useState<{
    isOpen: boolean
    draft: BlogDraftData | null
    blog: BlogDto | null
    isNew: boolean
  }>({ isOpen: false, draft: null, blog: null, isNew: false })

  const fetchBlogs = useCallback(async () => {
    if (!token) {
      setBlogs([])
      setLoading(false)
      return
    }

    setLoading(true)
    try {
      const data = await getAdminBlogs(token)
      setBlogs(data)
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
      console.error('Failed to fetch blogs:', error)
    } finally {
      setLoading(false)
    }
  }, [handleUnauthorized, notify, t, token])
  
  useEffect(() => {
    void fetchBlogs()
  }, [fetchBlogs])
  
  useEffect(() => {
    if (refreshKey && refreshKey > 0) {
      void fetchBlogs()
    }
  }, [fetchBlogs, refreshKey])

  // 进入编辑模式时加载草稿
  const loadDraftForBlog = useCallback(async (blogId?: string) => {
    try {
      const draft = await getBlogDraftFromDB(blogId)
      if (draft) {
        setLastSavedAt(draft.savedAt)
        return draft
      }
    } catch (e) {
      console.error('Failed to load blog draft', e)
    }
    return null
  }, [])

  // 保存草稿到 IndexedDB
  const saveDraft = useCallback(async () => {
    if (!currentBlog) return
    if (!currentBlog.title && !currentBlog.content) return

    try {
      await saveBlogDraftToDB({
        blogId: currentBlog.id,
        title: currentBlog.title,
        content: currentBlog.content,
        contentJson: currentBlog.contentJson ?? null,
        category: currentBlog.category,
        tags: currentBlog.tags,
        isPublished: currentBlog.isPublished,
      })
      setLastSavedAt(Date.now())
      setDraftSaved(true)
      setTimeout(() => setDraftSaved(false), 2000)
    } catch (e) {
      console.error('Failed to save blog draft', e)
    }
  }, [currentBlog])

  // 从 IndexedDB 清除草稿
  const clearDraft = useCallback(async (blogId?: string) => {
    try {
      await clearBlogDraftFromDB(blogId)
      setLastSavedAt(null)
    } catch (e) {
      console.error('Failed to clear blog draft', e)
    }
  }, [])

  // 格式化相对时间
  const formatRelativeTime = useMemo(() => {
    if (!lastSavedAt) return null
    return formatRelativeTimeLabel(lastSavedAt, t)
  }, [lastSavedAt, t])

  // 检查内容是否变更（脏检查）
  useEffect(() => {
    if (editMode !== 'editor' || !currentBlog || !initialBlogRef.current) {
      setIsDirty(false)
      return
    }
    
    const initial = initialBlogRef.current
    const hasChanged =
      currentBlog.title !== initial.title ||
      currentBlog.content !== initial.content ||
      JSON.stringify(currentBlog.contentJson ?? null) !== JSON.stringify(initial.contentJson ?? null) ||
      currentBlog.category !== initial.category ||
      currentBlog.tags !== initial.tags ||
      currentBlog.isPublished !== initial.isPublished
    
    setIsDirty(hasChanged)
  }, [editMode, currentBlog?.title, currentBlog?.content, currentBlog?.contentJson, currentBlog?.category, currentBlog?.tags, currentBlog?.isPublished])

  // 内容变更时自动保存草稿（仅在有修改时）
  useEffect(() => {
    if (isAiTaskLocked || !currentBlog || !isDirty) return
    if (!currentBlog.title && !currentBlog.content) return

    // 清除已有定时器
    if (autoSaveTimerRef.current) {
      clearTimeout(autoSaveTimerRef.current)
    }

    // 设置新的自动保存定时器
    autoSaveTimerRef.current = setTimeout(() => {
      saveDraft()
    }, AUTO_SAVE_DELAY)

    return () => {
      if (autoSaveTimerRef.current) {
        clearTimeout(autoSaveTimerRef.current)
      }
    }
  }, [currentBlog?.title, currentBlog?.content, currentBlog?.contentJson, currentBlog?.category, currentBlog?.tags, currentBlog?.isPublished, saveDraft, isAiTaskLocked, isDirty])

  // 将草稿应用到当前博客
  const applyDraft = useCallback((draft: BlogDraftData, blogId?: string) => {
    setCurrentBlog({
      id: blogId,
      title: draft.title,
      content: draft.content,
      contentJson: draft.contentJson ?? null,
      category: draft.category || t('blog.uncategorized'),
      tags: draft.tags || '',
      isPublished: draft.isPublished,
    })
    setLastSavedAt(draft.savedAt)
    // 更新初始引用以匹配恢复的草稿（不视为脏数据）
    initialBlogRef.current = {
      title: draft.title,
      content: draft.content,
      contentJson: draft.contentJson ?? null,
      category: draft.category || t('blog.uncategorized'),
      tags: draft.tags || '',
      isPublished: draft.isPublished,
    }
    notify(t('admin.restored_from_draft'), 'info')
  }, [t, notify])

  // 草稿恢复对话框 - 确认恢复
  const handleDraftRestore = useCallback(() => {
    if (draftRestoreDialog.draft) {
      applyDraft(draftRestoreDialog.draft, draftRestoreDialog.blog?.id)
    }
    setDraftRestoreDialog({ isOpen: false, draft: null, blog: null, isNew: false })
    setEditMode('editor')
  }, [draftRestoreDialog, applyDraft])

  // 草稿恢复对话框 - 丢弃草稿
  const handleDraftDiscard = useCallback(() => {
    if (draftRestoreDialog.isNew) {
      setCurrentBlog({
        title: '',
        content: '',
        contentJson: null,
        category: t('blog.uncategorized'),
        tags: '',
        isPublished: false,
      })
    } else if (draftRestoreDialog.blog) {
      setCurrentBlog({
        id: draftRestoreDialog.blog.id,
        title: draftRestoreDialog.blog.title,
        content: draftRestoreDialog.blog.content,
        contentJson: draftRestoreDialog.blog.contentJson ?? null,
        category: draftRestoreDialog.blog.category || t('blog.uncategorized'),
        tags: draftRestoreDialog.blog.tags || '',
        isPublished: draftRestoreDialog.blog.isPublished,
      })
    }
    setLastSavedAt(null)
    setDraftRestoreDialog({ isOpen: false, draft: null, blog: null, isNew: false })
    setEditMode('editor')
  }, [draftRestoreDialog, t])

  // 草稿恢复对话框 - 取消（关闭不操作）
  const handleDraftCancel = useCallback(() => {
    setDraftRestoreDialog({ isOpen: false, draft: null, blog: null, isNew: false })
    setCurrentBlog(null)
  }, [])

  const handleCreateBlog = async () => {
    setDraftDocumentId(rotateBlogDraftDocumentId)
    // 设置脏检查的初始状态
    initialBlogRef.current = {
      title: '',
      content: '',
      contentJson: null,
      category: t('blog.uncategorized'),
      tags: '',
      isPublished: false,
    }
    
    // 检查是否存在新博客的草稿
    const draft = await loadDraftForBlog(undefined)
    if (draft && (draft.title || draft.content)) {
      // 弹出对话框询问用户是否恢复草稿
      setCurrentBlog({
        title: '',
        content: '',
        contentJson: null,
        category: t('blog.uncategorized'),
        tags: '',
        isPublished: false,
      })
      setDraftRestoreDialog({ isOpen: true, draft, blog: null, isNew: true })
      return
    }
    
    setCurrentBlog({
      title: '',
      content: '',
      contentJson: null,
      category: t('blog.uncategorized'),
      tags: '',
      isPublished: false,
    })
    setEditMode('editor')
  }

  const handleEditBlog = async (blog: BlogDto) => {
    // 设置脏检查的初始状态
    initialBlogRef.current = {
      title: blog.title,
      content: blog.content,
      contentJson: blog.contentJson ?? null,
      category: blog.category || t('blog.uncategorized'),
      tags: blog.tags || '',
      isPublished: blog.isPublished,
    }
    
    // 检查是否存在该博客的草稿
    const draft = await loadDraftForBlog(blog.id)
    if (draft && draft.savedAt > new Date(blog.updatedAt).getTime()) {
      // 草稿比已保存版本更新，弹出对话框
      setCurrentBlog({
        id: blog.id,
        title: blog.title,
        content: blog.content,
        contentJson: blog.contentJson ?? null,
        category: blog.category || t('blog.uncategorized'),
        tags: blog.tags || '',
        isPublished: blog.isPublished,
      })
      setDraftRestoreDialog({ isOpen: true, draft, blog, isNew: false })
      return
    }
    
    setCurrentBlog({
      id: blog.id,
      title: blog.title,
      content: blog.content,
      contentJson: blog.contentJson ?? null,
      category: blog.category || t('blog.uncategorized'),
      tags: blog.tags || '',
      isPublished: blog.isPublished,
    })
    setLastSavedAt(null)
    setEditMode('editor')
  }

  const confirmDeleteBlog = async () => {
    if (!token || !deleteBlogId) return
    try {
      await deleteBlog(token, deleteBlogId)
      await fetchBlogs()
      notify(t('admin.notify_log_deleted'))
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
      console.error('Failed to delete blog:', error)
    } finally {
      setDeleteBlogId(null)
    }
  }

  const handleSaveBlog = async () => {
    if (isAiTaskLocked || !currentBlog || !token) return
    if (!currentBlog.title.trim()) {
      notify(t('blog.enter_title'), 'error')
      return
    }
    if (!currentBlog.content.trim()) {
      notify(t('blog.enter_content'), 'error')
      return
    }

    setSaving(true)
    try {
      if (currentBlog.id) {
        // 更新已有博客
        await updateBlog(token, currentBlog.id, {
          title: currentBlog.title,
          content: currentBlog.content,
          contentJson: currentBlog.contentJson ?? null,
          category: currentBlog.category,
          tags: currentBlog.tags,
          isPublished: currentBlog.isPublished,
        })
      } else {
        // 创建新博客
        await createBlog(token, {
          title: currentBlog.title,
          content: currentBlog.content,
          contentJson: currentBlog.contentJson ?? null,
          category: currentBlog.category,
          tags: currentBlog.tags,
          isPublished: currentBlog.isPublished,
        })
      }
      // 保存成功后清除草稿
      await clearDraft(currentBlog.id)
      
      await fetchBlogs()
      setEditMode('list')
      setCurrentBlog(null)
      setLastSavedAt(null)
      notify(t('admin.notify_log_saved'))
    } catch (error) {
      if (error instanceof ApiUnauthorizedError) {
        handleUnauthorized(error)
        return
      }
      notify(t('common.error'), 'error')
      console.error('Failed to save blog:', error)
    } finally {
      setSaving(false)
    }
  }

  const insertPhotoIntoBlog = (photo: PhotoDto) => {
    if (isAiTaskLocked) return
    const markdown = buildStoryMarkdownImage({
      url: resolveAssetUrl(photo.url, settings?.cdn_domain),
      alt: photo.title,
    })
    if (editorRef.current) {
      editorRef.current.insertMarkdown(markdown)
      const nextValue = editorRef.current.getValue()
      const nextJsonValue = editorRef.current.getJsonValue()
      setCurrentBlog((prev) => (prev ? { ...prev, content: nextValue, contentJson: nextJsonValue } : prev))
    } else if (currentBlog) {
      setCurrentBlog({ ...currentBlog, content: currentBlog.content + markdown })
    }
    setIsInsertingPhoto(false)
    notify(t('admin.notify_photo_inserted'), 'info')
  }

  const handleContentChange = (content: string) => {
    setCurrentBlog((prev) => (prev ? { ...prev, content } : prev))
  }

  const handleJsonContentChange = (contentJson: NonNullable<BlogDto['contentJson']>) => {
    setCurrentBlog((prev) => (prev ? { ...prev, contentJson } : prev))
  }

  const resolvedCdnDomain = settings?.cdn_domain?.trim() || undefined
  const blogDocumentId = resolveBlogDocumentId(currentBlog?.id, draftDocumentId)


  // 博客发布状态筛选选项
  const statusOptions: SelectOption[] = [
    { value: '', label: t('admin.all_status') || '全部状态' },
    { value: 'published', label: t('admin.published') || '已发布' },
    { value: 'draft', label: t('admin.draft') || '草稿' },
  ]

  return (
    <div className="h-full flex flex-col gap-6 overflow-hidden">
      {editMode === 'list' ? (
        <div className="space-y-8 flex-1 flex flex-col overflow-hidden">
          <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
            <div className="flex items-center gap-4">
              <input
                type="text"
                placeholder={t('admin.search_placeholder') || '搜索...'}
                className="px-3 py-2 text-sm bg-transparent border border-border rounded-md focus:border-primary outline-none w-48"
              />
              <AdminSelect
                value={statusFilter}
                options={statusOptions}
                onChange={setStatusFilter}
                placeholder={t('admin.all_status') || '全部状态'}
                className="w-32"
              />
            </div>
            <AdminButton
              onClick={handleCreateBlog}
              adminVariant="primary"
              size="lg"
              className="flex items-center rounded-md"
            >
              <Plus className="w-4 h-4 mr-2" />
              {t('ui.create_blog')}
            </AdminButton>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar">
            {loading ? (
              <div className="p-6"><ListSkeleton count={5} /></div>
            ) : (
              <div className="grid grid-cols-1 gap-4">
              {blogs
                .filter((blog) => {
                  if (!statusFilter) return true
                  if (statusFilter === 'published') return blog.isPublished
                  if (statusFilter === 'draft') return !blog.isPublished
                  return true
                })
                .map((blog) => (
                <div
                  key={blog.id}
                  className="flex items-center justify-between p-6 border border-border hover:border-primary transition-all group"
                >
                  <div
                    className="flex-1 min-w-0"
                    onClick={() => handleEditBlog(blog)}
                    style={{ cursor: 'pointer' }}
                  >
                    <div className="flex items-center gap-3 mb-1">
                      <h4 className="font-serif text-xl group-hover:text-primary transition-colors">
                        {blog.title || t('admin.untitled')}
                      </h4>
                      <span
                        className={`text-[8px] font-black uppercase px-1.5 py-0.5 border ${
                          blog.isPublished
                            ? 'border-primary text-primary'
                            : 'border-muted-foreground text-muted-foreground'
                        }`}
                      >
                        {blog.isPublished ? 'published' : 'draft'}
                      </span>
                    </div>
                    <div className="flex items-center gap-4 text-[10px] text-muted-foreground font-mono uppercase">
                      <span className="flex items-center gap-1">
                        <History className="w-3 h-3" />{' '}
                        {new Date(blog.updatedAt).toLocaleString()}
                      </span>
                      <span className="flex items-center gap-1">
                        <FileText className="w-3 h-3" /> {blog.content.length}{' '}
                        {t('admin.characters')}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <AdminButton
                      onClick={() => handleEditBlog(blog)}
                      adminVariant="iconPrimary"
                    >
                      <Edit3 className="w-4 h-4" />
                    </AdminButton>
                    <AdminButton
                      onClick={() => setDeleteBlogId(blog.id)}
                      adminVariant="iconDestructive"
                    >
                      <Trash2 className="w-4 h-4" />
                    </AdminButton>
                  </div>
                </div>
              ))}
              {blogs.length === 0 && (
                <div className="py-24 text-center border border-dashed border-border">
                  <BookText className="w-12 h-12 mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
                    {t('ui.no_blog')}
                  </p>
                </div>
              )}
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col gap-6 overflow-hidden">
          <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
            <div className="flex items-center gap-4">
              <AdminButton
                onClick={() => {
                  setEditMode('list')
                  setCurrentBlog(null)
                  setLastSavedAt(null)
                  initialBlogRef.current = null
                  setIsDirty(false)
                }}
                disabled={isAiTaskLocked}
                adminVariant="link"
                className="flex items-center gap-2 hover:no-underline"
              >
                <ChevronLeft className="w-4 h-4" /> {t('admin.back_list')}
              </AdminButton>
              {/* 草稿状态指示器 */}
              {draftSaved && (
                <div className="flex items-center gap-1 text-[10px] text-green-500">
                  <Check className="w-3 h-3" />
                  <span>{t('story.draft_saved') || '已保存'}</span>
                </div>
              )}
              {!draftSaved && lastSavedAt && (
                <div className="flex items-center gap-1 text-[10px] text-muted-foreground/60">
                  <Clock className="w-3 h-3" />
                  <span>{formatRelativeTime}</span>
                </div>
              )}
            </div>
            <div className="flex items-center gap-4">
              <label className="flex items-center gap-2 text-xs">
                <input
                  type="checkbox"
                  disabled={isAiTaskLocked}
                  checked={currentBlog?.isPublished || false}
                  onChange={(e) =>
                    setCurrentBlog((prev) => ({
                      ...prev!,
                      isPublished: e.target.checked,
                    }))
                  }
                  className="w-4 h-4"
                />
                <span className="font-bold uppercase tracking-widest">{t('admin.publish')}</span>
              </label>
              <AdminButton
                onClick={handleSaveBlog}
                disabled={saving || isAiTaskLocked}
                adminVariant="primary"
                size="lg"
                className="flex items-center gap-2"
              >
                {saving ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Save className="w-4 h-4" />
                )}
                <span>{t('admin.save')}</span>
              </AdminButton>
            </div>
          </div>
          <div className="flex-1 flex flex-col gap-4 overflow-hidden relative">
            <div className="flex-1 flex flex-col gap-4 overflow-hidden">
              <input
                type="text"
                disabled={isAiTaskLocked}
                value={currentBlog?.title || ''}
                onChange={(e) =>
                  setCurrentBlog((prev) => ({
                    ...prev!,
                    title: e.target.value,
                  }))
                }
                placeholder={t('blog.title_placeholder')}
                className="w-full p-6 bg-transparent border border-border focus:border-primary outline-none text-2xl font-serif rounded-none"
              />
              <div className="flex gap-4">
                <input
                  type="text"
                  disabled={isAiTaskLocked}
                  value={currentBlog?.category || ''}
                  onChange={(e) =>
                    setCurrentBlog((prev) => ({
                      ...prev!,
                      category: e.target.value,
                    }))
                  }
                  placeholder={t('ui.category_filter')}
                  className="flex-1 p-3 bg-transparent border border-border focus:border-primary outline-none text-sm rounded-none"
                />
                <input
                  type="text"
                  disabled={isAiTaskLocked}
                  value={currentBlog?.tags || ''}
                  onChange={(e) =>
                    setCurrentBlog((prev) => ({
                      ...prev!,
                      tags: e.target.value,
                    }))
                  }
                  placeholder="Tags"
                  className="flex-1 p-3 bg-transparent border border-border focus:border-primary outline-none text-sm rounded-none"
                />
              </div>
              <div className="flex-1 relative border border-border bg-card/30 overflow-visible">
                {currentBlog && (
                  <NarrativeTipTapEditor
                    key={blogDocumentId}
                    ref={editorRef}
                    value={currentBlog.content}
                    jsonValue={currentBlog.contentJson ?? null}
                    onChange={handleContentChange}
                    onJsonChange={handleJsonContentChange}
                    placeholder={t('ui.markdown_placeholder')}
                    className="overflow-hidden bg-background"
                    documentId={blogDocumentId}
                    documentKind="blog"
                    onAiTaskLockChange={setIsAiTaskLocked}
                    aiOptions={token ? {
                      enabled: true,
                      token,
                      scopeId: blogDocumentId,
                      title: currentBlog.title,
                    } : undefined}
                  />
                )}
                <AdminButton
                  onClick={() => setIsInsertingPhoto(true)}
                  disabled={isAiTaskLocked}
                  adminVariant="unstyled"
                  className="absolute bottom-6 right-6 p-4 bg-background border border-border hover:border-primary text-primary transition-all shadow-2xl z-10"
                  title={t('blog.insert_photo')}
                >
                  <ImageIcon className="w-6 h-6" />
                </AdminButton>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* 插入照片弹窗 */}
      {isInsertingPhoto && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 md:p-12 bg-background/95 backdrop-blur-sm">
          <div className="w-full h-full max-w-6xl bg-background border border-border flex flex-col overflow-hidden shadow-2xl">
            <div className="p-6 border-b border-border flex items-center justify-between">
              <h3 className="font-serif text-2xl uppercase tracking-tight">
                {t('blog.insert_photo')}
              </h3>
              <AdminButton
                onClick={() => setIsInsertingPhoto(false)}
                adminVariant="icon"
              >
                <X className="w-6 h-6" />
              </AdminButton>
            </div>
            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
              <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-4">
                {photos.map((photo) => (
                  <div
                    key={photo.id}
                    onClick={() => insertPhotoIntoBlog(photo)}
                    className="group relative aspect-square bg-muted cursor-pointer overflow-hidden border border-transparent hover:border-primary transition-all"
                  >
                    <img
                      src={resolveAssetUrl(
                        photo.thumbnailUrl || photo.url,
                        resolvedCdnDomain
                      )}
                      alt=""
                      className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all"
                    />
                    <div className="absolute inset-0 bg-primary/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Plus className="w-8 h-8 text-white" />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      <SimpleDeleteDialog isOpen={!!deleteBlogId} onConfirm={confirmDeleteBlog} onCancel={() => setDeleteBlogId(null)} t={t} />
      <DraftRestoreDialog
        isOpen={draftRestoreDialog.isOpen}
        draftTime={draftRestoreDialog.draft?.savedAt || 0}
        onRestore={handleDraftRestore}
        onDiscard={handleDraftDiscard}
        onCancel={handleDraftCancel}
        t={t}
      />
    </div>
  )
}

/**
 * 日志管理页面 - 聚合博客、故事和草稿管理的入口页
 */
'use client'

import React, { useState, useEffect, useMemo, useRef } from 'react'
import { useSearchParams } from 'next/navigation'
import { BookText, BookOpen, FileArchive, Clock, Trash2, Eye, X, Image as ImageIcon, Edit3, ArrowRight } from 'lucide-react'
import { useAdmin } from '../layout'
import { BlogTab } from './BlogTab'
import { StoriesTab } from './StoriesTab'
import {
  getAllDraftsFromDB,
  clearDraftFromDB,
  clearBlogDraftFromDB,
  clearStoryEditorDraftFromDB,
  clearAllDraftsFromDB,
  type StoryDraftData,
  type BlogDraftData,
  type StoryEditorDraftData
} from '@/lib/client-db'
import { motion, AnimatePresence } from 'framer-motion'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'
import { AdminButton } from '@/components/admin/AdminButton'
import { AdminSelect, type SelectOption } from '@/components/admin/AdminFormControls'
import { countStoryCharacters } from '@/lib/story-rich-content'
import { formatRelativeTimeLabel } from '@/lib/utils'

// 扩展类型：为故事草稿文件添加预览 URL
interface StoryDraftWithPreviews extends Omit<StoryDraftData, 'files'> {
  files: { id: string; file: File; preview: string }[]
}

export default function LogsPage() {
  const searchParams = useSearchParams()
  const editStoryId = searchParams.get('editStory')
  const {
    token,
    photos,
    settings,
    t,
    notify,
    isImmersiveMode,
  } = useAdmin()

  // 当前激活的子标签页（默认为故事标签）
  const [activeSubTab, setActiveSubTab] = useState<'blog' | 'stories' | 'drafts'>('stories')

  // 草稿状态管理 - 使用带预览 URL 的扩展类型
  const [storyDraft, setStoryDraft] = useState<StoryDraftWithPreviews | null>(null) // 故事上传草稿（只读）
  const [blogDrafts, setBlogDrafts] = useState<BlogDraftData[]>([]) // 博客草稿列表
  const [storyEditorDrafts, setStoryEditorDrafts] = useState<StoryEditorDraftData[]>([]) // 故事编辑器草稿列表
  const [loadingDrafts, setLoadingDrafts] = useState(false) // 草稿加载状态
  const [selectedDraft, setSelectedDraft] = useState<StoryDraftWithPreviews | BlogDraftData | StoryEditorDraftData | null>(null) // 当前预览的草稿

  // 从草稿恢复编辑的状态
  const [editFromDraft, setEditFromDraft] = useState<StoryEditorDraftData | null>(null)

  // 删除确认对话框状态
  const [deleteDialog, setDeleteDialog] = useState<{
    isOpen: boolean
    type: 'story' | 'blog' | 'storyEditor' | 'all'
    id?: string
  }>({ isOpen: false, type: 'story' })

  // 保存预览 URL 引用，用于组件卸载时清理，防止内存泄漏
  const previewUrlsRef = useRef<string[]>([])

  // 双击刷新功能：记录上次点击的标签页和时间
  const lastClickRef = useRef<{ tab: string; time: number }>({ tab: '', time: 0 })
  const [storiesRefreshKey, setStoriesRefreshKey] = useState(0) // 故事标签页刷新键
  const [blogRefreshKey, setBlogRefreshKey] = useState(0) // 博客标签页刷新键
  const [isStoriesEditing, setIsStoriesEditing] = useState(false)

  // 草稿筛选状态
  const [draftTypeFilter, setDraftTypeFilter] = useState('') // 类型筛选（story/blog/all）
  const [draftSearchQuery, setDraftSearchQuery] = useState('') // 搜索关键词

  // 切换到草稿标签时重新加载草稿
  useEffect(() => {
    if (activeSubTab === 'drafts') {
      loadDrafts()
    }
  }, [activeSubTab])

  // 组件卸载时清理预览 URL，防止内存泄漏
  useEffect(() => {
    return () => {
      previewUrlsRef.current.forEach(url => URL.revokeObjectURL(url))
    }
  }, [])

  /**
   * 从 IndexedDB 加载所有草稿数据
   * 包括故事上传草稿、博客草稿和故事编辑器草稿
   */
  async function loadDrafts() {
    setLoadingDrafts(true)

    // 清理旧的预览 URL，避免内存泄漏
    previewUrlsRef.current.forEach(url => URL.revokeObjectURL(url))
    previewUrlsRef.current = []

    try {
      const { storyDraft: rawStoryDraft, blogDrafts, storyEditorDrafts } = await getAllDraftsFromDB()

      // 处理故事草稿：为文件生成预览 URL
      if (rawStoryDraft && rawStoryDraft.files && rawStoryDraft.files.length > 0) {
        const filesWithPreviews = rawStoryDraft.files.map(f => {
          let preview = ''
          if (f.file instanceof File) {
            try {
              preview = URL.createObjectURL(f.file)
              previewUrlsRef.current.push(preview)
            } catch (e) {
              console.error('Failed to create object URL:', e)
            }
          }
          return { id: f.id, file: f.file, preview }
        })

        setStoryDraft({
          ...rawStoryDraft,
          files: filesWithPreviews
        })
      } else if (rawStoryDraft) {
        setStoryDraft({
          ...rawStoryDraft,
          files: []
        })
      } else {
        setStoryDraft(null)
      }

      setBlogDrafts(blogDrafts)
      setStoryEditorDrafts(storyEditorDrafts)
    } catch (err) {
      console.error('Failed to load drafts:', err)
      notify(t('common.error'), 'error')
    } finally {
      setLoadingDrafts(false)
    }
  }

  /**
   * 确认删除草稿
   * 根据类型删除对应的草稿数据
   */
  async function confirmDelete() {
    try {
      if (deleteDialog.type === 'all') {
        // 删除所有草稿
        await clearAllDraftsFromDB()
        setStoryDraft(null)
        setBlogDrafts([])
        setStoryEditorDrafts([])
      } else if (deleteDialog.type === 'story') {
        // 删除故事上传草稿
        await clearDraftFromDB()
        setStoryDraft(null)
      } else if (deleteDialog.type === 'blog') {
        // 删除指定博客草稿
        await clearBlogDraftFromDB(deleteDialog.id)
        setBlogDrafts(prev => prev.filter(d => d.blogId !== deleteDialog.id))
      } else if (deleteDialog.type === 'storyEditor') {
        // 删除指定故事编辑器草稿
        await clearStoryEditorDraftFromDB(deleteDialog.id)
        setStoryEditorDrafts(prev => prev.filter(d => d.id !== deleteDialog.id))
      }
      notify(t('admin.draft_deleted'))
    } catch (err) {
      console.error('Failed to delete draft:', err)
      notify(t('common.error'), 'error')
    } finally {
      setDeleteDialog({ isOpen: false, type: 'story' })
    }
  }

  /**
   * 从草稿恢复并编辑故事
   * 将草稿数据传递给故事编辑器
   */
  function handleEditStoryFromDraft(draft: StoryEditorDraftData) {
    setEditFromDraft(draft)
    setActiveSubTab('stories')
  }

  // 格式化相对时间显示
  function formatRelativeTime(timestamp: number): string {
    return formatRelativeTimeLabel(timestamp, t, 'datetime')
  }

  // 计算草稿总数（用于显示徽章）
  const totalDrafts = useMemo(() => {
    let count = blogDrafts.length + storyEditorDrafts.length
    if (storyDraft) count++
    return count
  }, [storyDraft, blogDrafts, storyEditorDrafts])

  // 草稿类型筛选选项
  const draftTypeOptions: SelectOption[] = useMemo(() => [
    { value: '', label: t('admin.all_types') },
    { value: 'story', label: t('nav.story') },
    { value: 'blog', label: t('admin.blog') },
  ], [t])

  // 根据类型和搜索关键词筛选故事上传草稿
  const filteredStoryDraft = useMemo(() => {
    if (draftTypeFilter === 'blog') return null
    if (!storyDraft) return null
    if (draftSearchQuery) {
      const query = draftSearchQuery.toLowerCase()
      if (!storyDraft.title?.toLowerCase().includes(query) && !storyDraft.content?.toLowerCase().includes(query)) {
        return null
      }
    }
    return storyDraft
  }, [storyDraft, draftTypeFilter, draftSearchQuery])

  // 根据类型和搜索关键词筛选故事编辑器草稿
  const filteredStoryEditorDrafts = useMemo(() => {
    if (draftTypeFilter === 'blog') return []
    if (!draftSearchQuery) return storyEditorDrafts
    const query = draftSearchQuery.toLowerCase()
    return storyEditorDrafts.filter(d =>
      d.title?.toLowerCase().includes(query) || d.content?.toLowerCase().includes(query)
    )
  }, [storyEditorDrafts, draftTypeFilter, draftSearchQuery])

  // 根据类型和搜索关键词筛选博客草稿
  const filteredBlogDrafts = useMemo(() => {
    if (draftTypeFilter === 'story') return []
    if (!draftSearchQuery) return blogDrafts
    const query = draftSearchQuery.toLowerCase()
    return blogDrafts.filter(d =>
      d.title?.toLowerCase().includes(query) || d.content?.toLowerCase().includes(query)
    )
  }, [blogDrafts, draftTypeFilter, draftSearchQuery])

  /**
   * 标签页点击处理：支持双击刷新
   * 单击切换标签页，双击（300ms内）刷新当前标签页内容
   */
  function handleTabClick(tab: 'blog' | 'stories' | 'drafts') {
    const now = Date.now()
    if (lastClickRef.current.tab === tab && now - lastClickRef.current.time < 300) {
      // 双击 - 刷新对应标签页
      if (tab === 'drafts') {
        loadDrafts()
      } else if (tab === 'stories') {
        setStoriesRefreshKey(k => k + 1)
      } else if (tab === 'blog') {
        setBlogRefreshKey(k => k + 1)
      }
    }
    lastClickRef.current = { tab, time: now }
    setActiveSubTab(tab)
  }

  return (
    <div className="h-full flex flex-col">
      {/* 子标签页导航 */}
      <div className={`${(isStoriesEditing && activeSubTab === 'stories') || isImmersiveMode ? 'hidden' : 'flex'} space-x-1 border-b border-border px-8 flex-shrink-0`}>
        <AdminButton
          onClick={() => handleTabClick('stories')}
          adminVariant="tab"
          data-state={activeSubTab === 'stories' ? 'active' : 'inactive'}
          className="flex items-center gap-2 px-6 py-4 text-xs font-bold uppercase tracking-[0.2em]"
          title={t('admin.double_click_refresh')}
        >
          <BookOpen className="w-4 h-4" />
          {t('nav.story')}
        </AdminButton>
        <AdminButton
          onClick={() => handleTabClick('blog')}
          adminVariant="tab"
          data-state={activeSubTab === 'blog' ? 'active' : 'inactive'}
          className="flex items-center gap-2 px-6 py-4 text-xs font-bold uppercase tracking-[0.2em]"
          title={t('admin.double_click_refresh')}
        >
          <BookText className="w-4 h-4" />
          {t('admin.blog')}
        </AdminButton>
        <AdminButton
          onClick={() => handleTabClick('drafts')}
          adminVariant="tab"
          data-state={activeSubTab === 'drafts' ? 'active' : 'inactive'}
          className="flex items-center gap-2 px-6 py-4 text-xs font-bold uppercase tracking-[0.2em]"
          title={t('admin.double_click_refresh')}
        >
          <FileArchive className="w-4 h-4" />
          {t('admin.drafts')}
          {totalDrafts > 0 && (
            <span className="ml-1 px-1.5 py-0.5 text-[10px] bg-primary/10 text-primary rounded-full">
              {totalDrafts}
            </span>
          )}
        </AdminButton>
      </div>

      {/* 子标签页内容 */}
      <div className={`flex-1 overflow-hidden ${isImmersiveMode ? 'pt-0' : isStoriesEditing && activeSubTab === 'stories' ? 'pt-0' : 'px-8 pb-8 pt-6'}`}>
        <div className={activeSubTab === 'blog' ? 'h-full' : 'hidden'}>
          <BlogTab
            photos={photos}
            settings={settings}
            t={t}
            notify={notify}
            refreshKey={blogRefreshKey}
          />
        </div>
        <div className={activeSubTab === 'stories' ? 'h-full' : 'hidden'}>
          <StoriesTab
            token={token}
            t={t}
            notify={notify}
            editStoryId={editStoryId || undefined}
            editFromDraft={editFromDraft}
            onDraftConsumed={() => setEditFromDraft(null)}
            refreshKey={storiesRefreshKey}
            onEditingChange={setIsStoriesEditing}
          />
        </div>
        {activeSubTab === 'drafts' ? (
          <div className="h-full flex flex-col gap-6 overflow-hidden">
            <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
              <div className="flex items-center gap-4">
                <input
                  type="text"
                  value={draftSearchQuery}
                  onChange={(e) => setDraftSearchQuery(e.target.value)}
                  placeholder={t('admin.search_placeholder')}
                  className="px-3 py-2 text-sm bg-transparent border border-border rounded-md focus:border-primary outline-none w-48"
                />
                <AdminSelect
                  value={draftTypeFilter}
                  options={draftTypeOptions}
                  onChange={setDraftTypeFilter}
                  placeholder={t('admin.all_types')}
                  className="w-32"
                />
              </div>
              <div className="flex items-center gap-2">
                {totalDrafts > 0 && (
                  <AdminButton
                    onClick={() => setDeleteDialog({ isOpen: true, type: 'all' })}
                    adminVariant="destructiveOutline"
                    size="sm"
                    className="gap-2 rounded-md"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                    {t('admin.delete_all')}
                  </AdminButton>
                )}
                <AdminButton
                  onClick={loadDrafts}
                  adminVariant="outline"
                  size="sm"
                  className="rounded-md"
                >
                  {t('common.refresh')}
                </AdminButton>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto custom-scrollbar space-y-6">
              {loadingDrafts ? (
                <div className="flex items-center justify-center py-20">
                  <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                </div>
              ) : (
                <>
                  {/* 故事上传草稿区 */}
                  {filteredStoryDraft && (
                    <div className="space-y-3">
                      <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-muted-foreground">
                        <BookOpen className="w-3.5 h-3.5" />
                        <span>{t('admin.story_draft')}</span>
                        <span className="text-[10px] px-1.5 py-0.5 bg-amber-500/10 text-amber-600 rounded">
                          {t('admin.read_only')}
                        </span>
                      </div>
                      <div className="p-5 border border-border hover:border-primary/50 transition-colors rounded-lg group">
                        <div className="flex items-start justify-between">
                          <div className="flex-1 min-w-0">
                            <h4 className="font-serif text-xl mb-1">
                              {filteredStoryDraft.title || t('story.untitled')}
                            </h4>
                            <p className="text-sm text-muted-foreground line-clamp-2 mb-3">
                              {filteredStoryDraft.content?.substring(0, 150) || t('admin.no_content')}
                              {filteredStoryDraft.content?.length > 150 ? '...' : ''}
                            </p>
                            <div className="flex items-center gap-4 text-[10px] text-muted-foreground font-mono uppercase">
                              <span className="flex items-center gap-1">
                                <Clock className="w-3 h-3" />
                                {formatRelativeTime(filteredStoryDraft.savedAt)}
                              </span>
                              {filteredStoryDraft.files && filteredStoryDraft.files.length > 0 && (
                                <span>{filteredStoryDraft.files.length} {t('admin.photos')}</span>
                              )}
                              {filteredStoryDraft.selectedAlbumIds && filteredStoryDraft.selectedAlbumIds.length > 0 && (
                                <span>{filteredStoryDraft.selectedAlbumIds.length} {t('admin.albums')}</span>
                              )}
                            </div>
                          </div>
                          <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                            <AdminButton
                              onClick={() => setSelectedDraft(filteredStoryDraft)}
                              adminVariant="icon"
                              size="xs"
                              className="p-2 rounded-md"
                              title={t('common.view')}
                            >
                              <Eye className="w-4 h-4" />
                            </AdminButton>
                            <AdminButton
                              onClick={() => setDeleteDialog({ isOpen: true, type: 'story' })}
                              adminVariant="iconDestructive"
                              size="xs"
                              className="p-2 rounded-md"
                              title={t('common.delete')}
                            >
                              <Trash2 className="w-4 h-4" />
                            </AdminButton>
                          </div>
                        </div>
                      </div>
                    </div>
                  )}

                  {/* 故事编辑器草稿区 */}
                  {filteredStoryEditorDrafts.length > 0 && (
                    <div className="space-y-3">
                      <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-muted-foreground">
                        <Edit3 className="w-3.5 h-3.5" />
                        <span>{t('admin.story_editor_drafts')}</span>
                        <span className="text-muted-foreground/50">({filteredStoryEditorDrafts.length})</span>
                      </div>
                      <div className="space-y-3">
                        {filteredStoryEditorDrafts.map((draft) => (
                          <div
                            key={draft.id}
                            className="p-5 border border-border hover:border-primary/50 transition-colors rounded-lg group"
                          >
                            <div className="flex items-start justify-between">
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 mb-1">
                                    <h4 className="font-serif text-xl">
                                      {draft.title || t('story.untitled')}
                                    </h4>
                                    {draft.storyId ? (
                                      <span className="text-[8px] font-black uppercase px-1.5 py-0.5 border border-muted-foreground text-muted-foreground rounded">
                                        {t('common.edit')}
                                      </span>
                                    ) : (
                                      <span className="text-[8px] font-black uppercase px-1.5 py-0.5 border border-primary text-primary rounded">
                                        {t('admin.new')}
                                      </span>
                                    )}
                                  </div>
                                  <p className="text-sm text-muted-foreground line-clamp-2 mb-3">
                                    {draft.content?.substring(0, 150) || t('admin.no_content')}
                                    {draft.content?.length > 150 ? '...' : ''}
                                  </p>
                                  <div className="flex items-center gap-4 text-[10px] text-muted-foreground font-mono uppercase">
                                    <span className="flex items-center gap-1">
                                      <Clock className="w-3 h-3" />
                                      {formatRelativeTime(draft.savedAt)}
                                    </span>
                                    {draft.content && (
                                      <span>{countStoryCharacters(draft.content)} {t('admin.characters')}</span>
                                    )}
                                    {draft.photoIds?.length > 0 && (
                                      <span>{draft.photoIds.length} {t('admin.photos')}</span>
                                    )}
                                  </div>
                                </div>
                                <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                  <AdminButton
                                    onClick={() => handleEditStoryFromDraft(draft)}
                                    adminVariant="icon"
                                    size="xs"
                                    className="p-2 rounded-md flex items-center gap-1"
                                    title={t('common.edit')}
                                  >
                                    <ArrowRight className="w-4 h-4" />
                                  </AdminButton>
                                  <AdminButton
                                    onClick={() => setSelectedDraft(draft)}
                                    adminVariant="icon"
                                    size="xs"
                                    className="p-2 rounded-md"
                                    title={t('common.view')}
                                  >
                                    <Eye className="w-4 h-4" />
                                  </AdminButton>
                                  <AdminButton
                                    onClick={() => setDeleteDialog({ isOpen: true, type: 'storyEditor', id: draft.id })}
                                    adminVariant="iconDestructive"
                                    size="xs"
                                    className="p-2 rounded-md"
                                    title={t('common.delete')}
                                  >
                                    <Trash2 className="w-4 h-4" />
                                  </AdminButton>
                                </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* 博客草稿区 */}
                  {filteredBlogDrafts.length > 0 && (
                    <div className="space-y-3">
                      <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-muted-foreground">
                        <BookText className="w-3.5 h-3.5" />
                        <span>{t('admin.blog_drafts')}</span>
                        <span className="text-muted-foreground/50">({filteredBlogDrafts.length})</span>
                      </div>
                      <div className="space-y-3">
                        {filteredBlogDrafts.map((draft) => (
                          <div
                            key={draft.id}
                            className="p-5 border border-border hover:border-primary/50 transition-colors rounded-lg group"
                          >
                            <div className="flex items-start justify-between">
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 mb-1">
                                  <h4 className="font-serif text-xl">
                                    {draft.title || t('admin.untitled')}
                                  </h4>
                                  {draft.blogId ? (
                                    <span className="text-[8px] font-black uppercase px-1.5 py-0.5 border border-muted-foreground text-muted-foreground rounded">
                                      {t('common.edit')}
                                    </span>
                                  ) : (
                                    <span className="text-[8px] font-black uppercase px-1.5 py-0.5 border border-primary text-primary rounded">
                                      {t('admin.new')}
                                    </span>
                                  )}
                                </div>
                                <p className="text-sm text-muted-foreground line-clamp-2 mb-3">
                                  {draft.content?.substring(0, 150) || t('admin.no_content')}
                                  {draft.content?.length > 150 ? '...' : ''}
                                </p>
                                <div className="flex items-center gap-4 text-[10px] text-muted-foreground font-mono uppercase">
                                  <span className="flex items-center gap-1">
                                    <Clock className="w-3 h-3" />
                                    {formatRelativeTime(draft.savedAt)}
                                  </span>
                                  {draft.category && (
                                    <span>{draft.category}</span>
                                  )}
                                  {draft.content && (
                                    <span>{draft.content.length} {t('admin.characters')}</span>
                                  )}
                                </div>
                              </div>
                              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                <AdminButton
                                  onClick={() => setSelectedDraft(draft)}
                                  adminVariant="icon"
                                  size="xs"
                                  className="p-2 rounded-md"
                                  title={t('common.view')}
                                >
                                  <Eye className="w-4 h-4" />
                                </AdminButton>
                                <AdminButton
                                  onClick={() => setDeleteDialog({ isOpen: true, type: 'blog', id: draft.blogId })}
                                  adminVariant="iconDestructive"
                                  size="xs"
                                  className="p-2 rounded-md"
                                  title={t('common.delete')}
                                >
                                  <Trash2 className="w-4 h-4" />
                                </AdminButton>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* 空状态提示 */}
                  {!filteredStoryDraft && filteredBlogDrafts.length === 0 && filteredStoryEditorDrafts.length === 0 && (
                    <div className="py-24 text-center border border-dashed border-border rounded-lg">
                      <FileArchive className="w-12 h-12 mx-auto mb-4 opacity-10" />
                      <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground mb-2">
                        {t('admin.no_drafts')}
                      </p>
                      <p className="text-xs text-muted-foreground/60 max-w-sm mx-auto">
                        {t('admin.drafts_hint')}
                      </p>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>
        ) : null}
      </div>

      {/* 草稿预览弹窗 */}
      <AnimatePresence>
        {selectedDraft && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-background/95 backdrop-blur-sm flex items-center justify-center p-4 md:p-12"
            onClick={() => setSelectedDraft(null)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="w-full max-w-3xl max-h-[80vh] bg-background border border-border shadow-2xl flex flex-col overflow-hidden rounded-lg"
            >
              {/* 弹窗头部 */}
              <div className="flex items-center justify-between p-6 border-b border-border">
                <div>
                  <h3 className="font-serif text-2xl">
                    {selectedDraft.title || t('admin.untitled')}
                  </h3>
                  <div className="flex items-center gap-3 mt-1 text-[10px] text-muted-foreground font-mono uppercase">
                    <span className="flex items-center gap-1">
                      <Clock className="w-3 h-3" />
                      {formatRelativeTime(selectedDraft.savedAt)}
                    </span>
                    {'blogId' in selectedDraft ? (
                      <span className="flex items-center gap-1">
                        <BookText className="w-3 h-3" />
                        {t('admin.blog')}
                      </span>
                    ) : (
                      <span className="flex items-center gap-1">
                        <BookOpen className="w-3 h-3" />
                        {t('nav.story')}
                      </span>
                    )}
                  </div>
                </div>
                <AdminButton
                  onClick={() => setSelectedDraft(null)}
                  adminVariant="icon"
                  size="sm"
                  className="p-2 rounded-md"
                >
                  <X className="w-5 h-5" />
                </AdminButton>
              </div>

              {/* 弹窗内容 */}
              <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
                <div className="prose prose-sm dark:prose-invert max-w-none">
                  <pre className="whitespace-pre-wrap font-mono text-sm bg-muted/30 p-4 rounded-lg overflow-x-auto">
                    {selectedDraft.content || t('admin.no_content')}
                  </pre>
                </div>

                {/* 博客草稿元信息 */}
                {'category' in selectedDraft && (
                  <div className="mt-6 pt-6 border-t border-border">
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">{t('ui.category_filter')}</span>
                        <p className="mt-1">{(selectedDraft as BlogDraftData).category || '-'}</p>
                      </div>
                      <div>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Tags</span>
                        <p className="mt-1">{(selectedDraft as BlogDraftData).tags || '-'}</p>
                      </div>
                    </div>
                  </div>
                )}

                {/* 故事草稿元信息 */}
                {'files' in selectedDraft && (selectedDraft as StoryDraftWithPreviews).files?.length > 0 && (
                  <div className="mt-6 pt-6 border-t border-border">
                    <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
                      {t('admin.pending_files')} ({(selectedDraft as StoryDraftWithPreviews).files.length})
                    </span>
                    <div className="mt-3 grid grid-cols-4 gap-2">
                      {(selectedDraft as StoryDraftWithPreviews).files.slice(0, 8).map((f, i) => (
                        <div key={f.id || i} className="aspect-square bg-muted rounded-md overflow-hidden">
                          {f.preview ? (
                            <img
                              src={f.preview}
                              alt={f.file?.name || `${t('admin.files')} ${i + 1}`}
                              className="w-full h-full object-cover"
                            />
                          ) : (
                            <div className="w-full h-full flex flex-col items-center justify-center text-muted-foreground gap-1">
                              <ImageIcon className="w-4 h-4 opacity-30" />
                              <span className="text-[10px] truncate max-w-full px-1">
                                {f.file?.name?.substring(0, 10) || `${t('admin.files')} ${i + 1}`}
                              </span>
                            </div>
                          )}
                        </div>
                      ))}
                      {(selectedDraft as StoryDraftWithPreviews).files.length > 8 && (
                        <div className="aspect-square bg-muted rounded-md flex items-center justify-center text-muted-foreground text-xs">
                          +{(selectedDraft as StoryDraftWithPreviews).files.length - 8}
                        </div>
                      )}
                    </div>
                  </div>
                )}
              </div>

              {/* 弹窗底部 */}
              <div className="p-4 border-t border-border bg-muted/20">
                <p className="text-[10px] text-muted-foreground text-center">
                  {t('admin.draft_preview_hint')}
                </p>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <SimpleDeleteDialog
        isOpen={deleteDialog.isOpen}
        message={deleteDialog.type === 'all' ? t('admin.confirm_delete_all_drafts') : undefined}
        onConfirm={confirmDelete}
        onCancel={() => setDeleteDialog({ isOpen: false, type: 'story' })}
        t={t}
      />
    </div>
  )
}

'use client'

import { useMemo, useState } from 'react'
import {
  BookOpen,
  Calendar,
  Edit3,
  Eye,
  EyeOff,
  FileText,
  History,
  Image as ImageIcon,
  Plus,
  RefreshCw,
  Trash2,
  X,
} from 'lucide-react'
import type { SelectOption } from '@/components/admin/AdminFormControls'
import { AdminSelect } from '@/components/admin/AdminFormControls'
import { AdminButton } from '@/components/admin/AdminButton'
import { ListSkeleton } from '@/components/admin/Skeleton'
import type { StoryDto } from '@/lib/api/types'
import { resolveAssetUrl } from '@/lib/api/core'
import { countStoryCharacters } from '@/lib/story-rich-content'

interface StoryListViewProps {
  stories: StoryDto[]
  loading: boolean
  statusFilter: string
  onStatusFilterChange: (value: string) => void
  onCreateStory: () => void
  onEditStory: (story: StoryDto) => void
  onTogglePublish: (story: StoryDto) => void
  onRequestDelete: (storyId: string) => void
  t: (key: string) => string
  cdnDomain?: string
  onRefresh?: () => void
}

export function StoryListView({
  stories,
  loading,
  statusFilter,
  onStatusFilterChange,
  onCreateStory,
  onEditStory,
  onTogglePublish,
  onRequestDelete,
  t,
  cdnDomain,
  onRefresh,
}: StoryListViewProps) {
  const [searchQuery, setSearchQuery] = useState('')

  const statusOptions: SelectOption[] = [
    { value: '', label: t('admin.all_status') },
    { value: 'published', label: t('admin.published') },
    { value: 'draft', label: t('admin.draft') },
  ]

  const filteredStories = useMemo(() => {
    const normalizedSearch = searchQuery.trim().toLowerCase()

    return stories.filter((story) => {
      const matchesStatus = (() => {
        if (!statusFilter) return true
        if (statusFilter === 'published') return story.isPublished
        if (statusFilter === 'draft') return !story.isPublished
        return true
      })()

      const matchesSearch =
        !normalizedSearch ||
        (story.title || '').toLowerCase().includes(normalizedSearch)

      return matchesStatus && matchesSearch
    })
  }, [stories, statusFilter, searchQuery])

  const hasActiveFilters = !!statusFilter || !!searchQuery.trim()

  return (
    <div className="flex flex-1 flex-col space-y-8 overflow-hidden">
      <div className="flex shrink-0 items-center justify-between border-b border-border pb-4">
        <div className="flex min-w-0 flex-1 items-center gap-3">
          <input
            type="text"
            placeholder={t('admin.search_placeholder')}
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            className="w-48 border border-border bg-background px-3 py-2 text-sm outline-none transition-all focus:border-primary focus:ring-1 focus:ring-primary"
          />
          <AdminSelect
            value={statusFilter}
            options={statusOptions}
            onChange={onStatusFilterChange}
            placeholder={t('admin.all_status')}
            className="w-32"
          />
        </div>
        <div className="flex items-center gap-2">
          {onRefresh && (
            <AdminButton
              onClick={onRefresh}
              adminVariant="outline"
              size="lg"
              className="flex items-center"
              title={t('common.refresh')}
            >
              <RefreshCw className="h-4 w-4" />
            </AdminButton>
          )}
          <AdminButton onClick={onCreateStory} adminVariant="primary" size="lg" className="flex items-center">
            <Plus className="mr-2 h-4 w-4" />
            {t('ui.create_story')}
          </AdminButton>
        </div>
      </div>

      <div className="custom-scrollbar flex-1 overflow-y-auto">
        {loading ? (
          <div className="p-6"><ListSkeleton count={5} /></div>
        ) : (
          <div className="grid grid-cols-1 gap-4">
            {filteredStories.map((story) => (
              <div
                key={story.id}
                className="group flex items-center gap-5 border border-border bg-card px-5 py-5 transition-colors hover:border-primary/50 sm:gap-6"
              >
                {(() => {
                  const coverPhoto = story.coverPhotoId
                    ? story.photos.find(p => p.id === story.coverPhotoId) || story.photos[0]
                    : story.photos[0]
                  return coverPhoto ? (
                    <div
                      className="hidden h-16 w-24 flex-shrink-0 cursor-pointer overflow-hidden border border-border/70 bg-muted sm:block"
                      onClick={() => onEditStory(story)}
                    >
                      <img
                        src={resolveAssetUrl(coverPhoto.thumbnailUrl || coverPhoto.url, cdnDomain)}
                        alt=""
                        className="w-full h-full object-cover"
                        loading="lazy"
                      />
                    </div>
                  ) : null
                })()}
                <div className="min-w-0 flex-1 cursor-pointer pr-1 sm:pr-2" onClick={() => onEditStory(story)}>
                  <div className="mb-2 flex items-center gap-3">
                    <h4 className="truncate text-lg font-semibold transition-colors group-hover:text-primary">
                      {story.title || t('story.untitled')}
                    </h4>
                    <span
                      className={`shrink-0 border px-2 py-0.5 text-[10px] font-bold uppercase ${
                        story.isPublished
                          ? 'border-green-500/30 bg-green-500/10 text-green-600 dark:text-green-400'
                          : 'border-slate-500/30 bg-slate-500/10 text-slate-600 dark:text-slate-400'
                      }`}
                    >
                      {story.isPublished ? 'PUBLISHED' : 'DRAFT'}
                    </span>
                  </div>
                  <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1.5" title="Created At">
                      <Calendar className="h-3.5 w-3.5" />
                      {new Date(story.createdAt).toLocaleDateString()}
                    </span>
                    <span className="flex items-center gap-1.5" title="Updated At">
                      <History className="h-3.5 w-3.5" />
                      {new Date(story.updatedAt).toLocaleString()}
                    </span>
                    <span className="flex items-center gap-1.5" title="Word Count">
                      <FileText className="h-3.5 w-3.5" />
                      {countStoryCharacters(story.content)} {t('admin.characters')}
                    </span>
                    {story.photos && story.photos.length > 0 ? (
                      <span className="flex items-center gap-1.5" title="Photos">
                        <ImageIcon className="h-3.5 w-3.5" />
                        {story.photos.length} {t('ui.photos_count')}
                      </span>
                    ) : null}
                  </div>
                </div>

                <div className="ml-auto flex shrink-0 items-center gap-1.5 opacity-100 transition-opacity duration-200 sm:gap-2 sm:pl-2 sm:opacity-0 sm:group-hover:opacity-100">
                  <AdminButton
                    onClick={(event) => {
                      event.stopPropagation()
                      onTogglePublish(story)
                    }}
                    adminVariant="iconPrimary"
                    title={story.isPublished ? t('story.unpublish') : t('story.publish')}
                  >
                    {story.isPublished ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </AdminButton>
                  <AdminButton
                    onClick={(event) => {
                      event.stopPropagation()
                      onEditStory(story)
                    }}
                    adminVariant="iconPrimary"
                  >
                    <Edit3 className="h-4 w-4" />
                  </AdminButton>
                  <AdminButton
                    onClick={(event) => {
                      event.stopPropagation()
                      onRequestDelete(story.id)
                    }}
                    adminVariant="iconDestructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </AdminButton>
                </div>
              </div>
            ))}

            {stories.length === 0 ? (
              <div className="flex flex-col items-center justify-center border border-dashed border-border bg-card/50 px-4 py-20 text-center">
                <div className="mb-4 flex h-16 w-16 items-center justify-center border border-border bg-muted">
                  <BookOpen className="h-8 w-8 text-muted-foreground/50" />
                </div>
                <h3 className="mb-1 text-sm font-semibold text-foreground">{t('ui.no_story')}</h3>
              </div>
            ) : filteredStories.length === 0 ? (
              <div className="flex flex-col items-center justify-center border border-dashed border-border bg-card/50 px-4 py-20 text-center">
                <div className="mb-4 flex h-16 w-16 items-center justify-center border border-border bg-muted">
                  <BookOpen className="h-8 w-8 text-muted-foreground/50" />
                </div>
                <h3 className="mb-2 text-sm font-semibold text-foreground">
                  {t('common.search')}
                </h3>
                <p className="mb-4 text-xs text-muted-foreground">
                  {t('admin.no_albums_match_filters') || 'No stories match the current filters'}
                </p>
                {hasActiveFilters && (
                  <div className="flex items-center gap-2">
                    {!!searchQuery.trim() && (
                      <AdminButton
                        onClick={() => setSearchQuery('')}
                        adminVariant="outline"
                        size="sm"
                        className="flex items-center gap-1.5"
                      >
                        <X className="h-3.5 w-3.5" />
                        {t('common.search')}
                      </AdminButton>
                    )}
                    {!!statusFilter && (
                      <AdminButton
                        onClick={() => onStatusFilterChange('')}
                        adminVariant="outline"
                        size="sm"
                        className="flex items-center gap-1.5"
                      >
                        <X className="h-3.5 w-3.5" />
                        {t('admin.filter') || 'Filter'}
                      </AdminButton>
                    )}
                  </div>
                )}
              </div>
            ) : null}
          </div>
        )}
      </div>
    </div>
  )
}

'use client'

import { useCallback, useRef, useState } from 'react'
import type { Dispatch, MutableRefObject, SetStateAction } from 'react'
import type { DragEvent } from 'react'
import ExifReader from 'exifreader'
import { compressImage, extractExifToJson, stripGpsFromExifJson } from '@/lib/image-compress'
import { calculateFileHash } from '@/lib/file-hash'
import { stripGpsData } from '@/lib/privacy-strip'
import {
  addPhotosToAlbum,
  addPhotosToStory,
  checkDuplicatePhoto,
  getPhotos,
  uploadPhotoWithProgress,
  type PhotoDto,
  type StoryDto,
} from '@/lib/api'
import { buildStoryMarkdownImage } from '@/lib/story-rich-content'
import type { NarrativeTipTapEditorHandle } from '@/components/NarrativeTipTapEditor'
import type { PendingImage } from '@/components/admin/StoryPhotoPanel'
import type { UploadSettings } from '@/components/admin/ImageUploadSettingsModal'
import { STORY_PASTE_UPLOAD_SETTINGS_KEY, STORY_UPLOAD_SETTINGS_KEY } from './constants'
import type { UploadProgressState } from './types'
import { useStoryPasteUploads } from './useStoryPasteUploads'

interface UseStoryEditorActionsParams {
  token: string | null
  currentStory: StoryDto | null
  allPhotos: PhotoDto[]
  stories: StoryDto[]
  pendingImages: PendingImage[]
  initialUploadSettings: UploadSettings
  initialPasteUploadSettings: UploadSettings
  pendingPhotoIdsRef: MutableRefObject<string[] | null>
  setCurrentStory: Dispatch<SetStateAction<StoryDto | null>>
  setAllPhotos: Dispatch<SetStateAction<PhotoDto[]>>
  setPendingImages: Dispatch<SetStateAction<PendingImage[]>>
  notify: (message: string, type?: 'success' | 'error' | 'info') => void
  t: (key: string) => string
  onRequestSave: () => Promise<void>
}

interface UseStoryEditorActionsResult {
  editorRef: MutableRefObject<NarrativeTipTapEditorHandle | null>
  showUploadSettings: boolean
  setShowUploadSettings: Dispatch<SetStateAction<boolean>>
  showPasteUploadSettings: boolean
  setShowPasteUploadSettings: Dispatch<SetStateAction<boolean>>
  isUploading: boolean
  uploadProgress: UploadProgressState
  pendingPasteFilesRef: MutableRefObject<File[] | null>
  uploadSettings: UploadSettings
  pasteUploadSettings: UploadSettings
  hasConfirmedPasteSettings: boolean
  handlePhotoPanelDrop: (event: DragEvent) => Promise<void>
  handleRemovePendingImage: (id: string) => void
  handleConfirmUpload: (settings: UploadSettings) => Promise<void>
  handleRetryFailedUploads: () => void
  handlePasteFiles: (files: File[]) => void
  handleConfirmPasteUpload: (settings: UploadSettings) => Promise<void>
  handleInsertPhotoMarkdown: (photo: PhotoDto) => void
  handleInsertGalleryMarkdown: (photoIds: string[]) => void
  handleInsertExternalPhotoMarkdown: () => void
  restoreUploadSettings: (settings: UploadSettings) => void
  restorePasteUploadSettings: (settings: UploadSettings) => void
}

async function readTakenAt(file: File) {
  try {
    const tags = await ExifReader.load(file)
    const dateTime = tags.DateTimeOriginal || tags.DateTime
    if (!dateTime?.description) return undefined

    const match = dateTime.description.match(/^(\d{4}):(\d{2}):(\d{2}) (\d{2}):(\d{2}):(\d{2})/)
    if (!match) return undefined

    const [, year, month, day, hour, minute, second] = match
    return `${year}-${month}-${day}T${hour}:${minute}:${second}.000Z`
  } catch {
    return undefined
  }
}

export function useStoryEditorActions({
  token,
  currentStory,
  allPhotos,
  stories,
  pendingImages,
  initialUploadSettings,
  initialPasteUploadSettings,
  pendingPhotoIdsRef,
  setCurrentStory,
  setAllPhotos,
  setPendingImages,
  notify,
  t,
  onRequestSave,
}: UseStoryEditorActionsParams): UseStoryEditorActionsResult {
  const editorRef = useRef<NarrativeTipTapEditorHandle>(null)
  const pendingPasteFilesRef = useRef<File[] | null>(null)

  const [showUploadSettings, setShowUploadSettings] = useState(false)
  const [showPasteUploadSettings, setShowPasteUploadSettings] = useState(false)
  const [isUploading, setIsUploading] = useState(false)
  const [uploadProgress, setUploadProgress] = useState<UploadProgressState>({ current: 0, total: 0, currentFile: '' })
  const [hasConfirmedPasteSettings, setHasConfirmedPasteSettings] = useState(false)
  const [uploadSettings, setUploadSettings] = useState<UploadSettings>(initialUploadSettings)
  const [pasteUploadSettings, setPasteUploadSettings] = useState<UploadSettings>(initialPasteUploadSettings)

  const persistUploadSettings = useCallback((settings: UploadSettings) => {
    setUploadSettings(settings)

    if (typeof window === 'undefined') return

    try {
      window.localStorage.setItem(STORY_UPLOAD_SETTINGS_KEY, JSON.stringify(settings))
    } catch (error) {
      console.error('Failed to persist upload settings:', error)
    }
  }, [])

  const persistPasteUploadSettings = useCallback((settings: UploadSettings) => {
    setPasteUploadSettings(settings)
    setHasConfirmedPasteSettings(true)

    if (typeof window === 'undefined') return

    try {
      window.localStorage.setItem(STORY_PASTE_UPLOAD_SETTINGS_KEY, JSON.stringify(settings))
    } catch (error) {
      console.error('Failed to persist paste upload settings:', error)
    }
  }, [])

  const restorePasteUploadSettings = useCallback((settings: UploadSettings) => {
    setPasteUploadSettings(settings)
  }, [])

  const restoreUploadSettings = useCallback((settings: UploadSettings) => {
    setUploadSettings(settings)
  }, [])

  const insertDirective = useCallback((markdown: string) => {
    editorRef.current?.insertValue(markdown)
    const nextValue = editorRef.current?.getValue() || currentStory?.content || ''
    const nextJsonValue = editorRef.current?.getJsonValue() ?? currentStory?.contentJson ?? null
    setCurrentStory((prev) => (prev ? { ...prev, content: nextValue, contentJson: nextJsonValue } : prev))
  }, [currentStory?.content, currentStory?.contentJson, setCurrentStory])

  const replaceEditorText = useCallback((searchValue: string, nextValue: string) => {
    editorRef.current?.replaceText(searchValue, nextValue)
    const latestValue = editorRef.current?.getValue() || currentStory?.content || ''
    const latestJsonValue = editorRef.current?.getJsonValue() ?? currentStory?.contentJson ?? null
    setCurrentStory((prev) => (prev ? { ...prev, content: latestValue, contentJson: latestJsonValue } : prev))
  }, [currentStory?.content, currentStory?.contentJson, setCurrentStory])

  const addPhotoToCurrentStory = useCallback((photo: PhotoDto) => {
    setCurrentStory((prev) => {
      if (!prev) return prev
      if (prev.photos.some((item) => item.id === photo.id)) return prev
      return { ...prev, photos: [...prev.photos, photo] }
    })
  }, [setCurrentStory])

  const addPhotoToCache = useCallback((photo: PhotoDto) => {
    setAllPhotos((prev) => (prev.some((item) => item.id === photo.id) ? prev : [photo, ...prev]))
  }, [setAllPhotos])

  const findExistingPhotoById = useCallback(async (photoId: string) => {
    const cachedPhoto = currentStory?.photos.find((photo) => photo.id === photoId)
      || allPhotos.find((photo) => photo.id === photoId)

    if (cachedPhoto) {
      return cachedPhoto
    }

    const photos = await getPhotos({ all: true })
    setAllPhotos(photos)
    return photos.find((photo) => photo.id === photoId) ?? null
  }, [allPhotos, currentStory?.photos, setAllPhotos])

  const { uploadAndInsertFiles } = useStoryPasteUploads({
    token: token || '',
    currentStory,
    allPhotos,
    notify,
    setAllPhotos,
    setUploadProgress,
    insertDirective,
    replaceEditorText,
    addPhotoToCache,
    addPhotoToCurrentStory,
    persistPasteUploadSettings,
    setShowPasteUploadSettings,
    setIsUploading,
    pendingPasteFilesRef,
  })

  const handlePhotoPanelDrop = useCallback(async (event: DragEvent) => {
    event.preventDefault()
    const files = Array.from(event.dataTransfer.files).filter((file) => file.type.startsWith('image/'))
    if (files.length === 0) return

    const newPending = await Promise.all(files.map(async (file) => ({
      id: crypto.randomUUID(),
      file,
      previewUrl: URL.createObjectURL(file),
      status: 'pending' as const,
      progress: 0,
      takenAt: await readTakenAt(file),
    })))

    setPendingImages((prev) => [...prev, ...newPending])
  }, [setPendingImages])

  const handleRemovePendingImage = useCallback((id: string) => {
    setPendingImages((prev) => {
      const item = prev.find((image) => image.id === id)
      if (item) URL.revokeObjectURL(item.previewUrl)
      return prev.filter((image) => image.id !== id)
    })
  }, [setPendingImages])

  const handleConfirmUpload = useCallback(async (settings: UploadSettings) => {
    if (!token || !currentStory) return

    persistUploadSettings(settings)
    setShowUploadSettings(false)
    setIsUploading(true)
    const toUpload = pendingImages.filter((image) => image.status === 'pending' || image.status === 'failed')
    setUploadProgress({ current: 0, total: toUpload.length, currentFile: '' })

    const uploadedPhotoIds: string[] = []
    const uploadedPhotos: PhotoDto[] = []

    for (let index = 0; index < toUpload.length; index += 1) {
      const pending = toUpload[index]
      setUploadProgress({ current: index + 1, total: toUpload.length, currentFile: pending.file.name })
      setPendingImages((prev) => prev.map((image) => image.id === pending.id ? { ...image, status: 'uploading' as const, progress: 0 } : image))

      try {
        const fileHash = await calculateFileHash(pending.file)
        const duplicate = await checkDuplicatePhoto(token, fileHash)

        if (duplicate.isDuplicate && duplicate.existingPhoto) {
          const existingPhoto = await findExistingPhotoById(duplicate.existingPhoto.id)

          if (existingPhoto) {
            if (!uploadedPhotoIds.includes(existingPhoto.id)) {
              uploadedPhotoIds.push(existingPhoto.id)
            }
            if (!uploadedPhotos.some((photo) => photo.id === existingPhoto.id)) {
              uploadedPhotos.push(existingPhoto)
            }
            addPhotoToCache(existingPhoto)
            setPendingImages((prev) => prev.map((image) => image.id === pending.id ? { ...image, status: 'success' as const, progress: 100, photoId: existingPhoto.id } : image))
            notify(`图片已重复，已替换为已上传照片：${existingPhoto.title}`, 'info')
            continue
          }
        }

        let fileToUpload = pending.file

        // Extract EXIF before compression/GPS-strip (compression discards EXIF).
        let exifJsonString: string | undefined
        try {
          let exifJson = await extractExifToJson(fileToUpload)
          if (settings.stripGps) {
            exifJson = stripGpsFromExifJson(exifJson)
          }
          if (Object.keys(exifJson).length > 0) {
            exifJsonString = JSON.stringify(exifJson)
          }
        } catch {
          // EXIF read failure should not block upload
        }

        if (settings.stripGps) {
          fileToUpload = await stripGpsData(fileToUpload)
        }

        if (settings.compressionMode && settings.compressionMode !== 'none') {
          fileToUpload = await compressImage(fileToUpload, {
            mode: settings.compressionMode,
            maxSizeMB: settings.maxSizeMB && settings.maxSizeMB > 0 ? settings.maxSizeMB : undefined,
            maxWidthOrHeight: 4096,
          })
        }

        const photo = await uploadPhotoWithProgress({
          token,
          file: fileToUpload,
          title: pending.file.name.replace(/\.[^/.]+$/, ''),
          category: settings.categories?.length ? settings.categories : settings.category,
          storage_provider: settings.storageProvider,
          storage_source_id: settings.storageSourceId,
          storage_path: settings.storagePath,
          storage_path_full: settings.storagePathFull,
          show_flag: settings.showFlag,
          compression_mode: settings.compressionMode,
          max_size_mb: settings.maxSizeMB,
          exif_json: exifJsonString,
          strip_gps: settings.stripGps ? 'true' : undefined,
          file_hash: fileHash,
          onProgress: (progress) => {
            setPendingImages((prev) => prev.map((image) => image.id === pending.id ? { ...image, progress } : image))
          },
        })

        if (!uploadedPhotoIds.includes(photo.id)) {
          uploadedPhotoIds.push(photo.id)
        }
        if (!uploadedPhotos.some((item) => item.id === photo.id)) {
          uploadedPhotos.push(photo)
        }
        setPendingImages((prev) => prev.map((image) => image.id === pending.id ? { ...image, status: 'success' as const, progress: 100, photoId: photo.id } : image))
      } catch (error) {
        setPendingImages((prev) => prev.map((image) => image.id === pending.id ? { ...image, status: 'failed' as const, error: error instanceof Error ? error.message : 'Upload failed' } : image))
      }
    }

    if (settings.albumIds?.length && uploadedPhotoIds.length > 0) {
      for (const albumId of settings.albumIds) {
        try {
          await addPhotosToAlbum(token, albumId, uploadedPhotoIds)
        } catch {}
      }
    } else if (settings.albumId && uploadedPhotoIds.length > 0) {
      try {
        await addPhotosToAlbum(token, settings.albumId, uploadedPhotoIds)
      } catch {}
    }

    if (uploadedPhotos.length > 0) {
      const isNew = !stories.find((story) => story.id === currentStory.id)
      if (isNew) {
        setCurrentStory((prev) => {
          if (!prev) return prev
          const existingIds = new Set((prev.photos || []).map((photo) => photo.id))
          const nextPhotos = uploadedPhotos.filter((photo) => !existingIds.has(photo.id))
          return nextPhotos.length > 0 ? { ...prev, photos: [...(prev.photos || []), ...nextPhotos] } : prev
        })
      } else {
        try {
          const existingIds = new Set((currentStory.photos || []).map((photo) => photo.id))
          const newPhotoIds = uploadedPhotoIds.filter((photoId) => !existingIds.has(photoId))
          if (newPhotoIds.length > 0) {
            await addPhotosToStory(token, currentStory.id, newPhotoIds)
          }
          setCurrentStory((prev) => {
            if (!prev) return prev
            const currentIds = new Set((prev.photos || []).map((photo) => photo.id))
            const nextPhotos = uploadedPhotos.filter((photo) => !currentIds.has(photo.id))
            return nextPhotos.length > 0 ? { ...prev, photos: [...(prev.photos || []), ...nextPhotos] } : prev
          })
        } catch {}
      }
    }

    setPendingImages((prev) => {
      prev.filter((image) => image.status === 'success').forEach((image) => URL.revokeObjectURL(image.previewUrl))
      return prev.filter((image) => image.status !== 'success')
    })
    setIsUploading(false)

    const failedCount = pendingImages.filter((image) => image.status === 'failed').length
    if (failedCount === 0) {
      // Pass uploaded photo IDs via ref so doSaveStory can merge them
      // (setCurrentStory hasn't re-rendered yet, so the closure state is stale)
      pendingPhotoIdsRef.current = uploadedPhotoIds
      await onRequestSave()
      return
    }

    notify(`${failedCount} ${t('admin.upload_failed_count')}`, 'error')
  }, [addPhotoToCache, currentStory, findExistingPhotoById, notify, onRequestSave, pendingImages, persistUploadSettings, setCurrentStory, setPendingImages, stories, t, token])

  const handleRetryFailedUploads = useCallback(() => {
    setPendingImages((prev) => prev.map((image) => image.status === 'failed' ? { ...image, status: 'pending' as const, error: undefined, progress: 0 } : image))
    setShowUploadSettings(true)
  }, [setPendingImages])

  const handlePasteFiles = useCallback((files: File[]) => {
    if (!token || !currentStory) return

    if (!hasConfirmedPasteSettings) {
      pendingPasteFilesRef.current = files
      setShowPasteUploadSettings(true)
      return
    }

    void uploadAndInsertFiles(files, pasteUploadSettings)
  }, [currentStory, hasConfirmedPasteSettings, pasteUploadSettings, setShowPasteUploadSettings, token, uploadAndInsertFiles])

  const handleConfirmPasteUpload = useCallback(async (settings: UploadSettings) => {
    persistPasteUploadSettings({ ...settings, category: settings.category?.trim() || '' })

    const files = pendingPasteFilesRef.current
    if (!files?.length) {
      setShowPasteUploadSettings(false)
      return
    }

    await uploadAndInsertFiles(files, settings)
  }, [persistPasteUploadSettings, uploadAndInsertFiles])

  const handleInsertPhotoMarkdown = useCallback((photo: PhotoDto) => {
    insertDirective(buildStoryMarkdownImage({ url: photo.url, alt: photo.title, photoId: photo.id }))
    notify('Inserted Markdown image', 'success')
  }, [insertDirective, notify])

  const handleInsertGalleryMarkdown = useCallback((photoIds: string[]) => {
    if (photoIds.length === 0) {
      notify('No photos available to insert', 'info')
      return
    }

    const photosToInsert = photoIds
      .map((photoId) => currentStory?.photos?.find((photo) => photo.id === photoId))
      .filter((photo): photo is PhotoDto => Boolean(photo))

    if (photosToInsert.length === 0) {
      notify('No photos available to insert', 'info')
      return
    }

    const markdown = photosToInsert
      .map((photo) => buildStoryMarkdownImage({ url: photo.url, alt: photo.title, photoId: photo.id }).trim())
      .join('\n\n')
    insertDirective(`\n${markdown}\n`)
    notify('Inserted Markdown gallery', 'success')
  }, [currentStory?.photos, insertDirective, notify])

  const handleInsertExternalPhotoMarkdown = useCallback(() => {
    const url = window.prompt('Enter external image URL (https)')
    if (!url) return

    const trimmedUrl = url.trim()
    if (!/^https:\/\//i.test(trimmedUrl)) {
      notify('External images must use an https URL', 'error')
      return
    }

    const caption = window.prompt('Enter image caption (optional)')?.trim() || ''
    insertDirective(buildStoryMarkdownImage({ url: trimmedUrl, alt: caption }))
    notify('Inserted external Markdown image', 'success')
  }, [insertDirective, notify])

  return {
    editorRef,
    showUploadSettings,
    setShowUploadSettings,
    showPasteUploadSettings,
    setShowPasteUploadSettings,
    isUploading,
    uploadProgress,
    pendingPasteFilesRef,
    uploadSettings,
    pasteUploadSettings,
    hasConfirmedPasteSettings,
    handlePhotoPanelDrop,
    handleRemovePendingImage,
    handleConfirmUpload,
    handleRetryFailedUploads,
    handlePasteFiles,
    handleConfirmPasteUpload,
    handleInsertPhotoMarkdown,
    handleInsertGalleryMarkdown,
    handleInsertExternalPhotoMarkdown,
    restoreUploadSettings,
    restorePasteUploadSettings,
  }
}

'use client'

import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react'
import {
  LayoutGrid,
  List as ListIcon,
  Trash2,
  RefreshCw,
  X,
  ImageIcon,
  Star,
  SlidersHorizontal,
} from 'lucide-react'
import { resolveAssetUrl } from '@/lib/api/core'
import { getAlbums } from '@/lib/api/albums'
import { getCameras, getLenses } from '@/lib/api/equipment'
import {
  MAX_PHOTO_GRID_COLUMNS,
  MIN_PHOTO_GRID_COLUMNS,
  type PhotosSortOption,
  type PhotosFilterPreference,
  useAdminPreferenceStore,
  useAdminSessionPreferenceStore,
} from '@/lib/admin-preferences'
import { AdminButton } from '@/components/admin/AdminButton'
import { AdminSelect } from '@/components/admin/AdminFormControls'
import { AdminCollectionToolbar } from '@/components/admin/AdminCollectionToolbar'
import type { PhotoDto, AlbumDto, AdminSettingsDto, CameraDto, LensDto } from '@/lib/api/types'

type ViewMode = 'grid' | 'list'

const PHOTO_GRID_CLASS_NAME =
  'grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-[repeat(var(--admin-photo-grid-columns),minmax(0,1fr))] gap-0.5'

interface PhotoGridCardProps {
  photo: PhotoDto
  isSelected: boolean
  resolvedCdnDomain: string | undefined
  onSelect: (id: string, shiftKey?: boolean) => void
  onDelete: (id: string) => void
  onToggleFeatured: (photo: PhotoDto) => void
  onClick: (event: React.MouseEvent, photo: PhotoDto) => void
}

const PhotoGridCard = React.memo(function PhotoGridCard({
  photo,
  isSelected,
  resolvedCdnDomain,
  onSelect,
  onDelete,
  onToggleFeatured,
  onClick,
}: PhotoGridCardProps) {
  return (
    <div
      className={`group relative cursor-pointer bg-muted rounded-lg overflow-hidden border-2 transition-colors w-full ${
        isSelected
          ? 'border-primary'
          : 'border-transparent hover:border-border'
      }`}
      onClick={(event) => onClick(event, photo)}
    >
      <div className="relative w-full aspect-[4/5]">
        <img
          src={resolveAssetUrl(
            photo.thumbnailUrl || photo.url,
            resolvedCdnDomain
          )}
          alt={photo.title}
          className="w-full h-full object-cover"
          decoding="async"
          loading="lazy"
        />
      </div>

      <div
        className="absolute top-2 left-2 z-10"
        onClick={(e) => e.stopPropagation()}
      >
        <input
          type="checkbox"
          checked={isSelected}
          onClick={(event) => onSelect(photo.id, event.shiftKey)}
          onChange={() => undefined}
          className="w-4 h-4 accent-primary cursor-pointer rounded border-2 border-white/80 shadow-sm"
        />
      </div>

      <div className="absolute inset-0 z-10 bg-gradient-to-t from-black/80 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-150 pointer-events-none">
        <div className="absolute top-2 right-2 flex flex-col gap-1.5 pointer-events-none group-hover:pointer-events-auto">
          <AdminButton
            onClick={(e) => {
              e.stopPropagation()
              onToggleFeatured(photo)
            }}
            adminVariant={photo.isFeatured ? 'iconAccent' : 'iconOnDark'}
            size="xs"
            className="p-1.5 rounded"
            title={photo.isFeatured ? "Remove from featured" : "Add to featured"}
          >
            <Star className={`w-3.5 h-3.5 ${photo.isFeatured ? 'fill-current' : ''}`} />
          </AdminButton>
          <AdminButton
            onClick={(e) => {
              e.stopPropagation()
              onDelete(photo.id)
            }}
            adminVariant="iconOnDarkDanger"
            size="xs"
            className="p-1.5 rounded"
            title="Delete photo"
          >
            <Trash2 className="w-3.5 h-3.5" />
          </AdminButton>
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-3">
          <p className="text-[10px] font-bold text-primary uppercase tracking-wider mb-0.5 truncate">
            {photo.category.split(',')[0]}
          </p>
          <h3 className="text-sm font-medium text-white leading-tight truncate">
            {photo.title}
          </h3>
        </div>
      </div>

      {photo.isFeatured && (
        <AdminButton
          onClick={(e) => {
            e.stopPropagation()
            onToggleFeatured(photo)
          }}
          adminVariant="iconAccent"
          size="xs"
          className="absolute top-2 right-2 p-1.5 z-20 shadow-lg pointer-events-auto group-hover:invisible group-hover:pointer-events-none"
          title="Remove from featured"
        >
          <Star className="w-3 h-3 fill-current" />
        </AdminButton>
      )}
    </div>
  )
}, (prev, next) => {
  return (
    prev.photo.id === next.photo.id &&
    prev.isSelected === next.isSelected &&
    prev.photo.isFeatured === next.photo.isFeatured &&
    prev.photo.thumbnailUrl === next.photo.thumbnailUrl &&
    prev.photo.url === next.photo.url &&
    prev.photo.title === next.photo.title &&
    prev.photo.category === next.photo.category &&
    prev.resolvedCdnDomain === next.resolvedCdnDomain &&
    prev.onSelect === next.onSelect &&
    prev.onDelete === next.onDelete &&
    prev.onToggleFeatured === next.onToggleFeatured &&
    prev.onClick === next.onClick
  )
})

interface PhotoListRowProps {
  photo: PhotoDto
  isSelected: boolean
  resolvedCdnDomain: string | undefined
  onSelect: (id: string, shiftKey?: boolean) => void
  onDelete: (id: string) => void
  onToggleFeatured: (photo: PhotoDto) => void
  onClick: (event: React.MouseEvent, photo: PhotoDto) => void
}

const PhotoListRow = React.memo(function PhotoListRow({
  photo,
  isSelected,
  resolvedCdnDomain,
  onSelect,
  onDelete,
  onToggleFeatured,
  onClick,
}: PhotoListRowProps) {
  return (
    <div
      className={`flex items-center gap-4 p-3 border-b border-border last:border-0 hover:bg-muted/50 transition-colors cursor-pointer ${
        isSelected ? 'bg-primary/5' : ''
      }`}
      onClick={(event) => onClick(event, photo)}
    >
      <div
        className="flex items-center"
        onClick={(e) => e.stopPropagation()}
      >
        <input
          type="checkbox"
          checked={isSelected}
          onClick={(event) => onSelect(photo.id, event.shiftKey)}
          onChange={() => undefined}
          className="w-4 h-4 accent-primary cursor-pointer rounded"
        />
      </div>
      <div className="w-12 h-12 flex-shrink-0 bg-muted rounded overflow-hidden">
        <img
          src={resolveAssetUrl(
            photo.thumbnailUrl || photo.url,
            resolvedCdnDomain
          )}
          alt=""
          className="w-full h-full object-cover"
          decoding="async"
        />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium truncate text-foreground">
          {photo.title}
        </p>
        <p className="text-xs text-muted-foreground truncate">
          {photo.category}
        </p>
      </div>
      <div className="hidden md:flex items-center gap-4 text-xs text-muted-foreground">
        <span className="font-mono">{photo.width} × {photo.height}</span>
        <span className="uppercase">{photo.storageProvider}</span>
      </div>
      <div className="flex items-center gap-1">
        <AdminButton
          onClick={(e) => {
            e.stopPropagation()
            onToggleFeatured(photo)
          }}
          adminVariant="icon"
          size="xs"
          className={`p-2 ${
            photo.isFeatured ? 'text-amber-500' : 'text-muted-foreground hover:text-amber-500'
          }`}
        >
          <Star className={`w-4 h-4 ${photo.isFeatured ? 'fill-current' : ''}`} />
        </AdminButton>
        <AdminButton
          onClick={(e) => {
            e.stopPropagation()
            onDelete(photo.id)
          }}
          adminVariant="iconDestructive"
          size="xs"
          className="p-2"
        >
          <Trash2 className="w-4 h-4" />
        </AdminButton>
      </div>
    </div>
  )
}, (prev, next) => {
  return (
    prev.photo.id === next.photo.id &&
    prev.isSelected === next.isSelected &&
    prev.photo.isFeatured === next.photo.isFeatured &&
    prev.photo.thumbnailUrl === next.photo.thumbnailUrl &&
    prev.photo.url === next.photo.url &&
    prev.photo.title === next.photo.title &&
    prev.photo.category === next.photo.category &&
    prev.photo.width === next.photo.width &&
    prev.photo.height === next.photo.height &&
    prev.photo.storageProvider === next.photo.storageProvider &&
    prev.resolvedCdnDomain === next.resolvedCdnDomain &&
    prev.onSelect === next.onSelect &&
    prev.onDelete === next.onDelete &&
    prev.onToggleFeatured === next.onToggleFeatured &&
    prev.onClick === next.onClick
  )
})

interface PhotosTabProps {
  photos: PhotoDto[]
  categories: string[]
  loading: boolean
  error: string
  viewMode: ViewMode
  onViewModeChange: (mode: ViewMode) => void
  selectedIds: Set<string>
  onSelect: (id: string) => void
  onSelectionChange: React.Dispatch<React.SetStateAction<Set<string>>>
  onDelete: (id?: string) => void
  onBatchAction: () => void
  onRefresh: () => void
  onToggleFeatured: (photo: PhotoDto) => void
  onPreview: (photo: PhotoDto) => void
  t: (key: string) => string
  settings: AdminSettingsDto | null
  notify?: (message: string, type?: 'success' | 'error' | 'info') => void
  initialFilters?: Partial<Pick<PhotosFilterPreference, 'categoryFilter' | 'photoTypeFilter' | 'albumFilter' | 'onlyFeatured'>>
}

export function PhotosTab({
  photos,
  categories,
  loading,
  error,
  viewMode,
  onViewModeChange,
  selectedIds,
  onSelect,
  onSelectionChange,
  onDelete,
  onBatchAction,
  onRefresh,
  onToggleFeatured,
  onPreview,
  t,
  settings,
  notify,
  initialFilters,
}: PhotosTabProps) {
  const photosFilters = useAdminSessionPreferenceStore((state) => state.photosFilters)
  const setPhotosFilters = useAdminSessionPreferenceStore((state) => state.setPhotosFilters)
  const gridColumns = useAdminPreferenceStore((state) => state.photoGridColumns)
  const setPhotoGridColumns = useAdminPreferenceStore((state) => state.setPhotoGridColumns)
  const [albums, setAlbums] = useState<AlbumDto[]>([])
  const [cameras, setCameras] = useState<CameraDto[]>([])
  const [lenses, setLenses] = useState<LensDto[]>([])
  const [lastSelectedId, setLastSelectedId] = useState<string | null>(null)
  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const [toolbarScrolled, setToolbarScrolled] = useState(false)
  const gridContainerRef = useRef<HTMLDivElement>(null)
  const sliderRef = useRef<HTMLInputElement>(null)
  const columnsLabelRef = useRef<HTMLSpanElement>(null)
  const pendingColumnsRef = useRef<number>(gridColumns)
  const rafIdRef = useRef(0)

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault()
        document.querySelector<HTMLInputElement>('[data-search-input]')?.focus()
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [])

  const handleScroll = useCallback(() => {
    setToolbarScrolled((scrollContainerRef.current?.scrollTop ?? 0) > 0)
  }, [])

  const {
    search,
    categoryFilter,
    photoTypeFilter,
    channelFilter,
    albumFilter,
    cameraFilter,
    lensFilter,
    onlyFeatured,
    sortBy,
    showFilters,
  } = photosFilters

  const setSearch = useCallback((value: string) => setPhotosFilters({ search: value }), [setPhotosFilters])
  const setCategoryFilter = useCallback((value: string) => setPhotosFilters({ categoryFilter: value }), [setPhotosFilters])
  const setPhotoTypeFilter = useCallback((value: string) => setPhotosFilters({ photoTypeFilter: value }), [setPhotosFilters])
  const setChannelFilter = useCallback((value: string) => setPhotosFilters({ channelFilter: value }), [setPhotosFilters])
  const setAlbumFilter = useCallback((value: string) => setPhotosFilters({ albumFilter: value }), [setPhotosFilters])
  const setCameraFilter = useCallback((value: string) => setPhotosFilters({ cameraFilter: value }), [setPhotosFilters])
  const setLensFilter = useCallback((value: string) => setPhotosFilters({ lensFilter: value }), [setPhotosFilters])
  const setOnlyFeatured = useCallback((value: boolean) => setPhotosFilters({ onlyFeatured: value }), [setPhotosFilters])
  const setSortBy = useCallback((value: PhotosSortOption) => setPhotosFilters({ sortBy: value }), [setPhotosFilters])
  const setShowFilters = useCallback((value: boolean) => setPhotosFilters({ showFilters: value }), [setPhotosFilters])

  useEffect(() => {
    if (!initialFilters) return

    setPhotosFilters({
      categoryFilter: initialFilters.categoryFilter ?? 'all',
      photoTypeFilter: initialFilters.photoTypeFilter ?? 'all',
      albumFilter: initialFilters.albumFilter ?? 'all',
      onlyFeatured: initialFilters.onlyFeatured ?? false,
    })
  }, [initialFilters, setPhotosFilters])

  useEffect(() => {
    return () => {
      cancelAnimationFrame(rafIdRef.current)
      setPhotoGridColumns(pendingColumnsRef.current)
    }
  }, [setPhotoGridColumns])

  const resolvedCdnDomain = settings?.cdn_domain?.trim() || undefined

  // Load albums, cameras, and lenses on mount
  useEffect(() => {
    async function loadFilterData() {
      try {
        const [albumsData, camerasData, lensesData] = await Promise.all([
          getAlbums(),
          getCameras(),
          getLenses()
        ])
        setAlbums(albumsData)
        setCameras(camerasData)
        setLenses(lensesData)
      } catch (err) {
        console.error('Failed to load filter data:', err)
        notify?.(err instanceof Error ? err.message : t('common.error'), 'error')
      }
    }
    loadFilterData()
  }, [])

  // Camera options from API
  const cameraOptions = useMemo(() => {
    return cameras.map(c => ({
      value: c.id,
      label: c.displayName
    }))
  }, [cameras])

  // Lens options from API
  const lensOptions = useMemo(() => {
    return lenses.map(l => ({
      value: l.id,
      label: l.displayName
    }))
  }, [lenses])

  // Count active filters
  const activeFilterCount = useMemo(() => {
    let count = 0
    if (categoryFilter !== 'all') count++
    if (photoTypeFilter !== 'all') count++
    if (channelFilter !== 'all') count++
    if (albumFilter !== 'all') count++
    if (cameraFilter !== 'all') count++
    if (lensFilter !== 'all') count++
    if (onlyFeatured) count++
    return count
  }, [categoryFilter, photoTypeFilter, channelFilter, albumFilter, cameraFilter, lensFilter, onlyFeatured])

  // Get album photo IDs for filtering
  const albumPhotoIds = useMemo(() => {
    if (albumFilter === 'all') return null
    const album = albums.find(a => a.id === albumFilter)
    if (!album) return null
    return new Set(album.photos.map(p => p.id))
  }, [albumFilter, albums])

  const filteredPhotos = useMemo(() => {
    const filtered = photos.filter((p) => {
      const matchesSearch =
        p.title.toLowerCase().includes(search.toLowerCase()) ||
        p.category.toLowerCase().includes(search.toLowerCase())

      const matchesCategory =
        categoryFilter === 'all' || p.category.includes(categoryFilter)

      const matchesPhotoType =
        photoTypeFilter === 'all' || (p.photoType ?? 'digital') === photoTypeFilter

      const matchesChannel =
        channelFilter === 'all' || p.storageProvider === channelFilter

      const matchesAlbum =
        albumPhotoIds === null || albumPhotoIds.has(p.id)

      const matchesCamera = (() => {
        if (cameraFilter === 'all') return true
        return p.cameraId === cameraFilter
      })()

      const matchesLens = (() => {
        if (lensFilter === 'all') return true
        return p.lensId === lensFilter
      })()

      const matchesFeatured = !onlyFeatured || p.isFeatured

      return matchesSearch && matchesCategory && matchesPhotoType && matchesChannel && matchesAlbum && matchesCamera && matchesLens && matchesFeatured
    })

    // Apply sorting
    return filtered.toSorted((a, b) => {
      switch (sortBy) {
        case 'upload-desc':
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        case 'upload-asc':
          return new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
        case 'taken-desc':
          if (!a.takenAt && !b.takenAt) return 0
          if (!a.takenAt) return 1
          if (!b.takenAt) return -1
          return new Date(b.takenAt).getTime() - new Date(a.takenAt).getTime()
        case 'taken-asc':
          if (!a.takenAt && !b.takenAt) return 0
          if (!a.takenAt) return 1
          if (!b.takenAt) return -1
          return new Date(a.takenAt).getTime() - new Date(b.takenAt).getTime()
        default:
          return 0
      }
    })
  }, [photos, search, categoryFilter, photoTypeFilter, channelFilter, albumPhotoIds, cameraFilter, lensFilter, onlyFeatured, sortBy])

  const clearAllFilters = () => {
    setPhotosFilters({
      search: '',
      categoryFilter: 'all',
      photoTypeFilter: 'all',
      channelFilter: 'all',
      albumFilter: 'all',
      cameraFilter: 'all',
      lensFilter: 'all',
      onlyFeatured: false,
    })
  }

  const sortOptions: { value: PhotosSortOption; label: string }[] = [
    { value: 'upload-desc', label: t('admin.sort_upload_desc') },
    { value: 'upload-asc', label: t('admin.sort_upload_asc') },
    { value: 'taken-desc', label: t('admin.sort_taken_desc') },
    { value: 'taken-asc', label: t('admin.sort_taken_asc') },
  ]

  const handleSelectPhoto = useCallback((photoId: string, shiftKey = false) => {
    if (!shiftKey || !lastSelectedId) {
      onSelect(photoId)
      setLastSelectedId(photoId)
      return
    }

    const startIndex = filteredPhotos.findIndex((photo) => photo.id === lastSelectedId)
    const endIndex = filteredPhotos.findIndex((photo) => photo.id === photoId)

    if (startIndex === -1 || endIndex === -1) {
      onSelect(photoId)
      setLastSelectedId(photoId)
      return
    }

    const [rangeStart, rangeEnd] = startIndex < endIndex
      ? [startIndex, endIndex]
      : [endIndex, startIndex]
    const rangeIds = filteredPhotos.slice(rangeStart, rangeEnd + 1).map((photo) => photo.id)
    const shouldSelectRange = !selectedIds.has(photoId)

    onSelectionChange((prev) => {
      const next = new Set(prev)
      for (const id of rangeIds) {
        if (shouldSelectRange) next.add(id)
        else next.delete(id)
      }
      return next
    })
    setLastSelectedId(photoId)
  }, [filteredPhotos, lastSelectedId, onSelect, onSelectionChange, selectedIds])

  const handlePhotoClick = useCallback((event: React.MouseEvent, photo: PhotoDto) => {
    if (event.shiftKey) {
      event.preventDefault()
      handleSelectPhoto(photo.id, true)
      return
    }
    onPreview(photo)
  }, [handleSelectPhoto, onPreview])

  const hasSelectedPhotos = selectedIds.size >= 1

  // 全选只作用于当前筛选结果；勾选态也按"筛选结果是否全部选中"计算，
  // 避免选中集合里残留不可见照片时批量操作误伤。
  const allVisibleSelected =
    filteredPhotos.length > 0 && filteredPhotos.every((photo) => selectedIds.has(photo.id))

  const handleToggleSelectAll = useCallback(() => {
    onSelectionChange((prev) => {
      const visibleIds = filteredPhotos.map((photo) => photo.id)
      const allSelected = visibleIds.length > 0 && visibleIds.every((id) => prev.has(id))
      return allSelected ? new Set<string>() : new Set(visibleIds)
    })
  }, [filteredPhotos, onSelectionChange])

  // 筛选条件变化时清空选中，防止批量删除命中已被筛掉的照片
  useEffect(() => {
    onSelectionChange(new Set())
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [search, categoryFilter, photoTypeFilter, channelFilter, albumFilter, cameraFilter, lensFilter, onlyFeatured])

  const handleGridColumnsChange = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const value = Number(event.target.value)
    pendingColumnsRef.current = value
    if (columnsLabelRef.current) {
      columnsLabelRef.current.textContent = String(value)
    }
    cancelAnimationFrame(rafIdRef.current)
    rafIdRef.current = requestAnimationFrame(() => {
      if (gridContainerRef.current) {
        gridContainerRef.current.style.setProperty('--admin-photo-grid-columns', String(value))
      }
    })
  }, [])

  const persistGridColumns = useCallback(() => {
    const value = pendingColumnsRef.current
    if (value !== gridColumns) {
      setPhotoGridColumns(value)
    }
  }, [gridColumns, setPhotoGridColumns])

  return (
    <div className="h-full flex flex-col overflow-hidden relative">
      <AdminCollectionToolbar
        scrolled={toolbarScrolled}
        info={(
          <>
            <label className="flex items-center gap-2 cursor-pointer">
              <input
                type="checkbox"
                checked={allVisibleSelected}
                onChange={handleToggleSelectAll}
                className="w-4 h-4 accent-primary cursor-pointer rounded"
              />
              <span className="text-sm font-medium text-muted-foreground">
                {filteredPhotos.length} {t('admin.photos')}
              </span>
            </label>
          </>
        )}
        searchValue={search}
        onSearchChange={setSearch}
        searchPlaceholder={t('common.search')}
        actions={(
          <>
            {/* Sort */}
            <AdminSelect
              value={sortBy}
              onChange={(v) => setSortBy(v as PhotosSortOption)}
              options={sortOptions.map(opt => ({ value: opt.value, label: opt.label }))}
              className="min-w-[140px]"
            />

            {/* Filter Toggle */}
            <AdminButton
              onClick={() => setShowFilters(!showFilters)}
              adminVariant="unstyled"
              className={`flex items-center gap-2 px-3 py-2 text-xs font-medium border rounded-md transition-all ${
                showFilters || activeFilterCount > 0
                  ? 'bg-primary/10 border-primary/30 text-primary'
                  : 'bg-background border-border text-muted-foreground hover:text-foreground hover:border-foreground/30'
              }`}
            >
              <SlidersHorizontal className="w-4 h-4" />
              <span className="hidden sm:inline">{t('admin.filter') || 'Filter'}</span>
              {activeFilterCount > 0 && (
                <span className="flex items-center justify-center w-5 h-5 bg-primary text-primary-foreground text-[10px] font-bold rounded-full">
                  {activeFilterCount}
                </span>
              )}
            </AdminButton>

            <div className="h-5 w-px bg-border mx-0.5" />

            {/* View Mode Toggle */}
            <div className="flex bg-background border border-border rounded-md overflow-hidden">
              <AdminButton
                onClick={() => onViewModeChange('grid')}
                adminVariant="unstyled"
                className={`p-2 transition-colors ${
                  viewMode === 'grid'
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                }`}
                title="Grid view"
              >
                <LayoutGrid className="w-4 h-4" />
              </AdminButton>
              <AdminButton
                onClick={() => onViewModeChange('list')}
                adminVariant="unstyled"
                className={`p-2 transition-colors ${
                  viewMode === 'list'
                    ? 'bg-primary text-primary-foreground'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                }`}
                title="List view"
              >
                <ListIcon className="w-4 h-4" />
              </AdminButton>
            </div>

            {viewMode === 'grid' ? (
              <div
                className="hidden h-9 items-center gap-2 rounded-md border border-border bg-background px-3 sm:flex"
                title="Grid columns"
              >
                <LayoutGrid className="h-4 w-4 text-muted-foreground" />
                <input
                  ref={sliderRef}
                  key={gridColumns}
                  type="range"
                  min={MIN_PHOTO_GRID_COLUMNS}
                  max={MAX_PHOTO_GRID_COLUMNS}
                  step={1}
                  defaultValue={gridColumns}
                  onChange={handleGridColumnsChange}
                  onMouseUp={persistGridColumns}
                  onTouchEnd={persistGridColumns}
                  aria-label="Grid columns"
                  className="w-24 accent-primary"
                />
                <span ref={columnsLabelRef} className="w-5 text-right font-mono text-xs tabular-nums text-muted-foreground">
                  {gridColumns}
                </span>
              </div>
            ) : null}

            <div className="h-5 w-px bg-border mx-0.5" />

            {/* Refresh */}
            <AdminButton
              onClick={onRefresh}
              adminVariant="unstyled"
              className="p-2 bg-background border border-border rounded-md text-muted-foreground hover:text-foreground hover:border-foreground/30 transition-colors"
              title={t('common.refresh')}
            >
              <RefreshCw className="w-4 h-4" />
            </AdminButton>
          </>
        )}
        filters={showFilters ? (
          <div className="flex flex-wrap items-center gap-3">
              {/* Category Filter */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground whitespace-nowrap">{t('ui.category_filter')}:</span>
                <AdminSelect
                  value={categoryFilter}
                  onChange={setCategoryFilter}
                  options={[
                    { value: 'all', label: t('gallery.all') },
                    ...categories.filter(c => c !== 'all' && c !== '全部').map(cat => ({ value: cat, label: cat }))
                  ]}
                  className="min-w-[120px]"
                />
              </div>

              {/* Photo Type Filter */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground whitespace-nowrap">{t('admin.all_types')}:</span>
                <AdminSelect
                  value={photoTypeFilter}
                  onChange={setPhotoTypeFilter}
                  options={[
                    { value: 'all', label: t('gallery.all') },
                    { value: 'digital', label: t('admin.upload_type_digital') },
                    { value: 'film', label: t('admin.upload_type_film') },
                  ]}
                  className="min-w-[120px]"
                />
              </div>

              {/* Storage Filter */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground whitespace-nowrap">{t('ui.channel_filter')}:</span>
                <AdminSelect
                  value={channelFilter}
                  onChange={setChannelFilter}
                  options={[
                    { value: 'all', label: t('gallery.all') },
                    { value: 'local', label: 'Local' },
                    { value: 's3', label: 'S3' },
                    { value: 'github', label: 'GitHub' },
                  ]}
                  className="min-w-[130px]"
                />
              </div>

              {/* Album Filter */}
              <div className="flex items-center gap-2">
                <span className="text-xs text-muted-foreground whitespace-nowrap">{t('admin.album') || 'Album'}:</span>
                <AdminSelect
                  value={albumFilter}
                  onChange={setAlbumFilter}
                  options={[
                    { value: 'all', label: t('gallery.all') },
                    ...albums.map(album => ({ value: album.id, label: `${album.name} (${album.photoCount})` }))
                  ]}
                  className="min-w-[140px]"
                />
              </div>

              {/* Camera Filter */}
              {cameraOptions.length > 0 && (
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground whitespace-nowrap">{t('admin.camera') || 'Camera'}:</span>
                  <AdminSelect
                    value={cameraFilter}
                    onChange={setCameraFilter}
                    options={[
                      { value: 'all', label: t('gallery.all') },
                      ...cameraOptions
                    ]}
                    className="min-w-[160px]"
                  />
                </div>
              )}

              {/* Lens Filter */}
              {lensOptions.length > 0 && (
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground whitespace-nowrap">{t('admin.lens') || 'Lens'}:</span>
                  <AdminSelect
                    value={lensFilter}
                    onChange={setLensFilter}
                    options={[
                      { value: 'all', label: t('gallery.all') },
                      ...lensOptions
                    ]}
                    className="min-w-[160px]"
                  />
                </div>
              )}

              {/* Featured Toggle */}
              <label className={`flex items-center gap-2 px-3 py-1.5 border rounded-md cursor-pointer transition-colors ${
                onlyFeatured 
                  ? 'bg-amber-500/10 border-amber-500/30 text-amber-600' 
                  : 'bg-background border-border text-muted-foreground hover:text-foreground'
              }`}>
                <Star className={`w-3.5 h-3.5 ${onlyFeatured ? 'fill-current' : ''}`} />
                <span className="text-xs font-medium">{t('admin.feat')}</span>
                <input
                  type="checkbox"
                  checked={onlyFeatured}
                  onChange={() => setOnlyFeatured(!onlyFeatured)}
                  className="sr-only"
                />
              </label>

              {/* Clear Filters */}
              {activeFilterCount > 0 && (
                <>
                  <div className="h-5 w-px bg-border" />
                  <AdminButton
                    onClick={clearAllFilters}
                    adminVariant="unstyled"
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground transition-colors"
                  >
                    <X className="w-3.5 h-3.5" />
                    <span>{t('admin.clear_all_filters')}</span>
                  </AdminButton>
                </>
              )}
          </div>
        ) : undefined}
        activeFilters={activeFilterCount > 0 && !showFilters ? (
          <div className="mt-3 pt-3 border-t border-border flex flex-wrap items-center gap-2">
            <span className="text-xs text-muted-foreground">{t('admin.active_filters_label')}:</span>
            {categoryFilter !== 'all' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                {categoryFilter}
                <AdminButton
                  onClick={() => setCategoryFilter('all')}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-primary/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            {photoTypeFilter !== 'all' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                {t(`admin.upload_type_${photoTypeFilter}`)}
                <AdminButton
                  onClick={() => setPhotoTypeFilter('all')}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-primary/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            {channelFilter !== 'all' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                {channelFilter}
                <AdminButton
                  onClick={() => setChannelFilter('all')}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-primary/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            {albumFilter !== 'all' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                {albums.find(a => a.id === albumFilter)?.name || albumFilter}
                <AdminButton
                  onClick={() => setAlbumFilter('all')}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-primary/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            {cameraFilter !== 'all' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                {cameraOptions.find(c => c.value === cameraFilter)?.label || cameraFilter}
                <AdminButton
                  onClick={() => setCameraFilter('all')}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-primary/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            {lensFilter !== 'all' && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-primary/10 text-primary text-xs rounded-md">
                {lensOptions.find(l => l.value === lensFilter)?.label || lensFilter}
                <AdminButton
                  onClick={() => setLensFilter('all')}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-primary/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            {onlyFeatured && (
              <span className="inline-flex items-center gap-1 px-2 py-1 bg-amber-500/10 text-amber-600 text-xs rounded-md">
                <Star className="w-3 h-3 fill-current" />
                {t('admin.featured_only')}
                <AdminButton
                  onClick={() => setOnlyFeatured(false)}
                  adminVariant="icon"
                  size="xs"
                  className="p-0 hover:text-amber-500/70"
                >
                  <X className="w-3 h-3" />
                </AdminButton>
              </span>
            )}
            <AdminButton
              onClick={clearAllFilters}
              adminVariant="unstyled"
              className="text-xs text-muted-foreground hover:text-foreground underline"
            >
              {t('admin.clear_all_filters')}
            </AdminButton>
          </div>
        ) : undefined}
      />

      <div ref={scrollContainerRef} onScroll={handleScroll} className="flex-1 overflow-y-auto custom-scrollbar">
      {error && (
        <div className="p-4 bg-destructive/10 border border-destructive/30 rounded-lg text-destructive text-sm flex items-center gap-2">
          <X className="w-4 h-4 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {/* Photo Grid/List */}
      <div className="space-y-4">
        {loading ? (
          <div className={PHOTO_GRID_CLASS_NAME} style={{ '--admin-photo-grid-columns': String(gridColumns) } as React.CSSProperties}>
            {[...Array(12)].map((_, i) => (
              <div key={i} className="aspect-[4/5] bg-muted animate-pulse rounded-lg" />
            ))}
          </div>
        ) : (
          <div
            ref={viewMode === 'grid' ? gridContainerRef : undefined}
            className={
              viewMode === 'grid'
                ? PHOTO_GRID_CLASS_NAME
                : 'flex flex-col border border-border rounded-lg overflow-hidden'
            }
            style={viewMode === 'grid' ? { '--admin-photo-grid-columns': String(gridColumns) } as React.CSSProperties : undefined}
          >
            {filteredPhotos.map((photo) =>
              viewMode === 'grid' ? (
                <PhotoGridCard
                  key={photo.id}
                  photo={photo}
                  isSelected={selectedIds.has(photo.id)}
                  resolvedCdnDomain={resolvedCdnDomain}
                  onSelect={handleSelectPhoto}
                  onDelete={onDelete}
                  onToggleFeatured={onToggleFeatured}
                  onClick={handlePhotoClick}
                />
              ) : (
                <PhotoListRow
                  key={photo.id}
                  photo={photo}
                  isSelected={selectedIds.has(photo.id)}
                  resolvedCdnDomain={resolvedCdnDomain}
                  onSelect={handleSelectPhoto}
                  onDelete={onDelete}
                  onToggleFeatured={onToggleFeatured}
                  onClick={handlePhotoClick}
                />
              )
            )}
            {filteredPhotos.length === 0 && (
              <div className="col-span-full py-24 flex flex-col items-center justify-center text-muted-foreground">
                <ImageIcon className="w-16 h-16 mb-4 opacity-10" />
                <p className="text-sm font-medium mb-2">
                  {t('admin.no_photos')}
                </p>
                {activeFilterCount > 0 && (
                  <AdminButton
                    onClick={clearAllFilters}
                    adminVariant="link"
                    size="xs"
                    className="text-xs text-primary hover:underline normal-case"
                  >
                    Clear filters to see all photos
                  </AdminButton>
                )}
              </div>
            )}
          </div>
        )}
      </div>
      </div>

      <div
        className={`absolute bottom-6 left-1/2 -translate-x-1/2 z-20 flex items-center gap-3 px-5 py-3 bg-background/95 backdrop-blur-xl border border-border rounded-xl shadow-lg shadow-black/10 dark:shadow-black/30 transition-all duration-200 ease-out ${
          hasSelectedPhotos
            ? 'translate-y-0 opacity-100'
            : 'translate-y-5 opacity-0 pointer-events-none'
        }`}
      >
        <span className="text-sm font-medium text-primary">
          {selectedIds.size} {t('admin.selected') || 'selected'}
        </span>
        <div className="w-px h-5 bg-border" />
        <AdminButton
          onClick={onBatchAction}
          adminVariant="outline"
          size="sm"
          className="gap-1.5 rounded-lg text-xs font-medium"
        >
          <SlidersHorizontal className="w-3.5 h-3.5" />
          <span>{t('admin.batch_actions') || 'Batch actions'}</span>
        </AdminButton>
        <AdminButton
          onClick={() => onDelete()}
          adminVariant="destructiveOutline"
          size="sm"
          className="gap-1.5 rounded-lg text-xs font-medium"
        >
          <Trash2 className="w-3.5 h-3.5" />
          <span>{t('common.delete')}</span>
        </AdminButton>
      </div>
    </div>
  )
}

'use client'

import React, { useState, useEffect } from 'react'
import {
  Save,
  Loader2,
  X,
  Plus,
  MessageSquare,
  Globe,
  Check,
  Trash2,
  User,
  Link,
  Unlink,
  ChevronLeft,
  ChevronRight,
  Pencil,
  HardDrive,
  Github,
  Database,
} from 'lucide-react'
import {
  AdminSettingsDto,
  CommentDto,
  LinuxDoBinding,
  StorageSourceDto,
  StorageSourceCreateDto,
  StorageSourceUpdateDto,
  getComments,
  updateCommentStatus,
  deleteComment,
  getLinuxDoBinding,
  unbindLinuxDoAccount,
  getLinuxDoAuthUrl,
  isLinuxDoEnabled,
  getStorageSources,
  createStorageSource,
  updateStorageSource,
  deleteStorageSource,
  ApiUnauthorizedError,
} from '@/lib/api'
import { setAdminBindSession, setOAuthState } from '@/lib/auth-session'
import { AdminButton } from '@/components/admin/AdminButton'
import { AdminInput, AdminSelect } from '@/components/admin/AdminFormControls'
import { FormSkeleton, ListSkeleton } from '@/components/admin/Skeleton'
import { SimpleDeleteDialog } from '@/components/admin/SimpleDeleteDialog'

interface SettingsTabProps {
  token: string | null
  settings: AdminSettingsDto | null
  setSettings: (settings: AdminSettingsDto) => void
  categories: string[]
  loading: boolean
  saving: boolean
  error: string
  onSave: () => void
  t: (key: string) => string
  notify: (message: string, type?: 'success' | 'error' | 'info') => void
  onUnauthorized: () => void
}

export function SettingsTab({
  token,
  settings,
  setSettings,
  categories,
  loading,
  saving,
  error,
  onSave,
  t,
  notify,
  onUnauthorized,
}: SettingsTabProps) {
  const [settingsTab, setSettingsTab] = useState('site')
  const [comments, setComments] = useState<CommentDto[]>([])
  const [commentsLoading, setCommentsLoading] = useState(false)
  const [commentTab, setCommentTab] = useState<'manage' | 'config'>('manage')
  const [page, setPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [limit] = useState(20)
  const [commentStatusFilter, setCommentStatusFilter] = useState('')

  // Storage sources state
  const [storageSources, setStorageSources] = useState<StorageSourceDto[]>([])
  const [storageSourcesLoading, setStorageSourcesLoading] = useState(false)
  const [editingSource, setEditingSource] = useState<StorageSourceDto | null>(null)
  const [addingSourceType, setAddingSourceType] = useState<'github' | 's3' | null>(null)
  const [sourceForm, setSourceForm] = useState<Partial<StorageSourceCreateDto>>({})
  const [sourceSaving, setSourceSaving] = useState(false)

  // Linux DO binding state
  const [linuxDoEnabled, setLinuxDoEnabled] = useState(false)
  const [linuxDoBinding, setLinuxDoBinding] = useState<LinuxDoBinding | null>(null)
  const [linuxDoLoading, setLinuxDoLoading] = useState(false)
  const [linuxDoBindLoading, setLinuxDoBindLoading] = useState(false)
  const [deleteDialog, setDeleteDialog] = useState<
    | { type: 'linuxdo-unbind' }
    | null
  >(null)
  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null)

  // Reset confirm state when clicking outside
  useEffect(() => {
    if (!confirmingDeleteId) return
    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      if (!target.closest('[data-confirm-delete]')) {
        setConfirmingDeleteId(null)
      }
    }
    document.addEventListener('mousedown', handleClick)
    return () => document.removeEventListener('mousedown', handleClick)
  }, [confirmingDeleteId])

  const refreshStorageSources = async () => {
    if (!token) return
    setStorageSourcesLoading(true)
    try {
      const sources = await getStorageSources(token)
      setStorageSources(sources)
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    } finally {
      setStorageSourcesLoading(false)
    }
  }

  const handleSaveSource = async () => {
    if (!token) return
    setSourceSaving(true)
    try {
      if (editingSource) {
        const updated = await updateStorageSource(token, editingSource.id, sourceForm as StorageSourceUpdateDto)
        setStorageSources(prev => prev.map(s => s.id === updated.id ? updated : s))
      } else if (addingSourceType) {
        const created = await createStorageSource(token, { ...sourceForm, type: addingSourceType } as StorageSourceCreateDto)
        setStorageSources(prev => [...prev, created])
      }
      setEditingSource(null)
      setAddingSourceType(null)
      setSourceForm({})
      notify(t('admin.notify_success'))
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    } finally {
      setSourceSaving(false)
    }
  }

  const handleDeleteSource = async (id: string) => {
    if (!token) return
    try {
      await deleteStorageSource(token, id)
      setStorageSources(prev => prev.filter(s => s.id !== id))
      notify(t('admin.notify_success'))
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    }
  }

  const openEdit = (source: StorageSourceDto) => {
    setEditingSource(source)
    setAddingSourceType(null)
    setSourceForm({
      name: source.name,
      accessKey: source.accessKey ?? '',
      secretKey: source.secretKey ?? '',
      bucket: source.bucket ?? '',
      region: source.region ?? '',
      endpoint: source.endpoint ?? '',
      publicUrl: source.publicUrl ?? '',
      basePath: source.basePath ?? '',
      branch: source.branch ?? '',
      accessMethod: source.accessMethod ?? '',
    })
  }

  const openAdd = (type: 'github' | 's3') => {
    setAddingSourceType(type)
    setEditingSource(null)
    setSourceForm({ name: '', accessKey: '', secretKey: '', bucket: '', region: '', endpoint: '', publicUrl: '', basePath: '', branch: type === 'github' ? 'main' : '', accessMethod: type === 'github' ? 'jsdelivr' : '' })
  }

  const cancelSourceForm = () => {
    setEditingSource(null)
    setAddingSourceType(null)
    setSourceForm({})
  }

  const refreshComments = async () => {
    if (!token) return
    setCommentsLoading(true)
    try {
      const { data, meta } = await getComments(token, { page, limit, status: commentStatusFilter || undefined })
      setComments(data)
      setTotalPages(meta.totalPages)
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) {
        onUnauthorized()
        return
      }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    } finally {
      setCommentsLoading(false)
    }
  }

  const handleUpdateCommentStatus = async (
    id: string,
    status: 'approved' | 'rejected'
  ) => {
    if (!token) return
    try {
      await updateCommentStatus(token, id, status)
      await refreshComments()
      notify(t('admin.notify_success'))
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) {
        onUnauthorized()
        return
      }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    }
  }

  const handleDeleteComment = async (id: string) => {
    if (!token) return
    if (confirmingDeleteId === id) {
      // Second click — confirm delete
      try {
        await deleteComment(token, id)
        await refreshComments()
        notify(t('admin.notify_success'))
      } catch (err) {
        if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
        notify(err instanceof Error ? err.message : t('common.error'), 'error')
      } finally {
        setConfirmingDeleteId(null)
      }
    } else {
      // First click — enter confirm state
      setConfirmingDeleteId(id)
    }
  }

  // Load Linux DO status and binding
  const loadLinuxDoStatus = async () => {
    setLinuxDoLoading(true)
    try {
      const enabled = await isLinuxDoEnabled()
      setLinuxDoEnabled(enabled)
      if (enabled && token) {
        const binding = await getLinuxDoBinding(token)
        setLinuxDoBinding(binding)
      } else {
        setLinuxDoBinding(null)
      }
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) {
        onUnauthorized()
        return
      }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    } finally {
      setLinuxDoLoading(false)
    }
  }

  // Handle Linux DO bind
  const handleLinuxDoBind = async () => {
    if (!token) return
    try {
      setLinuxDoBindLoading(true)
      const { url, state } = await getLinuxDoAuthUrl()
      setOAuthState(state)
      setAdminBindSession(window.location.pathname)
      // Redirect to Linux DO auth
      window.location.href = url
    } catch (err) {
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
      setLinuxDoBindLoading(false)
    }
  }

  // Handle Linux DO unbind
  const handleLinuxDoUnbind = () => {
    if (!token) return
    setDeleteDialog({ type: 'linuxdo-unbind' })
  }

  const confirmDeleteDialog = async () => {
    if (!token || !deleteDialog) return

    try {
      setLinuxDoBindLoading(true)
      await unbindLinuxDoAccount(token)
      setLinuxDoBinding(null)
      notify(t('admin.notify_success'))
      setDeleteDialog(null)
    } catch (err) {
      if (err instanceof ApiUnauthorizedError) { onUnauthorized(); return }
      notify(err instanceof Error ? err.message : t('common.error'), 'error')
    } finally {
      setLinuxDoBindLoading(false)
    }
  }

  const handleCommentStatusChange = (status: string) => {
    setCommentStatusFilter(status)
    setPage(1)
  }

  useEffect(() => {
    loadLinuxDoStatus()
  }, [token]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (settingsTab === 'comments') {
      refreshComments()
    }
    if (settingsTab === 'account') {
      loadLinuxDoStatus()
    }
    if (settingsTab === 'storage') {
      refreshStorageSources()
    }
  }, [settingsTab, token, page, commentStatusFilter]) // eslint-disable-line react-hooks/exhaustive-deps

  const isSettingsReady = !loading && !!settings

  return (
    <>
      <div className="max-w-[1920px]">
      <div className="flex flex-col md:flex-row gap-12 relative">
        <aside className="w-full md:w-48 space-y-1 md:sticky md:top-0 md:h-fit">
          {[
            { id: 'site', label: t('admin.general') },
            { id: 'categories', label: t('admin.taxonomy') },
            { id: 'storage', label: t('admin.engine') },
            { id: 'comments', label: t('admin.comments') },
            { id: 'account', label: t('admin.account') },
          ].map((tab) => (
            <AdminButton
              key={tab.id}
              onClick={() => setSettingsTab(tab.id)}
              adminVariant="unstyled"
              className={`w-full flex items-center justify-between px-2 py-3 text-xs font-bold uppercase tracking-widest transition-all border-l-2 ${
                settingsTab === tab.id
                  ? 'border-primary text-primary pl-4'
                  : 'border-transparent text-muted-foreground hover:text-foreground pl-2'
              }`}
            >
              <span>{tab.label}</span>
            </AdminButton>
          ))}
        </aside>
        <div className="flex-1 min-h-[500px] flex flex-col">
          {error && (
            <div className="mb-8 p-4 border border-destructive text-destructive text-xs tracking-widest uppercase flex items-center space-x-2">
              <X className="w-4 h-4" />
              <span>{error}</span>
            </div>
          )}

          <div className="flex-1 space-y-12">
            {!isSettingsReady ? (
              <div className="max-w-2xl"><FormSkeleton rows={4} /></div>
            ) : (
              <>
            {settingsTab === 'site' && (
              <div className="max-w-2xl space-y-8">
                <div className="pb-4 border-b border-border">
                  <h3 className="font-serif text-2xl">{t('admin.general')}</h3>
                </div>
                <div className="space-y-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                      {t('admin.site_title')}
                    </label>
                    <AdminInput
                      variant="config"
                      value={settings.site_title}
                      disabled
                      className="opacity-60 cursor-not-allowed"
                    />
                    <p className="text-[10px] text-muted-foreground font-mono">
                      Configure via SITE_TITLE in .env file
                    </p>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                      {t('admin.cdn_host')}
                    </label>
                    <AdminInput
                      variant="config"
                      value={settings.cdn_domain}
                      disabled
                      className="opacity-60 cursor-not-allowed"
                      placeholder="https://cdn.example.com"
                    />
                    <p className="text-[10px] text-muted-foreground font-mono">
                      Configure via CDN_DOMAIN in .env file
                    </p>
                  </div>
                </div>
              </div>
            )}

            {settingsTab === 'categories' && (
              <div className="space-y-8">
                <div className="pb-4 border-b border-border">
                  <h3 className="font-serif text-2xl">{t('admin.taxonomy')}</h3>
                </div>
                <div className="flex flex-wrap gap-3">
                  {categories.map((cat) => (
                    <div
                      key={cat}
                      className="flex items-center space-x-2 px-4 py-2 bg-muted border border-border text-xs font-bold uppercase tracking-widest"
                    >
                      <span>{cat}</span>
                    </div>
                  ))}
                </div>
                <p className="text-[10px] text-muted-foreground font-mono">
                  Categories are automatically managed based on photo metadata.
                </p>
              </div>
            )}

            {settingsTab === 'storage' && (
              <div className="max-w-3xl space-y-8">
                <div className="pb-4 border-b border-border">
                  <h3 className="font-serif text-2xl">{t('admin.engine')}</h3>
                </div>

                {storageSourcesLoading ? (
                  <ListSkeleton count={3} />
                ) : (
                  <div className="space-y-4">
                    {storageSources.map((source) => {
                      const isEditing = editingSource?.id === source.id
                      const Icon = source.type === 'local' ? HardDrive : source.type === 'github' ? Github : Database
                      return (
                        <div key={source.id} className="border border-border bg-muted/10">
                          {/* Header row */}
                          <div className="flex items-center justify-between px-6 py-4">
                            <div className="flex items-center gap-3">
                              <Icon className="w-4 h-4 text-muted-foreground" />
                              <span className="font-bold text-sm">{source.name}</span>
                              <span className="text-[9px] font-black uppercase px-2 py-0.5 border border-border text-muted-foreground tracking-widest">
                                {source.type}
                              </span>
                            </div>
                            <div className="flex items-center gap-2">
                              <AdminButton
                                onClick={() => isEditing ? cancelSourceForm() : openEdit(source)}
                                adminVariant="icon"
                                title={isEditing ? t('common.cancel') : t('admin.edit')}
                              >
                                {isEditing ? <X className="w-4 h-4" /> : <Pencil className="w-4 h-4" />}
                              </AdminButton>
                              <AdminButton
                                onClick={() => handleDeleteSource(source.id)}
                                adminVariant="iconDestructive"
                                title={t('admin.delete')}
                              >
                                <Trash2 className="w-4 h-4" />
                              </AdminButton>
                            </div>
                          </div>

                          {/* Edit form */}
                          {isEditing && (
                            <div className="px-6 pb-6 pt-2 border-t border-border space-y-4">
                              <StorageSourceForm
                                type={source.type}
                                form={sourceForm}
                                setForm={setSourceForm}
                                token={token}
                                notify={notify}
                                t={t}
                              />
                              <div className="flex gap-3 pt-2">
                                <AdminButton
                                  onClick={handleSaveSource}
                                  disabled={sourceSaving}
                                  adminVariant="primary"
                                  size="none"
                                  className="px-6 py-3 flex items-center gap-2"
                                >
                                  {sourceSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
                                  <span>{t('admin.save')}</span>
                                </AdminButton>
                                <AdminButton onClick={cancelSourceForm} adminVariant="unstyled" className="px-6 py-3 border border-border text-xs font-bold uppercase tracking-widest">
                                  {t('common.cancel')}
                                </AdminButton>
                              </div>
                            </div>
                          )}
                        </div>
                      )
                    })}

                    {/* Add form */}
                    {addingSourceType && (
                      <div className="border border-primary/40 bg-muted/10 p-6 space-y-4">
                        <div className="flex items-center gap-2 pb-2 border-b border-border">
                          {addingSourceType === 'github' ? <Github className="w-4 h-4" /> : <Database className="w-4 h-4" />}
                          <span className="text-xs font-bold uppercase tracking-widest">
                            {t('admin.add')} {addingSourceType.toUpperCase()}
                          </span>
                        </div>
                        <StorageSourceForm
                          type={addingSourceType}
                          form={sourceForm}
                          setForm={setSourceForm}
                          token={token}
                          notify={notify}
                          t={t}
                        />
                        <div className="flex gap-3 pt-2">
                          <AdminButton
                            onClick={handleSaveSource}
                            disabled={sourceSaving}
                            adminVariant="primary"
                            size="none"
                            className="px-6 py-3 flex items-center gap-2"
                          >
                            {sourceSaving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
                            <span>{t('admin.add')}</span>
                          </AdminButton>
                          <AdminButton onClick={cancelSourceForm} adminVariant="unstyled" className="px-6 py-3 border border-border text-xs font-bold uppercase tracking-widest">
                            {t('common.cancel')}
                          </AdminButton>
                        </div>
                      </div>
                    )}

                    {/* Add buttons */}
                    {!addingSourceType && !editingSource && (
                      <div className="flex gap-3 pt-2">
                        {!storageSources.some(s => s.type === 'local') && (
                          <AdminButton
                            onClick={async () => {
                              if (!token) return
                              try {
                                const created = await createStorageSource(token, { name: 'Local', type: 'local' } as StorageSourceCreateDto)
                                setStorageSources(prev => [...prev, created])
                                notify(t('admin.notify_success'))
                              } catch (err) {
                                notify(err instanceof Error ? err.message : t('common.error'), 'error')
                              }
                            }}
                            adminVariant="unstyled"
                            className="flex items-center gap-2 px-4 py-2.5 border border-border text-xs font-bold uppercase tracking-widest hover:border-foreground transition-all"
                          >
                            <Plus className="w-3.5 h-3.5" />
                            <HardDrive className="w-3.5 h-3.5" />
                            Local
                          </AdminButton>
                        )}
                        <AdminButton
                          onClick={() => openAdd('github')}
                          adminVariant="unstyled"
                          className="flex items-center gap-2 px-4 py-2.5 border border-border text-xs font-bold uppercase tracking-widest hover:border-foreground transition-all"
                        >
                          <Plus className="w-3.5 h-3.5" />
                          <Github className="w-3.5 h-3.5" />
                          GitHub
                        </AdminButton>
                        <AdminButton
                          onClick={() => openAdd('s3')}
                          adminVariant="unstyled"
                          className="flex items-center gap-2 px-4 py-2.5 border border-border text-xs font-bold uppercase tracking-widest hover:border-foreground transition-all"
                        >
                          <Plus className="w-3.5 h-3.5" />
                          <Database className="w-3.5 h-3.5" />
                          S3
                        </AdminButton>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {settingsTab === 'comments' && (
              <div className="space-y-8">
                <div className="flex space-x-1 border-b border-border">
                  {(['manage', 'config'] as const).map((tab) => (
                    <AdminButton
                      key={tab}
                      onClick={() => setCommentTab(tab)}
                      adminVariant="tab"
                      size="none"
                      data-state={commentTab === tab ? 'active' : 'inactive'}
                      className="px-6 py-3"
                    >
                      {t(`admin.comments_tabs_${tab}`)}
                    </AdminButton>
                  ))}
                </div>

                {commentTab === 'config' && (
                  <div className="max-w-2xl space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="pb-4 border-b border-border">
                      <h3 className="font-serif text-2xl">
                        {t('admin.comments_config')}
                      </h3>
                    </div>
                    <div className="space-y-6">
                      <div className="flex items-center justify-between p-4 border border-border bg-muted/10">
                        <div>
                          <label className="text-[10px] font-bold text-foreground uppercase tracking-widest">
                            {t('admin.comment_moderation')}
                          </label>
                          <p className="text-[10px] text-muted-foreground mt-1">
                            Require approval for new comments
                          </p>
                        </div>
                        <input
                          type="checkbox"
                          checked={settings.comment_moderation || false}
                          onChange={(e) =>
                            setSettings({
                              ...settings,
                              comment_moderation: e.target.checked,
                            })
                          }
                          className="w-5 h-5 accent-primary cursor-pointer"
                        />
                      </div>

                      <div className="space-y-2">
                        <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                          {t('admin.comment_provider')}
                        </label>
                        <AdminSelect
                          value={settings.comment_provider || 'local'}
                          onChange={(value) =>
                            setSettings({
                              ...settings,
                              comment_provider: value,
                            })
                          }
                          options={[
                            { value: 'local', label: 'Local (Basic)' },
                            { value: 'openai', label: 'OpenAI' },
                            { value: 'gemini', label: 'Google Gemini' },
                            { value: 'anthropic', label: 'Anthropic Claude' },
                          ]}
                        />
                      </div>

                      {settings.comment_provider &&
                        settings.comment_provider !== 'local' && (
                          <div className="space-y-6 p-6 border border-border bg-muted/20">
                            <div className="space-y-2">
                              <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                                {t('admin.comment_api_key')}
                              </label>
                              <AdminInput
                                variant="config"
                                type="password"
                                value={settings.comment_api_key || ''}
                                onChange={(e) =>
                                  setSettings({
                                    ...settings,
                                    comment_api_key: e.target.value,
                                  })
                                }
                                placeholder="sk-..."
                              />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                                {t('admin.comment_endpoint')}
                              </label>
                              <AdminInput
                                variant="config"
                                type="text"
                                value={settings.comment_api_endpoint || ''}
                                onChange={(e) =>
                                  setSettings({
                                    ...settings,
                                    comment_api_endpoint: e.target.value,
                                  })
                                }
                                placeholder="https://api.openai.com/v1"
                              />
                            </div>
                            <div className="space-y-2">
                              <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                                {t('admin.comment_model')}
                              </label>
                              <AdminInput
                                variant="config"
                                type="text"
                                value={settings.comment_model || ''}
                                onChange={(e) =>
                                  setSettings({
                                    ...settings,
                                    comment_model: e.target.value,
                                  })
                                }
                                placeholder="gpt-4o, gemini-pro..."
                              />
                            </div>
                          </div>
                        )}

                      <div className="space-y-2">
                        <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest">
                          {t('admin.blocked_keywords')}
                        </label>
                        <textarea
                          value={settings.blocked_keywords || ''}
                          onChange={(e) =>
                            setSettings({
                              ...settings,
                              blocked_keywords: e.target.value,
                            })
                          }
                          placeholder="comma, separated, keywords"
                          className="w-full p-4 h-32 bg-transparent border border-border focus:border-primary outline-none text-sm transition-colors rounded-none resize-none font-mono"
                        />
                        <p className="text-[10px] text-muted-foreground font-mono">
                          Comments containing these keywords will be automatically rejected.
                        </p>
                      </div>
                    </div>
                  </div>
                )}

                {commentTab === 'manage' && (
                  <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="pb-4 border-b border-border flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <h3 className="font-serif text-2xl">
                          {t('admin.comments_manage')}
                        </h3>
                        <div className="flex bg-background border border-border rounded-md overflow-hidden">
                          {[
                            { value: '', label: t('admin.all') },
                            { value: 'pending', label: t('admin.pending') },
                            { value: 'approved', label: t('admin.published') },
                            { value: 'rejected', label: t('admin.rejected') },
                          ].map(opt => (
                            <AdminButton
                              key={opt.value}
                              onClick={() => handleCommentStatusChange(opt.value)}
                              adminVariant="unstyled"
                              className={`px-3 py-1.5 text-xs font-medium transition-colors ${
                                commentStatusFilter === opt.value
                                  ? 'bg-primary/10 text-primary'
                                  : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                              }`}
                            >
                              {opt.label}
                            </AdminButton>
                          ))}
                        </div>
                      </div>
                      <AdminButton
                        onClick={refreshComments}
                        adminVariant="icon"
                      >
                        <Globe className="w-4 h-4" />
                      </AdminButton>
                    </div>

                    {commentsLoading ? (
                      <div className="space-y-4">
                        {[...Array(3)].map((_, i) => (
                          <div
                            key={i}
                            className="h-20 bg-muted animate-pulse"
                          />
                        ))}
                      </div>
                    ) : comments.length === 0 ? (
                      <div className="py-12 text-center border border-dashed border-border">
                        <MessageSquare className="w-8 h-8 mx-auto mb-4 opacity-20" />
                        <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
                          No comments found
                        </p>
                      </div>
                    ) : (
                      <div className="grid gap-4">
                        {comments.map((comment) => (
                          <div
                            key={comment.id}
                            className="p-6 border border-border hover:border-primary transition-all bg-card/30"
                          >
                            <div className="flex items-start justify-between gap-4">
                              {/* Avatar */}
                              <div className="flex-shrink-0">
                                {comment.avatarUrl ? (
                                  <img
                                    src={comment.avatarUrl}
                                    alt={comment.author}
                                    className="w-10 h-10 rounded-full object-cover border border-border"
                                  />
                                ) : (
                                  <div className="w-10 h-10 rounded-full bg-muted flex items-center justify-center border border-border">
                                    <span className="text-sm font-bold text-muted-foreground">
                                      {comment.author.charAt(0).toUpperCase()}
                                    </span>
                                  </div>
                                )}
                              </div>
                              <div className="space-y-2 flex-1">
                                <div className="flex items-center gap-3">
                                  <span className="text-xs font-bold uppercase tracking-wider">
                                    {comment.author}
                                  </span>
                                  <span
                                    className={`text-[8px] font-black uppercase px-1.5 py-0.5 border ${
                                      comment.status === 'approved'
                                        ? 'border-primary text-primary'
                                        : comment.status === 'rejected'
                                        ? 'border-destructive text-destructive'
                                        : 'border-amber-500 text-amber-500'
                                    }`}
                                  >
                                    {comment.status}
                                  </span>
                                  <span className="text-[10px] text-muted-foreground font-mono">
                                    {new Date(comment.createdAt).toLocaleString()}
                                  </span>
                                </div>
                                <p className="text-sm text-foreground/80 leading-relaxed">
                                  {comment.content}
                                </p>
                              </div>

                              <div className="flex items-center gap-2">
                                {comment.status !== 'approved' && (
                                  <AdminButton
                                    onClick={() =>
                                      handleUpdateCommentStatus(
                                        comment.id,
                                        'approved'
                                      )
                                    }
                                    adminVariant="iconPrimary"
                                    title="Approve"
                                  >
                                    <Check className="w-4 h-4" />
                                  </AdminButton>
                                )}
                                {comment.status !== 'rejected' && (
                                  <AdminButton
                                    onClick={() =>
                                      handleUpdateCommentStatus(
                                        comment.id,
                                        'rejected'
                                      )
                                    }
                                    adminVariant="iconDestructive"
                                    title="Reject"
                                  >
                                    <X className="w-4 h-4" />
                                  </AdminButton>
                                )}
                                <AdminButton
                                  onClick={() =>
                                    handleDeleteComment(comment.id)
                                  }
                                  adminVariant={confirmingDeleteId === comment.id ? 'unstyled' : 'iconDestructive'}
                                  className={confirmingDeleteId === comment.id ? 'p-2 bg-destructive text-destructive-foreground hover:bg-destructive/80 rounded' : ''}
                                  title={t('common.delete')}
                                  data-confirm-delete={confirmingDeleteId === comment.id ? '' : undefined}
                                >
                                  {confirmingDeleteId === comment.id ? (
                                    <Check className="w-4 h-4" />
                                  ) : (
                                    <Trash2 className="w-4 h-4" />
                                  )}
                                </AdminButton>
                              </div>
                            </div>
                          </div>
                        ))}

                        {/* Pagination */}
                        {totalPages > 1 && (
                          <div className="flex items-center justify-center gap-4 mt-8">
                            <AdminButton
                              onClick={() => setPage((p) => Math.max(1, p - 1))}
                              disabled={page === 1}
                              adminVariant="unstyled"
                              className="p-2 border border-border disabled:opacity-50 disabled:cursor-not-allowed hover:bg-muted/50 transition-colors"
                            >
                              <ChevronLeft className="w-4 h-4" />
                            </AdminButton>
                            <span className="text-xs font-mono">
                              {page} / {totalPages}
                            </span>
                            <AdminButton
                              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                              disabled={page === totalPages}
                              adminVariant="unstyled"
                              className="p-2 border border-border disabled:opacity-50 disabled:cursor-not-allowed hover:bg-muted/50 transition-colors"
                            >
                              <ChevronRight className="w-4 h-4" />
                            </AdminButton>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}

            {settingsTab === 'account' && (
              <div className="max-w-2xl space-y-8">
                <div className="pb-4 border-b border-border">
                  <h3 className="font-serif text-2xl">{t('admin.account')}</h3>
                </div>

                {/* Linux DO Binding Section */}
                <div className="space-y-6">
                  <div className="pb-4 border-b border-border/50">
                    <div className="flex items-center gap-2">
                      <svg className="w-5 h-5 text-[#f8d568]" viewBox="0 0 24 24" fill="currentColor">
                        <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
                      </svg>
                      <h4 className="text-[10px] font-bold text-foreground uppercase tracking-widest">
                        Linux DO
                      </h4>
                    </div>
                    <p className="text-[10px] text-muted-foreground mt-2">
                      {t('admin.linuxdo_binding_desc')}
                    </p>
                  </div>

                  {!linuxDoEnabled ? (
                    <div className="p-6 border border-dashed border-border text-center">
                      <p className="text-xs text-muted-foreground">
                        {t('admin.linuxdo_not_configured')}
                      </p>
                      <p className="text-[10px] text-muted-foreground/70 mt-2 font-mono">
                        Configure LINUXDO_CLIENT_ID and LINUXDO_CLIENT_SECRET in .env
                      </p>
                    </div>
                  ) : linuxDoLoading ? (
                    <div className="flex items-center justify-center p-8">
                      <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
                    </div>
                  ) : linuxDoBinding ? (
                    <div className="p-6 border border-border bg-muted/10 space-y-6">
                      <div className="flex items-center gap-4">
                        {linuxDoBinding.avatarUrl ? (
                          <img
                            src={linuxDoBinding.avatarUrl}
                            alt={linuxDoBinding.username || ''}
                            className="w-12 h-12 rounded-full border border-border"
                          />
                        ) : (
                          <div className="w-12 h-12 rounded-full border border-border bg-muted flex items-center justify-center">
                            <User className="w-6 h-6 text-muted-foreground" />
                          </div>
                        )}
                        <div>
                          <p className="font-bold text-foreground">
                            {linuxDoBinding.username}
                          </p>
                          {linuxDoBinding.trustLevel !== null && (
                            <p className="text-[10px] text-muted-foreground font-mono">
                              Trust Level: {linuxDoBinding.trustLevel}
                            </p>
                          )}
                        </div>
                        <div className="ml-auto">
                          <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-primary/10 text-primary text-[9px] font-bold uppercase tracking-widest border border-primary/20">
                            <Link className="w-3 h-3" />
                            {t('admin.linuxdo_bound')}
                          </span>
                        </div>
                      </div>
                      <AdminButton
                        onClick={handleLinuxDoUnbind}
                        disabled={linuxDoBindLoading}
                        adminVariant="unstyled"
                        className="w-full py-3 border border-destructive/50 text-destructive hover:bg-destructive/10 text-xs font-bold uppercase tracking-widest transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                      >
                        {linuxDoBindLoading ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <Unlink className="w-4 h-4" />
                        )}
                        {t('admin.linuxdo_unbind')}
                      </AdminButton>
                    </div>
                  ) : (
                    <div className="p-6 border border-dashed border-border text-center space-y-4">
                      <div className="space-y-2">
                        <p className="text-xs text-muted-foreground">
                          {t('admin.linuxdo_not_bound')}
                        </p>
                        <p className="text-[10px] text-muted-foreground/70">
                          {t('admin.linuxdo_bind_hint')}
                        </p>
                      </div>
                      <AdminButton
                        onClick={handleLinuxDoBind}
                        disabled={linuxDoBindLoading}
                        adminVariant="unstyled"
                        className="px-6 py-3 bg-[#f8d568] text-[#1a1a1a] hover:bg-[#f5c842] text-xs font-bold uppercase tracking-widest transition-all disabled:opacity-50 flex items-center justify-center gap-2 mx-auto"
                      >
                        {linuxDoBindLoading ? (
                          <Loader2 className="w-4 h-4 animate-spin" />
                        ) : (
                          <Link className="w-4 h-4" />
                        )}
                        {t('admin.linuxdo_bind')}
                      </AdminButton>
                    </div>
                  )}
                </div>
              </div>
            )}

            {settingsTab !== 'site' && settingsTab !== 'account' && settingsTab !== 'storage' && settingsTab !== 'comments' && (
              <div className="pt-8 border-t border-border flex justify-end">
                <AdminButton
                  onClick={onSave}
                  disabled={saving}
                  adminVariant="primary"
                  size="none"
                  className="px-8 py-4 flex items-center space-x-2"
                >
                  {saving ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : (
                    <Save className="w-4 h-4" />
                  )}
                  <span>{t('admin.save')}</span>
                </AdminButton>
              </div>
            )}
              </>
            )}
          </div>
        </div>
      </div>
      </div>
      <SimpleDeleteDialog
        isOpen={deleteDialog !== null}
        title={t('common.confirm')}
        message={t('admin.linuxdo_unbind_confirm')}
        onConfirm={confirmDeleteDialog}
        onCancel={() => {
          if (!linuxDoBindLoading) {
            setDeleteDialog(null)
          }
        }}
        t={t}
      />
    </>
  )
}

// ─── StorageSourceForm ────────────────────────────────────────────────────────

function StorageSourceForm({
  type,
  form,
  setForm,
  token,
  notify,
  t,
}: {
  type: 'local' | 'github' | 's3'
  form: Partial<StorageSourceCreateDto>
  setForm: (f: Partial<StorageSourceCreateDto>) => void
  token: string | null
  notify: (msg: string, type?: 'success' | 'error' | 'info') => void
  t: (key: string) => string
}) {
  const f = (field: string, value: string) => setForm({ ...form, [field]: value })

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {/* Name (all types) */}
      <div className="md:col-span-2 space-y-1.5">
        <label className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">Name</label>
        <AdminInput variant="config" value={form.name ?? ''} onChange={e => f('name', e.target.value)} placeholder="My Storage" />
      </div>

      {/* Local */}
      {type === 'local' && (
        <div className="md:col-span-2 space-y-1.5">
          <label className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">{t('admin.path_prefix')}</label>
          <AdminInput variant="config" value={form.basePath ?? ''} onChange={e => f('basePath', e.target.value)} placeholder="photos (appended to public/uploads/)" />
          <p className="text-[10px] text-muted-foreground font-mono">Stored under public/uploads/{'<path>'}. Leave blank for root.</p>
        </div>
      )}

      {/* GitHub */}
      {type === 'github' && (<>
        <div className="md:col-span-2 space-y-1.5">
          <label className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">Personal Access Token</label>
          <AdminInput variant="config" type="password" value={form.accessKey ?? ''} onChange={e => f('accessKey', e.target.value)} placeholder={t('admin.gh_placeholder_token')} />
        </div>
        <div className="space-y-1.5">
          <label className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">Repo (owner/repo)</label>
          <AdminInput variant="config" value={form.bucket ?? ''} onChange={e => f('bucket', e.target.value)} placeholder={t('admin.gh_placeholder_repo')} />
        </div>
        <div className="space-y-1.5">
          <div className="flex justify-between items-center">
            <label className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">{t('admin.gh_branch')}</label>
            <AdminButton
              onClick={async () => {
                if (!form.accessKey || !form.bucket) { notify('Token and Repo required', 'info'); return }
                try {
                  const res = await fetch(`https://api.github.com/repos/${form.bucket}/branches`, { headers: { Authorization: `token ${form.accessKey}` } })
                  if (!res.ok) throw new Error('Failed')
                  const data = await res.json()
                  const names = Array.isArray(data) ? data.map((b: unknown) => typeof b === 'object' && b && 'name' in b ? (b as Record<string,unknown>).name : null).filter((n): n is string => typeof n === 'string') : []
                  notify(`${t('admin.notify_gh_branches')}: ${names.join(', ')}`, 'info')
                } catch { notify('Error fetching branches', 'error') }
              }}
              adminVariant="unstyled"
              className="text-[8px] font-bold text-primary uppercase hover:underline"
            >{t('admin.gh_test')}</AdminButton>
          </div>
          <AdminInput variant="config" value={form.branch ?? ''} onChange={e => f('branch', e.target.value)} placeholder="main" />
        </div>
        <div className="md:col-span-2 space-y-1.5">
          <label className="text-[9px] font-black uppercase text-muted-foreground tracking-widest">{t('admin.path_prefix')}</label>
