        </button>

        {/* 搜索 */}
        <div className="relative min-w-0 max-w-sm flex-1">
          <Search size={14} className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground" />
          <input
            type="text"
            value={searchInput}
            onChange={event => setSearchInput(event.target.value)}
            onKeyDown={event => event.key === 'Enter' && setSearch(searchInput.trim())}
            placeholder={t('common.search')}
            className="h-8 w-full rounded-md border border-border bg-background pl-8 pr-8 text-xs outline-none focus:border-primary"
          />
          {searchInput && (
            <button
              type="button"
              onClick={clearSearch}
              aria-label={t('common.close')}
              className="absolute right-1.5 top-1/2 -translate-y-1/2 rounded p-1 text-muted-foreground hover:bg-secondary"
            >
              <X size={13} />
            </button>
          )}
        </div>
      </div>

      {/* 主区域：左侧概览/文件夹 + 右侧文件列表（桌面 master-detail） */}
      <div className="flex min-h-0 flex-1">
        <aside className="flex w-72 shrink-0 flex-col overflow-hidden border-r border-border bg-card">
          {/* 状态概览 */}
          <div className="shrink-0 border-b border-border">
            <SectionHeader
              label={t('admin.storage_section_overview')}
              count={files.length}
              open={sections.overview}
              onToggle={() => toggleSection('overview')}
            />
            {sections.overview && (
              <div className="p-2">
                {statItems.map(item => {
                  const active = statusFilter === item.status
                  return (
                    <button
                      key={item.status || 'total'}
                      type="button"
                      onClick={() => {
                        setFolderFilter(null)
                        setStatusFilter(item.status)
