              </div>
            )}
          </div>

          {/* 文件夹（树形） */}
          <div className="flex min-h-0 flex-1 flex-col">
            <SectionHeader
              label={t('admin.storage_section_folders')}
              count={folderTreeNodeCount}
              open={sections.folders}
