            />
            {sections.folders && (
              <div className="min-h-0 flex-1 overflow-y-auto p-2">
                <button
                  type="button"
                  onClick={() => setFolderFilter(null)}
                  className="mb-0.5 flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-xs transition-colors hover:bg-secondary"
                  style={{ backgroundColor: folderFilter === null ? 'var(--accent)' : undefined }}
                >
                  <FolderOpen size={13} className="shrink-0 text-muted-foreground" />
                  <span
                    className="min-w-0 flex-1 truncate text-left"
                    style={{ color: folderFilter === null ? 'var(--accent-foreground)' : 'var(--foreground)' }}
                  >
                    {t('admin.storage_all_folders')}
                  </span>
                  <span
                    className="rounded bg-secondary px-1.5 py-0.5 text-[10px] tabular-nums"
                    style={{ color: folderFilter === null ? 'var(--accent-foreground)' : 'var(--muted-foreground)' }}
                  >
                    {baseList.length}
                  </span>
                </button>

                {renderFolderTree(folderTree)}

                {folderTree.length === 0 && (
                  <div className="px-2 py-6 text-center text-[11px] text-muted-foreground">
                    {t('admin.storage_no_files')}
                  </div>
                )}
              </div>
            )}
          </div>
        </aside>

        {/* 右侧文件列表 */}
        <main className="flex min-w-0 flex-1 flex-col overflow-hidden">
          {/* 列表头 */}
          <div className="flex h-9 shrink-0 items-center justify-between gap-2 border-b border-border px-3">
            <div className="flex min-w-0 items-center gap-2">
              {folderFilter ? (
                <span className="flex items-center gap-1.5 rounded-md border border-border bg-secondary px-2 py-1 text-[10px]">
                  <Folder size={11} className="text-muted-foreground" />
                  <span className="max-w-56 truncate font-mono">{folderFilter}</span>
                  <button
                    type="button"
                    onClick={() => setFolderFilter(null)}
                    aria-label={t('common.close')}
                    className="rounded p-0.5 hover:bg-black/10"
                  >
                    <X size={10} />
                  </button>
                </span>
              ) : (
                <span className="text-[10px] font-medium uppercase tracking-[0.16em] text-muted-foreground">
                  {t('admin.storage_file_list')}
                </span>
              )}
              <span className="rounded bg-secondary px-1.5 py-0.5 text-[10px] tabular-nums text-muted-foreground">
                {visibleFiles.length}
              </span>
              {issuesOnly && (
                <span className="flex items-center gap-1 rounded-full bg-amber-500/10 px-2 py-0.5 text-[10px] font-medium text-amber-600 dark:text-amber-400">
                  <AlertTriangle size={10} />
                  {t('admin.storage_only_issues')}
                </span>
              )}
            </div>
            <button
              type="button"
              onClick={() => setShowGuide(value => !value)}
              className="flex shrink-0 items-center gap-1 rounded px-1.5 py-1 text-[10px] transition-colors hover:bg-secondary"
              style={{ color: showGuide ? 'var(--primary)' : 'var(--muted-foreground)' }}
            >
              <CircleHelp size={12} />
              {t('admin.storage_help_title')}
            </button>
          </div>

          {/* 状态说明 */}
          {showGuide && (
            <div className="flex shrink-0 flex-wrap items-center gap-x-4 gap-y-1 border-b border-border px-3 py-1.5 text-[10px] text-muted-foreground">
              <span className="flex items-center gap-1">
                <CheckCircle2 size={11} className="shrink-0 text-emerald-500" />
                {t('admin.storage_help_linked')}
              </span>
              <span className="flex items-center gap-1">
                <AlertTriangle size={11} className="shrink-0 text-amber-500" />
                {t('admin.storage_help_orphan')}
              </span>
              <span className="flex items-center gap-1">
                <XCircle size={11} className="shrink-0 text-red-500" />
                {t('admin.storage_help_missing')}
              </span>
            </div>
          )}

          {/* 选中操作条 */}
          {selected.size > 0 && (
            <div className="flex shrink-0 flex-wrap items-center gap-2 border-b border-border bg-primary/5 px-3 py-2">
              <span className="text-xs font-semibold text-primary">
                {t('admin.selected')} {selected.size}
              </span>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={selectAllActionable}
                  className="flex h-7 items-center gap-1.5 rounded-md border border-border px-2.5 text-[11px] transition-colors hover:bg-secondary"
                >
                  <CheckCircle2 size={12} />
                  {t('admin.storage_select_all')}
                </button>
                <button
                  type="button"
                  onClick={() => setCleanupDialogOpen(true)}
                  disabled={cleanupDeleting}
                  className="flex h-7 items-center gap-1.5 rounded-md bg-destructive px-2.5 text-[11px] font-medium text-destructive-foreground transition-opacity hover:opacity-90 disabled:cursor-wait disabled:opacity-50"
                >
                  {cleanupDeleting ? <Loader2 size={12} className="animate-spin" /> : <Trash2 size={12} />}
                  {t('admin.storage_cleanup_selected')}
                </button>
                <button
                  type="button"
                  onClick={clearSelection}
                  disabled={cleanupDeleting}
                  className="flex h-7 items-center rounded-md border border-border px-2.5 text-[11px] transition-colors hover:bg-secondary disabled:opacity-50"
                >
                  {t('common.cancel')}
                </button>
              </div>
            </div>
          )}

          {/* 列头 */}
          {visibleFiles.length > 0 && !loading && (
            <div className="hidden shrink-0 items-center gap-3 border-b border-border px-3 py-1.5 text-[10px] font-medium uppercase tracking-[0.14em] text-muted-foreground lg:flex">
              <span className="flex w-8 shrink-0">
                <input
                  type="checkbox"
                  className="size-4 accent-[var(--primary)]"
                  checked={allActionableSelected}
                  onChange={event => (event.target.checked ? selectAllActionable() : clearSelection())}
                  disabled={actionable.length === 0}
                  aria-label={t('admin.storage_select_all')}
                />
              </span>
              <span className="w-12 shrink-0" />
              <span className="min-w-0 flex-1">{t('admin.storage_file_key')}</span>
              <span className="hidden w-44 shrink-0 xl:block">{t('admin.photo_title')}</span>
              <span className="w-16 shrink-0 text-right">{t('admin.storage_file_size')}</span>
              <span className="hidden w-24 shrink-0 text-right md:block">{t('admin.storage_last_modified')}</span>
              <span className="w-28 shrink-0 text-right">{t('admin.storage_file_status')}</span>
              <span className="w-14 shrink-0" />
            </div>
          )}

          {/* 文件行 */}
          <div className="min-h-0 flex-1 overflow-y-auto">
            {loading ? (
              Array.from({ length: 6 }, (_, index) => (
                <div key={index} className="flex items-center gap-3 border-b border-border px-3 py-2">
                  <div className="size-4 shrink-0 animate-pulse rounded bg-muted" />
                  <div className="size-11 shrink-0 animate-pulse rounded-md bg-muted" />
                  <div className="min-w-0 flex-1 space-y-1.5">
                    <div className="h-3 w-1/3 animate-pulse rounded bg-muted" />
                    <div className="h-2 w-1/4 animate-pulse rounded bg-muted" />
                  </div>
                </div>
              ))
            ) : files.length === 0 ? (
              <div className="flex h-full min-h-48 flex-col items-center justify-center gap-3 p-6 text-muted-foreground">
                <span className="flex size-14 items-center justify-center rounded-lg bg-muted">
                  <HardDrive size={24} />
                </span>
                <p className="text-sm">{t('admin.storage_no_files')}</p>
                <button
                  type="button"
                  onClick={() => void loadFiles()}
                  className="flex items-center gap-1.5 rounded-md border border-border px-3 py-1.5 text-xs hover:bg-secondary"
                >
                  <HardDrive size={14} />
                  {t('admin.storage_scan')}
                </button>
              </div>
            ) : visibleFiles.length === 0 ? (
              <div className="flex h-full min-h-48 flex-col items-center justify-center gap-3 p-6 text-muted-foreground">
                <span className="flex size-14 items-center justify-center rounded-lg bg-muted">
                  <Search size={24} />
                </span>
                <p className="text-sm">{t('admin.storage_no_match')}</p>
                <button
                  type="button"
                  onClick={resetFilters}
                  className="text-xs text-muted-foreground underline-offset-2 hover:underline"
                >
                  {t('common.reset')}
                </button>
              </div>
            ) : (
              visibleFiles.map(file => {
                const selectedRow = selected.has(file.key)
                const name = file.key.split('/').pop() || file.key
                const missing = isMissingStatus(file.status)
                return (
                  <div
                    key={file.key}
                    className="group flex items-center gap-3 border-b border-border px-3 py-2 transition-colors hover:bg-muted/30"
                    style={{ backgroundColor: selectedRow ? 'color-mix(in srgb, var(--accent) 55%, transparent)' : undefined }}
                  >
                    <span className="flex w-8 shrink-0">
                      <input
                        type="checkbox"
                        className="size-4 accent-[var(--primary)]"
                        checked={selectedRow}
                        onChange={() => toggleSelect(file.key)}
                        disabled={file.status === 'linked'}
                        title={file.status === 'linked' ? t('admin.storage_help_linked') : undefined}
                      />
                    </span>
                    <FileThumb
                      file={file}
                      onClick={() => { if (missing || isImageFile(file.key)) missing ? setReuploadFile(file) : setPreviewUrl(file.url) }}
                    />
                    <div className="min-w-0 flex-1">
                      <div
                        className={`truncate font-mono text-xs ${
                          missing
                            ? 'cursor-pointer hover:text-red-500 hover:underline'
                            : isImageFile(file.key)
                              ? 'cursor-pointer text-foreground hover:text-primary hover:underline'
                              : ''
                        }`}
                        title={file.key}
                        onClick={() => {
                          if (missing) setReuploadFile(file)
                          else if (isImageFile(file.key)) setPreviewUrl(file.url)
                        }}
                      >
                        {name}
                      </div>
                      <div className="truncate text-[10px] text-muted-foreground">
                        {folderOf(file.key)}
                      </div>
                    </div>
                    <span className="hidden w-44 shrink-0 truncate text-xs text-muted-foreground xl:block" title={file.photoTitle}>
                      {file.photoTitle || '-'}
                    </span>
                    <span className="w-16 shrink-0 text-right text-xs tabular-nums">{formatSize(file.size)}</span>
                    <span className="hidden w-24 shrink-0 text-right text-[11px] text-muted-foreground md:block">
                      {file.lastModified ? new Date(file.lastModified).toLocaleDateString() : '-'}
                    </span>
                    <span className="flex w-28 shrink-0 justify-end">
                      <StatusPill status={file.status} t={t} />
                    </span>
                    <span className="flex w-14 shrink-0 items-center justify-end gap-0.5 opacity-0 transition-opacity group-hover:opacity-100 focus-visible:opacity-100">
                      {isImageFile(file.key) && !missing && (
                        <button
                          type="button"
                          onClick={() => setPreviewUrl(file.url)}
                          title={t('admin.preview')}
                          className="rounded p-1 text-muted-foreground transition-colors hover:bg-secondary"
                        >
                          <Eye size={13} />
                        </button>
                      )}
                      {file.status === 'linked' && !file.hasThumb && (
                        <button
                          type="button"
                          onClick={() => void handleGenerateThumb(file)}
                          disabled={generatingThumb.has(file.photoId || '')}
                          title={t('admin.storage_generate')}
                          className="rounded p-1 transition-colors hover:bg-secondary"
                          style={{ color: generatingThumb.has(file.photoId || '') ? 'var(--muted-foreground)' : 'var(--primary)' }}
                        >
                          {generatingThumb.has(file.photoId || '') ? (
                            <Loader2 size={13} className="animate-spin" />
                          ) : (
                            <RefreshCw size={13} />
                          )}
                        </button>
                      )}
                    </span>
                  </div>
                )
              })
            )}
          </div>
        </main>
      </div>

      {/* 底部状态栏：与照片库一致 */}
      <div className="flex min-h-10 shrink-0 items-center gap-3 border-t border-border bg-card px-4">
        <div className="flex min-w-0 flex-1 items-center gap-2 overflow-hidden whitespace-nowrap text-[11px] text-muted-foreground">
          <span>{stats.total} {t('admin.storage_file_unit')}</span>
          <span className="opacity-60">·</span>
          <span className="flex items-center gap-1 text-emerald-500">
            <Link2 size={11} />{stats.linked} {t('admin.storage_linked')}
          </span>
          <span className="opacity-60">·</span>
          <span className="flex items-center gap-1 text-amber-500">
            <AlertTriangle size={11} />{stats.orphan} {t('admin.storage_orphan')}
          </span>
          <span className="opacity-60">·</span>
          <span className="flex items-center gap-1 text-red-500">
            <XCircle size={11} />{stats.missing + stats.missingOriginal + stats.missingThumbnail} {t('admin.storage_missing')}
          </span>
          {folderFilter && (
            <>
              <span className="opacity-60">·</span>
              <span className="max-w-48 truncate font-mono">{folderFilter}</span>
            </>
          )}
        </div>
        <button
          type="button"
          disabled={loading}
          onClick={() => void loadFiles()}
          className="flex items-center gap-1.5 rounded px-2 py-1 text-[10px] hover:bg-secondary disabled:cursor-wait disabled:opacity-50"
        >
          <RefreshCw size={11} className={loading ? 'animate-spin' : ''} />
          {t('common.refresh')}
        </button>
      </div>

      {/* 图片预览 */}
      {previewUrl && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-8 backdrop-blur-sm"
          onClick={() => setPreviewUrl(null)}
        >
          <img
            src={previewUrl}
            alt={t('admin.preview')}
            className="max-h-full max-w-full rounded-lg object-contain"
            onClick={event => event.stopPropagation()}
          />
          <button
            type="button"
            onClick={() => setPreviewUrl(null)}
            aria-label={t('admin.close_preview')}
            className="absolute right-6 top-6 flex h-10 w-10 items-center justify-center rounded-md border border-white/20 bg-black/40 text-white/80 transition-colors hover:border-white/50 hover:text-white"
          >
            <X size={18} />
          </button>
        </div>
      )}

      <MissingFileUploadModal
        isOpen={!!reuploadFile}
        fileInfo={reuploadFile ? {
          photoId: reuploadFile.photoId || '',
          photoTitle: reuploadFile.photoTitle || '',
          storageKey: reuploadFile.key,
          storageProvider: provider,
          missingType: reuploadFile.missingType,
        } : null}
        token={token}
        onClose={() => setReuploadFile(null)}
        onSuccess={() => loadFiles()}
        t={t}
        notify={notify}
      />

      <SimpleDeleteDialog
        isOpen={cleanupDialogOpen}
        title={t('admin.storage_cleanup_selected')}
        message={`${t('admin.storage_cleanup_confirm')} (${selected.size})`}
        onConfirm={handleCleanup}
        onCancel={() => setCleanupDialogOpen(false)}
        t={t}
      />

      <Toast notifications={notifications} remove={removeNotification} />
    </div>
  )
}

