// Confirmation Modal Component
function ConfirmModal({
  open,
  onClose,
  onConfirm,
  fileCount,
  categories,
  albumNames,
  storyName,
  storageProvider,
  storagePath,
  compressionEnabled,
  privacyStripEnabled,
  t
}: {
  open: boolean
  onClose: () => void
  onConfirm: () => void
  fileCount: number
  categories: string[]
  albumNames: string[]
  storyName?: string
  storageProvider: string
  storagePath?: string
  compressionEnabled: boolean
  privacyStripEnabled: boolean
  t: (key: string) => string
}) {
  if (!open) return null

  return (
