              </div>
            ) : null}
          </aside>
        </div>
      </div>

      <PhotoDetailModal
        photo={selectedPhoto}
        isOpen={!!selectedPhoto}
        onClose={() => setSelectedPhoto(null)}
        onPhotoChange={setSelectedPhoto}
        allPhotos={story.photos}
        hideStoryTab
      />
      <Toast
        notifications={notifications}
        remove={(id) => setNotifications((prev) => prev.filter((item) => item.id !== id))}
