'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { MessageSquare, LogIn, Send } from 'lucide-react'
import { getPhotoComments, submitPhotoComment } from '@/lib/api/comments'
import type { PublicCommentDto } from '@/lib/api/types'
import { useLanguage } from '@/contexts/LanguageContext'
import { useAuth } from '@/contexts/AuthContext'
import { useSettings } from '@/contexts/SettingsContext'
import { Toast, type Notification } from '@/components/Toast'
import dynamic from 'next/dynamic'

const WalineCommentsWrapper = dynamic(
  () => import('./WalineComments').then((mod) => mod.WalineComments),
  {
    ssr: false,
    loading: () => (
      <div className="animate-pulse space-y-4 p-6">
        <div className="h-4 w-1/4 rounded bg-muted" />
        <div className="h-3 rounded bg-muted" />
      </div>
    ),
  },
)

interface CommentsTabProps {
  photoId: string
}

export function CommentsTab({ photoId }: CommentsTabProps) {
  const { t, locale } = useLanguage()
  const { user, token } = useAuth()
  const { settings, isLoading: settingsLoading } = useSettings()
  const router = useRouter()
  const pathname = usePathname()
  const [comments, setComments] = useState<PublicCommentDto[]>([])
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [formData, setFormData] = useState({
    author: '',
    email: '',
    content: '',
  })
  const [notifications, setNotifications] = useState<Notification[]>([])

  const linuxdoOnly = settings?.linuxdo_only ?? false
  const isLinuxDoUser = user?.oauthProvider === 'linuxdo'
  const isAdmin = user?.isAdmin === true
  const canComment = !linuxdoOnly || isLinuxDoUser || isAdmin

  const commentsStorage = settings?.comments_storage?.toUpperCase() || ''
  const isWaline = commentsStorage === 'LEANCLOUD'
  const walineServerUrl = settings?.waline_server_url || ''

  const fetchComments = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const data = await getPhotoComments(photoId)
      setComments(data.toSorted((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()))
    } catch (err) {
      console.error('Failed to load comments:', err)
      setError(err instanceof Error ? err.message : 'Failed to load comments')
    } finally {
      setLoading(false)
    }
  }, [photoId])

  useEffect(() => {
    if (!isWaline) {
      void fetchComments()
    }
  }, [fetchComments, isWaline])

  useEffect(() => {
    if ((isLinuxDoUser || isAdmin) && user?.username && !formData.author) {
      setFormData((previous) => ({ ...previous, author: user.username }))
    }
  }, [formData.author, isAdmin, isLinuxDoUser, user?.username])

  const notify = useCallback((message: string, type: 'success' | 'error' | 'info' = 'success') => {
    const id = Math.random().toString(36).substring(2, 9)
    setNotifications((previous) => [...previous, { id, message, type }])
    setTimeout(() => {
      setNotifications((previous) => previous.filter((notification) => notification.id !== id))
    }, 4000)
  }, [])

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()

    if (!formData.author.trim() || !formData.content.trim()) {
      return
    }

    if (linuxdoOnly && !isLinuxDoUser && !isAdmin) {
      notify(t('gallery.comment_linuxdo_only'), 'error')
      return
    }

    try {
      setSubmitting(true)

      const result = await submitPhotoComment(
        photoId,
        {
          author: formData.author.trim(),
          email: formData.email.trim() || undefined,
          content: formData.content.trim(),
        },
        (linuxdoOnly && isLinuxDoUser) || isAdmin ? token : undefined,
      )

      if (result.status === 'approved') {
        notify(t('gallery.comment_success'), 'success')
        await fetchComments()
      } else {
        notify(t('gallery.comment_pending'), 'info')
      }

      setFormData({
        author: (isLinuxDoUser || isAdmin) && user?.username ? user.username : '',
        email: '',
        content: '',
      })
    } catch (err) {
      console.error('Failed to submit comment:', err)
      notify(err instanceof Error ? err.message : t('gallery.comment_error'), 'error')
    } finally {
      setSubmitting(false)
    }
  }

  if (isWaline) {
    return (
      <div className="relative flex h-full flex-col">
        <Toast
          notifications={notifications}
          remove={(id) => setNotifications((previous) => previous.filter((item) => item.id !== id))}
        />
        <div className="custom-scrollbar flex-1 overflow-y-auto p-6 md:p-8">
          {walineServerUrl ? (
            <WalineCommentsWrapper
              serverURL={walineServerUrl}
              path={`/photos/${photoId}`}
              lang={locale === 'zh' ? 'zh-CN' : 'en'}
            />
          ) : (
            <div className="py-12 text-center text-muted-foreground">
              <MessageSquare className="mx-auto mb-4 h-12 w-12 opacity-50" />
              <p className="text-sm">{t('gallery.comment_waline_not_configured')}</p>
            </div>
          )}
        </div>
      </div>
    )
  }

  if (loading || settingsLoading) {
    return (
      <div className="custom-scrollbar flex-1 overflow-y-auto p-6 md:p-8">
        <div className="animate-pulse space-y-4">
          {[...Array(3)].map((_, index) => (
            <div key={index} className="space-y-2">
              <div className="h-4 w-1/4 rounded bg-muted" />
              <div className="h-3 rounded bg-muted" />
              <div className="h-3 w-5/6 rounded bg-muted" />
            </div>
          ))}
        </div>
      </div>
    )
  }

  return (
    <div className="relative flex h-full flex-col">
      <Toast
        notifications={notifications}
        remove={(id) => setNotifications((previous) => previous.filter((item) => item.id !== id))}
      />
      <div className="custom-scrollbar flex-1 space-y-6 overflow-y-auto p-6 md:p-8">
        {error ? (
          <div className="rounded-[28px] border border-destructive/20 bg-destructive/5 px-6 py-12 text-center text-destructive">
            <p className="text-sm">{error}</p>
          </div>
        ) : comments.length === 0 ? (
          <div className="rounded-[28px] border border-border/20 bg-muted/5 px-6 py-12 text-center text-muted-foreground">
            <MessageSquare className="mx-auto mb-4 h-12 w-12 opacity-50" />
            <p className="text-sm">{t('gallery.no_comments')}</p>
          </div>
        ) : (
          <div className="grid gap-4">
            {comments.map((comment) => (
              <div
                key={comment.id}
                className="rounded-[24px] border border-border/30 bg-background/80 p-4 shadow-[0_10px_30px_rgba(15,23,42,0.04)] sm:p-5"
              >
                <div className="flex items-start gap-4">
                <div className="flex-shrink-0">
                  {comment.avatarUrl ? (
                    <img
                      src={comment.avatarUrl}
                      alt={comment.author}
                      className="h-11 w-11 rounded-full border border-border/30 object-cover"
                    />
                  ) : (
                    <div className="flex h-11 w-11 items-center justify-center rounded-full border border-border/30 bg-muted/40">
                      <span className="text-sm font-bold uppercase tracking-wide text-muted-foreground">
                        {comment.author.charAt(0).toUpperCase()}
                      </span>
                    </div>
                  )}
                </div>
                <div className="min-w-0 flex-1">
                  <div className="mb-2 flex flex-wrap items-center gap-2">
                    <span className="text-sm font-bold uppercase tracking-[0.16em] text-foreground">
                      {comment.author}
                    </span>
                    <span className="inline-flex items-center rounded-full bg-muted/35 px-2 py-1 text-[10px] font-mono uppercase tracking-widest text-muted-foreground">
                      {new Date(comment.createdAt).toLocaleString(locale, {
                        year: 'numeric',
                        month: '2-digit',
                        day: '2-digit',
                        hour: '2-digit',
                        minute: '2-digit',
                      })}
                    </span>
                  </div>
                  <p className="whitespace-pre-wrap font-serif text-sm leading-relaxed text-foreground/80">
                    {comment.content}
                  </p>
                </div>
              </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="shrink-0 border-t border-border bg-muted/5 p-6 md:p-8">
        {!canComment ? (
          <div className="rounded-[24px] border border-dashed border-border/30 bg-background/60 px-6 py-8 text-center">
            <p className="mb-4 text-sm text-muted-foreground">
              {t('gallery.comment_linuxdo_only')}
            </p>
            <button
              type="button"
              onClick={() => {
                const returnUrl = encodeURIComponent(pathname || '/')
                router.push(`/login?returnUrl=${returnUrl}`)
              }}
              className="inline-flex items-center gap-2 rounded-full bg-primary px-6 py-3 text-xs font-bold uppercase tracking-[0.15em] text-primary-foreground transition-all hover:bg-primary/90"
            >
              <LogIn className="h-4 w-4" />
              {t('gallery.comment_login_to_comment')}
            </button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-5 rounded-[28px] border border-border/30 bg-background/70 p-5 shadow-[0_18px_40px_rgba(15,23,42,0.06)] sm:p-6">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
              <div>
                <label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
                  {t('gallery.comment_author')}
                </label>
                <input
                  type="text"
                  value={formData.author}
                  onChange={(event) =>
                    setFormData({ ...formData, author: event.target.value })
                  }
                  className="w-full rounded-2xl border border-border/35 bg-background/80 px-4 py-3 text-sm text-foreground outline-none transition-colors focus:border-primary focus:bg-background"
                  required
                  disabled={submitting || isLinuxDoUser || isAdmin}
                />
              </div>
              <div>
                <label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
                  {(linuxdoOnly && isLinuxDoUser) || isAdmin
                    ? t('gallery.comment_username')
                    : t('gallery.comment_email')}
                </label>
                {isAdmin && !isLinuxDoUser ? (
                  <div className="flex min-h-12 items-center gap-2 rounded-2xl border border-primary/30 bg-primary/10 px-4 py-3">
                    <svg className="h-4 w-4 text-primary" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 10.99h7c-.53 4.12-3.28 7.79-7 8.94V12H5V6.3l7-3.11v8.8z" />
                    </svg>
                    <span className="text-sm font-medium text-primary">{t('admin.admin')}</span>
                  </div>
                ) : linuxdoOnly && isLinuxDoUser ? (
                  <div className="flex min-h-12 items-center gap-2 rounded-2xl border border-border/35 bg-muted/30 px-4 py-3">
                    <svg className="h-4 w-4 text-primary/70" viewBox="0 0 24 24" fill="currentColor">
                      <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z" />
                    </svg>
                    <span className="text-sm font-medium text-foreground/75">
                      {t('gallery.comment_linuxdo_badge')}
                    </span>
                  </div>
                ) : (
                  <input
                    type="email"
                    value={formData.email}
                    onChange={(event) =>
                      setFormData({ ...formData, email: event.target.value })
                    }
                    className="w-full rounded-2xl border border-border/35 bg-background/80 px-4 py-3 text-sm text-foreground outline-none transition-colors focus:border-primary focus:bg-background"
                    disabled={submitting}
                  />
                )}
              </div>
            </div>

            <div>
              <label className="mb-2 block text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
                {t('gallery.comment_content')}
              </label>
              <textarea
                value={formData.content}
                onChange={(event) =>
                  setFormData({ ...formData, content: event.target.value })
                }
                className="min-h-[120px] w-full resize-none rounded-[24px] border border-border/35 bg-background/80 px-4 py-3 text-sm font-serif text-foreground outline-none transition-colors focus:border-primary focus:bg-background"
                rows={4}
                required
                disabled={submitting}
              />
            </div>

            <button
              type="submit"
              disabled={submitting || !formData.author.trim() || !formData.content.trim()}
              className="flex w-full items-center justify-center gap-2 rounded-full bg-primary px-6 py-3 text-xs font-bold uppercase tracking-[0.2em] text-primary-foreground transition-all hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {!submitting ? <Send className="h-3.5 w-3.5" /> : null}
              {submitting ? t('gallery.comment_submitting') : t('gallery.comment_submit')}
            </button>
          </form>
        )}
      </div>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { motion, AnimatePresence } from 'framer-motion'
import { MessageSquare, LogIn, Send } from 'lucide-react'
import { getStoryComments, submitPhotoComment } from '@/lib/api/comments'
import type { PublicCommentDto } from '@/lib/api/types'
import { useLanguage } from '@/contexts/LanguageContext'
import { useAuth } from '@/contexts/AuthContext'
import { useSettings } from '@/contexts/SettingsContext'
import { useTheme } from '@/contexts/ThemeContext'
import { Toast, type Notification } from '@/components/Toast'
import dynamic from 'next/dynamic'

const WalineCommentsWrapper = dynamic(
  () => import('./WalineComments').then(mod => mod.WalineComments),
  { 
    ssr: false, 
    loading: () => (
      <div className="space-y-4 animate-pulse">
        <div className="flex gap-3">
          <div className="size-8 rounded-full bg-muted/60" />
          <div className="flex-1 space-y-2">
            <div className="h-3 w-1/4 rounded bg-muted/60" />
            <div className="h-3 w-full rounded bg-muted/60" />
          </div>
        </div>
      </div>
    )
  }
)

interface StoryCommentsProps {
  storyId: string
  targetPhotoId: string
  compact?: boolean
}

export function StoryComments({ storyId, targetPhotoId, compact = false }: StoryCommentsProps) {
  const { t, locale } = useLanguage()
  const { user, token } = useAuth()
  const { settings, isLoading: settingsLoading } = useSettings()
  const { resolvedTheme } = useTheme()
  const router = useRouter()
  const pathname = usePathname()
  const [comments, setComments] = useState<PublicCommentDto[]>([])
  const [loading, setLoading] = useState(true)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [formData, setFormData] = useState({
    author: '',
    email: '',
    content: '',
  })
  const [notifications, setNotifications] = useState<Notification[]>([])

  const linuxdoOnly = settings?.linuxdo_only ?? false
  const isLinuxDoUser = user?.oauthProvider === 'linuxdo'
  const isAdmin = user?.isAdmin === true
  const canComment = !linuxdoOnly || isLinuxDoUser || isAdmin

  const commentsStorage = settings?.comments_storage?.toUpperCase() || ''
  const isWaline = commentsStorage === 'LEANCLOUD'
  const walineServerUrl = settings?.waline_server_url || ''
  const isDark = resolvedTheme === 'dark'
  const containerClassName = compact
    ? 'space-y-5'
    : ''
  const formPanelClassName = compact
    ? 'mb-5 rounded-[24px] border border-border/20 bg-background/55 p-4 shadow-[0_10px_30px_rgba(15,23,42,0.04)] sm:p-5'
    : 'mb-6 rounded-[28px] border border-border/30 bg-background/70 p-5 shadow-[0_18px_40px_rgba(15,23,42,0.06)] sm:p-6'
  const emptyPanelClassName = compact
    ? 'rounded-[24px] border border-border/20 bg-muted/5 px-5 py-8 text-center'
    : 'rounded-[28px] border border-border/20 bg-muted/5 px-6 py-10 text-center'
  const listClassName = compact ? 'space-y-3' : 'space-y-4'
  const commentCardClassName = compact
    ? 'group rounded-[20px] border border-border/20 bg-background/70 p-4 shadow-[0_8px_24px_rgba(15,23,42,0.04)]'
    : 'group rounded-[24px] border border-border/25 bg-background/80 p-4 shadow-[0_10px_30px_rgba(15,23,42,0.04)] sm:p-5'

  useEffect(() => {
    if (!isWaline) {
      fetchComments()
    }
  }, [storyId, isWaline])

  useEffect(() => {
    if ((isLinuxDoUser || isAdmin) && user?.username && !formData.author) {
      setFormData(prev => ({ ...prev, author: user.username }))
    }
  }, [isLinuxDoUser, isAdmin, user?.username])

  async function fetchComments() {
    try {
      setLoading(true)
      setError(null)
      const data = await getStoryComments(storyId)
      setComments(data.toSorted((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()))
    } catch (err) {
      console.error('Failed to load comments:', err)
      setError(err instanceof Error ? err.message : 'Failed to load comments')
    } finally {
      setLoading(false)
    }
  }

  async function refreshComments() {
    try {
      const data = await getStoryComments(storyId)
      setComments(data.toSorted((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()))
    } catch (err) {
      console.error('Failed to refresh comments:', err)
    }
  }

  const notify = useCallback((message: string, type: 'success' | 'error' | 'info' = 'success') => {
    const id = Math.random().toString(36).substring(2, 9)
    setNotifications(prev => [...prev, { id, message, type }])
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 4000)
  }, [])

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()

    if (!formData.author.trim() || !formData.content.trim()) return
    if (linuxdoOnly && !isLinuxDoUser && !isAdmin) {
      notify(t('gallery.comment_linuxdo_only'), 'error')
      return
    }

    try {
      setSubmitting(true)

      const result = await submitPhotoComment(targetPhotoId, {
        author: formData.author.trim(),
        email: formData.email.trim() || undefined,
        content: formData.content.trim(),
      }, (linuxdoOnly && isLinuxDoUser) || isAdmin ? token : undefined)

      if (result.status === 'approved') {
        notify(t('gallery.comment_success'), 'success')
        await refreshComments()
      } else {
        notify(t('gallery.comment_pending'), 'info')
      }

      setFormData(prev => ({
        author: (isLinuxDoUser || isAdmin) && user?.username ? user.username : '',
        email: '',
        content: ''
      }))
    } catch (err) {
      console.error('Failed to submit comment:', err)
      notify(err instanceof Error ? err.message : t('gallery.comment_error'), 'error')
    } finally {
      setSubmitting(false)
    }
  }

  const handleLoginClick = () => {
    const returnUrl = encodeURIComponent(pathname)
    router.push(`/login?returnUrl=${returnUrl}`)
  }

  if (settingsLoading && loading && !isWaline) return null

  if (isWaline) {
    return (
      <div className={`relative ${containerClassName}`}>
        <Toast notifications={notifications} remove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
        {walineServerUrl ? (
          <WalineCommentsWrapper
            serverURL={walineServerUrl}
            path={`/stories/${storyId}`}
            lang={locale === 'zh' ? 'zh-CN' : 'en'}
            dark={isDark ? 'html.dark' : ''}
          />
        ) : (
          <p className="py-4 text-center text-xs text-muted-foreground">
            Comments not configured
          </p>
        )}
      </div>
    )
  }

  return (
    <div className={`relative ${containerClassName}`}>
      <Toast notifications={notifications} remove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
      
      {/* Comment Form */}
      <div className={formPanelClassName}>
        {!canComment ? (
          <div className="rounded-[24px] border border-dashed border-border/30 bg-background/60 px-5 py-8 text-center">
            <p className="mb-4 text-xs text-muted-foreground">
              {t('gallery.comment_linuxdo_only')}
            </p>
            <button
              type="button"
              onClick={handleLoginClick}
              className="inline-flex cursor-pointer items-center gap-2 rounded-full bg-primary px-4 py-2 text-[11px] font-semibold text-primary-foreground transition-colors hover:bg-primary/90"
            >
              <LogIn className="size-3.5" />
              {t('gallery.comment_login_to_comment')}
            </button>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Author Field */}
            <div>
              <label className="mb-1.5 block text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
                {t('gallery.comment_author')}
              </label>
              <input
                type="text"
                value={formData.author}
                onChange={(e) => setFormData({ ...formData, author: e.target.value })}
                className="w-full rounded-2xl border border-border/35 bg-background/80 px-4 py-3 text-sm text-foreground outline-none transition-colors focus:border-primary focus:bg-background"
                required
                disabled={submitting || isLinuxDoUser || isAdmin}
              />
            </div>

            {/* Email Field */}
            {isAdmin && !isLinuxDoUser ? (
              <div className="flex min-h-12 items-center gap-2 rounded-2xl border border-primary/20 bg-primary/5 px-4 py-3">
                <svg className="size-4 text-primary" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4zm0 10.99h7c-.53 4.12-3.28 7.79-7 8.94V12H5V6.3l7-3.11v8.8z"/>
                </svg>
                <span className="text-sm font-medium text-primary">{t('admin.admin')}</span>
              </div>
            ) : linuxdoOnly && isLinuxDoUser ? (
              <div className="flex min-h-12 items-center gap-2 rounded-2xl border border-border/35 bg-muted/30 px-4 py-3">
                <svg className="size-4 text-primary/70" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
                </svg>
                <span className="text-sm font-medium text-foreground/75">Linux DO</span>
              </div>
            ) : (
              <div>
                <label className="mb-1.5 block text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
                  {t('gallery.comment_email')} <span className="normal-case font-normal">(optional)</span>
                </label>
                <input
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  className="w-full rounded-2xl border border-border/35 bg-background/80 px-4 py-3 text-sm text-foreground outline-none transition-colors focus:border-primary focus:bg-background"
                  disabled={submitting}
                />
              </div>
            )}

            {/* Content Field */}
            <div>
              <label className="mb-1.5 block text-[10px] font-medium uppercase tracking-wider text-muted-foreground">
                {t('gallery.comment_content')}
              </label>
              <textarea
                value={formData.content}
                onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                className="min-h-[120px] w-full resize-none rounded-[24px] border border-border/35 bg-background/80 px-4 py-3 text-sm font-serif text-foreground outline-none transition-colors focus:border-primary focus:bg-background"
                rows={3}
                required
                disabled={submitting}
              />
            </div>

            {/* Submit Button */}
            <button
              type="submit"
              disabled={submitting || !formData.author.trim() || !formData.content.trim()}
              className="inline-flex w-full cursor-pointer items-center justify-center gap-2 rounded-full bg-primary px-5 py-3 text-xs font-semibold uppercase tracking-wider text-primary-foreground transition-colors hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-40"
            >
              {submitting ? (
                <>
                  <div className="size-3 animate-spin rounded-full border-2 border-current border-t-transparent" />
                  {t('gallery.comment_submitting')}
                </>
              ) : (
                <>
                  <Send className="size-3" />
                  {t('gallery.comment_submit')}
                </>
              )}
            </button>
          </form>
        )}
      </div>

      {/* Comments List */}
      {loading ? (
        <div className="grid gap-4 sm:grid-cols-2">
          {[1, 2].map((i) => (
            <div key={i} className="flex gap-3 rounded-[24px] border border-border/20 bg-muted/10 p-5 animate-pulse">
              <div className="size-10 shrink-0 rounded-full bg-muted/60" />
              <div className="flex-1 space-y-2">
                <div className="h-3 w-1/3 rounded-full bg-muted/60" />
                <div className="h-3 w-full rounded-full bg-muted/60" />
                <div className="h-3 w-2/3 rounded-full bg-muted/40" />
              </div>
            </div>
          ))}
        </div>
      ) : comments.length === 0 ? (
        <div className={emptyPanelClassName}>
          <MessageSquare className="mb-2 size-5 text-muted-foreground/40" />
          <p className="text-xs text-muted-foreground">
            {t('gallery.no_comments')}
          </p>
        </div>
      ) : (
        <div className={listClassName}>
          <AnimatePresence mode="popLayout">
            {comments.map((comment) => (
              <motion.div
                key={comment.id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
                className={commentCardClassName}
              >
                <div className="flex gap-3">
                  {/* Avatar */}
                  <div className="shrink-0">
                    {comment.avatarUrl ? (
                      <img
                        src={comment.avatarUrl}
                        alt={comment.author}
                        className="size-10 rounded-full border border-border/30 object-cover"
                      />
                    ) : (
                      <div className="flex size-10 items-center justify-center rounded-full border border-border/30 bg-muted/35">
                        <span className="text-xs font-bold uppercase tracking-wide text-foreground/70">
                          {comment.author.charAt(0)}
                        </span>
                      </div>
                    )}
                  </div>

                  {/* Content */}
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="text-xs font-semibold uppercase tracking-[0.16em] text-foreground">
                        {comment.author}
                      </span>
                      <time className="inline-flex items-center rounded-full bg-muted/35 px-2 py-1 text-[10px] font-mono uppercase tracking-wider text-muted-foreground">
                        {new Date(comment.createdAt).toLocaleDateString(locale === 'zh' ? 'zh-CN' : 'en-US', {
                          month: 'short',
                          day: 'numeric',
                        })}
                      </time>
                    </div>
                    <p className="mt-2 font-serif text-sm leading-relaxed text-foreground/75">
                      {comment.content}
                    </p>
                  </div>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>
      )}
    </div>
  )
}

'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { MapPin, Maximize2, Minimize2, Camera, Images } from 'lucide-react'
import Map, { Marker, NavigationControl, Popup, type MapRef } from 'react-map-gl/maplibre'
import type { StyleSpecification } from 'maplibre-gl'
import { resolveAssetUrl } from '@/lib/api/core'
import type { PhotoDto } from '@/lib/api/types'
import { useLanguage } from '@/contexts/LanguageContext'
import { useTheme } from '@/contexts/ThemeContext'
import { clusterMarkers, type ClusterPoint } from '@/lib/map-clustering'
import { getPhotoCoordinates, type PhotoCoordinates } from '@/lib/photo-location'

// High-contrast dark map style
const MAP_STYLE: StyleSpecification = {
  version: 8,
  sources: {
    carto: {
      type: 'raster',
      tiles: [
        'https://a.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}@2x.png',
      ],
      tileSize: 256,
      attribution: '© OpenStreetMap contributors, © CARTO',
    },
  },
  layers: [
    {
      id: 'carto',
      type: 'raster',
      source: 'carto',
    },
  ],
}

const LIGHT_MAP_STYLE: StyleSpecification = {
  ...MAP_STYLE,
  sources: {
    carto: {
      type: 'raster',
      tiles: [
        'https://a.basemaps.cartocdn.com/light_all/{z}/{x}/{y}@2x.png',
      ],
      tileSize: 256,
      attribution: '&copy; OpenStreetMap contributors, &copy; CARTO',
    },
  },
}

type GeotaggedPhoto = PhotoDto & {
  coordinates: PhotoCoordinates
}

type PopupAnchor = 'top' | 'bottom' | 'left' | 'right' | 'top-left' | 'top-right' | 'bottom-left' | 'bottom-right'

const POPUP_ANCHORS: PopupAnchor[] = ['bottom', 'top', 'left', 'right', 'bottom-left', 'bottom-right', 'top-left', 'top-right']

interface StoryMapPanelProps {
  photos: PhotoDto[]
  cdnDomain?: string
  expanded?: boolean
  onToggleExpanded?: () => void
}

interface PopupLayout {
  width: number
  imageHeight: number
  edgePadding: number
}

interface PopupPlacement {
  anchor: PopupAnchor
  offsetX: number
  offsetY: number
}

const POPUP_GAP = 14
const POPUP_MARGIN = 12
const POPUP_TEXT_HEIGHT = 42

function getPopupRect(
  anchor: PopupAnchor,
  pointX: number,
  pointY: number,
  popupWidth: number,
  popupHeight: number
) {
  switch (anchor) {
    case 'top':
      return { left: pointX - popupWidth / 2, right: pointX + popupWidth / 2, top: pointY + POPUP_GAP, bottom: pointY + POPUP_GAP + popupHeight }
    case 'bottom':
      return { left: pointX - popupWidth / 2, right: pointX + popupWidth / 2, top: pointY - POPUP_GAP - popupHeight, bottom: pointY - POPUP_GAP }
    case 'left':
      return { left: pointX + POPUP_GAP, right: pointX + POPUP_GAP + popupWidth, top: pointY - popupHeight / 2, bottom: pointY + popupHeight / 2 }
    case 'right':
      return { left: pointX - POPUP_GAP - popupWidth, right: pointX - POPUP_GAP, top: pointY - popupHeight / 2, bottom: pointY + popupHeight / 2 }
    case 'top-left':
      return { left: pointX, right: pointX + popupWidth, top: pointY + POPUP_GAP, bottom: pointY + POPUP_GAP + popupHeight }
    case 'top-right':
      return { left: pointX - popupWidth, right: pointX, top: pointY + POPUP_GAP, bottom: pointY + POPUP_GAP + popupHeight }
    case 'bottom-left':
      return { left: pointX, right: pointX + popupWidth, top: pointY - POPUP_GAP - popupHeight, bottom: pointY - POPUP_GAP }
    case 'bottom-right':
      return { left: pointX - popupWidth, right: pointX, top: pointY - POPUP_GAP - popupHeight, bottom: pointY - POPUP_GAP }
  }
}

function getOverflowScore(
  rect: { left: number; right: number; top: number; bottom: number },
  containerWidth: number,
  containerHeight: number
) {
  const overflowLeft = Math.max(0, POPUP_MARGIN - rect.left)
  const overflowRight = Math.max(0, rect.right - (containerWidth - POPUP_MARGIN))
  const overflowTop = Math.max(0, POPUP_MARGIN - rect.top)
  const overflowBottom = Math.max(0, rect.bottom - (containerHeight - POPUP_MARGIN))

  return {
    total: overflowLeft + overflowRight + overflowTop + overflowBottom,
    dx:
      overflowLeft > 0
        ? overflowLeft
        : overflowRight > 0
          ? -overflowRight
          : 0,
    dy:
      overflowTop > 0
        ? overflowTop
        : overflowBottom > 0
          ? -overflowBottom
          : 0,
  }
}

function toGeotaggedPhoto(photo: PhotoDto): GeotaggedPhoto | null {
  const coordinates = getPhotoCoordinates(photo)
  if (!coordinates) {
    return null
  }

  return {
    ...photo,
    coordinates,
  }
}

// Cluster marker component
interface ClusterMarkerProps {
  point: ClusterPoint
  isDark: boolean
  onFocusPhoto: (photo: GeotaggedPhoto) => void
}

function ClusterMarker({ point, isDark, onFocusPhoto }: ClusterMarkerProps) {
  const { t } = useLanguage()
  const [isExpanded, setIsExpanded] = useState(false)
  const photos = point.properties.clusteredPhotos ?? []
  const count = point.properties.point_count ?? 0

  const handleClick = () => {
    setIsExpanded(!isExpanded)
  }

  return (
    <Marker
      longitude={point.geometry.coordinates[0]}
      latitude={point.geometry.coordinates[1]}
      anchor="center"
    >
      <div className="relative">
        {/* Expanded cluster grid */}
        {isExpanded && photos.length > 0 && (
          <div
            className="absolute bottom-full left-1/2 mb-2 -translate-x-1/2 overflow-hidden rounded-xl border border-border/60 bg-background/95 p-2 shadow-2xl backdrop-blur-md"
          >
            <div className="grid grid-cols-3 gap-1.5">
              {photos.slice(0, 9).map((photo) => (
                <button
                  key={photo.id}
                  type="button"
                  onClick={(e) => {
                    e.stopPropagation()
                    setIsExpanded(false)
                    onFocusPhoto(photo)
                  }}
                  className="size-10 overflow-hidden rounded-lg transition-transform hover:scale-110"
                >
                  <img
                    src={resolveAssetUrl(photo.thumbnailUrl || photo.url)}
                    alt={photo.title}
                    className="h-full w-full object-cover"
                  />
                </button>
              ))}
            </div>
            {count > 9 && (
              <p className="mt-1.5 text-center text-[9px] text-muted-foreground">
                +{count - 9} {t('story.map_cluster_more')}
              </p>
            )}
          </div>
        )}

        {/* Cluster pin */}
        <button
          type="button"
          onClick={handleClick}
          className="group relative cursor-pointer transition-all hover:scale-110"
          aria-label={`${count} ${t('story.map_cluster_aria_suffix')}`}
        >
          {/* Background preview */}
          {photos[0] && (
            <div className="absolute inset-0 overflow-hidden rounded-full">
              <img
                src={resolveAssetUrl(photos[0].thumbnailUrl || photos[0].url)}
                alt=""
                className="h-full w-full object-cover opacity-40"
              />
              <div className="absolute inset-0 bg-background/55" />
            </div>
          )}

          {/* Cluster count */}
          <div
            className="relative flex size-9 items-center justify-center rounded-full border-2 border-background bg-background/95 shadow-lg"
          >
            <Images className="mr-0.5 size-3.5 text-foreground/70" />
            <span
              className="absolute -right-1 -top-1 flex size-5 items-center justify-center rounded-full bg-primary text-[9px] font-bold text-primary-foreground shadow-md"
            >
              {count > 99 ? '99+' : count}
            </span>
          </div>

          {/* Pin tail */}
          <div
            className="absolute -bottom-1 left-1/2 size-2 -translate-x-1/2 rotate-45 bg-background/95"
          />
        </button>
      </div>
    </Marker>
  )
}

export function StoryMapPanel({ photos, cdnDomain, expanded = false, onToggleExpanded }: StoryMapPanelProps) {
  const { locale, t } = useLanguage()
  const { resolvedTheme } = useTheme()
  const mapRef = useRef<MapRef | null>(null)
  const geotaggedPhotos = useMemo(
    () => photos.map(toGeotaggedPhoto).filter((photo): photo is GeotaggedPhoto => photo !== null),
    [photos]
  )
  const [selectedPhotoId, setSelectedPhotoId] = useState<string | null>(null)
  const [popupPhotoId, setPopupPhotoId] = useState<string | null>(null)
  const [popupAnchor, setPopupAnchor] = useState<PopupAnchor>('top')
  const [popupLayout, setPopupLayout] = useState<PopupLayout>({
    width: 176,
    imageHeight: 112,
    edgePadding: 96,
  })
  const [currentZoom, setCurrentZoom] = useState(expanded ? 14.5 : 13.5)
  const isDark = resolvedTheme === 'dark'
  const mapStyle = isDark ? MAP_STYLE : LIGHT_MAP_STYLE

  // Clustered markers based on zoom level
  const clusteredMarkers = useMemo(
    () => clusterMarkers(geotaggedPhotos, currentZoom),
    [geotaggedPhotos, currentZoom]
  )

  const selectedPhoto = useMemo(
    () => geotaggedPhotos.find((photo) => photo.id === selectedPhotoId) ?? null,
    [geotaggedPhotos, selectedPhotoId]
  )

  const popupPhoto = useMemo(
    () => geotaggedPhotos.find((photo) => photo.id === popupPhotoId) ?? null,
    [geotaggedPhotos, popupPhotoId]
  )

  const fitMapToPhotos = useCallback(() => {
    const map = mapRef.current

    if (!map || geotaggedPhotos.length === 0) {
      return
    }

    if (geotaggedPhotos.length === 1) {
      const photo = geotaggedPhotos[0]
      map.flyTo({
        center: [photo.coordinates.lng, photo.coordinates.lat],
        zoom: 13.5,
        duration: 0,
      })
      return
    }

    let minLng = geotaggedPhotos[0].coordinates.lng
    let maxLng = geotaggedPhotos[0].coordinates.lng
    let minLat = geotaggedPhotos[0].coordinates.lat
    let maxLat = geotaggedPhotos[0].coordinates.lat

    for (const photo of geotaggedPhotos) {
      minLng = Math.min(minLng, photo.coordinates.lng)
      maxLng = Math.max(maxLng, photo.coordinates.lng)
      minLat = Math.min(minLat, photo.coordinates.lat)
      maxLat = Math.max(maxLat, photo.coordinates.lat)
    }

    const lngSpan = maxLng - minLng
    const latSpan = maxLat - minLat
    const isTightCluster = lngSpan < 0.01 && latSpan < 0.01
    const lngPadding = Math.max(lngSpan * 0.08, isTightCluster ? 0.0012 : 0.003)
    const latPadding = Math.max(latSpan * 0.08, isTightCluster ? 0.0012 : 0.003)
    const container = map.getContainer()
    const width = container.clientWidth || 320
    const height = container.clientHeight || 320
    const horizontalPadding = Math.max(18, Math.min(48, Math.round(width * 0.06)))
    const verticalPadding = Math.max(18, Math.min(40, Math.round(height * 0.06)))

    map.fitBounds(
      [
        [minLng - lngPadding, minLat - latPadding],
        [maxLng + lngPadding, maxLat + latPadding],
      ],
      {
        padding: {
          top: verticalPadding,
          right: horizontalPadding,
          bottom: verticalPadding,
          left: horizontalPadding,
        },
        duration: 0,
        maxZoom: isTightCluster ? 16 : 15,
      }
    )
  }, [geotaggedPhotos])

  const updatePopupLayout = useCallback((photo?: GeotaggedPhoto | null) => {
    const map = mapRef.current
    if (!map) {
      return
    }

    const container = map.getContainer()
    const width = container.clientWidth || 320
    const height = container.clientHeight || 320
    const targetPhoto = photo ?? popupPhoto ?? selectedPhoto ?? geotaggedPhotos[0] ?? null
    const aspectRatio = targetPhoto && targetPhoto.width > 0 && targetPhoto.height > 0
      ? targetPhoto.width / targetPhoto.height
      : 4 / 3

    const minWidth = expanded ? 176 : 144
    const maxWidth = expanded
      ? Math.min(320, Math.round(width * 0.34))
      : Math.min(214, Math.round(width * 0.8))
    const minHeight = expanded ? 132 : 102
    const maxHeight = expanded
      ? Math.min(276, Math.round(height * 0.46))
      : Math.min(176, Math.round(height * 0.5))

    let imageWidth = maxWidth
    let imageHeight = imageWidth / aspectRatio

    if (imageHeight > maxHeight) {
      imageHeight = maxHeight
      imageWidth = imageHeight * aspectRatio
    }
    if (imageWidth < minWidth) {
      imageWidth = minWidth
      imageHeight = imageWidth / aspectRatio
    }
    if (imageHeight < minHeight) {
      imageHeight = minHeight
      imageWidth = imageHeight * aspectRatio
    }
    if (imageWidth > maxWidth) {
      imageWidth = maxWidth
    }
    if (imageHeight > maxHeight) {
      imageHeight = maxHeight
    }

    const popupWidth = Math.round(Math.max(minWidth, Math.min(maxWidth, imageWidth)))
    const finalImageHeight = Math.round(Math.max(minHeight, Math.min(maxHeight, imageHeight)))
    const edgePadding = Math.max(80, Math.min(132, Math.round(popupWidth * 0.58)))

    setPopupLayout((current) => {
      if (
        current.width === popupWidth &&
        current.imageHeight === finalImageHeight &&
        current.edgePadding === edgePadding
      ) {
        return current
      }

      return {
        width: popupWidth,
        imageHeight: finalImageHeight,
        edgePadding,
      }
    })
  }, [expanded, geotaggedPhotos, popupPhoto, selectedPhoto])

  useEffect(() => {
    const frame = window.requestAnimationFrame(() => {
      fitMapToPhotos()
      updatePopupLayout()
    })

    const handleResize = () => {
      const map = mapRef.current
      if (!map) return
      map.resize()
      fitMapToPhotos()
      updatePopupLayout()
    }

    window.addEventListener('resize', handleResize)
    return () => {
      window.cancelAnimationFrame(frame)
      window.removeEventListener('resize', handleResize)
    }
  }, [fitMapToPhotos, updatePopupLayout])

  useEffect(() => {
    if (!geotaggedPhotos.length) {
      return
    }

    const frame = window.requestAnimationFrame(() => {
      const map = mapRef.current
      if (!map) return
      map.resize()
      fitMapToPhotos()
      updatePopupLayout()
    })

    return () => window.cancelAnimationFrame(frame)
  }, [expanded, fitMapToPhotos, geotaggedPhotos.length, updatePopupLayout])

  const getPopupPlacement = useCallback((photo: GeotaggedPhoto): PopupPlacement => {
    const map = mapRef.current
    if (!map) {
      return { anchor: 'bottom', offsetX: 0, offsetY: 0 }
    }

    const point = map.project([photo.coordinates.lng, photo.coordinates.lat])
    const container = map.getContainer()
    const width = container.clientWidth || 320
    const height = container.clientHeight || 320
    const popupHeight = popupLayout.imageHeight + POPUP_TEXT_HEIGHT

    let bestPlacement: PopupPlacement = { anchor: 'bottom', offsetX: 0, offsetY: 0 }
    let bestScore = Number.POSITIVE_INFINITY

    for (const anchor of POPUP_ANCHORS) {
      const rect = getPopupRect(anchor, point.x, point.y, popupLayout.width, popupHeight)
      const overflow = getOverflowScore(rect, width, height)

      if (overflow.total < bestScore) {
        bestScore = overflow.total
        bestPlacement = {
          anchor,
          offsetX: point.x + overflow.dx - width / 2,
          offsetY: point.y + overflow.dy - height / 2,
        }
      }
    }

    return bestPlacement
  }, [popupLayout.imageHeight, popupLayout.width])

  const focusPhotoOnMap = useCallback((photo: GeotaggedPhoto) => {
    setSelectedPhotoId(photo.id)
    setPopupPhotoId(null)

    const map = mapRef.current
    if (!map) {
      window.requestAnimationFrame(() => {
        setPopupAnchor('bottom')
        setPopupPhotoId(photo.id)
      })
      return
    }

    updatePopupLayout(photo)
    const placement = getPopupPlacement(photo)

    map.once('moveend', () => {
      updatePopupLayout(photo)
      setPopupAnchor(placement.anchor)
      setPopupPhotoId(photo.id)
    })

    map.flyTo({
      center: [photo.coordinates.lng, photo.coordinates.lat],
      zoom: Math.max(map.getZoom(), expanded ? 14.5 : 13.5),
      offset: [placement.offsetX, placement.offsetY],
      duration: 450,
      essential: true,
    })
  }, [expanded, getPopupPlacement, updatePopupLayout])

  return (
    <section
      className={`overflow-hidden rounded-[28px] border border-border/30 bg-background/80 ${
        expanded ? 'shadow-2xl' : 'shadow-lg'
      }`}
    >
      {/* Header */}
      <div className="relative border-b border-border/30 px-5 pb-4 pt-5">
        <div className="flex items-center justify-between">
          <div>
            <span className="text-[10px] font-medium uppercase tracking-[0.3em] text-muted-foreground">
              {t('story.map_locations')}
            </span>
            <div className="mt-1 flex items-center gap-2">
              <MapPin className="size-3.5 text-primary/70" />
              <span className="text-sm font-medium text-foreground/80">
                {geotaggedPhotos.length} {t('story.map_mapped_suffix')}
              </span>
            </div>
          </div>
          <button
            type="button"
            onClick={onToggleExpanded}
            className="flex size-9 cursor-pointer items-center justify-center rounded-full border border-border/40 text-muted-foreground transition-all hover:border-primary/40 hover:bg-primary/5 hover:text-primary"
            aria-label={expanded ? t('story.map_collapse') : t('story.map_expand')}
            title={expanded ? t('story.map_collapse') : t('story.map_expand')}
          >
            {expanded ? <Minimize2 className="size-4" /> : <Maximize2 className="size-4" />}
          </button>
        </div>
      </div>

      {geotaggedPhotos.length === 0 ? (
        /* Empty State */
        <div className="flex flex-col items-center justify-center px-6 py-12">
          <div className="mb-4 flex size-12 items-center justify-center rounded-full bg-muted/30">
            <Camera className="size-5 text-muted-foreground/60" />
          </div>
          <p className="text-sm font-medium text-foreground/75">
            {t('story.map_empty_title')}
          </p>
          <p className="mt-1 text-xs text-muted-foreground">
            {t('story.map_empty_description')}
          </p>
        </div>
      ) : (
        /* Map Container */
        <div
          className={`relative overflow-hidden ${
            expanded ? 'h-[min(72vh,720px)] min-h-[420px]' : 'h-[280px]'
          } ${
            isDark
              ? '[&_.maplibregl-ctrl-group]:border [&_.maplibregl-ctrl-group]:border-border/40 [&_.maplibregl-ctrl-group]:bg-background/88 [&_.maplibregl-ctrl-group]:shadow-xl [&_.maplibregl-ctrl-button]:bg-transparent [&_.maplibregl-ctrl-button]:text-foreground [&_.maplibregl-ctrl-button:hover]:bg-muted/50 [&_.maplibregl-popup-tip]:border-b-background [&_.maplibregl-popup-tip]:border-t-background'
              : '[&_.maplibregl-ctrl-group]:border [&_.maplibregl-ctrl-group]:border-border/60 [&_.maplibregl-ctrl-group]:bg-background/92 [&_.maplibregl-ctrl-group]:shadow-lg [&_.maplibregl-ctrl-button]:bg-transparent [&_.maplibregl-ctrl-button]:text-foreground [&_.maplibregl-ctrl-button:hover]:bg-muted/60 [&_.maplibregl-popup-tip]:border-b-background [&_.maplibregl-popup-tip]:border-t-background'
          }`}
        >
          <Map
            ref={mapRef}
            initialViewState={{
              longitude: selectedPhoto?.coordinates.lng ?? geotaggedPhotos[0].coordinates.lng,
              latitude: selectedPhoto?.coordinates.lat ?? geotaggedPhotos[0].coordinates.lat,
              zoom: geotaggedPhotos.length === 1 ? 13.5 : 2.5,
            }}
            mapStyle={mapStyle}
            attributionControl={false}
            reuseMaps
            scrollZoom={expanded}
            onLoad={fitMapToPhotos}
            onMove={(evt) => setCurrentZoom(evt.viewState.zoom)}
          >
            <NavigationControl position="top-right" showCompass={false} />

            {clusteredMarkers.map((clusterPoint) => {
              if (clusterPoint.properties.cluster) {
                // Render cluster marker
                return (
                  <ClusterMarker
                    key={`cluster-${clusterPoint.geometry.coordinates[0]}-${clusterPoint.geometry.coordinates[1]}`}
                    point={clusterPoint}
                    isDark={isDark}
                    onFocusPhoto={focusPhotoOnMap}
                  />
                )
              } else {
                // Render individual marker
                const photo = clusterPoint.properties.marker!
                const isSelected = photo.id === selectedPhoto?.id

                return (
                  <Marker
                    key={photo.id}
                    longitude={photo.coordinates.lng}
                    latitude={photo.coordinates.lat}
                    anchor="bottom"
                  >
                    <button
                      type="button"
                      onClick={() => focusPhotoOnMap(photo)}
                      className={`group relative cursor-pointer transition-all ${
                        isSelected ? 'scale-110' : 'hover:scale-110'
                      }`}
                      aria-label={`${t('story.map_view_photo_on_map')} ${photo.title}`}
                    >
                      {/* Marker Pin */}
                      <div
                        className={`flex size-7 items-center justify-center rounded-full border-[2.5px] shadow-lg transition-all ${
                          isSelected
                            ? 'border-primary bg-background'
                            : 'border-background/80 bg-background/95'
                        }`}
                      >
                        <Camera
                          className={`size-3 ${
                            isSelected
                              ? 'text-primary'
                              : 'text-foreground/65'
                          }`}
                        />
                      </div>
                      {/* Pin Tail */}
                      <div
                        className={`absolute -bottom-1 left-1/2 size-2 -translate-x-1/2 rotate-45 ${
                          isSelected ? 'bg-background' : 'bg-background/95'
                        }`}
                      />
                      {/* Selection Ring */}
                      {isSelected && (
                        <div className="absolute -inset-2 rounded-full border-2 border-primary/25" />
                      )}
                    </button>
                  </Marker>
                )
              }
            })}

            {popupPhoto ? (
              <Popup
                key={popupPhoto.id}
                longitude={popupPhoto.coordinates.lng}
                latitude={popupPhoto.coordinates.lat}
                anchor={popupAnchor}
                offset={16}
                closeButton={false}
                onClose={() => setPopupPhotoId(null)}
                maxWidth={`${popupLayout.width}px`}
                style={{ ['--story-popup-width' as string]: `${popupLayout.width}px` }}
                className={`[&_.maplibregl-popup-content]:w-[var(--story-popup-width)] [&_.maplibregl-popup-content]:max-w-[var(--story-popup-width)] [&_.maplibregl-popup-content]:min-w-[var(--story-popup-width)] [&_.maplibregl-popup-content]:box-border [&_.maplibregl-popup-content]:overflow-hidden [&_.maplibregl-popup-content]:rounded-2xl [&_.maplibregl-popup-content]:p-0 [&_.maplibregl-popup-content]:shadow-2xl [&_.maplibregl-popup-content]:ring-1 ${
                  isDark
                    ? '[&_.maplibregl-popup-content]:bg-background [&_.maplibregl-popup-content]:ring-border/50'
                    : '[&_.maplibregl-popup-content]:bg-background [&_.maplibregl-popup-content]:ring-border/60'
                }`}
              >
                <div className="w-full overflow-hidden rounded-2xl">
                  {/* Photo */}
                  <div
                    className="relative flex items-center justify-center bg-muted/40"
                    style={{ height: popupLayout.imageHeight }}
                  >
                    <img
                      src={resolveAssetUrl(popupPhoto.thumbnailUrl || popupPhoto.url, cdnDomain)}
                      alt={popupPhoto.title}
                      className="block h-full w-full object-cover"
                    />
                    {/* Photo Number Badge */}
                    <div className="absolute left-2 top-2">
                      <span
                        className={`rounded-full px-2 py-0.5 text-[9px] font-medium backdrop-blur-sm ${
                          isDark
                            ? 'bg-background/80 text-foreground ring-1 ring-border/50'
                            : 'bg-background/90 text-foreground ring-1 ring-border/60'
                        }`}
                      >
                        {geotaggedPhotos.findIndex((p) => p.id === popupPhoto.id) + 1}/{geotaggedPhotos.length}
                      </span>
                    </div>
                  </div>
                  {/* Info */}
                  <div className="px-3 py-2.5">
                    <h3 className="line-clamp-1 text-xs font-medium text-foreground">
                      {popupPhoto.title}
                    </h3>
                    {popupPhoto.takenAt && (
                      <p className="mt-0.5 text-[10px] text-muted-foreground">
                        {new Date(popupPhoto.takenAt).toLocaleDateString(locale === 'zh' ? 'zh-CN' : 'en-US', {
                          month: 'short',
                          day: 'numeric',
                          year: 'numeric',
                        })}
                      </p>
                    )}
                  </div>
                </div>
              </Popup>
            ) : null}
          </Map>
        </div>
      )}
    </section>
  )
}

'use client'

import { memo, useCallback, useMemo } from 'react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { resolveAssetUrl } from '@/lib/api/core'
import { resolveStoredMediaEmbedInfo } from '@mo-gallery/tiptap-editor'
import type { PhotoDto } from '@/lib/api/types'
import {
  buildStoryPhotoIndex,
  escapeHtmlAttribute,
  type StoryPhotoIndex,
} from '@/lib/story-rich-content'
import './story-rich-content.css'

interface StoryRichContentProps {
  content: string
  photos: PhotoDto[]
  cdnDomain?: string
  className?: string
  onPhotoClick?: (photo: PhotoDto) => void
}

const HTML_TAG_PATTERN = /<\/?[a-z][\s\S]*>/i
const HTML_ANCHOR_PATTERN = /<a\b([^>]*?)href=(['"])(.*?)\2([^>]*)>/gi
const HTML_IMAGE_TAG_PATTERN = /<img\b[^>]*>/gi
const HTML_HR_TAG_PATTERN = /<hr\b[^>]*\/?>/gi
const HTML_MEDIA_EMBED_PATTERN = /<div\b[^>]*data-type=(['"])(?:media-embed|music-embed|spotify-embed)\1[^>]*>\s*<\/div>/gi
const HTML_STORY_LINK_CARD_PATTERN = /<div\b[^>]*data-type=(['"])story-link-card\1[^>]*>\s*<\/div>/gi

const IMG_SRC_ATTR_PATTERN = /\bsrc=(['"])(.*?)\1/i
const IMG_PHOTO_ID_ATTR_PATTERN = /\bdata-photo-id=(['"])(.*?)\1/i
const IMG_WIDTH_ATTR_PATTERN = /\bwidth=(?:(['"])(\d+)\1|(\d+))/i
const IMG_ALIGN_ATTR_PATTERN = /\bdata-align=(['"])(.*?)\1/i
const IMG_STYLE_ATTR_PATTERN = /\bstyle=(['"])(.*?)\1/i
const IMG_ALT_ATTR_PATTERN = /\balt=(['"])(.*?)\1/i
const IMG_TAG_PREFIX_PATTERN = /<img/i
const EMBED_PROVIDER_ATTR_PATTERN = /\bdata-provider=(['"])(.*?)\1/i
const EMBED_URL_ATTR_PATTERN = /\bdata-url=(['"])(.*?)\1/i
const EMBED_SRC_ATTR_PATTERN = /\bdata-src=(['"])(.*?)\1/i
const EMBED_TITLE_ATTR_PATTERN = /\bdata-title=(['"])(.*?)\1/i
const EMBED_HEIGHT_ATTR_PATTERN = /\bdata-height=(['"])(.*?)\1/i
const EMBED_ALLOW_ATTR_PATTERN = /\bdata-allow=(['"])(.*?)\1/i
const EMBED_ALLOW_FULLSCREEN_ATTR_PATTERN = /\bdata-allowfullscreen=(['"])(.*?)\1/i
const EMBED_FRAME_BORDER_ATTR_PATTERN = /\bdata-frameborder=(['"])(.*?)\1/i
const EMBED_MARGIN_WIDTH_ATTR_PATTERN = /\bdata-marginwidth=(['"])(.*?)\1/i
const EMBED_MARGIN_HEIGHT_ATTR_PATTERN = /\bdata-marginheight=(['"])(.*?)\1/i
const EMBED_SCROLLING_ATTR_PATTERN = /\bdata-scrolling=(['"])(.*?)\1/i
const EMBED_BORDER_ATTR_PATTERN = /\bdata-border=(['"])(.*?)\1/i
const EMBED_FRAME_SPACING_ATTR_PATTERN = /\bdata-framespacing=(['"])(.*?)\1/i
const STORY_CARD_STORY_ID_ATTR_PATTERN = /\bdata-story-id=(['"])(.*?)\1/i
const STORY_CARD_URL_ATTR_PATTERN = /\bdata-url=(['"])(.*?)\1/i
const STORY_CARD_TITLE_ATTR_PATTERN = /\bdata-title=(['"])(.*?)\1/i
const STORY_CARD_SUMMARY_ATTR_PATTERN = /\bdata-summary=(['"])(.*?)\1/i
const STORY_CARD_COVER_ATTR_PATTERN = /\bdata-cover-url=(['"])(.*?)\1/i
const STORY_CARD_DATE_ATTR_PATTERN = /\bdata-date=(['"])(.*?)\1/i
const STORY_CARD_PUBLISHED_ATTR_PATTERN = /\bdata-published=(['"])(.*?)\1/i
const EXTERNAL_URL_PATTERN = /^(https?:\/\/|data:|blob:|uploading:\/\/)/i
const MARKDOWN_IMAGE_WIDTH_PATTERN = /^(.+?)\s*=\s*(\d+)x\s*$/

function normalizeImageWidth(width?: number | string) {
  if (typeof width === 'number' && Number.isFinite(width)) return Math.max(160, Math.round(width))
  if (typeof width === 'string') {
    const parsed = Number.parseInt(width, 10)
    if (Number.isFinite(parsed)) return Math.max(160, parsed)
  }
  return undefined
}

function parseMarkdownImageSrc(rawSrc: string): { url: string; width?: number } {
  const trimmed = rawSrc.trim()
  const match = trimmed.match(MARKDOWN_IMAGE_WIDTH_PATTERN)
  if (!match) return { url: trimmed, width: undefined }

  const parsed = Number.parseInt(match[2], 10)
  return { url: match[1].trim(), width: Number.isFinite(parsed) ? Math.max(160, parsed) : undefined }
}

function resolveStoryAssetUrl(rawUrl: string, index: StoryPhotoIndex, cdnDomain?: string, photoId?: string) {
  const matchedById = index.findById(photoId)
  if (matchedById) return resolveAssetUrl(matchedById.url, cdnDomain)

  const trimmed = rawUrl.trim()
  const matchedPhoto = index.findByExactUrl(trimmed)

  if (matchedPhoto) return resolveAssetUrl(matchedPhoto.url, cdnDomain)
  if (EXTERNAL_URL_PATTERN.test(trimmed)) return trimmed
  return resolveAssetUrl(trimmed, cdnDomain)
}

function normalizeHtmlImageTag(tag: string, index: StoryPhotoIndex, cdnDomain?: string) {
  const srcMatch = tag.match(IMG_SRC_ATTR_PATTERN)
  const photoId = tag.match(IMG_PHOTO_ID_ATTR_PATTERN)?.[2]?.trim()
  const matchedPhoto = index.findById(photoId)
  if (!srcMatch && !photoId) return tag

  const resolvedSrc = resolveStoryAssetUrl(srcMatch?.[2] || '', index, cdnDomain, photoId)
  const widthMatch = tag.match(IMG_WIDTH_ATTR_PATTERN)
  const alignMatch = tag.match(IMG_ALIGN_ATTR_PATTERN)
  const styleMatch = tag.match(IMG_STYLE_ATTR_PATTERN)
  const normalizedWidth = normalizeImageWidth(widthMatch?.[2] || widthMatch?.[3])
  const align = alignMatch?.[2]

  const styleParts: string[] = []
  if (styleMatch?.[2]) styleParts.push(styleMatch[2].trim().replace(/;?$/, ';'))
  if (normalizedWidth) styleParts.push(`width:${normalizedWidth}px;`)
  styleParts.push('display:inline-block;')
  styleParts.push('vertical-align:top;')
  styleParts.push('margin:0 0.75rem 0.75rem 0;')
  styleParts.push('max-width:100%;')
  styleParts.push('height:auto;')

  if (align === 'center') {
    styleParts.push('display:block;')
    styleParts.push('margin-left:auto;')
    styleParts.push('margin-right:auto;')
  } else if (align === 'right') {
    styleParts.push('display:block;')
    styleParts.push('margin-left:auto;')
    styleParts.push('margin-right:0;')
  }

  let nextTag = srcMatch
    ? tag.replace(srcMatch[0], `src="${resolvedSrc}"`)
    : tag.replace(IMG_TAG_PREFIX_PATTERN, `<img src="${resolvedSrc}"`)
  const altMatch = tag.match(IMG_ALT_ATTR_PATTERN)
  if ((!altMatch || !altMatch[2]) && matchedPhoto?.title) {
    const escapedAlt = escapeHtmlAttribute(matchedPhoto.title)
    nextTag = altMatch
      ? nextTag.replace(altMatch[0], `alt="${escapedAlt}"`)
      : nextTag.replace(IMG_TAG_PREFIX_PATTERN, `<img alt="${escapedAlt}"`)
  }

  if (matchedPhoto && !photoId) {
    nextTag = nextTag.replace(IMG_TAG_PREFIX_PATTERN, `<img data-photo-id="${escapeHtmlAttribute(matchedPhoto.id)}"`)
  }

  if (styleMatch) {
    nextTag = nextTag.replace(styleMatch[0], `style="${styleParts.join(' ')}"`)
  } else {
    nextTag = nextTag.replace(IMG_TAG_PREFIX_PATTERN, `<img style="${styleParts.join(' ')}"`)
  }

  return nextTag
}

function buildMediaEmbedHtml(tag: string) {
  const provider = tag.match(EMBED_PROVIDER_ATTR_PATTERN)?.[2]?.trim() || ''
  const url = tag.match(EMBED_URL_ATTR_PATTERN)?.[2]?.trim() || ''
  const embedInfo = resolveStoredMediaEmbedInfo({
    provider,
    url,
    src: tag.match(EMBED_SRC_ATTR_PATTERN)?.[2]?.trim() || '',
    title: tag.match(EMBED_TITLE_ATTR_PATTERN)?.[2]?.trim() || '',
    height: tag.match(EMBED_HEIGHT_ATTR_PATTERN)?.[2]?.trim() || '',
    allow: tag.match(EMBED_ALLOW_ATTR_PATTERN)?.[2]?.trim() || '',
    allowFullScreen: tag.match(EMBED_ALLOW_FULLSCREEN_ATTR_PATTERN)?.[2] === 'true',
    frameBorder: tag.match(EMBED_FRAME_BORDER_ATTR_PATTERN)?.[2]?.trim() || '',
    marginWidth: (() => {
      const value = tag.match(EMBED_MARGIN_WIDTH_ATTR_PATTERN)?.[2]?.trim()
      return value ? Number.parseInt(value, 10) : undefined
    })(),
    marginHeight: (() => {
      const value = tag.match(EMBED_MARGIN_HEIGHT_ATTR_PATTERN)?.[2]?.trim()
      return value ? Number.parseInt(value, 10) : undefined
    })(),
    scrolling: tag.match(EMBED_SCROLLING_ATTR_PATTERN)?.[2]?.trim() || '',
    border: tag.match(EMBED_BORDER_ATTR_PATTERN)?.[2]?.trim() || '',
    frameSpacing: tag.match(EMBED_FRAME_SPACING_ATTR_PATTERN)?.[2]?.trim() || '',
  })
  if (!embedInfo) {
    return tag
  }

  const escapedUrl = embedInfo.url ? escapeHtmlAttribute(embedInfo.url) : ''
  const escapedEmbedUrl = escapeHtmlAttribute(embedInfo.src)
  const escapedProviderAttribute = embedInfo.provider ? ` data-provider="${escapeHtmlAttribute(embedInfo.provider)}"` : ''
  const escapedTitle = escapeHtmlAttribute(embedInfo.title)
  const frameBorderAttribute = embedInfo.frameBorder ? ` frameborder="${escapeHtmlAttribute(embedInfo.frameBorder)}"` : ''
  const marginWidthAttribute = embedInfo.marginWidth !== undefined ? ` marginwidth="${escapeHtmlAttribute(String(embedInfo.marginWidth))}"` : ''
  const marginHeightAttribute = embedInfo.marginHeight !== undefined ? ` marginheight="${escapeHtmlAttribute(String(embedInfo.marginHeight))}"` : ''
  const allowAttribute = embedInfo.allow ? ` allow="${escapeHtmlAttribute(embedInfo.allow)}"` : ''
  const allowFullScreenAttribute = embedInfo.allowFullScreen ? ' allowfullscreen' : ''
  const scrollingAttribute = embedInfo.scrolling ? ` scrolling="${escapeHtmlAttribute(embedInfo.scrolling)}"` : ''
  const borderAttribute = embedInfo.border ? ` border="${escapeHtmlAttribute(embedInfo.border)}"` : ''
  const frameSpacingAttribute = embedInfo.frameSpacing ? ` framespacing="${escapeHtmlAttribute(embedInfo.frameSpacing)}"` : ''
  const styleAttribute = embedInfo.provider === 'spotify' ? ' style="border-radius:12px"' : ''
  const dataUrlAttribute = escapedUrl ? ` data-media-url="${escapedUrl}"` : ''

  return `
    <div class="story-media-card" data-type="media-embed"${escapedProviderAttribute}>
      <iframe
        src="${escapedEmbedUrl}"
        title="${escapedTitle}"
        width="100%"
        ${embedInfo.height ? `height="${escapeHtmlAttribute(embedInfo.height)}"` : ''}
        ${dataUrlAttribute}
        loading="lazy"
        ${allowAttribute}${allowFullScreenAttribute}${frameBorderAttribute}${marginWidthAttribute}${marginHeightAttribute}${scrollingAttribute}${borderAttribute}${frameSpacingAttribute}${styleAttribute}
      ></iframe>
    </div>
  `
}

function formatStoryCardDate(value: string) {
  if (!value) return ''
  const date = new Date(value)
  if (!Number.isFinite(date.getTime())) return ''
  return date.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' })
}

function buildStoryLinkCardHtml(tag: string) {
  const storyId = tag.match(STORY_CARD_STORY_ID_ATTR_PATTERN)?.[2]?.trim() || ''
  const url = tag.match(STORY_CARD_URL_ATTR_PATTERN)?.[2]?.trim() || (storyId ? `/story/${storyId}` : '#')
  const title = tag.match(STORY_CARD_TITLE_ATTR_PATTERN)?.[2]?.trim() || 'Untitled story'
  const summary = tag.match(STORY_CARD_SUMMARY_ATTR_PATTERN)?.[2]?.trim() || ''
  const coverUrl = tag.match(STORY_CARD_COVER_ATTR_PATTERN)?.[2]?.trim() || ''
  const date = formatStoryCardDate(tag.match(STORY_CARD_DATE_ATTR_PATTERN)?.[2]?.trim() || '')
  const isPublished = tag.match(STORY_CARD_PUBLISHED_ATTR_PATTERN)?.[2] !== 'false'

  return `
    <a class="story-link-card" data-type="story-link-card" href="${escapeHtmlAttribute(url)}" target="_blank" rel="noreferrer">
      ${coverUrl ? `<img class="story-link-card__cover" src="${escapeHtmlAttribute(coverUrl)}" alt="">` : ''}
      <span class="story-link-card__body">
        <span class="story-link-card__eyebrow"><span>Story</span>${isPublished ? '' : '<span>Draft</span>'}</span>
        <span class="story-link-card__title">${escapeHtmlAttribute(title)}</span>
        ${summary ? `<span class="story-link-card__summary">${escapeHtmlAttribute(summary)}</span>` : ''}
        ${date ? `<span class="story-link-card__meta">${escapeHtmlAttribute(date)}</span>` : ''}
      </span>
    </a>
  `
}

function resolveStoryHtml(content: string, index: StoryPhotoIndex, cdnDomain?: string) {
  const withResolvedLinks = content.replace(
    HTML_ANCHOR_PATTERN,
    (_match, beforeHref: string, quote: string, href: string, afterHref: string) => {
      if (!/^https?:\/\//i.test(href) || /target=|rel=/i.test(`${beforeHref} ${afterHref}`)) {
        return `<a${beforeHref}href=${quote}${href}${quote}${afterHref}>`
      }
      return `<a${beforeHref}href=${quote}${href}${quote}${afterHref} target="_blank" rel="noreferrer">`
    }
  )

  return withResolvedLinks
    .replace(HTML_IMAGE_TAG_PATTERN, (tag) => normalizeHtmlImageTag(tag, index, cdnDomain))
    .replace(HTML_MEDIA_EMBED_PATTERN, (tag) => buildMediaEmbedHtml(tag))
    .replace(HTML_STORY_LINK_CARD_PATTERN, (tag) => buildStoryLinkCardHtml(tag))
    .replace(HTML_HR_TAG_PATTERN, (tag) => {
      if (/\bstyle=/i.test(tag)) return tag
      return tag.replace(/<hr/i, '<hr style="border: none; border-top: 1px solid currentColor; margin: 2rem 0;"')
    })
}

function createMarkdownComponents(index: StoryPhotoIndex, cdnDomain?: string) {
  return {
    img: ({ src, alt, width }: React.ComponentProps<'img'>) => {
      const rawSrc = typeof src === 'string' ? src.trim() : ''
      const { url: parsedUrl, width: parsedWidth } = parseMarkdownImageSrc(rawSrc)
      const resolvedSrc = resolveStoryAssetUrl(parsedUrl, index, cdnDomain)
      const matchedPhoto = index.findByImageUrl(parsedUrl)
      const normalizedWidth = parsedWidth ?? normalizeImageWidth(width)

      return (
        <img
          src={resolvedSrc}
          alt={alt ?? matchedPhoto?.title ?? ''}
          data-photo-id={matchedPhoto?.id ?? undefined}
          width={normalizedWidth}
          style={normalizedWidth ? {
            display: 'inline-block',
            verticalAlign: 'top',
            margin: '0 0.75rem 0.75rem 0',
            width: `${normalizedWidth}px`,
            maxWidth: '100%',
            height: 'auto',
          } : {
            display: 'inline-block',
            verticalAlign: 'top',
            margin: '0 0.75rem 0.75rem 0',
            maxWidth: '100%',
            height: 'auto',
          }}
        />
      )
    },
    a: ({ children, href }: React.ComponentProps<'a'>) => (
      <a href={href} target="_blank" rel="noreferrer">{children}</a>
    ),
  }
}

export const StoryRichContent = memo(function StoryRichContent({
  content,
  photos,
  cdnDomain,
  className = '',
  onPhotoClick,
}: StoryRichContentProps) {
  const photoIndex = useMemo(
    () => buildStoryPhotoIndex(photos, cdnDomain),
    [photos, cdnDomain],
  )
  const markdownComponents = useMemo(
    () => createMarkdownComponents(photoIndex, cdnDomain),
    [photoIndex, cdnDomain],
  )
  const isHtmlContent = HTML_TAG_PATTERN.test(content)
  const rootClassName = ['story-rich-content', onPhotoClick ? 'story-rich-content--interactive' : '', className].filter(Boolean).join(' ')
  const resolvedHtml = useMemo(() => {
    if (!isHtmlContent) return null
    return resolveStoryHtml(content, photoIndex, cdnDomain)
  }, [cdnDomain, content, isHtmlContent, photoIndex])
  const handleContentClick = useCallback((event: React.MouseEvent<HTMLDivElement>) => {
    if (!onPhotoClick) return

    const target = event.target
    if (!(target instanceof HTMLElement)) {
      return
    }

    const imageElement = target.closest('img')
    if (!(imageElement instanceof HTMLImageElement)) {
      return
    }

    const photoId = imageElement.getAttribute('data-photo-id')?.trim()
    const matchedById = photoIndex.findById(photoId)
    if (matchedById) {
      onPhotoClick(matchedById)
      return
    }

    const imageSrc = imageElement.getAttribute('src')
    const matchedByUrl = photoIndex.findByImageUrl(imageSrc)
    if (matchedByUrl) {
      onPhotoClick(matchedByUrl)
    }
  }, [onPhotoClick, photoIndex])

  if (isHtmlContent) {
    return (
      <div className={rootClassName} onClick={handleContentClick}>
        <div className="story-rich-html" dangerouslySetInnerHTML={{ __html: resolvedHtml ?? '' }} />
      </div>
    )
  }

  return (
    <div className={rootClassName} onClick={handleContentClick}>
      <ReactMarkdown remarkPlugins={[remarkGfm]} components={markdownComponents}>
        {content}
      </ReactMarkdown>
    </div>
  )
})

export default StoryRichContent

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { BookOpen, MessageSquare, ChevronLeft, ChevronRight, Send, LogIn } from 'lucide-react'
import { useRouter, usePathname } from 'next/navigation'
import { motion } from 'framer-motion'
import dynamic from 'next/dynamic'
import { getPhotoComments, getStoryComments, submitPhotoComment } from '@/lib/api/comments'
import { resolveAssetUrl } from '@/lib/api/core'
import { getPhotoStory } from '@/lib/api/stories'
import type { PhotoDto, PublicCommentDto, StoryDto } from '@/lib/api/types'
import { useLanguage } from '@/contexts/LanguageContext'
import { useSettings } from '@/contexts/SettingsContext'
import { useAuth } from '@/contexts/AuthContext'
import { Toast, type Notification } from '@/components/Toast'
import { StoryRichContent } from '@/components/StoryRichContent'

const WalineCommentsWrapper = dynamic(
  () => import('./WalineComments').then((mod) => mod.WalineComments),
  {
    ssr: false,
    loading: () => (
      <div className="animate-pulse space-y-5">
        <div className="h-4 w-1/4 rounded-none bg-muted" />
        <div className="h-4 w-full rounded-none bg-muted" />
      </div>
    ),
  },
)

interface StoryTabProps {
  photoId: string
  currentPhoto: PhotoDto
  onPhotoChange?: (photo: PhotoDto) => void
  cachedStory?: StoryDto | null
  cachedComments?: PublicCommentDto[]
  isLoading?: boolean
  onCommentsUpdate?: (comments: PublicCommentDto[]) => void
}

export function StoryTab({
  photoId,
  currentPhoto,
  onPhotoChange,
  cachedStory,
  cachedComments,
  isLoading: externalLoading,
  onCommentsUpdate,
}: StoryTabProps) {
  const { t, locale } = useLanguage()
  const { settings, isLoading } = useSettings()
  const { user, token } = useAuth()
  const router = useRouter()
  const pathname = usePathname()

  const hasCachedData = cachedStory !== undefined
  const [internalStory, setInternalStory] = useState<StoryDto | null>(null)
  const [internalLoading, setInternalLoading] = useState(!hasCachedData)
  const [error, setError] = useState<string | null>(null)
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0)

  const story = hasCachedData ? (cachedStory ?? null) : internalStory
  const loading = hasCachedData ? (externalLoading ?? false) : internalLoading

  const [internalComments, setInternalComments] = useState<PublicCommentDto[]>([])
  const comments = hasCachedData && cachedComments ? cachedComments : internalComments
  const [commentsLoading, setCommentsLoading] = useState(!hasCachedData)
  const [submitting, setSubmitting] = useState(false)
  const [formData, setFormData] = useState({
    author: '',
    email: '',
    content: '',
  })
  const [notifications, setNotifications] = useState<Notification[]>([])

  const linuxdoOnly = settings?.linuxdo_only ?? false
  const settingsLoaded = !isLoading

  const commentsStorage = settings?.comments_storage?.toUpperCase() || ''
  const isWaline = commentsStorage === 'LEANCLOUD'
  const walineServerUrl = settings?.waline_server_url || ''

  const isLinuxDoUser = user?.oauthProvider === 'linuxdo'
  const isAdmin = user?.isAdmin === true
  const canComment = !linuxdoOnly || isLinuxDoUser || isAdmin

  const fetchedForPhotoId = useRef<string | null>(null)
  const isFetching = useRef(false)
  const isInitialLoad = useRef(true)

  const isPhotoInCurrentStory = useCallback((targetPhotoId: string) => {
    return story?.photos?.some((photo) => photo.id === targetPhotoId) ?? false
  }, [story?.photos])

  useEffect(() => {
    if ((isLinuxDoUser || isAdmin) && user?.username && !formData.author) {
      setFormData((previous) => ({ ...previous, author: user.username }))
    }
  }, [formData.author, isAdmin, isLinuxDoUser, user?.username])

  useEffect(() => {
    if (hasCachedData) {
      if (story?.photos) {
        const index = story.photos.findIndex((photo) => photo.id === currentPhoto.id)
        setCurrentPhotoIndex(index >= 0 ? index : 0)
      }
      setCommentsLoading(false)
      return
    }

    if (isPhotoInCurrentStory(photoId)) {
      const index = story?.photos?.findIndex((photo) => photo.id === currentPhoto.id) ?? 0
      setCurrentPhotoIndex(index >= 0 ? index : 0)
      return
    }

    if (fetchedForPhotoId.current === photoId || isFetching.current) {
      return
    }

    isFetching.current = true
    fetchedForPhotoId.current = photoId

    async function fetchData() {
      if (isInitialLoad.current) {
        setInternalLoading(true)
        setCommentsLoading(true)
      }
      setError(null)

      try {
        const data = await getPhotoStory(photoId)
        setInternalStory(data)

        if (data?.photos) {
          const index = data.photos.findIndex((photo) => photo.id === currentPhoto.id)
          setCurrentPhotoIndex(index >= 0 ? index : 0)
        }

        if (data?.id) {
          const allComments = await getStoryComments(data.id)
          setInternalComments(allComments.toSorted((a, b) =>
            new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
          ))
        }
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : t('story.load_failed')
        if (errorMessage.includes('No story found')) {
          setInternalStory(null)
          setError(null)
          try {
            const photoComments = await getPhotoComments(photoId)
            setInternalComments(photoComments)
          } catch (commentErr) {
            console.error('Failed to load comments:', commentErr)
          }
        } else {
          console.error('Failed to load story:', err)
          setError(errorMessage)
        }
      } finally {
        setInternalLoading(false)
        setCommentsLoading(false)
        isFetching.current = false
        isInitialLoad.current = false
      }
    }

    void fetchData()
  }, [currentPhoto.id, hasCachedData, isPhotoInCurrentStory, photoId, story?.photos, t])

  useEffect(() => {
    if (story?.photos) {
      const index = story.photos.findIndex((photo) => photo.id === currentPhoto.id)
      if (index >= 0) {
        setCurrentPhotoIndex(index)
      }
    }
  }, [currentPhoto.id, story?.photos])

  async function refreshComments() {
    try {
      const newComments = story?.id
        ? await getStoryComments(story.id)
        : await getPhotoComments(photoId)

      const sorted = newComments.toSorted((a, b) =>
        new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      )

      if (onCommentsUpdate) {
        onCommentsUpdate(sorted)
      } else {
        setInternalComments(sorted)
      }
    } catch (err) {
      console.error('Failed to refresh comments:', err)
    }
  }

  const notify = useCallback((message: string, type: 'success' | 'error' | 'info' = 'success') => {
    const id = Math.random().toString(36).substring(2, 9)
    setNotifications((previous) => [...previous, { id, message, type }])
    setTimeout(() => {
      setNotifications((previous) => previous.filter((notification) => notification.id !== id))
    }, 4000)
  }, [])

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault()
    if (!formData.author.trim() || !formData.content.trim()) return

    if (linuxdoOnly && !isLinuxDoUser && !isAdmin) {
      notify(t('gallery.comment_linuxdo_only'), 'error')
      return
    }

    try {
      setSubmitting(true)
      const result = await submitPhotoComment(
        photoId,
        {
          author: formData.author.trim(),
          email: formData.email.trim() || undefined,
          content: formData.content.trim(),
        },
        (linuxdoOnly && isLinuxDoUser) || isAdmin ? token : undefined,
      )

      if (result.status === 'approved') {
        notify(t('gallery.comment_success'), 'success')
        await refreshComments()
      } else {
        notify(t('gallery.comment_pending'), 'info')
      }

      setFormData({
        author: (isLinuxDoUser || isAdmin) && user?.username ? user.username : '',
        email: '',
        content: '',
      })
    } catch (err) {
      console.error('Failed to submit comment:', err)
      notify(err instanceof Error ? err.message : t('gallery.comment_error'), 'error')
    } finally {
      setSubmitting(false)
    }
  }

  if (loading) {
    return (
      <div className="custom-scrollbar flex-1 overflow-y-auto p-8">
        <div className="animate-pulse space-y-6">
          <div className="h-10 w-3/4 rounded-none bg-muted" />
          <div className="h-4 w-1/4 rounded-none bg-muted" />
          <div className="mt-12 space-y-3">
            <div className="h-4 rounded-none bg-muted" />
            <div className="h-4 rounded-none bg-muted" />
            <div className="h-4 w-5/6 rounded-none bg-muted" />
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="custom-scrollbar relative flex-1 space-y-8 overflow-y-auto p-5 md:p-6">
      <Toast
        notifications={notifications}
        remove={(id) => setNotifications((previous) => previous.filter((item) => item.id !== id))}
      />

      {!story ? (
        <div className="space-y-8">
          <div className="border border-dashed border-border/30 py-12 text-center">
            <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-muted/30">
              <BookOpen className="h-5 w-5 text-muted-foreground/30" />
            </div>
            <p className="font-serif text-ui-xs italic text-muted-foreground/60">{t('gallery.no_story')}</p>
            {error ? <p className="mt-2 text-ui-micro text-destructive/70">{error}</p> : null}
          </div>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <div className="h-px w-4 bg-primary/40" />
              <span className="text-ui-micro font-bold uppercase tracking-[0.25em] text-primary/70">
                {t('story.journal')}
              </span>
            </div>
            <a
              href={`/story/${story.id}`}
              target="_blank"
              rel="noopener noreferrer"
              className="block text-xl leading-tight tracking-tight text-foreground transition-colors hover:text-primary md:text-2xl"
            >
              {story.title}
            </a>
            <div className="text-ui-micro font-mono uppercase tracking-widest text-muted-foreground/50">
              {new Date(story.createdAt).toLocaleDateString(locale === 'zh' ? 'zh-CN' : 'en-US', {
                year: 'numeric',
                month: 'long',
                day: 'numeric',
              })}
            </div>
          </div>

          {story.photos && story.photos.length > 1 && onPhotoChange ? (
            <div className="border-b border-t border-border/30 py-4">
              <div className="mb-3 flex items-center justify-between">
                <div className="space-y-0.5">
                  <h4 className="text-ui-micro font-bold uppercase tracking-[0.15em] text-primary/80">
                    {t('story.story_album')}
                  </h4>
                  <div className="text-ui-micro font-mono uppercase text-muted-foreground/50">
                    {currentPhotoIndex + 1} / {story.photos.length}
                  </div>
                </div>
                <div className="flex gap-1.5">
                  <button
                    onClick={() => currentPhotoIndex > 0 && onPhotoChange(story.photos[currentPhotoIndex - 1])}
                    disabled={currentPhotoIndex === 0}
                    className="flex h-8 w-8 items-center justify-center border border-border/50 transition-all hover:border-primary hover:text-primary disabled:cursor-not-allowed disabled:opacity-20"
                  >
                    <ChevronLeft className="h-3.5 w-3.5" />
                  </button>
                  <button
                    onClick={() => currentPhotoIndex < story.photos.length - 1 && onPhotoChange(story.photos[currentPhotoIndex + 1])}
                    disabled={currentPhotoIndex === story.photos.length - 1}
                    className="flex h-8 w-8 items-center justify-center border border-border/50 transition-all hover:border-primary hover:text-primary disabled:cursor-not-allowed disabled:opacity-20"
                  >
                    <ChevronRight className="h-3.5 w-3.5" />
                  </button>
                </div>
              </div>

              <div className="custom-scrollbar flex snap-x gap-2 overflow-x-auto pb-2">
                {story.photos.map((photo, index) => (
                  <button
                    key={photo.id}
                    onClick={() => onPhotoChange(photo)}
                    className={`relative h-14 w-14 flex-shrink-0 snap-start overflow-hidden transition-all duration-200 ${
                      index === currentPhotoIndex
                        ? 'ring-2 ring-primary ring-offset-1 ring-offset-background'
                        : 'opacity-50 hover:opacity-100'
                    }`}
                  >
                    <img
                      src={resolveAssetUrl(photo.thumbnailUrl || photo.url, settings?.cdn_domain)}
                      alt={photo.title}
                      className="h-full w-full object-cover"
                    />
                  </button>
                ))}
              </div>
            </div>
          ) : null}

          <StoryRichContent
            content={story.content}
            photos={story.photos || []}
            cdnDomain={settings?.cdn_domain}
            className="story-rich-content--compact"
          />
        </div>
      )}

      <div className="border-t border-border/30 pt-8">
        <div className="mb-8 flex items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <MessageSquare className="h-3.5 w-3.5 text-primary/60" />
            <h3 className="text-ui-micro font-bold uppercase tracking-[0.2em] text-primary/80">
              {t('gallery.comments')}
            </h3>
          </div>
          {!isWaline && comments.length > 0 ? (
            <span className="inline-flex items-center justify-center rounded-full border border-border/40 bg-muted/20 px-3 py-1 text-ui-micro font-mono uppercase tracking-[0.2em] text-muted-foreground/60">
              {comments.length}
            </span>
          ) : null}
        </div>

        {isWaline ? (
          walineServerUrl ? (
            <WalineCommentsWrapper
              serverURL={walineServerUrl}
              path={story ? `/stories/${story.id}` : `/photos/${photoId}`}
              lang={locale === 'zh' ? 'zh-CN' : 'en'}
            />
          ) : (
            <div className="border border-border/30 bg-muted/5 py-10 text-center">
              <p className="font-serif text-ui-xs italic text-muted-foreground/50">
