'use client'

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  createPositioner,
  useContainerPosition,
  useMasonry,
  useResizeObserver,
  useScroller,
  type Positioner,
  type RenderComponentProps,
} from 'masonic'

import type { PhotoDto, PublicSettingsDto } from '@/lib/api/types'
import { MASONRY_CAPTION_HEIGHT, masonryImageHeight, photoAspectRatio } from './masonry-metrics'
import { PhotoCard } from './PhotoCard'
import { useResponsiveColumnCount } from './useResponsiveColumnCount'

const MASONRY_COLUMN_RULES = [
  { minWidth: 1280, columns: 5 },
  { minWidth: 1024, columns: 4 },
  { minWidth: 640, columns: 3 },
  { minWidth: 0, columns: 2 },
]

const LOADING_ASPECT_RATIOS = [4 / 5, 3 / 2, 2 / 3, 1, 5 / 4, 3 / 4, 16 / 10, 4 / 3]

const SCROLL_FPS = 60
const OVERSCAN_BY = 4
const EMPTY_ITEMS: MasonryItem[] = []

interface MasonryViewProps {
  photos: PhotoDto[]
  settings: PublicSettingsDto | null
  grayscale: boolean
  immersive?: boolean
  loadingMore: boolean
  hasMore: boolean
  totalItems: number
  onLoadMore: (targetIndex?: number) => Promise<void>
  onPhotoClick: (photo: PhotoDto) => void
}

interface LoadingMasonryItem {
  kind: 'loading'
  id: string
  aspectRatio: number
}

interface PositionerCache {
  signature: string
  positioner: Positioner
  heights: number[]
  keys: string[]
}

type MasonryItem = PhotoDto | LoadingMasonryItem

function isLoadingItem(item: MasonryItem): item is LoadingMasonryItem {
  return 'kind' in item && item.kind === 'loading'
}

function getItemKey(item: MasonryItem) {
  return item.id
}

function getLoadingItemKey(index: number) {
  return `gallery-loading-${index}`
}

function computeItemHeight(item: MasonryItem, columnWidth: number, immersive: boolean) {
  const aspectRatio = isLoadingItem(item) ? item.aspectRatio : photoAspectRatio(item)
  const imageHeight = masonryImageHeight(columnWidth, aspectRatio)
  return immersive ? imageHeight : imageHeight + MASONRY_CAPTION_HEIGHT
}

function useWindowSize(): [number, number] {
  const [size, setSize] = useState<[number, number]>(() => (
    typeof window === 'undefined' ? [1024, 768] : [window.innerWidth, window.innerHeight]
  ))

  useEffect(() => {
    const handleResize = () => {
      setSize((current) => (
        current[0] === window.innerWidth && current[1] === window.innerHeight
          ? current
          : [window.innerWidth, window.innerHeight]
      ))
    }

    handleResize()
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return size
}

function LoadingMasonryCard({
  item,
  width,
  immersive,
}: {
  item: LoadingMasonryItem
  width: number
  immersive: boolean
}) {
  return (
    <div aria-hidden="true" className="w-full animate-pulse">
      <div
        className="w-full bg-muted"
        style={{ height: masonryImageHeight(width, item.aspectRatio) }}
      />
      {!immersive ? (
        // Mirrors PhotoCard's caption block: 16 + 20 + 6 + 18 = MASONRY_CAPTION_HEIGHT,
        // so swapping in the real card never shifts the caption area.
        <div className="mt-4 flex items-start justify-between gap-4">
          <div className="w-3/5">
            <div className="h-5 bg-muted" />
            <div className="mt-1.5 h-[18px] w-2/3 bg-muted" />
          </div>
          <div className="h-3 w-8 bg-muted" />
        </div>
      ) : null}
    </div>
  )
}

export function MasonryView({
  photos,
  settings,
  grayscale,
  immersive = false,
  loadingMore,
  hasMore,
  totalItems,
  onLoadMore,
  onPhotoClick,
}: MasonryViewProps) {
  const columnCount = useResponsiveColumnCount(MASONRY_COLUMN_RULES)
  const columnGutter = immersive ? 4 : columnCount >= 4 ? 32 : columnCount === 3 ? 24 : 8
  const rowGutter = immersive ? 4 : columnCount >= 4 ? 80 : columnCount === 3 ? 72 : 56

  const [windowWidth, windowHeight] = useWindowSize()
  const containerRef = useRef<HTMLElement | null>(null)
  const positionerCacheRef = useRef<PositionerCache | null>(null)
  const { offset, width } = useContainerPosition(containerRef, [windowWidth, windowHeight])
  const { scrollTop, isScrolling } = useScroller(offset, SCROLL_FPS)

  const items = useMemo<MasonryItem[]>(() => {
    const itemCount = Math.max(photos.length, totalItems)

    return Array.from({ length: itemCount }, (_, index) => (
      photos[index] ?? {
        kind: 'loading',
        id: getLoadingItemKey(index),
        aspectRatio: LOADING_ASPECT_RATIOS[index % LOADING_ASPECT_RATIOS.length],
      }
    ))
  }, [photos, totalItems])

  const columnWidth = Math.max(
    1,
    Math.floor((width - columnGutter * (columnCount - 1)) / columnCount),
  )

  // Every item height is known up front (photo dimensions or placeholder ratio),
  // so the positioner can be seeded before masonic renders. Keep the same
  // positioner across pagination appends; otherwise replacing a loading page
  // rebuilds every cached position and causes the visible masonry grid to flash.
  const positioner = useMemo(() => {
    const signature = `${columnCount}:${columnWidth}:${columnGutter}:${rowGutter}:${immersive}`
    const cache = positionerCacheRef.current

    let shouldReset =
      width <= 0 ||
      !cache ||
      cache.signature !== signature ||
      items.length < cache.keys.length

    if (!shouldReset && cache) {
      for (let index = 0; index < cache.keys.length; index++) {
        const previousKey = cache.keys[index]
        const nextItem = items[index]
        const nextKey = nextItem ? getItemKey(nextItem) : undefined

        if (previousKey !== nextKey && previousKey !== getLoadingItemKey(index)) {
          shouldReset = true
          break
        }
      }
    }

    if (shouldReset || !cache) {
      const next = createPositioner(columnCount, columnWidth, columnGutter, rowGutter)
      const heights: number[] = []
      const keys: string[] = []

      if (width > 0) {
        for (let index = 0; index < items.length; index++) {
          const height = computeItemHeight(items[index], columnWidth, immersive)
          next.set(index, height)
          heights[index] = height
          keys[index] = getItemKey(items[index])
        }
      }

      positionerCacheRef.current = { signature, positioner: next, heights, keys }
      return next
    }

    const updates: number[] = []
    const seededItems = cache.positioner.size()
    const existingItems = Math.min(seededItems, items.length)

    for (let index = 0; index < existingItems; index++) {
      const height = computeItemHeight(items[index], columnWidth, immersive)
      const key = getItemKey(items[index])

      if (cache.heights[index] !== height) {
        updates.push(index, height)
        cache.heights[index] = height
      }

      cache.keys[index] = key
    }

    if (updates.length > 0) {
      cache.positioner.update(updates)
    }

    for (let index = seededItems; index < items.length; index++) {
      const height = computeItemHeight(items[index], columnWidth, immersive)
      cache.positioner.set(index, height)
      cache.heights[index] = height
      cache.keys[index] = getItemKey(items[index])
    }

    return cache.positioner
  }, [columnCount, columnGutter, columnWidth, immersive, items, rowGutter, width])

  const resizeObserver = useResizeObserver(positioner)

  const renderItem = useCallback(({ data, index, width: cellWidth }: RenderComponentProps<MasonryItem>) => {
    if (isLoadingItem(data)) {
      return <LoadingMasonryCard item={data} width={cellWidth} immersive={immersive} />
    }

    return (
      <PhotoCard
        photo={data}
        index={index}
        width={cellWidth}
        settings={settings}
        grayscale={grayscale}
        immersive={immersive}
        onPhotoClick={onPhotoClick}
      />
    )
  }, [grayscale, immersive, onPhotoClick, settings])

  const handleRender = useCallback((_startIndex: number, stopIndex: number) => {
    if (!hasMore || loadingMore) return

    // Keep roughly two viewports of loaded photos ahead of the render window.
    const lookahead = Math.max(16, columnCount * 8)
    if (stopIndex + lookahead >= photos.length) {
      void onLoadMore(stopIndex)
    }
  }, [columnCount, hasMore, loadingMore, onLoadMore, photos.length])

  return useMasonry<MasonryItem>({
    positioner,
    resizeObserver,
    items: width > 0 ? items : EMPTY_ITEMS,
    height: windowHeight,
    scrollTop,
    isScrolling,
    overscanBy: OVERSCAN_BY,
    itemHeightEstimate: immersive ? 280 : 360,
    itemKey: getItemKey,
    render: renderItem,
    onRender: handleRender,
    role: 'list',
    tabIndex: -1,
    containerRef,
  })
}

'use client'

import { useState, useRef, useCallback, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Upload, X, Loader2, Image as ImageIcon, Send, Sparkles, Check, FolderOpen, Minimize2, Save, Clock, Trash2 } from 'lucide-react'
import { compressImage } from '@/lib/image-compress'
import { calculateFileHash } from '@/lib/file-hash'
import { useAuth } from '@/contexts/AuthContext'
import { resolveAssetUrl } from '@/lib/api/core'
import { getAdminAlbums, addPhotosToAlbum } from '@/lib/api/albums'
import { uploadPhotoWithProgress, checkDuplicatePhoto, getPhotos } from '@/lib/api/photos'
import { createStory } from '@/lib/api/stories'
import type { PhotoDto, AlbumDto } from '@/lib/api/types'
import { useSettings } from '@/contexts/SettingsContext'
import { useLanguage } from '@/contexts/LanguageContext'
import { useDropzone } from 'react-dropzone'
import { saveDraftToDB, getDraftFromDB, clearDraftFromDB } from '@/lib/client-db'
import { Toast, type Notification } from '@/components/Toast'
import { formatRelativeTimeLabel } from '@/lib/utils'

const AUTO_SAVE_DELAY = 2000 // 2 seconds debounce

interface QuickStoryEditorProps {
  onSuccess: () => void
}

export function QuickStoryEditor({ onSuccess }: QuickStoryEditorProps) {
  const { user, token } = useAuth()
  const { settings } = useSettings()
  const { t } = useLanguage()

  // UI State
  const [isExpanded, setIsExpanded] = useState(false)
  const [loading, setLoading] = useState(false)
  const [isAlbumOpen, setIsAlbumOpen] = useState(false)
  const [draftSaved, setDraftSaved] = useState(false)
  const [lastSavedAt, setLastSavedAt] = useState<number | null>(null)
  const [notifications, setNotifications] = useState<Notification[]>([])

  // Data State
  const [title, setTitle] = useState('')
  const [content, setContent] = useState('')
  const [photos, setPhotos] = useState<PhotoDto[]>([])
  const [pendingFiles, setPendingFiles] = useState<{ id: string; file: File; preview: string }[]>([])
  const [uploadQueue, setUploadQueue] = useState<{ id: string; progress: number }[]>([])
  const [albums, setAlbums] = useState<AlbumDto[]>([])

  // Drag reorder state
  const [draggedItemId, setDraggedItemId] = useState<string | null>(null)

  // Configuration State
  const [selectedAlbumIds, setSelectedAlbumIds] = useState<string[]>([])
  const [compressionEnabled, setCompressionEnabled] = useState(false)
  const [maxSizeMB, setMaxSizeMB] = useState(0)

  // Auto-save timer ref
  const autoSaveTimerRef = useRef<NodeJS.Timeout | null>(null)

  // Internal drag state to disable dropzone
  const [isInternalDragging, setIsInternalDragging] = useState(false)

  // Refs for click outside
  const containerRef = useRef<HTMLDivElement>(null)
  const albumRef = useRef<HTMLDivElement>(null)

  const isAnyPopoverOpen = isAlbumOpen

  // Toast notification helper
  const notify = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    const id = crypto.randomUUID()
    setNotifications(prev => [...prev, { id, message, type }])
    setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 3000)
  }, [])

  // Load draft from IndexedDB on mount
  useEffect(() => {
    async function loadDraft() {
      try {
        const draft = await getDraftFromDB()
        if (draft) {
          setTitle(draft.title || '')
          setContent(draft.content || '')
          setSelectedAlbumIds(draft.selectedAlbumIds || [])
          setLastSavedAt(draft.savedAt)

          if (draft.files && draft.files.length > 0) {
            const restoredFiles = draft.files.map(f => ({
              id: f.id,
              file: f.file,
              preview: URL.createObjectURL(f.file)
            }))
            setPendingFiles(restoredFiles)
          }

          if (draft.title || draft.content || (draft.files && draft.files.length > 0)) {
            setIsExpanded(true)
          }
        }
      } catch (e) {
        console.error('Failed to load draft', e)
      }
    }
    loadDraft()
  }, [])

  // Initial Data Fetch
  useEffect(() => {
    async function initData() {
      if (token && user?.isAdmin) {
        try {
          const adminAlbums = await getAdminAlbums(token)
          setAlbums(adminAlbums)
        } catch (e) {
          console.error('Failed to init editor data', e)
        }
      }
    }
    initData()
  }, [token, user?.isAdmin])

  // Auto-save draft when title, content, albums or files change
  useEffect(() => {
    if (!title && !content && selectedAlbumIds.length === 0 && pendingFiles.length === 0) return

    // Clear existing timer
    if (autoSaveTimerRef.current) {
      clearTimeout(autoSaveTimerRef.current)
    }

    // Set new timer for auto-save
    autoSaveTimerRef.current = setTimeout(() => {
      saveDraft()
    }, AUTO_SAVE_DELAY)

    return () => {
      if (autoSaveTimerRef.current) {
        clearTimeout(autoSaveTimerRef.current)
      }
    }
  }, [title, content, selectedAlbumIds, pendingFiles])

  // Save draft to IndexedDB
  const saveDraft = useCallback(async () => {
    if (!title && !content && pendingFiles.length === 0) return

    try {
      await saveDraftToDB({
        title,
        content,
        selectedAlbumIds,
        files: pendingFiles.map(f => ({ id: f.id, file: f.file }))
      })
      setLastSavedAt(Date.now())
      setDraftSaved(true)
      setTimeout(() => setDraftSaved(false), 2000)
    } catch (e) {
      console.error('Failed to save draft', e)
    }
  }, [title, content, selectedAlbumIds, pendingFiles])

  // Clear draft from IndexedDB
  const clearDraft = useCallback(async () => {
    try {
      await clearDraftFromDB()
      setLastSavedAt(null)
    } catch (e) {
      console.error('Failed to clear draft', e)
    }
  }, [])

  // Discard draft and reset all content
  const discardDraft = useCallback(async () => {
    // Clear draft from storage
    await clearDraft()

    // Cleanup preview URLs
    pendingFiles.forEach(f => URL.revokeObjectURL(f.preview))

    // Reset all form state
    setTitle('')
    setContent('')
    setPhotos([])
    setPendingFiles([])
    setSelectedAlbumIds([])
  }, [clearDraft, pendingFiles])

  // Format relative time
  const formatRelativeTime = useMemo(() => {
    if (!lastSavedAt) return null
    return formatRelativeTimeLabel(lastSavedAt, t)
  }, [lastSavedAt, t])

  // Click Outside Handler
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const target = event.target as Node
      if (albumRef.current && !albumRef.current.contains(target)) setIsAlbumOpen(false)
    }
    document.addEventListener('click', handleClickOutside, true)
    return () => document.removeEventListener('click', handleClickOutside, true)
  }, [])

  // File Selection Handler (Deferred Upload)
  const handleFilesSelected = useCallback((acceptedFiles: File[]) => {
    const newPendingFiles = acceptedFiles.map(file => ({
      id: crypto.randomUUID(),
      file,
      preview: URL.createObjectURL(file)
    }))
    setPendingFiles(prev => [...prev, ...newPendingFiles])
  }, [])

  // Remove pending file
  const removePendingFile = useCallback((id: string) => {
    setPendingFiles(prev => {
      const file = prev.find(f => f.id === id)
      if (file) URL.revokeObjectURL(file.preview)
      return prev.filter(f => f.id !== id)
    })
  }, [])

  // Cleanup preview URLs on unmount
  useEffect(() => {
    return () => {
      pendingFiles.forEach(f => URL.revokeObjectURL(f.preview))
    }
  }, [])

  const { getRootProps, getInputProps, isDragActive, open: openFileDialog } = useDropzone({
    onDrop: handleFilesSelected,
    accept: { 'image/*': ['.png', '.jpg', '.jpeg', '.webp', '.avif'] },
    noClick: true,
    noDrag: isInternalDragging, // Disable dropzone when dragging internal items
    noDragEventsBubbling: true
  })

  // Drag reorder handlers for pending files
  const handleDragStart = useCallback((e: React.DragEvent, id: string) => {
    e.stopPropagation() // Vital: prevent bubbling to dropzone
    setIsInternalDragging(true)
    setDraggedItemId(id)
    e.dataTransfer.effectAllowed = 'move'
    e.dataTransfer.setData('text/plain', id)
  }, [])

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.dataTransfer.dropEffect = 'move'
  }, [])

  // Optimized Move Logic
  const movePendingFile = useCallback((sourceId: string, targetId?: string) => {
    setPendingFiles(prev => {
      const sourceIndex = prev.findIndex(f => f.id === sourceId)
      if (sourceIndex === -1) return prev

      const newFiles = [...prev]
      const [draggedItem] = newFiles.splice(sourceIndex, 1)

      if (targetId) {
        const targetIndex = prev.findIndex(f => f.id === targetId)
        if (targetIndex !== -1) {
          newFiles.splice(targetIndex, 0, draggedItem)
        } else {
          newFiles.push(draggedItem)
        }
      } else {
        // Drop on container -> Append to end
        newFiles.push(draggedItem)
      }

      return newFiles
    })
  }, [])

  const handleDrop = useCallback((e: React.DragEvent, targetId: string) => {
    e.preventDefault()
    e.stopPropagation()

    if (draggedItemId && draggedItemId !== targetId) {
      movePendingFile(draggedItemId, targetId)
    }
    setDraggedItemId(null)
  }, [draggedItemId, movePendingFile])

  const handleDragEnd = useCallback(() => {
    setIsInternalDragging(false)
    setDraggedItemId(null)
  }, [])

  // Handle drop on empty space (append to end)
  const handleContainerDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()

    if (draggedItemId) {
      movePendingFile(draggedItemId)
    }
    setDraggedItemId(null)
  }, [draggedItemId, movePendingFile])

  // Submit Handler - Upload files first, then create story
  const handleSubmit = async () => {
    if (!title.trim() && !content.trim()) return
    if (!token) return

    try {
      setLoading(true)
      const uploadedPhotos: PhotoDto[] = [...photos]

      // Upload all pending files
      if (pendingFiles.length > 0) {
        setUploadQueue(pendingFiles.map(f => ({ id: f.id, progress: 0 })))

        for (const pending of pendingFiles) {
          let fileToUpload = pending.file

          // Compression Logic
          if (compressionEnabled) {
            fileToUpload = await compressImage(fileToUpload, {
              maxSizeMB: maxSizeMB > 0 ? maxSizeMB : undefined,
              maxWidthOrHeight: 4096,
            })
          }

          try {
            const fileHash = await calculateFileHash(pending.file)
            const duplicate = await checkDuplicatePhoto(token, fileHash)

            if (duplicate.isDuplicate && duplicate.existingPhoto) {
              let existingPhoto = photos.find((photo) => photo.id === duplicate.existingPhoto?.id)
                || uploadedPhotos.find((photo) => photo.id === duplicate.existingPhoto?.id)

              if (!existingPhoto) {
                const allPhotos = await getPhotos({ all: true })
                existingPhoto = allPhotos.find((photo) => photo.id === duplicate.existingPhoto?.id)
              }

              if (existingPhoto) {
                if (!uploadedPhotos.some((photo) => photo.id === existingPhoto.id)) {
                  uploadedPhotos.push(existingPhoto)
                }

                notify(`图片已重复，已替换为已上传照片：${existingPhoto.title}`, 'info')

                if (selectedAlbumIds.length > 0) {
                  await Promise.all(selectedAlbumIds.map(async (albumId) => {
                    try {
                      await addPhotosToAlbum(token, albumId, [existingPhoto.id])
                    } catch (error) {
                      console.error('Failed to add duplicate photo to album:', error)
                    }
                  }))
                }

                continue
              }
            }

            const result = await uploadPhotoWithProgress({
              token,
              file: fileToUpload,
              title: fileToUpload.name,
              file_hash: fileHash,
              show_flag: true,
              compression_mode: compressionEnabled ? 'compress' : undefined,
              max_size_mb: compressionEnabled && maxSizeMB > 0 ? maxSizeMB : undefined,
              onProgress: (progress) => {
                setUploadQueue(prev => prev.map(p => p.id === pending.id ? { ...p, progress } : p))
              }
            })

            if (!uploadedPhotos.some((photo) => photo.id === result.id)) {
              uploadedPhotos.push(result)
            }

            // Auto-link to albums
            if (selectedAlbumIds.length > 0) {
              await Promise.all(selectedAlbumIds.map(albumId =>
                addPhotosToAlbum(token, albumId, [result.id])
              ))
            }
          } catch (error) {
            console.error('Upload failed:', error)
          } finally {
            setUploadQueue(prev => prev.filter(p => p.id !== pending.id))
          }
        }
      }

      // Create the story with all uploaded photos
      await createStory(token, {
        title,
        content,
        isPublished: true,
        photoIds: uploadedPhotos.map(p => p.id),
        coverPhotoId: uploadedPhotos.length > 0 ? uploadedPhotos[0].id : undefined
      })

      // Cleanup preview URLs
      pendingFiles.forEach(f => URL.revokeObjectURL(f.preview))

      // Clear draft after successful publish
      clearDraft()

      // Reset Form
      setTitle('')
      setContent('')
      setPhotos([])
      setPendingFiles([])
      setUploadQueue([])
      setIsExpanded(false)

      // Show success toast
      notify(t('story.published'), 'success')

      onSuccess()
