    throw new Error('useUploadQueue must be used within UploadQueueProvider')
  }
  return context
}

const CONCURRENCY = 4
const MAX_RETRIES = 2
const RETRY_DELAY_MS = 2000
const AVIF_FILE_TYPE = 'image/avif'
const AVIF_EXTENSION = '.avif'
const RETRYABLE_ERROR_PATTERNS = [
  /^Network error/i,
  /^Upload timeout/i,
  /^Failed to fetch/i,
  /TypeError/i,
  /network/i,
  /ECONNRESET/i,
  /ETIMEDOUT/i,
]

function isRetryableError(err: unknown): boolean {
  if (!(err instanceof Error)) return false
  return RETRYABLE_ERROR_PATTERNS.some((p) => p.test(err.message))
}

function replaceFileExtension(filename: string, extension: string) {
  return filename.replace(/\.[^.]*$/, '') + extension
}

function getFilenameFromStorageValue(value: string | null | undefined) {
  if (!value) return undefined
  try {
    const pathname = /^https?:\/\//i.test(value) ? new URL(value).pathname : value
    const normalized = pathname.replace(/\\/g, '/')
    const filename = normalized.split('/').filter(Boolean).pop()
    return filename || undefined
  } catch {
    const normalized = value.replace(/\\/g, '/')
    return normalized.split('/').filter(Boolean).pop() || undefined
  }
}

function inferFileTypeFromName(filename: string | undefined, fallback?: string) {
  const extension = filename?.split('.').pop()?.toLowerCase()
  switch (extension) {
    case 'avif':
      return 'image/avif'
    case 'webp':
      return 'image/webp'
    case 'jpg':
    case 'jpeg':
      return 'image/jpeg'
    case 'png':
      return 'image/png'
    case 'gif':
      return 'image/gif'
    default:
      return fallback
  }
}

export function UploadQueueProvider({
  children,
  onUploadComplete,
}: {
  children: React.ReactNode
  onUploadComplete?: (photoIds: string[], storyId?: string, albumIds?: string[], failedCount?: number) => void
}) {
  const [tasks, setTasks] = useState<UploadTask[]>([])
  const [isMinimized, setIsMinimized] = useState(false)
  const activeUploadsRef = useRef(0)
  const tokenRef = useRef<string>('')
  const onUploadCompleteRef = useRef(onUploadComplete)
  const notifiedBatchesRef = useRef<Set<string>>(new Set())
  const uploadingTasksRef = useRef<Set<string>>(new Set()) // Track tasks currently being uploaded

  // Keep the ref updated
  useEffect(() => {
    onUploadCompleteRef.current = onUploadComplete
  }, [onUploadComplete])

  const createPreview = (file: File): Promise<string | null> => {
    return new Promise((resolve) => {
      const reader = new FileReader()
      reader.onload = (e) => resolve(e.target?.result as string)
      reader.onerror = () => resolve(null)
      reader.readAsDataURL(file)
    })
  }

  const updateTaskProgress = useCallback((taskId: string, progress: number, status?: UploadTaskStatus) => {
    setTasks((prev) =>
      prev.map((t) =>
        t.id === taskId ? { ...t, progress, ...(status && { status }) } : t
      )
    )
  }, [])

  const notifyBatchComplete = useCallback(async (batchId: string, storyId: string | undefined, albumIds: string[] | undefined, filmRollId: string | undefined, photoIds: string[], failedCount: number) => {
    // Double-check we haven't already notified for this batch
    if (notifiedBatchesRef.current.has(batchId)) {
      return
    }
    notifiedBatchesRef.current.add(batchId)

    // If storyId is provided, add photos to the story
    if (storyId && photoIds.length > 0 && tokenRef.current) {
      try {
        await addPhotosToStory(tokenRef.current, storyId, photoIds)
      } catch (err) {
        console.error(`Failed to add photos to story ${storyId}:`, err)
      }
    }

    // If albumIds are provided, add photos to each album in parallel
    if (albumIds && albumIds.length > 0 && photoIds.length > 0 && tokenRef.current) {
      await Promise.all(
        albumIds.map(async (albumId) => {
          try {
            await addPhotosToAlbum(tokenRef.current, albumId, photoIds)
          } catch (err) {
            console.error(`Failed to add photos to album ${albumId}:`, err)
          }
        })
      )
    }

    // If filmRollId is provided, add photos to the film roll
    if (filmRollId && photoIds.length > 0 && tokenRef.current) {
      try {
        await addPhotosToFilmRoll(tokenRef.current, filmRollId, photoIds)
      } catch (err) {
        console.error(`Failed to add photos to film roll ${filmRollId}:`, err)
      }
    }

    if ((photoIds.length > 0 || failedCount > 0) && onUploadCompleteRef.current) {
      onUploadCompleteRef.current(photoIds, storyId, albumIds, failedCount)
    }
  }, [])

  const processQueue = useCallback(() => {
    setTasks((currentTasks) => {
      const pendingTasks = currentTasks.filter(
        (t) => t.status === 'pending' && !uploadingTasksRef.current.has(t.id)
      )
      const availableSlots = CONCURRENCY - activeUploadsRef.current

      if (availableSlots <= 0 || pendingTasks.length === 0) {
        return currentTasks
      }

      const tasksToStart = pendingTasks.slice(0, availableSlots)
      activeUploadsRef.current += tasksToStart.length

      // Mark tasks as uploading to prevent duplicate uploads
      tasksToStart.forEach((task) => {
        uploadingTasksRef.current.add(task.id)
        uploadSingleFile(task)
      })

      return currentTasks.map((t) =>
        tasksToStart.some((ts) => ts.id === t.id)
          ? {
              ...t,
              status: (t.compressionMode && t.compressionMode !== 'none'
                ? 'compressing'
                : 'uploading') as UploadTaskStatus,
              progress: 0,
            }
          : t
      )
    })
  }, [])

  const uploadSingleFile = async (task: UploadTask) => {
    try {
      let fileToUpload = task.file
      let compressedSize: number | undefined
      const shouldCompress = task.compressionMode && task.compressionMode !== 'none'

      const latestToken = typeof window !== 'undefined' ? localStorage.getItem('token') : null
      if (latestToken) tokenRef.current = latestToken

      // Extract EXIF from the original file before compression (compression
      // discards EXIF). GPS is stripped from the JSON here when enabled;
      // the server also strips GPS as a fallback via strip_gps.
      let exifJsonString: string | undefined
      try {
        let exifJson = await extractExifToJson(task.file)
        if (task.stripGps) {
          exifJson = stripGpsFromExifJson(exifJson)
        }
        if (Object.keys(exifJson).length > 0) {
          exifJsonString = JSON.stringify(exifJson)
        }
      } catch {
        // EXIF read failure should not block upload
      }

      // Step 1: Convert unsupported browser-upload formats if needed, then compress
      if (fileToUpload.type === 'image/bmp') {
        fileToUpload = await convertImageToJpeg(fileToUpload)
        compressedSize = fileToUpload.size
        setTasks((prev) =>
          prev.map((t) =>
            t.id === task.id
              ? {
                  ...t,
                  compressedSize,
                  fileSize: compressedSize!,
                  targetFileName: fileToUpload.name,
                  targetFileSize: compressedSize,
                  targetFileType: fileToUpload.type,
                }
              : t
          )
        )
      }

      if (shouldCompress) {
        try {
          fileToUpload = await compressImage(
            fileToUpload,
            { mode: task.compressionMode, maxSizeMB: task.maxSizeMB, maxWidthOrHeight: task.maxWidthOrHeight },
            (progress) => {
              updateTaskProgress(task.id, Math.round(progress * 0.3))
            }
          )
          compressedSize = fileToUpload.size

          // Update compressed size info
          setTasks((prev) =>
            prev.map((t) =>
              t.id === task.id
                ? {
                    ...t,
                    compressedSize,
                    fileSize: compressedSize!,
                    targetFileSize: compressedSize,
                    targetFileType: AVIF_FILE_TYPE,
                  }
                : t
            )
          )
        } catch (compressError) {
          const message =
            compressError instanceof Error && compressError.message
              ? compressError.message
              : 'Image compression failed'
          console.warn(`[upload] Compression failed for ${task.fileName}, falling back to original: ${message}`)
          compressedSize = fileToUpload.size
          setTasks((prev) =>
            prev.map((t) =>
              t.id === task.id
                ?                 {
                    ...t,
                    compressedSize: undefined,
                    fileSize: fileToUpload.size,
                    targetFileSize: fileToUpload.size,
                    targetFileType: AVIF_FILE_TYPE,
                    error: null,
                  }
                : t
            )
          )
        }
      }

      // Step 2: Upload (progress mapped from 30% to 100% if browser compression ran, else 0% to 100%)
      const browserCompressed = task.compressionMode && task.compressionMode !== 'none'
      const uploadProgressOffset = browserCompressed ? 30 : 0
      const uploadProgressRange = 100 - uploadProgressOffset

      const photo = await uploadPhotoWithProgress({
        token: tokenRef.current,
        file: fileToUpload,
        title: task.title,
        category: task.categories,
        storage_provider: task.storageProvider,
        storage_source_id: task.storageSourceId,
        storage_path: task.storagePath,
        storage_path_full: task.storagePathFull,
        file_hash: task.fileHash,
        film_roll_id: task.filmRollId,
        show_flag: task.showFlag,
        compression_mode: task.compressionMode,
        max_size_mb: task.maxSizeMB,
        exif_json: exifJsonString,
        strip_gps: task.stripGps ? 'true' : undefined,
        onProgress: (progress) => {
          const mappedProgress = Math.round(uploadProgressOffset + (progress / 100) * uploadProgressRange)
          updateTaskProgress(task.id, mappedProgress, 'uploading')
        },
      })

      // Update task status and check batch completion
      setTasks((prev) => {
        const updated = prev.map((t) =>
          t.id === task.id
            ? {
                ...t,
                status: 'completed' as UploadTaskStatus,
                progress: 100,
                photoId: photo.id,
                targetFileName: getFilenameFromStorageValue(photo.storageKey || photo.url) ?? t.targetFileName ?? fileToUpload.name,
                targetFileSize: photo.size ?? t.targetFileSize ?? fileToUpload.size,
                targetFileType: inferFileTypeFromName(photo.storageKey || photo.url, t.targetFileType ?? fileToUpload.type),
                compressedSize: photo.size ?? t.compressedSize,
                fileSize: photo.size ?? t.fileSize,
              }
            : t
        )

        // Check if this batch is complete
        const batchTasks = updated.filter((t) => t.batchId === task.batchId)
        const allDone = batchTasks.every((t) => t.status === 'completed' || t.status === 'failed')

        if (allDone && !notifiedBatchesRef.current.has(task.batchId)) {
          const completedTasks = batchTasks.filter((t) => t.status === 'completed')
          const failedTasks = batchTasks.filter((t) => t.status === 'failed')
          const photoIds = completedTasks
            .map((t) => t.photoId)
            .filter((id): id is string => !!id)

          // Schedule notification outside of setState
          setTimeout(() => {
            notifyBatchComplete(task.batchId, task.storyId, task.albumIds, task.filmRollId, photoIds, failedTasks.length)
          }, 0)
        }

        return updated
      })
    } catch (err) {
      const currentRetry = task.retryCount ?? 0
      const canRetry = isRetryableError(err) && currentRetry < MAX_RETRIES

      if (canRetry) {
        setTasks((prev) =>
          prev.map((t) =>
            t.id === task.id
              ? {
                  ...t,
                  status: 'pending' as UploadTaskStatus,
                  error: `Retry ${currentRetry + 1}/${MAX_RETRIES}...`,
                  progress: 0,
                  retryCount: currentRetry + 1,
                }
              : t
          )
        )
        setTimeout(processQueue, RETRY_DELAY_MS)
      } else {
        setTasks((prev) => {
          const updated = prev.map((t) =>
            t.id === task.id
              ? {
                  ...t,
                  status: 'failed' as UploadTaskStatus,
                  error: err instanceof Error ? err.message : 'Upload failed',
                }
              : t
          )

          // Check if this batch is complete (all done, even with failures)
          const batchTasks = updated.filter((t) => t.batchId === task.batchId)
          const allDone = batchTasks.every((t) => t.status === 'completed' || t.status === 'failed')

          if (allDone && !notifiedBatchesRef.current.has(task.batchId)) {
            const completedTasks = batchTasks.filter((t) => t.status === 'completed')
            const failedTasks = batchTasks.filter((t) => t.status === 'failed')
            const photoIds = completedTasks
              .map((t) => t.photoId)
              .filter((id): id is string => !!id)

            if (photoIds.length > 0 || failedTasks.length > 0) {
              setTimeout(() => {
                notifyBatchComplete(task.batchId, task.storyId, task.albumIds, task.filmRollId, photoIds, failedTasks.length)
              }, 0)
            }
          }

          return updated
        })
      }
    } finally {
      activeUploadsRef.current--
      uploadingTasksRef.current.delete(task.id) // Remove from uploading set
      // Process next in queue
      queueMicrotask(processQueue)
    }
  }

  const addTasks = useCallback(
    async (params: {
      files: { id: string; file: File; fileHash?: string }[]
      title: string
      categories: string[]
      storageProvider?: string
      storageSourceId?: string
      storagePath?: string
      storagePathFull?: boolean
      storyId?: string
      albumIds?: string[]
      filmRollId?: string
      showFlag?: boolean
      compressionMode?: CompressionMode
      maxSizeMB?: number
      maxWidthOrHeight?: number
      stripGps?: boolean
      token: string
    }) => {
      tokenRef.current = params.token

      // Generate a unique batch ID for this upload session
      const batchId = `batch-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`

      const newTasks: UploadTask[] = await Promise.all(
        params.files.map(async (item) => {
          const preview = await createPreview(item.file)
          const fallbackTitle = item.file.name.replace(/\.[^/.]+$/, '')
          const normalizedTitle = params.title.trim() || fallbackTitle
          return {
            id: item.id,
            file: item.file,
            fileName: item.file.name,
            fileSize: item.file.size,
            originalSize: item.file.size,
            preview,
            status: 'pending' as UploadTaskStatus,
            progress: 0,
            error: null,
            title:
              params.files.length === 1
                ? normalizedTitle
                : fallbackTitle,
            categories: params.categories,
            storageProvider: params.storageProvider,
            storageSourceId: params.storageSourceId,
            storagePath: params.storagePath,
            storagePathFull: params.storagePathFull,
            storyId: params.storyId,
            albumIds: params.albumIds,
            filmRollId: params.filmRollId,
            showFlag: params.showFlag ?? true,
            fileHash: item.fileHash,
            compressionMode: params.compressionMode,
            maxSizeMB: params.maxSizeMB,
            maxWidthOrHeight: params.maxWidthOrHeight,
            stripGps: params.stripGps,
            batchId,
          }
        })
      )

      setTasks((prev) => [...prev, ...newTasks])
      setIsMinimized(false)

      // Start processing queue
      queueMicrotask(processQueue)
    },
    [processQueue]
  )

  const retryTask = useCallback(
    (taskId: string, token: string) => {
      tokenRef.current = token

      setTasks((prev) => {
        const task = prev.find((t) => t.id === taskId)
        if (task) {
          // Remove the old batch from notified set so it can notify again
          notifiedBatchesRef.current.delete(task.batchId)
        }
        return prev.map((t) =>
          t.id === taskId
            ? { ...t, status: 'pending' as UploadTaskStatus, error: null, progress: 0 }
            : t
        )
      })
      setTimeout(processQueue, 0)
    },
    [processQueue]
  )

  const removeTask = useCallback((taskId: string) => {
    setTasks((prev) => {
      const task = prev.find((t) => t.id === taskId)
      if (task?.preview) {
        URL.revokeObjectURL(task.preview)
      }
      return prev.filter((t) => t.id !== taskId)
    })
  }, [])

  const clearCompleted = useCallback(() => {
    setTasks((prev) => {
      prev
        .filter((t) => t.status === 'completed')
        .forEach((t) => {
          if (t.preview) URL.revokeObjectURL(t.preview)
        })
      return prev.filter((t) => t.status !== 'completed')
    })
  }, [])

  const clearAll = useCallback(() => {
    setTasks((prev) => {
      prev.forEach((t) => {
        if (t.preview) URL.revokeObjectURL(t.preview)
      })
      return []
    })
    notifiedBatchesRef.current.clear()
  }, [])

  return (
    <UploadQueueContext.Provider
      value={{
        tasks,
        isMinimized,
        setIsMinimized,
        addTasks,
        retryTask,
        removeTask,
        clearCompleted,
        clearAll,
      }}
    >
      {children}
    </UploadQueueContext.Provider>
  )
}

/**
 * Privacy Strip Utility
 * 
 * Removes GPS/location data from images before upload.
 * This utility preserves other EXIF data like camera settings, date taken, etc.
 */

// GPS-related EXIF tags to remove (IFD GPS tags)
const GPS_TAGS_TO_REMOVE = [
  'GPSVersionID',
  'GPSLatitudeRef',
  'GPSLatitude',
  'GPSLongitudeRef',
  'GPSLongitude',
  'GPSAltitudeRef',
  'GPSAltitude',
  'GPSTimeStamp',
  'GPSSatellites',
  'GPSStatus',
  'GPSMeasureMode',
  'GPSDOP',
  'GPSSpeedRef',
  'GPSSpeed',
  'GPSTrackRef',
  'GPSTrack',
  'GPSImgDirectionRef',
  'GPSImgDirection',
  'GPSMapDatum',
  'GPSDestLatitudeRef',
  'GPSDestLatitude',
  'GPSDestLongitudeRef',
  'GPSDestLongitude',
  'GPSDestBearingRef',
  'GPSDestBearing',
  'GPSDestDistanceRef',
  'GPSDestDistance',
  'GPSProcessingMethod',
  'GPSAreaInformation',
  'GPSDateStamp',
  'GPSDifferential',
  'GPSHPositioningError',
]

/**
 * Strips GPS/location data from a JPEG image while preserving other EXIF data.
 * For non-JPEG images, returns the original file unchanged.
 * 
 * @param file - The image file to process
 * @returns A new File with GPS data removed (for JPEG) or the original file
 */
export async function stripGpsData(file: File): Promise<File> {
  // Only process JPEG images (EXIF is primarily in JPEG)
  if (!file.type.includes('jpeg') && !file.type.includes('jpg')) {
    return file
  }

  try {
    const arrayBuffer = await file.arrayBuffer()
    const dataView = new DataView(arrayBuffer)
    
    // Check for JPEG magic number
    if (dataView.getUint16(0) !== 0xFFD8) {
      return file
    }

    // Find and process EXIF data
    const strippedBuffer = await removeGpsFromJpeg(arrayBuffer)
    
    if (strippedBuffer) {
      return new File([strippedBuffer], file.name, {
        type: file.type,
        lastModified: Date.now(),
      })
    }
    
    return file
  } catch (error) {
    console.warn('Failed to strip GPS data, returning original file:', error)
    return file
  }
}

/**
 * Removes GPS IFD from JPEG EXIF data
 */
async function removeGpsFromJpeg(buffer: ArrayBuffer): Promise<ArrayBuffer | null> {
  const data = new Uint8Array(buffer)
  let offset = 2 // Skip SOI marker
  
  while (offset < data.length - 1) {
    // Check for marker
    if (data[offset] !== 0xFF) {
      offset++
      continue
    }
    
    const marker = data[offset + 1]
    
    // End of image
    if (marker === 0xD9) break
    
    // APP1 marker (EXIF)
    if (marker === 0xE1) {
      const segmentLength = (data[offset + 2] << 8) | data[offset + 3]
      
      // Check for "Exif\0\0" identifier
      if (
        data[offset + 4] === 0x45 && // E
        data[offset + 5] === 0x78 && // x
        data[offset + 6] === 0x69 && // i
        data[offset + 7] === 0x66 && // f
        data[offset + 8] === 0x00 &&
        data[offset + 9] === 0x00
      ) {
        // Found EXIF segment, process it
        const exifStart = offset + 10 // Start of TIFF header
        const processedExif = processExifSegment(data, exifStart, segmentLength - 8)
        
        if (processedExif) {
          // Rebuild the JPEG with modified EXIF
          const newBuffer = new Uint8Array(buffer.byteLength)
          
          // Copy everything before EXIF segment
          newBuffer.set(data.subarray(0, offset + 4), 0)
          
          // Write "Exif\0\0"
          newBuffer.set([0x45, 0x78, 0x69, 0x66, 0x00, 0x00], offset + 4)
          
          // Write processed EXIF
          newBuffer.set(processedExif, offset + 10)
          
          // Update segment length
          const newSegmentLength = processedExif.length + 8
          newBuffer[offset + 2] = (newSegmentLength >> 8) & 0xFF
          newBuffer[offset + 3] = newSegmentLength & 0xFF
          
          // Copy rest of the file
          const restStart = offset + 2 + segmentLength
          const newRestStart = offset + 10 + processedExif.length
          newBuffer.set(data.subarray(restStart), newRestStart)
          
          // Trim to actual size
          const actualSize = newRestStart + (data.length - restStart)
          return newBuffer.buffer.slice(0, actualSize)
        }
      }
    }
    
    // Skip to next marker
    if (marker >= 0xD0 && marker <= 0xD9) {
      // Standalone markers (RST, SOI, EOI)
      offset += 2
    } else {
      // Markers with length
      const length = (data[offset + 2] << 8) | data[offset + 3]
      offset += 2 + length
    }
  }
  
  return null
}

/**
 * Process EXIF segment to remove GPS IFD
 */
function processExifSegment(
  data: Uint8Array,
  exifStart: number,
  exifLength: number
): Uint8Array | null {
  try {
    // Copy EXIF data to work with
    const exifData = data.slice(exifStart, exifStart + exifLength)
    const view = new DataView(exifData.buffer, exifData.byteOffset, exifData.byteLength)
    
    // Determine byte order
    const byteOrder = view.getUint16(0)
    const littleEndian = byteOrder === 0x4949 // "II" = Intel = little endian
    
    // Verify TIFF magic number
    if (view.getUint16(2, littleEndian) !== 0x002A) {
      return null
    }
    
    // Get IFD0 offset
    const ifd0Offset = view.getUint32(4, littleEndian)
    
    // Process IFD0 to find and nullify GPS IFD pointer
    const numEntries = view.getUint16(ifd0Offset, littleEndian)
    
    for (let i = 0; i < numEntries; i++) {
      const entryOffset = ifd0Offset + 2 + i * 12
      const tag = view.getUint16(entryOffset, littleEndian)
      
      // GPS IFD Pointer tag (0x8825)
      if (tag === 0x8825) {
        // Zero out the GPS IFD pointer value
        // This effectively removes the GPS data reference
        view.setUint32(entryOffset + 8, 0, littleEndian)
        
        // Also zero out the GPS IFD data if we can find it
        const gpsIfdOffset = view.getUint32(entryOffset + 8, littleEndian)
        if (gpsIfdOffset > 0 && gpsIfdOffset < exifData.length - 2) {
          const gpsNumEntries = view.getUint16(gpsIfdOffset, littleEndian)
          // Zero out GPS IFD entries
          for (let j = 0; j < gpsNumEntries && gpsIfdOffset + 2 + j * 12 + 12 <= exifData.length; j++) {
            const gpsEntryOffset = gpsIfdOffset + 2 + j * 12
            // Zero out each GPS entry
            for (let k = 0; k < 12; k++) {
              exifData[gpsEntryOffset + k] = 0
            }
          }
        }
        
        break
      }
    }
    
    return exifData
  } catch (error) {
    console.warn('Error processing EXIF segment:', error)
    return null
  }
}

/**
 * Strips GPS data from multiple files
 * 
 * @param files - Array of files to process
 * @param onProgress - Optional progress callback
 * @returns Array of processed files
 */
export async function stripGpsDataBatch(
  files: File[],
  onProgress?: (current: number, total: number) => void
): Promise<File[]> {
  const results: File[] = []
  
  for (let i = 0; i < files.length; i++) {
    results.push(await stripGpsData(files[i]))
    onProgress?.(i + 1, files.length)
  }
  
  return results
}

/**
 * Check if a file likely contains GPS data
 * This is a quick check, not a full parse
 * 
 * @param file - The file to check
 * @returns true if GPS data might be present
 */
export async function mightContainGpsData(file: File): Promise<boolean> {
  if (!file.type.includes('jpeg') && !file.type.includes('jpg')) {
    return false
  }

  try {
    // Read first 64KB which should contain EXIF
    const slice = file.slice(0, 65536)
    const buffer = await slice.arrayBuffer()
    const data = new Uint8Array(buffer)
    
    // Look for GPS IFD tag (0x8825) in the data
    // This is a simplified check
    for (let i = 0; i < data.length - 1; i++) {
      // Check for GPS IFD tag in both byte orders
      if ((data[i] === 0x88 && data[i + 1] === 0x25) ||
          (data[i] === 0x25 && data[i + 1] === 0x88)) {
        return true
      }
    }
    
    return false
  } catch {
    return false
  }
}

'use client'

import React, { useState } from 'react'
import {
  BookText,
  Plus,
  History,
  FileText,
  Edit3,
  Trash2,
  ChevronLeft,
  Save,
  ImageIcon,
  X,
} from 'lucide-react'
import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'
import { PhotoDto, resolveAssetUrl, PublicSettingsDto } from '@/lib/api'

interface PhotoLog {
  id: string
  title: string
  content: string
  createdAt: string
  updatedAt: string
  status: 'draft' | 'published'
}

interface BlogTabProps {
  photos: PhotoDto[]
  settings: PublicSettingsDto | null
  t: (key: string) => string
  notify: (message: string, type?: 'success' | 'error' | 'info') => void
}

export function BlogTab({ photos, settings, t, notify }: BlogTabProps) {
  const [photoLogs, setPhotoLogs] = useState<PhotoLog[]>([
    {
      id: '1',
      title: 'Winter in Tokyo',
      content: 'Morning walk in Shibuya...',
      createdAt: '2025-12-20',
      updatedAt: '2025-12-21',
      status: 'published',
    },
    {
      id: '2',
      title: 'Draft: Mountain Peak',
      content: 'Gear used: Leica M11...',
      createdAt: '2025-12-22',
      updatedAt: '2025-12-22',
      status: 'draft',
    },
  ])
  const [currentLog, setCurrentLog] = useState<PhotoLog | null>(null)
  const [logEditMode, setLogEditMode] = useState<'list' | 'editor'>('list')
  const [logPreviewActive, setLogPreviewActive] = useState(false)
  const [isLogInsertingPhoto, setIsLogInsertingPhoto] = useState(false)

  const handleCreateLog = () => {
    setCurrentLog({
      id: crypto.randomUUID(),
      title: '',
      content: '',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: 'draft',
    })
    setLogEditMode('editor')
    setLogPreviewActive(false)
  }

  const handleEditLog = (log: PhotoLog) => {
    setCurrentLog({ ...log })
    setLogEditMode('editor')
    setLogPreviewActive(false)
  }

  const handleDeleteLog = (id: string) => {
    if (!window.confirm(t('common.confirm') + '?')) return
    setPhotoLogs((prev) => prev.filter((l) => l.id !== id))
    notify(t('admin.notify_log_deleted'))
  }

  const handleSaveLog = () => {
    if (!currentLog) return
    setPhotoLogs((prev) => {
      const idx = prev.findIndex((l) => l.id === currentLog.id)
      if (idx !== -1) {
        const next = [...prev]
        next[idx] = { ...currentLog, updatedAt: new Date().toISOString() }
        return next
      }
      return [
        ...prev,
        { ...currentLog, updatedAt: new Date().toISOString() },
      ]
    })
    setLogEditMode('list')
    setCurrentLog(null)
    notify(t('admin.notify_log_saved'))
  }

  const insertPhotoIntoLog = (photo: PhotoDto) => {
    const markdown = `\n![${photo.title}](${resolveAssetUrl(
      photo.url,
      settings?.cdn_domain
    )})\n`
    if (currentLog) {
      setCurrentLog({ ...currentLog, content: currentLog.content + markdown })
    }
    setIsLogInsertingPhoto(false)
    notify(t('admin.notify_photo_inserted'), 'info')
  }

  const resolvedCdnDomain = settings?.cdn_domain?.trim() || undefined

  return (
    <div className="h-full flex flex-col gap-6 overflow-hidden">
      {logEditMode === 'list' ? (
        <div className="space-y-8 flex-1 flex flex-col overflow-hidden">
          <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
            <div className="flex items-center gap-4">
              <BookText className="w-6 h-6 text-primary" />
              <h3 className="font-serif text-2xl uppercase tracking-tight">
                {t('admin.logs')}
              </h3>
            </div>
            <button
              onClick={handleCreateLog}
              className="flex items-center px-6 py-2 bg-primary text-primary-foreground text-xs font-bold uppercase tracking-widest hover:opacity-90 transition-all"
            >
              <Plus className="w-4 h-4 mr-2" />
              {t('admin.new_log')}
            </button>
          </div>
          <div className="flex-1 overflow-y-auto custom-scrollbar">
            <div className="grid grid-cols-1 gap-4">
              {photoLogs.map((log) => (
                <div
                  key={log.id}
                  className="flex items-center justify-between p-6 border border-border hover:border-primary transition-all group"
                >
                  <div
                    className="flex-1 min-w-0"
                    onClick={() => handleEditLog(log)}
                    style={{ cursor: 'pointer' }}
                  >
                    <div className="flex items-center gap-3 mb-1">
                      <h4 className="font-serif text-xl group-hover:text-primary transition-colors">
                        {log.title || t('admin.untitled')}
                      </h4>
                      <span
                        className={`text-[8px] font-black uppercase px-1.5 py-0.5 border ${
                          log.status === 'published'
                            ? 'border-primary text-primary'
                            : 'border-muted-foreground text-muted-foreground'
                        }`}
                      >
                        {log.status}
                      </span>
                    </div>
                    <div className="flex items-center gap-4 text-[10px] text-muted-foreground font-mono uppercase">
                      <span className="flex items-center gap-1">
                        <History className="w-3 h-3" />{' '}
                        {new Date(log.updatedAt).toLocaleDateString()}
                      </span>
                      <span className="flex items-center gap-1">
                        <FileText className="w-3 h-3" /> {log.content.length}{' '}
                        {t('admin.characters')}
                      </span>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    <button
                      onClick={() => handleEditLog(log)}
                      className="p-2 text-muted-foreground hover:text-primary transition-colors"
                    >
                      <Edit3 className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDeleteLog(log.id)}
                      className="p-2 text-muted-foreground hover:text-destructive transition-colors"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
              {photoLogs.length === 0 && (
                <div className="py-24 text-center border border-dashed border-border">
                  <BookText className="w-12 h-12 mx-auto mb-4 opacity-10" />
                  <p className="text-xs font-bold uppercase tracking-widest text-muted-foreground">
                    {t('admin.no_logs')}
                  </p>
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="flex-1 flex flex-col gap-6 overflow-hidden">
          <div className="flex items-center justify-between border-b border-border pb-4 flex-shrink-0">
            <button
              onClick={() => setLogEditMode('list')}
              className="flex items-center gap-2 text-xs font-bold uppercase tracking-widest hover:text-primary transition-colors"
            >
              <ChevronLeft className="w-4 h-4" /> {t('admin.back_list')}
            </button>
            <div className="flex items-center gap-4">
              <div className="flex bg-muted p-1 border border-border">
                <button
                  onClick={() => setLogPreviewActive(false)}
                  className={`p-1.5 transition-all text-[10px] font-black uppercase px-3 ${
                    !logPreviewActive
                      ? 'bg-background text-primary'
                      : 'text-muted-foreground'
                  }`}
                >
                  {t('admin.edit_log')}
                </button>
                <button
                  onClick={() => setLogPreviewActive(true)}
                  className={`p-1.5 transition-all text-[10px] font-black uppercase px-3 ${
                    logPreviewActive
                      ? 'bg-background text-primary'
                      : 'text-muted-foreground'
                  }`}
                >
                  {t('admin.preview')}
                </button>
              </div>
              <button
                onClick={handleSaveLog}
                className="flex items-center gap-2 px-6 py-2 bg-primary text-primary-foreground text-xs font-bold uppercase tracking-widest hover:opacity-90 transition-all"
              >
                <Save className="w-4 h-4" />
                <span>{t('admin.save')}</span>
              </button>
            </div>
          </div>
          <div className="flex-1 flex flex-col gap-4 overflow-hidden relative">
            {logPreviewActive ? (
              <div className="flex-1 overflow-y-auto custom-scrollbar border border-border bg-background p-12 prose prose-invert max-w-none prose-gold prose-serif">
                <h1 className="font-serif text-5xl mb-12 border-b border-border pb-6">
                  {currentLog?.title || t('admin.untitled')}
                </h1>
                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                  {currentLog?.content || ''}
                </ReactMarkdown>
              </div>
            ) : (
              <div className="flex-1 flex flex-col gap-4 overflow-hidden">
                <input
                  type="text"
                  value={currentLog?.title || ''}
                  onChange={(e) =>
                    setCurrentLog((prev) => ({
                      ...prev!,
                      title: e.target.value,
                    }))
                  }
                  placeholder={t('admin.log_title')}
                  className="w-full p-6 bg-transparent border border-border focus:border-primary outline-none text-2xl font-serif rounded-none"
                />
                <div className="flex-1 relative border border-border bg-card/30">
                  <textarea
                    value={currentLog?.content || ''}
                    onChange={(e) =>
                      setCurrentLog((prev) => ({
                        ...prev!,
                        content: e.target.value,
                      }))
                    }
                    placeholder={t('admin.log_content')}
                    className="w-full h-full p-8 bg-transparent outline-none resize-none font-mono text-sm leading-relaxed custom-scrollbar"
                  />
                  <button
                    onClick={() => setIsLogInsertingPhoto(true)}
                    className="absolute bottom-6 right-6 p-4 bg-background border border-border hover:border-primary text-primary transition-all shadow-2xl z-10"
                    title={t('admin.associate_photos')}
                  >
                    <ImageIcon className="w-6 h-6" />
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Archive Selection Modal for Logs (moved inside BlogTab) */}
      {isLogInsertingPhoto && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 md:p-12 bg-background/95 backdrop-blur-sm">
          <div className="w-full h-full max-w-6xl bg-background border border-border flex flex-col overflow-hidden shadow-2xl">
            <div className="p-6 border-b border-border flex items-center justify-between">
              <h3 className="font-serif text-2xl uppercase tracking-tight">
                {t('admin.insert_photo')}
              </h3>
              <button
                onClick={() => setIsLogInsertingPhoto(false)}
                className="p-2 hover:bg-muted"
              >
                <X className="w-6 h-6" />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
              <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-6 gap-4">
                {photos.map((photo) => (
                  <div
                    key={photo.id}
                    onClick={() => insertPhotoIntoLog(photo)}
                    className="group relative aspect-square bg-muted cursor-pointer overflow-hidden border border-transparent hover:border-primary transition-all"
                  >
                    <img
                      src={resolveAssetUrl(
                        photo.thumbnailUrl || photo.url,
                        resolvedCdnDomain
                      )}
                      alt=""
                      className="w-full h-full object-cover grayscale group-hover:grayscale-0 transition-all"
                    />
                    <div className="absolute inset-0 bg-primary/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Plus className="w-8 h-8 text-white" />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}
